window.songs=[{"order":1,"id":"01-prolog","title":"Prolog","titleZh":"序幕","lines":[{"id":"mozart-das-musical-01-001","lineIndex":1,"speaker":"","original":"Wo ist das Grab?","ipa":"/vo ɪst das ɡɾɑp/","zh":"（莫扎特的）坟墓在哪？","en":"Where is the grave?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-01-002","lineIndex":2,"speaker":"","original":"Ich glaube da drüben.","ipa":"/ɪç ɡlaʊbə dɑ dɾybən/","zh":"应该就在那边吧。","en":"I think over there.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-01-003","lineIndex":3,"speaker":"","original":"Sie erinnern sich nicht, Madame Mozart?","ipa":"/zi ɛɾɪnɜn zɪç nɪçt mɑdɑmə motsaɾt/","zh":"您不记得了吗，莫扎特夫人？","en":"You don't remember, Madame Mozart?","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-01-004","lineIndex":4,"speaker":"","original":"Nissen!","ipa":"/nɪsən/","zh":"尼森！","en":"Nit!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-01-005","lineIndex":5,"speaker":"","original":"Mein Name ist Nissen, nicht mehr Mozart.","ipa":"/maɪn nɑmə ɪst nɪsən nɪçt meɾ motsaɾt/","zh":"我现在姓尼森，不再是莫扎特！","en":"My name is Nissen, no longer Mozart.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-01-006","lineIndex":6,"speaker":"","original":"Wie oft, soll ich Ihnen das noch sagen?","ipa":"/vi ɔft zɔl ɪç inən das nɔx zɑɡən/","zh":"我到底还要跟你强调多少遍？！","en":"How many times do I have to tell you this?","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-01-007","lineIndex":7,"speaker":"","original":"Zeigen Sie mir, wo er begraben ist.","ipa":"/tsaɪɡən zi miɾ vo ɛɾ bəɡɾɑbən ɪst/","zh":"请告诉我，他到底埋在哪里。","en":"Show me where he is buried.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-01-008","lineIndex":8,"speaker":"","original":"Wir haben eine Abmachung.","ipa":"/viɾ hɑbən aɪnə apmaxʊŋ/","zh":"我们事先说好的。","en":"We have a deal.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-01-009","lineIndex":9,"speaker":"","original":"Ich war lange nicht mehr hier.","ipa":"/ɪç vɑɾ laŋə nɪçt meɾ hiɾ/","zh":"我已经很久没来过这里了。","en":"I haven't been here for a long time.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-01-010","lineIndex":10,"speaker":"","original":"Was haben Sie denn vor?","ipa":"/vas hɑbən zi dɛn fɔɾ/","zh":"您打算怎么做？","en":"What are you up to?","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-01-011","lineIndex":11,"speaker":"","original":"Wollen Sie ihn ausgraben?!","ipa":"/vɔlən zi in aʊsɡɾɑbən/","zh":"把他挖出来吗？！","en":"Do you want to dig him up?!","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-01-012","lineIndex":12,"speaker":"","original":"Nur den Schädel.","ipa":"/nuɾ den ʃɛdəl/","zh":"我只要头骨。","en":"Just the skull.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-01-013","lineIndex":13,"speaker":"","original":"Im Interesse der Wissenschaft.","ipa":"/ɪm ɪntərɛsə dɛɾ vɪsənʃaft/","zh":"科研需要。","en":"In the interest of science.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-01-014","lineIndex":14,"speaker":"","original":"Ich werde herausfinden, was ihn zum Genie gemacht hat.","ipa":"/ɪç vɛɾdə hɛraʊsfɪndən vas in tsʊm ɡəni ɡəmaxt hat/","zh":"我要弄清，究竟是什么造就了这个天才。","en":"I'm going to find out what made him a genius.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-01-015","lineIndex":15,"speaker":"","original":"Wir sind da. Hier ist es.","ipa":"/viɾ zɪnt dɑ hiɾ ɪst ɛs/","zh":"我们到了，这里便是。","en":"We are here. Here it is.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-01-016","lineIndex":16,"speaker":"","original":"Das da?! Sind Sie sicher?","ipa":"/das dɑ zɪnt zi zɪçɜ/","zh":"这里吗？！您确定？","en":"That one?! Are you sure?","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-01-017","lineIndex":17,"speaker":"","original":"Absolut.","ipa":"/apzolut/","zh":"确定（一定以及肯定）","en":"Absolutely.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-01-018","lineIndex":18,"speaker":"","original":"Hier also ist er begraben? Jean-Pierre!","ipa":"/hiɾ alzo ɪst ɛɾ bəɡɾɑbən dʒinpirə/","zh":"他就埋在这？让·皮埃尔！","en":"So this is where he is buried? Jean Pierre!","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-01-019","lineIndex":19,"speaker":"","original":"Mein Geld, Monsieur Mesmer! 5 Louis d'or!","ipa":"/maɪn ɡɛlt mɔnziuɾ mɛsmɜ fʏnf luɪs deoɾ/","zh":"我的报酬，梅斯默先生！5个金路易！","en":"My money, Monsieur Mesmer! 5 Louis d'or!","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-01-020","lineIndex":20,"speaker":"","original":"Das ist ein magischer Ort.","ipa":"/das ɪst aɪn mɑɡɪʃɜ ɔɾt/","zh":"这是个充满魔力的地方。","en":"This is a magical place.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-01-021","lineIndex":21,"speaker":"","original":"Écoutez! Hören Sie es?","ipa":"/ekutets hørən zi ɛs/","zh":"听！你听到了吗？","en":"Ecoutez! Do you hear it?","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-01-022","lineIndex":22,"speaker":"","original":"Machen Sie schnell. Mir ist kalt.","ipa":"/maxən zi ʃnɛl miɾ ɪst kalt/","zh":"动作快点，我很冷。","en":"Do it quickly. I'm cold.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-01-023","lineIndex":23,"speaker":"","original":"Madame, Hören Sie doch!","ipa":"/mɑdɑmə hørən zi dɔx/","zh":"夫人，您仔细听！","en":"Madame, listen!","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-01-024","lineIndex":24,"speaker":"","original":"Was?","ipa":"/vas/","zh":"听什么？","en":"What?","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-01-025","lineIndex":25,"speaker":"","original":"Das unendliche Universum der Musik, aus dem er kam...","ipa":"/das ʊnɛntlɪçə univɛɾzʊm dɛɾ muzik aʊs dem ɛɾ kɑm/","zh":"无垠音乐宇宙，他从中而来...","en":"The infinite universe of music from which he came...","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-01-026","lineIndex":26,"speaker":"","original":"Wie ein Stern fiel er auf die Erde...","ipa":"/vi aɪn ʃtɛɾn fil ɛɾ aʊf di eɾdə/","zh":"如流星降临于世...","en":"He fell to earth like a star...","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-01-027","lineIndex":27,"speaker":"","original":"un enfant de Dieu...","ipa":"/ʊn ɛnfant de diu/","zh":"天，之骄子...","en":"un enfant de Dieu...","note":"","sourceLineIndex":27}],"sourceOrder":1,"displayOrder":1},{"order":2,"id":"02-was-fur-ein-kind","title":"Was für ein Kind!","titleZh":"这是怎样的孩子！","lines":[{"id":"mozart-das-musical-02-002","lineIndex":1,"speaker":"Gäste","original":"Was für ein Kind!","ipa":"/vas fyɾ aɪn kɪnt/","zh":"神奇的孩子","en":"What a child!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-02-003","lineIndex":2,"speaker":"","original":"Phänomenal.","ipa":"/fɛnomənɑl/","zh":"非凡出众！","en":"Phenomenal.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-02-004","lineIndex":3,"speaker":"","original":"Dieses Talent - einfach genial!","ipa":"/dizəs talɛnt aɪnfax ɡenjɑl/","zh":"他的才华，无与伦比！","en":"This talent - simply brilliant!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-02-005","lineIndex":4,"speaker":"","original":"Wie fröhlich, so klein und manierlich.","ipa":"/vi frølɪç zo klaɪn ʊnt maniɾlɪç/","zh":"多么讨喜，年幼又知礼","en":"How happy, so small and mannerly.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-02-006","lineIndex":5,"speaker":"","original":"Wie niedlich, gescheit und possierlich.","ipa":"/vi nitlɪç ɡəʃaɪt ʊnt pɔsiɾlɪç/","zh":"多么可爱，伶俐又逗趣","en":"How cute, clever and cute.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-02-007","lineIndex":6,"speaker":"","original":"Ein Wunder, das lebt!","ipa":"/aɪn vʊndɜ das lept/","zh":"活生生的奇迹","en":"A miracle that lives!","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-02-008","lineIndex":7,"speaker":"Wahrhaftig","original":"Ein göttliches Kind!","ipa":"/vɑɾhaftɪç aɪn ɡœtlɪçəs kɪnt/","zh":"毫无疑问，一个非凡的孩子","en":"a divine child!","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-02-010","lineIndex":8,"speaker":"Leopold","original":"In der nächsten Abteilung","ipa":"/ɪn dɛɾ nɛçstən aptaɪlʊŋ/","zh":"下一个部分","en":"In the next department","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-02-011","lineIndex":9,"speaker":"","original":"Mesdames et Messieurs","ipa":"/mɛsdɑməs et mɛsiuɾs/","zh":"女士们先生们","en":"Mesdames and Messieurs","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-02-012","lineIndex":10,"speaker":"","original":"eine wahre Sensation:","ipa":"/aɪnə vɑrə zɛnzatsjon/","zh":"一个真正激动人心的表演","en":"a true sensation:","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-02-013","lineIndex":11,"speaker":"","original":"Der klare Beweis für das Gottestalent von meinem kleinen Sohn.","ipa":"/dɛɾ klˈɑːrə bəvˈaɪs fyːɾ das ɡˌɔtɛstalˈɛnt fɔn mˌaɪnəm klˈaɪnən zˈoːn/","zh":"是我那小儿子他天赋的又一明证","en":"The clear proof of God's talent from my little son.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-02-015","lineIndex":12,"speaker":"","original":"Seine Schwester, das Nannerl war, als sie noch klein war auch ein Wunderkind.","ipa":"/zˌaɪnə ʃvˈɛstɜ das nˈanɜl vɑːɾ als ziː nɔx klˈaɪn vɑːɾ ˌaʊx aɪn vˈʊndɜkˌɪnt/","zh":"他的姐姐，娜奈尔她小的时候也曾是一个神童","en":"His sister, Nannerl was when she was little also a child prodigy.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-02-018","lineIndex":13,"speaker":"","original":"Jetzt wird sie dem Bruder die Augen verbinden damit er völlig blind ist.","ipa":"/jˌɛtst vˌɪɾt ziː deːm bɾˈuːdɜ diː ˈaʊɡən fɛɾbˈɪndən dɑːmˈɪt ɛɾ fˈœlɪç blˈɪnt ɪst/","zh":"现在她将蒙上她弟弟的眼睛让他完全看不见","en":"Now she will blindfold her brother so that he is completely blind.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-02-020","lineIndex":14,"speaker":"","original":"Um die Tasten zu verstecken werden sie mit einem Tuch drapiert.","ipa":"/ʊm diː tˈastən tsuː fɛɾʃtˈɛkən vˌɛɾdən ziː mɪt ˌaɪnəm tˈʊx dɾapˈiːɾt/","zh":"琴键也将被隐藏被一块厚布所覆盖","en":"To hide the buttons they are draped with a cloth.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-02-022","lineIndex":15,"speaker":"","original":"Trotzdem wird er etwas spielen und wieder selber komponiert.","ipa":"/tɾˈɔtsdeːm vˌɪɾt ɛɾ ˈɛtvɑːs ʃpˈiːlən ʊnt vˈiːdɜ zˈɛlbɜ kɔmpoːnˈiːɾt/","zh":"而他依然能够演奏还是他自己作的曲","en":"Still he'll play something and again composed himself.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-02-025","lineIndex":16,"speaker":"Gäste","original":"Er schläft entrückt!","ipa":"/ɛɾ ʃlɛft ɛntɾʏkt/","zh":"他睡着了，神游天外","en":"He sleeps rapturously!","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-02-026","lineIndex":17,"speaker":"","original":"Er träumt verzückt! Er gähnt!","ipa":"/ɛɾ tɾɔømt fɛɾtsʏkt ɛɾ ɡɛnt/","zh":"他入梦了，心神空茫","en":"He dreams ecstatically! He's yawning!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-02-027","lineIndex":18,"speaker":"Leopold","original":"Amadé! Los doch! Amadé!","ipa":"/leopɔlt ɑmade los dɔx ɑmade/","zh":"利奥波德：阿玛迪！继续，阿玛迪！","en":"Amadé! Come on! Amade!","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-02-029","lineIndex":19,"speaker":"Gäste","original":"Was für ein Kind!","ipa":"/vas fyɾ aɪn kɪnt/","zh":"神奇的孩子","en":"What a child!","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-02-030","lineIndex":20,"speaker":"","original":"Wie talentiert!","ipa":"/vi talɛntiɾt/","zh":"天赋卓绝！","en":"How talented!","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-02-031","lineIndex":21,"speaker":"","original":"Selbst komponiert!","ipa":"/zɛlpst kɔmponiɾt/","zh":"还能作曲！","en":"Self-composed!","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-02-033","lineIndex":22,"speaker":"Gräfin Zinzendorf","original":"Ich bin gerührt!","ipa":"/ɪç bɪn ɡəryɾt/","zh":"太动人了！","en":"I'm touched!","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-02-035","lineIndex":23,"speaker":"Gäste","original":"Erstaunlicher Besitz und erbaulich.","ipa":"/ɛɾʃtaʊnlɪçɜ bəzɪts ʊnt ɛɾbaʊlɪç/","zh":"神奇，新鲜，让人满足","en":"Amazing property and uplifting.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-02-036","lineIndex":24,"speaker":"","original":"Begabt, amüsant und so traulich.","ipa":"/bəɡɑpt ɑmyzant ʊnt zo tɾaʊlɪç/","zh":"才华出众，诙谐有趣，惹人喜爱","en":"Talented, amusing and so trusting.","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-02-037","lineIndex":25,"speaker":"","original":"Ein Wunder, das lebt!","ipa":"/aɪn vʊndɜ das lept/","zh":"活生生的奇迹","en":"A miracle that lives!","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-02-038","lineIndex":26,"speaker":"Wahrhaftig","original":"Ein göttliches Kind!","ipa":"/vɑɾhaftɪç aɪn ɡœtlɪçəs kɪnt/","zh":"确实是个非凡的孩子","en":"a divine child!","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-02-039","lineIndex":27,"speaker":"Gräfin Zinzendorf","original":"Nun, Herr Hofkompositeur.","ipa":"/ɡɾɛfɪn tsɪntsəndɔɾf nun hɛɾ hɔlfkɔmpozitøɾ/","zh":"钦岑多夫伯爵夫人：那么，首席乐师先生","en":"Well, Mr. Holfcompositeur.","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-02-040","lineIndex":28,"speaker":"Salieri","original":"Zu Diensten, Kaiserliche Hoheit.","ipa":"/zɑliri tsu dinstən kaɪzɜlɪçə hoaɪt/","zh":"萨列里：为您服务，我的陛下","en":"At your service, Your Imperial Highness.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-02-041","lineIndex":29,"speaker":"Gräfin Zinzendorf","original":"Ihre Meinung, Signore Salieri?","ipa":"/ɡɾɛfɪn tsɪntsəndɔɾf irə maɪnʊŋ zɪɡnorə zɑliri/","zh":"钦岑多夫伯爵夫人：您怎么看，萨列里先生？","en":"Your opinion, Signore Salieri?","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-02-042","lineIndex":30,"speaker":"Salieri","original":"Eine Sensation, für den Jahrmarkt.","ipa":"/zɑliri aɪnə zɛnzatsjon fyɾ den jɑɾmaɾkt/","zh":"萨列里：在年集（一种一年定期举办有游乐活动的集市）上或许能技惊四座","en":"A sensation for the fair.","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-02-043","lineIndex":31,"speaker":"","original":"Aber nicht für die Kunst.","ipa":"/ɑbɜ nɪçt fyɾ di kʊnst/","zh":"艺术性而言则未必出众","en":"But not for art.","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-02-044","lineIndex":32,"speaker":"Gräfin Zinzendorf","original":"Fahren Sie fort, Herr Mozart.","ipa":"/ɡɾɛfɪn tsɪntsəndɔɾf fɑrən zi fɔɾt hɛɾ motsaɾt/","zh":"钦岑多夫伯爵夫人：请继续吧，莫扎特先生","en":"Continue, Mr. Mozart.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-02-046","lineIndex":33,"speaker":"Leopold","original":"Mit drei Jahren schon saß er auf meinem Knie und hat das Klavier entdeckt.","ipa":"/mɪt dɾˈaɪ jˈɑːrən ʃˌoːn zˈɑːs ɛɾ aʊf mˌaɪnəm knˈiː ʊnt hat das klavˈiːɾ ɛntdˈɛkt/","zh":"三岁的时候他就坐在我的膝盖上学习钢琴。","en":"At the age of three he sat on my knee and discovered the piano.","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-02-048","lineIndex":34,"speaker":"","original":"Mit fünf schrieb er ein komplettes Konzert harmonisch ganz korrekt.","ipa":"/mɪt fˈʏnf ʃrˈiːp ɛɾ aɪn kɔmplˈɛtəs kɔntsˈɛɾt haɾmˈoːnɪʃ ɡˌants kɔrˈɛkt/","zh":"五岁的时候他写出了一首完整的协奏曲并且音律和谐。","en":"At the age of five he wrote a complete concerto harmonically completely correct.","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-02-050","lineIndex":35,"speaker":"","original":"Er spielt alles vom Blatt!","ipa":"/ɛɾ ʃpilt aləs fɔm blat/","zh":"他能视奏曲谱上的所有内容","en":"He sight-reads everything!","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-02-051","lineIndex":36,"speaker":"","original":"Was er einmal gehört hat, kann er memorieren.","ipa":"/vˈas ɛɾ ˈaɪnmˌɑːl ɡəhˈœɾt hat kˌan ɛɾ mˌeːmoːrˈiːrən/","zh":"只要他听过一遍，就能完全记忆。","en":"He can remember what he once heard.","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-02-053","lineIndex":37,"speaker":"","original":"Wobei er sogar die schwierigsten Fugen fehlerfrei variiern kann.","ipa":"/voːbˈaɪ ɛɾ zoːɡˈɑːɾ diː ʃvˈiːrɪçstən fˈuːɡən fˈeːlɜfrˌaɪ vˈɑriːˌiːɾn kˌan/","zh":"即使是最难的赋格他也能加以变奏完美呈现。","en":"He can vary even the most difficult joints without errors.","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-02-055","lineIndex":38,"speaker":"","original":"Sein Gehör ist unbestechlich.","ipa":"/zaɪn ɡəhøɾ ɪst ʊnbəʃtɛçlɪç/","zh":"他的听力非凡","en":"His hearing is incorruptible.","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-02-056","lineIndex":39,"speaker":"","original":"Er gibt auf jede Note acht!","ipa":"/ɛɾ ɡipt aʊf jedə notə axt/","zh":"能够准确分辨每一个音符！","en":"He pays attention to every note!","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-02-057","lineIndex":40,"speaker":"","original":"Das Spiel auf meiner Violine hat er sich selber beigebracht!","ipa":"/das ʃpˈiːl aʊf mˌaɪnɜ vˌiːoːlˈiːnə hat ɛɾ zɪç zˈɛlbɜ bˈaɪɡəbɾˌaxt/","zh":"他用我的小提琴自学了演奏","en":"He taught himself how to play my violin!","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-02-060","lineIndex":41,"speaker":"Gäste","original":"Was für ein Kind!","ipa":"/vas fyɾ aɪn kɪnt/","zh":"神奇的孩子！","en":"What a child!","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-02-061","lineIndex":42,"speaker":"","original":"Welch eine Qual!","ipa":"/vɛlç aɪnə kvɑl/","zh":"真令人困扰！","en":"What torture!","note":"","sourceLineIndex":61},{"id":"mozart-das-musical-02-062","lineIndex":43,"speaker":"","original":"Ein kleiner Gott!","ipa":"/aɪn klaɪnɜ ɡɔt/","zh":"小小神童！","en":"A little god!","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-02-063","lineIndex":44,"speaker":"","original":"Ein Ideal!","ipa":"/aɪn ideɑl/","zh":"简直完美！","en":"An ideal!","note":"","sourceLineIndex":63},{"id":"mozart-das-musical-02-064","lineIndex":45,"speaker":"Antonio Salieri","original":"Wie abgeschmackt!","ipa":"/antonɪo zɑliri vi apɡəʃmakt/","zh":"安东尼奥·萨列里：真是无聊！","en":"How absurd!","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-02-065","lineIndex":46,"speaker":"Gäste","original":"Man muss ihn lieben.","ipa":"/ɡɛstə man mʊs in libən/","zh":"客人们：人们会喜欢他","en":"Gotta love him.","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-02-066","lineIndex":47,"speaker":"","original":"Ein Engel, dressiert und durchtrieben.","ipa":"/aɪn ɛŋəl dɾɛsiɾt ʊnt dʊɐçtɾibən/","zh":"一个天使，温驯又机敏","en":"An angel, trained and cunning.","note":"","sourceLineIndex":66},{"id":"mozart-das-musical-02-067","lineIndex":48,"speaker":"","original":"Ein Wunder, das lebt!","ipa":"/aɪn vʊndɜ das lept/","zh":"活生生的奇迹","en":"A miracle that lives!","note":"","sourceLineIndex":67},{"id":"mozart-das-musical-02-068","lineIndex":49,"speaker":"Wahrhaftig","original":"Ein göttliches Kind!","ipa":"/vɑɾhaftɪç aɪn ɡœtlɪçəs kɪnt/","zh":"毫无疑问，一个非凡的孩子","en":"a divine child!","note":"","sourceLineIndex":68},{"id":"mozart-das-musical-02-069","lineIndex":50,"speaker":"Gräfin Zinzendorf","original":"Komm hier, Kleiner.","ipa":"/ɡɾɛfɪn tsɪntsəndɔɾf kɔm hiɾ klaɪnɜ/","zh":"钦岑多夫伯爵夫人：来我这儿，孩子","en":"Come here, little one.","note":"","sourceLineIndex":69},{"id":"mozart-das-musical-02-070","lineIndex":51,"speaker":"Leopold","original":"Amadé, das ist die Kaiserin!","ipa":"/leopɔlt ɑmade das ɪst di kaɪzərɪn/","zh":"利奥波德：阿玛迪，这是女王陛下！","en":"Amadé, this is the Empress!","note":"","sourceLineIndex":70},{"id":"mozart-das-musical-02-071","lineIndex":52,"speaker":"Gräfin Zinzendorf","original":"Ist schon gut, Herr Mozart.","ipa":"/ɡɾɛfɪn tsɪntsəndɔɾf ɪst ʃon ɡut hɛɾ motsaɾt/","zh":"钦岑多夫伯爵夫人：没关系，莫扎特先生","en":"It's okay, Mr. Mozart.","note":"","sourceLineIndex":71},{"id":"mozart-das-musical-02-072","lineIndex":53,"speaker":"","original":"Er ist erst noch ein Kind.","ipa":"/ɛɾ ɪst eɾst nɔx aɪn kɪnt/","zh":"他只是个孩子","en":"He's only a child.","note":"","sourceLineIndex":72},{"id":"mozart-das-musical-02-073","lineIndex":54,"speaker":"Leopold","original":"Entschuldigen Sie, Kaiserliche Hoheit.","ipa":"/leopɔlt ɛntʃʊldɪɡən zi kaɪzɜlɪçə hoaɪt/","zh":"利奥波德：很抱歉，尊贵的陛下","en":"Excuse me, Imperial Highness.","note":"","sourceLineIndex":73},{"id":"mozart-das-musical-02-074","lineIndex":55,"speaker":"","original":"Verbeug dich!","ipa":"/fɛɾbɔøk dɪç/","zh":"快鞠躬！","en":"Take a bow!","note":"","sourceLineIndex":74},{"id":"mozart-das-musical-02-075","lineIndex":56,"speaker":"Gräfin Zinzendorf","original":"Dies ist mein Geschenk für dich, Amadé.","ipa":"/ɡɾɛfɪn tsɪntsəndɔɾf dis ɪst maɪn ɡəʃɛŋk fyɾ dɪç ɑmade/","zh":"钦岑多夫伯爵夫人：这是我给你的礼物，阿玛迪。","en":"This is my gift for you, Amadé.","note":"","sourceLineIndex":75},{"id":"mozart-das-musical-02-076","lineIndex":57,"speaker":"Leopold","original":"Untertänigsten Dank.","ipa":"/leopɔlt ʊntɜtɛnɪçstən daŋk/","zh":"利奥波德：由衷感谢","en":"Thank you most humbly.","note":"","sourceLineIndex":76},{"id":"mozart-das-musical-02-077","lineIndex":58,"speaker":"Gräfin Zinzendorf","original":"Der Prinzenrock meines Sohnes Maximilian.","ipa":"/ɡɾɛfɪn tsɪntsəndɔɾf dɛɾ pɾɪntsənrɔk maɪnəs zonəs maksimɪliɑn/","zh":"钦岑多夫伯爵夫人：这是我儿子马克西米立安的王子礼服","en":"My son Maximillian's prince's skirt.","note":"","sourceLineIndex":77},{"id":"mozart-das-musical-02-078","lineIndex":59,"speaker":"","original":"Er passt ihn nicht mehr.","ipa":"/ɛɾ past in nɪçt meɾ/","zh":"他已经穿不下了","en":"It doesn't fit anymore.","note":"","sourceLineIndex":78},{"id":"mozart-das-musical-02-079","lineIndex":60,"speaker":"","original":"Und jetzt sollst du ihn haben.","ipa":"/ʊnt jɛtst zɔlst du in hɑbən/","zh":"现在归你了","en":"And now you shall have it.","note":"","sourceLineIndex":79},{"id":"mozart-das-musical-02-080","lineIndex":61,"speaker":"Baronin von Waldstätten","original":"Amadé.","ipa":"/bɑronɪn fɔn valtʃtɛtən ɑmade/","zh":"沃德斯塔腾男爵夫人：阿玛迪","en":"Amadé.","note":"","sourceLineIndex":80},{"id":"mozart-das-musical-02-081","lineIndex":62,"speaker":"","original":"Ich bin die Baronin von Waldstätten.","ipa":"/ɪç bɪn di bɑronɪn fɔn valtʃtɛtən/","zh":"我是沃德斯塔腾男爵夫人","en":"I am the Baroness von Waldstätten.","note":"","sourceLineIndex":81},{"id":"mozart-das-musical-02-082","lineIndex":63,"speaker":"Leopold","original":"Zu gütig, Frau Baronin.","ipa":"/leopɔlt tsu ɡytɪç fraʊ bɑronɪn/","zh":"利奥波德：男爵夫人，感谢您的慈悲","en":"Too kind, Baroness.","note":"","sourceLineIndex":82},{"id":"mozart-das-musical-02-083","lineIndex":64,"speaker":"","original":"Eine kleine Spende wäre willkommen.","ipa":"/aɪnə klaɪnə ʃpɛndə vɛrə vɪlkɔmən/","zh":"任何小额赞助都十分感谢","en":"A small donation would be appreciated.","note":"","sourceLineIndex":83},{"id":"mozart-das-musical-02-084","lineIndex":65,"speaker":"","original":"Ich hatte Unkosten...","ipa":"/ɪç hatə ʊnkɔstən/","zh":"我的开支不菲…","en":"I had expenses...","note":"","sourceLineIndex":84},{"id":"mozart-das-musical-02-085","lineIndex":66,"speaker":"","original":"Da spielt man vor der Kaiserin unterhält nichts weiter als ein gebrauchtes Kleidungsstück.","ipa":"/dɑː ʃpˈiːlt man fˌɔɾ dɛɾ kˈaɪzərˌɪn ˌʊntɜhˈɛlt nˈɪçts vˈaɪtɜ als aɪn ɡəbɾˈaʊxtəs klˈaɪdʊŋsʃtˌʏk/","zh":"而在女王面前表演除了穿过的衣服并没有其他收获","en":"Playing in front of the Empress entertains nothing more than a used piece of clothing.","note":"","sourceLineIndex":85},{"id":"mozart-das-musical-02-087","lineIndex":67,"speaker":"","original":"Hat Ihnen unsere Gabe ungefallen?","ipa":"/hat inən ʊnzrə ɡɑbə ʊnɡəfalən/","zh":"您喜欢我们的表演么？","en":"Did you dislike our gift?","note":"","sourceLineIndex":87},{"id":"mozart-das-musical-02-088","lineIndex":68,"speaker":"Baronin","original":"Ihr Kind ist ein Genie.","ipa":"/bɑronɪn iɾ kɪnt ɪst aɪn ɡəni/","zh":"男爵夫人：您的孩子是个天才！","en":"Your child is a genius.","note":"","sourceLineIndex":88},{"id":"mozart-das-musical-02-089","lineIndex":69,"speaker":"Leopold","original":"In der Tat!","ipa":"/leopɔlt ɪn dɛɾ tɑt/","zh":"利奥波德：毫无疑问","en":"Indeed!","note":"","sourceLineIndex":89},{"id":"mozart-das-musical-02-090","lineIndex":70,"speaker":"","original":"Ich habe seine Begabung frühzeitig erkannt und in jeder Weise erfordert.","ipa":"/ɪç hɑːbə zˌaɪnə bəɡˈɑbʊŋ frˈyːtsaɪtˌɪç ɛɾkˈant ʊnt ɪn jˈeːdɜ vˈaɪzə ɛɾfˈɔɾdɜt/","zh":"我早就发现了他的天赋并全方位加以培养","en":"I recognized his talent early on and required it in every way.","note":"","sourceLineIndex":90},{"id":"mozart-das-musical-02-092","lineIndex":71,"speaker":"Baronin","original":"Überfordern Sie ihn nicht!","ipa":"/bɑronɪn ybɜfɔɾdɜn zi in nɪçt/","zh":"男爵夫人：您不要对他太过严格","en":"Don't overwhelm him!","note":"","sourceLineIndex":92},{"id":"mozart-das-musical-02-093","lineIndex":72,"speaker":"","original":"Er ist noch so klein, und zart.","ipa":"/ɛɾ ɪst nɔx zo klaɪn ʊnt tsaɾt/","zh":"他还这么幼小和脆弱","en":"He's still so small and delicate.","note":"","sourceLineIndex":93},{"id":"mozart-das-musical-02-094","lineIndex":73,"speaker":"","original":"Seien Sie vorsichtig!","ipa":"/zaɪən zi foɾzɪçtɪç/","zh":"您要注意分寸","en":"Be careful!","note":"","sourceLineIndex":94},{"id":"mozart-das-musical-02-095","lineIndex":74,"speaker":"","original":"Wie leicht kann er zerbrechen.","ipa":"/vi laɪçt kan ɛɾ tsɛɾbɾɛçən/","zh":"他是如此容易被伤害","en":"How easily it can break.","note":"","sourceLineIndex":95},{"id":"mozart-das-musical-02-096","lineIndex":75,"speaker":"Leopold","original":"Mach einen Diener vor der Baronin, Amadé.","ipa":"/leopɔlt max aɪnən dinɜ fɔɾ dɛɾ bɑronɪn ɑmade/","zh":"利奥波德：阿玛迪愿意为您效劳，男爵夫人","en":"Make a servant before the Baroness, Amadé.","note":"","sourceLineIndex":96},{"id":"mozart-das-musical-02-097","lineIndex":76,"speaker":"","original":"Amadé!","ipa":"/ɑmade/","zh":"阿玛迪！","en":"Amadé!","note":"","sourceLineIndex":97},{"id":"mozart-das-musical-02-098","lineIndex":77,"speaker":"Baronin","original":"Sie dürfen es nicht nehmen.","ipa":"/bɑronɪn zi dʏɾfən ɛs nɪçt nemən/","zh":"男爵夫人：不要拿走它。","en":"You can't take it.","note":"","sourceLineIndex":98},{"id":"mozart-das-musical-02-099","lineIndex":78,"speaker":"","original":"Es gehört ihm.","ipa":"/ɛs ɡəhœɾt im/","zh":"这个属于他。","en":"It's his.","note":"","sourceLineIndex":99},{"id":"mozart-das-musical-02-100","lineIndex":79,"speaker":"","original":"Es hat ihm immer schon gehört.","ipa":"/ɛs hat im ɪmɜ ʃon ɡəhœɾt/","zh":"这个一直都属于他。","en":"It's always been his.","note":"","sourceLineIndex":100},{"id":"mozart-das-musical-02-101","lineIndex":80,"speaker":"","original":"Was du trägst hat das Gewicht von allem Gold der Welt.","ipa":"/vas du tɾɛkst hat das ɡəvɪçt fɔn aləm ɡɔlt dɛɾ vɛlt/","zh":"你身上背负的，重如举世之金","en":"What you wear has the weight of all the gold in the world.","note":"","sourceLineIndex":101},{"id":"mozart-das-musical-02-102","lineIndex":81,"speaker":"","original":"Und ist leichter als das Licht.","ipa":"/ʊnt ɪst laɪçtɜ als das lɪçt/","zh":"却又比光还要轻","en":"And is lighter than light.","note":"","sourceLineIndex":102},{"id":"mozart-das-musical-02-103","lineIndex":82,"speaker":"Leopold","original":"Für meinen Sohn! (Mozart!)","ipa":"/leopɔlt fyɾ maɪnən zon motsaɾt/","zh":"利奥波德：为我的儿子（莫扎特！）","en":"For my son! (Mozart!)","note":"","sourceLineIndex":103},{"id":"mozart-das-musical-02-104","lineIndex":83,"speaker":"Nannerl","original":"Für sein Talent! (Mozart!)","ipa":"/nanɜl fyɾ zaɪn talɛnt motsaɾt/","zh":"娜奈尔：为他的才华（莫扎特！）","en":"For his talent! (Mozart!)","note":"","sourceLineIndex":104},{"id":"mozart-das-musical-02-105","lineIndex":84,"speaker":"Leopold","original":"Als Dank und Lohn.","ipa":"/leopɔlt als daŋk ʊnt lon/","zh":"利奥波德：作为感恩和回报","en":"As thanks and reward.","note":"","sourceLineIndex":105},{"id":"mozart-das-musical-02-106","lineIndex":85,"speaker":"","original":"Kunst braucht mehr als Können und Talent.","ipa":"/kʊnst bɾaʊxt meɾ als kœnən ʊnt talɛnt/","zh":"艺术不光只是技巧和天赋","en":"Art requires more than skill and talent.","note":"","sourceLineIndex":106},{"id":"mozart-das-musical-02-107","lineIndex":86,"speaker":"","original":"Von Applaus und Lob allein wird keiner satt.","ipa":"/fɔn aplaʊs ʊnt lop alaɪn vɪɾt kaɪnɜ zat/","zh":"掌声和赞美容不得沾沾自喜","en":"Nobody gets enough of applause and praise alone.","note":"","sourceLineIndex":107},{"id":"mozart-das-musical-02-108","lineIndex":87,"speaker":"","original":"Die Zeit ist knapp.","ipa":"/di tsaɪt ɪst knap/","zh":"光阴易逝","en":"Time is short.","note":"","sourceLineIndex":108},{"id":"mozart-das-musical-02-109","lineIndex":88,"speaker":"","original":"Als kleines Kind ist Mozart eine Attraktion.","ipa":"/als klaɪnəs kɪnt ɪst motsaɾt aɪnə atɾaktsjon/","zh":"孩童莫扎特引人瞩目","en":"As a small child, Mozart is an attraction.","note":"","sourceLineIndex":109},{"id":"mozart-das-musical-02-110","lineIndex":89,"speaker":"","original":"Jedoch auch er wird bald erwachsen sein.","ipa":"/jedɔx aʊx ɛɾ vɪɾt balt ɛɾvaxzən zaɪn/","zh":"但他很快会长大","en":"However, he too will soon be an adult.","note":"","sourceLineIndex":110},{"id":"mozart-das-musical-02-111","lineIndex":90,"speaker":"","original":"Dann ist er nur ein Komponist wie's viele sind.","ipa":"/dan ɪst ɛɾ nuɾ aɪn kɔmponɪst vis filə zɪnt/","zh":"那他就只是一个泯然众人的作曲家罢了","en":"Then he's just a composer like many others are.","note":"","sourceLineIndex":111},{"id":"mozart-das-musical-02-112","lineIndex":91,"speaker":"","original":"Ich wünsche mir, er wird für immer ein Kind!","ipa":"/ɪç vʏnʃə miɾ ɛɾ vɪɾt fyɾ ɪmɜ aɪn kɪnt/","zh":"我多么希望，他永远是个孩子","en":"I wish he becomes a child forever!","note":"","sourceLineIndex":112},{"id":"mozart-das-musical-02-113","lineIndex":92,"speaker":"Dr. Mesmer","original":"Auf Wolfgang Amadé Mozart!","ipa":"/deɛɾ mɛsmɜ aʊf vɔlfɡaŋ ɑmade motsaɾt/","zh":"迈斯莫博士：敬沃尔夫冈·阿玛迪·莫扎特！","en":"To Wolfgang Amadé Mozart!","note":"","sourceLineIndex":113},{"id":"mozart-das-musical-02-115","lineIndex":93,"speaker":"Gäste","original":"Was für ein Kind! Phänomenal.","ipa":"/vas fyɾ aɪn kɪnt fɛnomənɑl/","zh":"多么非凡的孩子！","en":"What a child! Phenomenal.","note":"","sourceLineIndex":115},{"id":"mozart-das-musical-02-116","lineIndex":94,"speaker":"Mehrere Gäste","original":"Dieser Vater ist ein Schinder.","ipa":"/dizɜ fɑtɜ ɪst aɪn ʃɪndɜ/","zh":"这个父亲是个苛刻的剥削者。","en":"This father is a slave driver.","note":"","sourceLineIndex":116},{"id":"mozart-das-musical-02-117","lineIndex":95,"speaker":"Gäste","original":"Dieses Talent – einfach genial!","ipa":"/dizəs talɛnt aɪnfax ɡenjɑl/","zh":"这份才华，简直是天才！","en":"Such talent – simply brilliant!","note":"","sourceLineIndex":117},{"id":"mozart-das-musical-02-118","lineIndex":96,"speaker":"Mehrere Gäste","original":"Er benutzt die eignen Kinder","ipa":"/ɛɾ bənʊtst di aɪɡnən kɪndɜ/","zh":"他利用自己的孩子","en":"He exploits his own children","note":"","sourceLineIndex":118},{"id":"mozart-das-musical-02-119","lineIndex":97,"speaker":"Gäste","original":"Wie fröhlich, geschickt und manierlich.","ipa":"/vi frølɪç ɡəʃɪkt ʊnt maniɾlɪç/","zh":"多么欢快、灵巧又彬彬有礼。","en":"How cheerful, skilful and well-mannered.","note":"","sourceLineIndex":119},{"id":"mozart-das-musical-02-120","lineIndex":98,"speaker":"Mehrere Gäste","original":"dressiert sie wie Affen","ipa":"/dɾɛsiɾt zi vi afən/","zh":"把他们像猴子一样训练","en":"trains them like monkeys","note":"","sourceLineIndex":120},{"id":"mozart-das-musical-02-121","lineIndex":99,"speaker":"Gäste","original":"Wie niedlich, gescheit und possierlich.","ipa":"/vi nitlɪç ɡəʃaɪt ʊnt pɔziɾlɪç/","zh":"多么可爱、聪明又逗趣。","en":"How sweet, clever and amusing.","note":"","sourceLineIndex":121},{"id":"mozart-das-musical-02-122","lineIndex":100,"speaker":"Mehrere Gäste","original":"und lässt sie begaffen.","ipa":"/ʊnt lɛst zi bəɡafən/","zh":"还让人围观他们。","en":"and lets people gawk at them.","note":"","sourceLineIndex":122},{"id":"mozart-das-musical-02-123","lineIndex":101,"speaker":"Gäste","original":"Ein Wunder, das lebt!","ipa":"/aɪn vʊndɜ das lept/","zh":"一个活生生的奇迹！","en":"A living miracle!","note":"","sourceLineIndex":123},{"id":"mozart-das-musical-02-124","lineIndex":102,"speaker":"Gäste","original":"Wahrhaftig: Ein göttliches Kind!","ipa":"/vɑɾhaftɪç aɪn ɡœtlɪçəs kɪnt/","zh":"的确，是个神一般的孩子！","en":"a divine child!","note":"","sourceLineIndex":124},{"id":"mozart-das-musical-02-125","lineIndex":103,"speaker":"Mehrere Gäste","original":"Schade um das hübsche Kind!","ipa":"/ʃɑdə ʊm das hʏpʃə kɪnt/","zh":"真可惜了这个可爱的孩子！","en":"What a shame for the lovely child!","note":"","sourceLineIndex":125},{"id":"mozart-das-musical-02-127","lineIndex":104,"speaker":"Alle Gäste","original":"Staunenswert. Ärgerlich.","ipa":"/ʃtaʊnənsveɾt ɛɾɡɜlɪç/","zh":"举座震惊，烦扰人心","en":"Amazing. Annoying.","note":"","sourceLineIndex":127},{"id":"mozart-das-musical-02-128","lineIndex":105,"speaker":"","original":"Sagenhaft. Wunderbar.","ipa":"/zɑɡənhaft vʊndɜbɑɾ/","zh":"难以置信，不可思议","en":"Fabulous. Wonderful.","note":"","sourceLineIndex":128},{"id":"mozart-das-musical-02-129","lineIndex":106,"speaker":"","original":"Unerhört.","ipa":"/ʊnɛɾhœɾt/","zh":"空前绝后的","en":"Outrageous.","note":"","sourceLineIndex":129},{"id":"mozart-das-musical-02-130","lineIndex":107,"speaker":"","original":"Wie wunderbar!","ipa":"/vi vʊndɜbɑɾ/","zh":"奇迹！","en":"How wonderful!","note":"","sourceLineIndex":130},{"id":"mozart-das-musical-02-131","lineIndex":108,"speaker":"","original":"Auf Amadé.","ipa":"/aʊf ɑmade/","zh":"敬阿玛迪！","en":"On Amadé.","note":"","sourceLineIndex":131},{"id":"mozart-das-musical-02-133","lineIndex":109,"speaker":"Baronin","original":"Menschen vergessen, Zeit wird zum Raum","ipa":"/mɛnʃən fɛɾɡɛsən tsaɪt vɪɾt tsʊm raʊm/","zh":"人们都忘了，时移世易","en":"People forget, time becomes space","note":"","sourceLineIndex":133},{"id":"mozart-das-musical-02-134","lineIndex":110,"speaker":"","original":"Erlebniss wird Erinnerung und Sehnsucht wird Traum","ipa":"/ɛɾlepnɪs vɪɾt ɛɾɪnərʊŋ ʊnt zenzuxt vɪɾt tɾaʊm/","zh":"经历变成回忆，渴望成为空想","en":"Experience becomes memory and longing becomes dream","note":"","sourceLineIndex":134},{"id":"mozart-das-musical-02-135","lineIndex":111,"speaker":"","original":"Der Frühling wird Sommer","ipa":"/dɛɾ frylɪŋ vɪɾt zɔmɜ/","zh":"春去夏来","en":"Spring becomes summer","note":"","sourceLineIndex":135},{"id":"mozart-das-musical-02-136","lineIndex":112,"speaker":"","original":"Die Jahre vergehn","ipa":"/di jɑrə fɛɾɡen/","zh":"年复一年","en":"The years pass","note":"","sourceLineIndex":136},{"id":"mozart-das-musical-02-137","lineIndex":113,"speaker":"","original":"Am Ende bleibt nur das, was wir nicht sehn.","ipa":"/am ɛndə blaɪpt nuɾ das vas viɾ nɪçt zen/","zh":"最后留下的那些，我们无法看见","en":"In the end all that remains is what we don't see.","note":"","sourceLineIndex":137},{"id":"mozart-das-musical-02-138","lineIndex":114,"speaker":"","original":"Manche finden, was sie glauben.","ipa":"/mançə fɪndən vas zi ɡlaʊbən/","zh":"一些人找到了信仰","en":"Some people find what they believe.","note":"","sourceLineIndex":138},{"id":"mozart-das-musical-02-139","lineIndex":115,"speaker":"","original":"Andre macht das Leben blind.","ipa":"/andɾə maxt das lebən blɪnt/","zh":"另一些盲目地活着","en":"Life makes life blind for Andre.","note":"","sourceLineIndex":139},{"id":"mozart-das-musical-02-140","lineIndex":116,"speaker":"","original":"Und die, die Gott besonders liebt sind wie Funkenflug im Wind.","ipa":"/ˈʊnt diː diː ɡˈɔt bəzˈɔndɜs lˈiːpt zɪnt viː fˈʊŋkənflˌuːk ɪm vˈɪnt/","zh":"而上帝的眷顾仿若风中的火花","en":"And those whom God especially loves are like flying sparks in the wind.","note":"","sourceLineIndex":140}],"sourceOrder":2,"displayOrder":2},{"order":3,"id":"03-die-wunder-sind-voruber","title":"Die Wunder sind vorüber","titleZh":"奇迹已成过去","lines":[{"id":"mozart-das-musical-03-001","lineIndex":1,"speaker":"WOLFGANG","original":"Eine 6, eine 5, zweimal die 4, gewonnen! Hier mit dem Gulden!","ipa":"/vɔlfɡaŋ aɪnə zɛks aɪnə fʏnf tsvaɪmɑl di fiɾ ɡəvɔnən hiɾ mɪt dem ɡʊldən/","zh":"一个6，一个5，两个4，我赢了！快把钱拿来！","en":"A 6, a 5, twice the 4, won! Here with the guilder!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-03-002","lineIndex":2,"speaker":"CHAMBERLAIN","original":"Noch eine Runde.","ipa":"/ʃambɜlaɪn nɔx aɪnə rʊndə/","zh":"侍从官：再来一局！","en":"One more round.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-03-003","lineIndex":3,"speaker":"","original":"Diesmal um 2.","ipa":"/dismɑl ʊm tsvaɪ/","zh":"这局赌两个古尔登。","en":"This time at 2.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-03-004","lineIndex":4,"speaker":"WOLFGANG","original":"Zu wenig.","ipa":"/vɔlfɡaŋ tsu venɪç/","zh":"切，才赌这么点。","en":"Not enough.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-03-005","lineIndex":5,"speaker":"","original":"Setz den Ringen an diener Hand!","ipa":"/zɛts den rɪŋən an dinɜ hant/","zh":"来赌你手上戴着的那枚戒指吧！","en":"Put the rings on your servant's hand!","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-03-006","lineIndex":6,"speaker":"CHAMBERLAIN","original":"Das ist ein fürstlicher Siegelring, den hat mir Graf Arco geschenkt.","ipa":"/ʃambɜlaɪn das ɪst aɪn fʏɾstlɪçɜ ziɡəlrɪŋ den hat miɾ ɡɾɑf aɾko ɡəʃɛŋkt/","zh":"侍从官：这可是阿尔科伯爵送给我的贵族图章戒。","en":"This is a royal signet ring that Count Arco gave to me.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-03-007","lineIndex":7,"speaker":"WOLFGANG","original":"Setz ihn oder wir hören auf.","ipa":"/vɔlfɡaŋ zɛts in odɜ viɾ hørən aʊf/","zh":"就赌它了，要不我就不玩了。","en":"Put him down or we'll stop.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-03-008","lineIndex":8,"speaker":"CHAMBERLAIN","original":"Was setzt du denn dagegen?","ipa":"/ʃambɜlaɪn vas zɛtst du dɛn daɡeɡən/","zh":"侍从官：那你要赌什么？","en":"What are you doing against it?","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-03-009","lineIndex":9,"speaker":"WOLFGANG","original":"Ich setze...... meine Geige.","ipa":"/vɔlfɡaŋ ɪç zɛtsə maɪnə ɡaɪɡə/","zh":"我赌……我的小提琴吧！","en":"I'm playing... my violin.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-03-010","lineIndex":10,"speaker":"","original":"Ein Geschenk vom Papst.","ipa":"/aɪn ɡəʃɛŋk fɔm pɑpst/","zh":"这是教皇大人送我的礼物。","en":"A gift from the Pope.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-03-011","lineIndex":11,"speaker":"CHAMBERLAIN","original":"Top. Es gilt.","ipa":"/ʃambɜlaɪn tɔp ɛs ɡɪlt/","zh":"侍从官：很好，一言为定。","en":"Great. It applies.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-03-012","lineIndex":12,"speaker":"","original":"Deine Wunderkindgeige gegen meinen Siegelring.","ipa":"/daɪnə vʊndɜkɪndɡaɪɡə ɡeɡən maɪnən ziɡəlrɪŋ/","zh":"你的神童小提琴赌我的图章戒指。","en":"Your prodigy violin against my signet ring.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-03-013","lineIndex":13,"speaker":"","original":"Her mit den Würfeln.","ipa":"/heɾ mɪt den vʏɾfəln/","zh":"把骰子给我。","en":"Bring on the dice.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-03-014","lineIndex":14,"speaker":"","original":"Aaah! Zweimal die 5, zweimal die 6. Macht 22.","ipa":"/ɑɑ evaɪmɑl di fʏnf tsvaɪmɑl di zɛks maxt tsvaɪ ʊnttsvantsɪç/","zh":"哈哈哈！两个5，两个6，一共22点！","en":"Aaah! The 5 twice, the 6 twice. Makes 22.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-03-015","lineIndex":15,"speaker":"WOLFGANG","original":"Keine Sorge, Amade.","ipa":"/vɔlfɡaŋ kaɪnə zɔɾɡə ɑmɑdə/","zh":"别担心，阿玛德。","en":"Don't worry, Amade.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-03-016","lineIndex":16,"speaker":"","original":"Du weißt doch","ipa":"/du vaɪst dɔx/","zh":"你清楚的","en":"You know","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-03-017","lineIndex":17,"speaker":"","original":"Ich hab immer Glück.","ipa":"/ɪç hɑp ɪmɜ ɡlʏk/","zh":"幸运女神总是站在我这边。","en":"I'm always lucky.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-03-018","lineIndex":18,"speaker":"","original":"Denn ich bin ein Schicksalsprinz.","ipa":"/dɛn ɪç bɪn aɪn ʃɪkzalʃpɾɪnts/","zh":"我可是命运的宠儿。","en":"Because I am a prince of fate.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-03-019","lineIndex":19,"speaker":"","original":"Was ich tu', gelingt.","ipa":"/vas ɪç tu ɡəlɪŋt/","zh":"我做的事都能成。","en":"What I do succeeds.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-03-020","lineIndex":20,"speaker":"","original":"Darum frisch gewagt...","ipa":"/dɑrʊm frɪʃ ɡəvɑkt/","zh":"所以我就再冒一次险……","en":"That's why it's fresh...","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-03-021","lineIndex":21,"speaker":"CHAMBERLAIN","original":"Das geht so nicht!","ipa":"/ʃambɜlaɪn das ɡet zo nɪçt/","zh":"侍从官：这不可能！","en":"It doesn't work that way!","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-03-022","lineIndex":22,"speaker":"WOLFGANG","original":"Sechs zerbarst, 24!","ipa":"/vɔlfɡaŋ zɛks tsɛɾbɑɾst fiɾ ʊnttsvantsɪç/","zh":"都是6！一共24！","en":"Six burst, 24!","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-03-023","lineIndex":23,"speaker":"","original":"Her mit dem Ring, Chamberlain!","ipa":"/heɾ mɪt dem rɪŋ ʃambɜlaɪn/","zh":"快把戒指拿过来，侍从官！","en":"Bring on the ring, Chamberlain!","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-03-024","lineIndex":24,"speaker":"GRAF ARCO","original":"Was geht hier vor?","ipa":"/ɡɾɑf aɾko vas ɡet hiɾ fɔɾ/","zh":"阿尔科伯爵：这儿发生了什么？","en":"What's going on here?","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-03-025","lineIndex":25,"speaker":"WOLFGANG","original":"Ihr Kammerherr, verehrte Graf Arco, hat zu ihm Ihren Siegelring verspielt.","ipa":"/vɔlfɡaŋ iɾ kamɜhɛɾ fɛɾeɾtə ɡɾɑf aɾko hat tsu im irən ziɡəlrɪŋ fɛɾʃpilt/","zh":"尊敬的阿尔科伯爵，您的侍从官用您的图章戒指作赌注","en":"Your chamberlain, revered Count Arco, gambled away your signet ring to him.","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-03-026","lineIndex":26,"speaker":"","original":"Jetzt gehört er mir.","ipa":"/itst ɡəhœɾt ɛɾ miɾ/","zh":"现在它已经被输给我了。","en":"He's mine now.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-03-027","lineIndex":27,"speaker":"GRAF ARCO","original":"Oh, nein!","ipa":"/ɡɾɑf aɾko o naɪn/","zh":"阿尔科伯爵：哦，不！","en":"Oh, no!","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-03-028","lineIndex":28,"speaker":"","original":"Als kleiner Musikant und Unterhalter hat er den Mund zu halten.","ipa":"/als klˈaɪnɜ muːziːkˈant ʊnt ˌʊntɜhˈaltɜ hat ɛɾ deːn mˈʊnt tsuː hˈaltən/","zh":"一个小小的艺人与乐师连自己的嘴都管不住。","en":"As a little musician and entertainer he has to keep his mouth shut.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-03-030","lineIndex":29,"speaker":"","original":"um sich zu unter steehende Schloss des Fürsten den Schulden einzufordern.","ipa":"/ʊm zɪç tsuː ˌʊntɜ ʃtˈeːhəndə ʃlˈɔs dɛs fˈyːɾstən deːn ʃˈʊldən ˈaɪntsuːfˌɔɾdɜn/","zh":"还敢来王侯的城堡前索要赌债？","en":"to go to the prince's castle to claim the debt.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-03-032","lineIndex":30,"speaker":"","original":"Weiß wäre nicht dass wären streng verboten sind?","ipa":"/vˈaɪs vˈɛːrə nˈɪçt das vˈɛːrən ʃtɾˈɛŋ fɛɾbˈoːtən zɪnt/","zh":"你难道不知道这是明令禁止的？","en":"Wouldn't you know that would be strictly forbidden?","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-03-034","lineIndex":31,"speaker":"ENSEMBLE","original":"Ganz recht, Herr Graf! Das Spiel mit Würfeln ist verboten.","ipa":"/ɑ̃sɑ̃bəl ɡants rɛçt hɛɾ ɡɾɑf das ʃpil mɪt vʏɾfəln ɪst fɛɾbotən/","zh":"众人：没错，伯爵大人！赌博是被禁止的！","en":"That’s right, Mr. Graf! Playing with dice is prohibited.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-03-035","lineIndex":32,"speaker":"GRAF ARCO","original":"Wenn ich das melde wird er in den Turm geschickt.","ipa":"/vˌɛn ɪç das mˈɛldə vˌɪɾt ɛɾ ɪn deːn tˈʊɐm ɡəʃˈɪkt/","zh":"阿尔科伯爵：要是我通知主教他会被关进塔里去。","en":"If I report this he will be sent to the tower.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-03-037","lineIndex":33,"speaker":"ENSEMBLE","original":"Ganz recht, Herr Graf!","ipa":"/ɑ̃sɑ̃bəl ɡants rɛçt hɛɾ ɡɾɑf/","zh":"众人：没错，伯爵大人！","en":"That’s right, Mr. Graf!","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-03-038","lineIndex":34,"speaker":"GRAF ARCO","original":"Statt die Musik zu verzier'n.","ipa":"/ɡɾɑf aɾko ʃtat di muzik tsu fɛɾtsɪɾhn/","zh":"阿尔科伯爵：莫因天赋而放纵。","en":"Instead of losing the music.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-03-039","lineIndex":35,"speaker":"","original":"Eins sollte er sich merken","ipa":"/aɪns zɔltə ɛɾ zɪç mɛɾkən/","zh":"唯一点他需谨记：","en":"He should remember one thing","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-03-040","lineIndex":36,"speaker":"","original":"Die Wunder sind vorüber jedenfalls für ihn.","ipa":"/diː vˈʊndɜ zɪnt foːrˈyːbɜ jˈeːdənfˌals fyːɾ ˈiːn/","zh":"奇迹已成云烟他已不再耀眼。","en":"The miracles are over at least for him.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-03-042","lineIndex":37,"speaker":"ENSEMBLE","original":"Jetzt heißt's bescheiden sein.","ipa":"/ɑ̃sɑ̃bəl jɛtst haɪsts bəʃaɪdən zaɪn/","zh":"众人：现在他只能安于现状。","en":"Now it's time to be humble.","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-03-043","lineIndex":38,"speaker":"GRAF ARCO","original":"Kein Kind mehr und dich wunderbar.","ipa":"/ɡɾɑf aɾko kaɪn kɪnt meɾ ʊnt dɪç vʊndɜbɑɾ/","zh":"阿尔科伯爵：不再是孩子，也不再是奇迹。","en":"No more children and you are wonderful.","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-03-044","lineIndex":39,"speaker":"","original":"Die Zeit, da er was Bess'res war ist lang schon zu Ende.","ipa":"/di tsaɪt dɑ ɛɾ vas bɛsrəs vɑɾ ɪst laŋ ʃon tsu ɛndə/","zh":"他举世无双的日子早已不再。","en":"The time when he was something better has long since come to an end.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-03-045","lineIndex":40,"speaker":"ENSEMBLE","original":"Schluss mit den Prahlerei!","ipa":"/ɑ̃sɑ̃bəl ʃlʊs mɪt den pɾɑleraɪ/","zh":"众人：别再自吹自擂！","en":"Stop showing off!","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-03-046","lineIndex":41,"speaker":"GRAF ARCO","original":"Jetzt gilt für ihn was immer schon für seinesgleichen gilt.","ipa":"/ɡɾɑf aɾko jɛtst ɡɪlt fyɾ in vas ɪmɜ ʃon fyɾ zaɪnɛsɡlaɪçən ɡɪlt/","zh":"阿尔科伯爵：现在他必须和他那类人一样。","en":"Now what has always applied to his peers applies to him.","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-03-047","lineIndex":42,"speaker":"","original":"Halt den Mund und senk den Kopf und kusch, wenn man dich schilt!","ipa":"/hˈalt deːn mˈʊnt ʊnt zˈɛŋk deːn kˈɔpf ʊnt kˈʊʃ vˌɛn man dɪç ʃˈɪlt/","zh":"闭上嘴，低下头默默承受他人的责骂！","en":"Shut up and lower your head and shush when someone scolds you!","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-03-049","lineIndex":43,"speaker":"LEOPOLD","original":"Wo willst du hin?","ipa":"/leopɔlt vo vɪlst du hɪn/","zh":"利奥波德：你想去哪？","en":"Where do you want to go?","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-03-050","lineIndex":44,"speaker":"WOLFGANG","original":"Graf Arco hat mich beleidigt, Papa!","ipa":"/vɔlfɡaŋ ɡɾɑf aɾko hat mɪç bəlaɪdɪçt pɑpɑ/","zh":"爸爸，阿尔科伯爵他羞辱我！","en":"Count Arco insulted me, dad!","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-03-051","lineIndex":45,"speaker":"","original":"Und sein kammerherr...","ipa":"/ʊnt zaɪn kamɜhɛɾ/","zh":"他的侍从官还—","en":"And his chamberlain...","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-03-052","lineIndex":46,"speaker":"LEOPOLD","original":"Du hast wieder gewürfelt!","ipa":"/leopɔlt du hast vidɜ ɡəvʏɾfəlt/","zh":"利奥波德：你又去赌博了！","en":"You rolled the dice again!","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-03-053","lineIndex":47,"speaker":"WOLFGANG","original":"Aber gewonnen, Papa!","ipa":"/vɔlfɡaŋ ɑbɜ ɡəvɔnən pɑpɑ/","zh":"但我赌赢了呀爸爸！","en":"But you won, Dad!","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-03-054","lineIndex":48,"speaker":"LEOPOLD","original":"Der Fürst erwartet uns in ein paar Stunden!","ipa":"/leopɔlt dɛɾ fyɾst ɛɾvaɾtət ʊns ɪn aɪn pɑɾ ʃtʊndən/","zh":"利奥波德：主教过几个小时就要召见我们了！","en":"The prince is expecting us in a few hours!","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-03-055","lineIndex":49,"speaker":"","original":"Was hat dich nur verleitet?","ipa":"/vas hat dɪç nuɾ fɛɾlaɪtət/","zh":"是什么让你这么上瘾？","en":"What tempted you?","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-03-056","lineIndex":50,"speaker":"","original":"Hast du schon das Konzert für heute Abend geübt und vorbereitet?","ipa":"/hast du ʃon das kɔntsɛɾt fyɾ hɔøtə ɑbənt ɡəypt ʊnt foɾbəraɪtət/","zh":"你今天晚上的音乐会都练习好准备好了吗？","en":"Have you already practiced and prepared for tonight's concert?","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-03-057","lineIndex":51,"speaker":"WOLFGANG","original":"Ja, das Konzert ist fix und fertig komponiert.","ipa":"/vɔlfɡaŋ jɑ das kɔntsɛɾt ɪst fɪks ʊnt fɛɾtɪç kɔmponiɾt/","zh":"嗯，音乐会的曲子我已经谱好了。","en":"Yes, the concert is completely composed.","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-03-058","lineIndex":52,"speaker":"LEOPOLD","original":"Zumindest das.","ipa":"/leopɔlt ɔømɪndəst das/","zh":"利奥波德：这还差不多。","en":"At least that.","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-03-059","lineIndex":53,"speaker":"","original":"Ich will es seh'n...","ipa":"/ɪç vɪl ɛs zen/","zh":"我得看看—","en":"I want to see it...","note":"","sourceLineIndex":59},{"id":"mozart-das-musical-03-060","lineIndex":54,"speaker":"","original":"Wo sind die Noten?","ipa":"/vo zɪnt di notən/","zh":"谱子在哪儿？","en":"Where are the notes?","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-03-061","lineIndex":55,"speaker":"WOLFGANG","original":"In meinem Kopf!","ipa":"/vɔlfɡaŋ ɪn maɪnəm kɔpf/","zh":"都在我的脑子里呢！","en":"In my head!","note":"","sourceLineIndex":61},{"id":"mozart-das-musical-03-062","lineIndex":56,"speaker":"","original":"Ich hab' sie bloss noch nicht notiert.","ipa":"/ɪç hɑp zi blɔs nɔx nɪçt notiɾt/","zh":"我只是还没写出来而已。","en":"I just haven't written them down yet.","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-03-063","lineIndex":57,"speaker":"LEOPOLD","original":"Du bringst mich um!","ipa":"/leopɔlt du bɾɪŋst mɪç ʊm/","zh":"利奥波德：你简直要搞死我！","en":"You're killing me!","note":"","sourceLineIndex":63},{"id":"mozart-das-musical-03-064","lineIndex":58,"speaker":"","original":"Warum tust du nicht deine Pflicht?","ipa":"/vɑrʊm tʊst du nɪçt daɪnə pflɪçt/","zh":"为什么你就是不好好干活！","en":"Why don't you do your duty?","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-03-065","lineIndex":59,"speaker":"","original":"Eins darfst du nicht vergessen:","ipa":"/aɪns daɾfst du nɪçt fɛɾɡɛsən/","zh":"有一点你可千万要记得：","en":"There's one thing you can't forget:","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-03-066","lineIndex":60,"speaker":"","original":"Die Wunder sind vorüber jedenfalls für uns.","ipa":"/diː vˈʊndɜ zɪnt foːrˈyːbɜ jˈeːdənfˌals fyːɾ ˈʊns/","zh":"奇迹已成云烟我们不再耀眼。","en":"The miracles are over at least for us.","note":"","sourceLineIndex":66},{"id":"mozart-das-musical-03-068","lineIndex":61,"speaker":"WOLFGANG","original":"Ich brauch' kein Wunder mehr.","ipa":"/vɔlfɡaŋ ɪç bɾaʊx kaɪn vʊndɜ meɾ/","zh":"我不再需要什么奇迹了。","en":"I don't need a miracle anymore.","note":"","sourceLineIndex":68},{"id":"mozart-das-musical-03-069","lineIndex":62,"speaker":"LEOPOLD","original":"Die Zeit, da uns die Welt umwarb ist leider zu Ende.","ipa":"/diː tsˈaɪt dɑː ʊns diː vˈɛlt ˈʊmvˌaɾp ɪst lˈaɪdɜ tsuː ˈɛndə/","zh":"利奥波德：世界追捧我们的日子已经走到了尽头。","en":"The time when the world courted us is unfortunately over.","note":"","sourceLineIndex":69},{"id":"mozart-das-musical-03-071","lineIndex":63,"speaker":"WOLFGANG","original":"Nimm das nicht so schwer.","ipa":"/vɔlfɡaŋ nɪm das nɪçt zo ʃveɾ/","zh":"别那么悲观嘛。","en":"Don't take it so seriously.","note":"","sourceLineIndex":71},{"id":"mozart-das-musical-03-072","lineIndex":64,"speaker":"LEOPOLD","original":"Jetzt gilt für dich was immer schon für unsergleichen gilt.","ipa":"/leopɔlt jɛtst ɡɪlt fyɾ dɪç vas ɪmɜ ʃon fyɾ ʊnzɛɾɡlaɪçən ɡɪlt/","zh":"利奥波德：现在你要和我们这类人一样","en":"Now what always applies to our kind applies to you.","note":"","sourceLineIndex":72},{"id":"mozart-das-musical-03-073","lineIndex":65,"speaker":"","original":"Halt den Mund und senk den Kopf und tu, was man befiehlt.","ipa":"/hˈalt deːn mˈʊnt ʊnt zˈɛŋk deːn kˈɔpf ʊnt tˈuː vˈas man bəfˈiːlt/","zh":"闭上嘴，低下头听命行事。","en":"Shut up and lower your head and do what you are told.","note":"","sourceLineIndex":73},{"id":"mozart-das-musical-03-075","lineIndex":66,"speaker":"","original":"Sich empör'n...","ipa":"/zɪç ɛmpøɾn/","zh":"无论愤怒","en":"Be outraged...","note":"","sourceLineIndex":75},{"id":"mozart-das-musical-03-076","lineIndex":67,"speaker":"WOLFGANG","original":"Das ist Pflicht!","ipa":"/vɔlfɡaŋ das ɪst pflɪçt/","zh":"这才是职责！","en":"That's mandatory!","note":"","sourceLineIndex":76},{"id":"mozart-das-musical-03-077","lineIndex":68,"speaker":"LEOPOLD","original":"oder wehr'n","ipa":"/leopɔlt odɜ veɾn/","zh":"利奥波德：或是抗拒","en":"or defend yourself","note":"","sourceLineIndex":77},{"id":"mozart-das-musical-03-078","lineIndex":69,"speaker":"WOLFGANG","original":"Warum nicht?!","ipa":"/vɔlfɡaŋ vɑrʊm nɪçt/","zh":"为什么不行？！","en":"Why not?!","note":"","sourceLineIndex":78},{"id":"mozart-das-musical-03-079","lineIndex":70,"speaker":"LEOPOLD","original":"ist vergebens.","ipa":"/leopɔlt ɪst fɛɾɡebəns/","zh":"利奥波德：都无济于事。","en":"it's in vain.","note":"","sourceLineIndex":79},{"id":"mozart-das-musical-03-080","lineIndex":71,"speaker":"","original":"Und jetzt beginn augenblicklich zu schreiben.","ipa":"/ʊnt jɛtst bəɡɪn aʊɡənblɪklɪç tsu ʃraɪbən/","zh":"现在赶紧去写你的谱子。","en":"And now start writing right now.","note":"","sourceLineIndex":80}],"sourceOrder":3,"displayOrder":3},{"order":4,"id":"04-ich-bin-ich-bin-musik","title":"Ich bin, ich bin Musik","titleZh":"我即音乐","lines":[{"id":"mozart-das-musical-04-001","lineIndex":1,"speaker":"","original":"Was er auch sagt.","ipa":"/vas ɛɾ aʊx zɑkt/","zh":"不管他说什么","en":"Whatever he says.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-04-002","lineIndex":2,"speaker":"","original":"Du weißt was Du willst und kannst!","ipa":"/du vaɪst vas du vɪlst ʊnt kanst/","zh":"你只要知道自己想要什么，能做什么！","en":"You know what you want and can do!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-04-003","lineIndex":3,"speaker":"","original":"Durch Dich werde ich frei sein.","ipa":"/dʊɐç dɪç vɛɾdə ɪç fraɪ zaɪn/","zh":"你可以让我得到自由","en":"Through you I will be free.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-04-004","lineIndex":4,"speaker":"","original":"Wir tun nur, was uns gefällt!","ipa":"/viɾ tun nuɾ vas ʊns ɡəfɛlt/","zh":"我们尽管随心所欲去做！","en":"We only do what we like!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-04-005","lineIndex":5,"speaker":"","original":"Du und ich haben vor nichts und niemand Angst.","ipa":"/du ʊnt ɪç hɑbən fɔɾ nɪçts ʊnt nimant aŋst/","zh":"你和我，无所畏惧，无需畏惧","en":"You and I are not afraid of anything or anyone.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-04-006","lineIndex":6,"speaker":"","original":"Uns kann die Pflicht einerlei sein.","ipa":"/ʊns kan di pflɪçt aɪnɜlaɪ zaɪn/","zh":"责任对我们来说是无用之物","en":"Our duty can be the same.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-04-007","lineIndex":7,"speaker":"","original":"Wir verzaubern die Welt!","ipa":"/viɾ fɛɾtsaʊbɜn di vɛlt/","zh":"我们让整个世界都为我们着迷！","en":"We enchant the world!","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-04-008","lineIndex":8,"speaker":"","original":"Ich überwinde jede Macht selbst wenn es schwer wird: ich gewinn!","ipa":"/ɪç ˌyːbɜvˈɪndə jˈeːdə mˈaxt zˈɛlpst vˌɛn ɛs ʃvˈeːɾ vˌɪɾt ɪç ɡəvˈɪn/","zh":"我战胜了所有强大的力量即使步履维艰，我赢得了胜利！","en":"I overcome every power even when it gets difficult: I win!","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-04-010","lineIndex":9,"speaker":"","original":"Ich weiß wohin.","ipa":"/ɪç vaɪs vohin/","zh":"我知道我要去哪里","en":"I know where.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-04-011","lineIndex":10,"speaker":"","original":"Die Wunder kommen wieder jedenfalls für mich.","ipa":"/diː vˈʊndɜ kˈɔmən vˈiːdɜ jˈeːdənfˌals fyːɾ mɪç/","zh":"奇迹会再次出现至少会为我降临","en":"The miracles are coming again at least for me.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-04-013","lineIndex":11,"speaker":"","original":"Ich fang erst richtig an.","ipa":"/ɪç faŋ eɾst rɪçtɪç an/","zh":"我的故事才刚刚开始","en":"I'm just getting started.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-04-014","lineIndex":12,"speaker":"","original":"Weil ich es einfach in mir hab","ipa":"/vaɪl ɪç ɛs aɪnfax ɪn miɾ hɑp/","zh":"我有这样的能力","en":"Because I just have it in me","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-04-015","lineIndex":13,"speaker":"","original":"Die Kraft, die mir der Himmel gab","ipa":"/di kɾaft di miɾ dɛɾ hɪməl ɡɑp/","zh":"这是天赐的礼物","en":"The strength that heaven gave me","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-04-016","lineIndex":14,"speaker":"","original":"Und ohne sie wär mein Leben ein Irrtum.","ipa":"/ʊnt onə zi vɛɾ maɪn lebən aɪn ɪɾtum/","zh":"没有它，我的人生会步入歧途","en":"And without it my life would be a mistake.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-04-017","lineIndex":15,"speaker":"","original":"Ich bin kein Dichter. Poetisch reden kann ich nicht.","ipa":"/ɪç bɪn kaɪn dɪçtɜ poetɪʃ redən kan ɪç nɪçt/","zh":"我不是诗人，我说不出优美的话语","en":"I'm not a poet. I can't speak poetically.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-04-018","lineIndex":16,"speaker":"","original":"Ich sag einfach wie mir zu mut ist.","ipa":"/ɪç zɑk aɪnfax vi miɾ tsu mut ɪst/","zh":"我只能直白的表达我的感受","en":"I'll just say what I feel like.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-04-019","lineIndex":17,"speaker":"","original":"Was mich bewegt, das lass ich raus.","ipa":"/vas mɪç bəvekt das las ɪç raʊs/","zh":"只要可以感动我自己，我就会直言不讳","en":"What moves me, I let it out.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-04-020","lineIndex":18,"speaker":"","original":"Ich bin auch kein Maler der mit Farben Schatten wirft und Licht bis ein Bild wirklich gut ist.","ipa":"/ɪç bɪn ˌaʊx kˈaɪn mˈɑːlɜ dɛɾ mɪt fˈaɾbən ʃˈatən vˈɪɾft ʊnt lˈɪçt bɪs aɪn bˈɪlt vˈɪɾklɪç ɡˈuːt ɪst/","zh":"我也不是画家不会用色彩描绘光影创作出惊世的作品","en":"I'm not a painter either who uses colors to cast shadows and light until a picture is really good.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-04-023","lineIndex":19,"speaker":"","original":"Ich mal nur meine Hoffnung mit Träumen aus.","ipa":"/ɪç mɑl nuɾ maɪnə hɔfnʊŋ mɪt tɾɔømən aʊs/","zh":"我只能用我的梦想去粉饰希望","en":"I'm just expressing my hope with dreams.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-04-024","lineIndex":20,"speaker":"","original":"Ich bin kein Schauspieler.","ipa":"/ɪç bɪn kaɪn ʃaʊʃpilɜ/","zh":"我不是演员","en":"I'm not an actor.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-04-025","lineIndex":21,"speaker":"","original":"Ich kann mich nicht verstellen.","ipa":"/ɪç kan mɪç nɪçt fɛɾʃtɛlən/","zh":"我不懂得伪装","en":"I can't pretend.","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-04-026","lineIndex":22,"speaker":"","original":"Mir sieht man immer gleich an, wie es aussieht in mir drin.","ipa":"/miɾ zit man ɪmɜ ɡlaɪç an vi ɛs aʊszit ɪn miɾ dɾin/","zh":"我看起来永远是那样，表里如一的模样","en":"You can always see what it looks like inside me.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-04-027","lineIndex":23,"speaker":"","original":"Und so kann ich nur hoffen dass mich jeder einfach so nimmt wie ich bin.","ipa":"/ʊnt zoː kˌan ɪç nˈuːɾ hˈɔfən das mɪç jˈeːdɜ ˈaɪnfˌax zoː nˈɪmt viː ɪç bɪn/","zh":"所以我只能希望每个人都不会对我抱有偏见","en":"And so I can only hope that everyone just accepts me as I am.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-04-029","lineIndex":24,"speaker":"","original":"Jeder Ton ein Wort und jeder Klang ein Satz mit dem ich sage, was ich fühle.","ipa":"/jˈeːdɜ tˈoːn aɪn vˈɔɾt ʊnt jˈeːdɜ klˈaŋ aɪn zˈats mɪt deːm ɪç zˈɑːɡə vˈas ɪç fˈyːlə/","zh":"每一个音符代表一个单词，每一段旋律都是一个句子我用它们来表达我的感受","en":"Every sound is a word and every sound is a sentence with which I say what I feel.","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-04-031","lineIndex":25,"speaker":"","original":"Ich bin Takt und Pause, Dissonanz und Harmonie ich bin Forte und Piano, Tanz und Fantasie.","ipa":"/ɪç bɪn tˈakt ʊnt pˈaʊzə dˈɪsoːnˌants ʊnt hˌaɾmoːnˈiː ɪç bɪn fˈɔɾtə ʊnt piːˈɑːnoː tˈants ʊnt fˌantazˈiː/","zh":"我是节拍也是间歇，是不和谐与和谐我是起伏也是舒缓，是舞蹈也是幻想","en":"I am beat and pause, dissonance and harmony I am forte and piano, dance and fantasy.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-04-033","lineIndex":26,"speaker":"","original":"Ich bin, ich bin Musik.","ipa":"/ɪç bɪn ɪç bɪn muzik/","zh":"我是，我就是音乐","en":"I am, I am music.","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-04-034","lineIndex":27,"speaker":"","original":"Ich bin Dur und ich bin Moll","ipa":"/ɪç bɪn duɾ ʊnt ɪç bɪn mɔl/","zh":"我是主人公，也是陪衬者","en":"I am major and I am minor","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-04-035","lineIndex":28,"speaker":"","original":"Jeder Ton ein Wort und jeder Klang ein Satz mit dem ich sage, was ich fühle.","ipa":"/jˈeːdɜ tˈoːn aɪn vˈɔɾt ʊnt jˈeːdɜ klˈaŋ aɪn zˈats mɪt deːm ɪç zˈɑːɡə vˈas ɪç fˈyːlə/","zh":"每一个音符代表一个单词，每一段旋律都是一个句子我用它们来表达我的感受","en":"Every sound is a word and every sound is a sentence with which I say what I feel.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-04-037","lineIndex":29,"speaker":"","original":"Ich bin Takt und Pause, Dissonanz und Harmonie ich bin Forte und Piano, Tanz und Fantasie.","ipa":"/ɪç bɪn tˈakt ʊnt pˈaʊzə dˈɪsoːnˌants ʊnt hˌaɾmoːnˈiː ɪç bɪn fˈɔɾtə ʊnt piːˈɑːnoː tˈants ʊnt fˌantazˈiː/","zh":"我是节拍也是间歇，是不和谐与和谐我是起伏也是舒缓，是舞蹈也是幻想","en":"I am beat and pause, dissonance and harmony I am forte and piano, dance and fantasy.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-04-039","lineIndex":30,"speaker":"","original":"Nacht und Licht und Wolf und Schaf und Blitz und Sinfonie","ipa":"/naxt ʊnt lɪçt ʊnt vɔlf ʊnt ʃɑf ʊnt blɪts ʊnt zɪnfoni/","zh":"黑夜与光明，狼与羊，闪电与交响乐","en":"night and light and wolf and sheep and lightning and symphony","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-04-040","lineIndex":31,"speaker":"","original":"klug und dumm und geil und braf","ipa":"/kluk ʊnt dʊm ʊnt ɡaɪl ʊnt bɾɑf/","zh":"聪明，愚蠢，玩世不恭，品行端正","en":"smart and stupid and horny and braf","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-04-041","lineIndex":32,"speaker":"","original":"ein Mensch und ein Genie.","ipa":"/aɪn mɛnʃ ʊnt aɪn ɡəni/","zh":"是一个人，也是一个天才","en":"a human being and a genius.","note":"","sourceLineIndex":41}],"sourceOrder":4,"displayOrder":4},{"order":5,"id":"05-wo-bleibt-mozart","title":"Wo bleibt Mozart?","titleZh":"莫扎特在哪？","lines":[{"id":"mozart-das-musical-05-001","lineIndex":1,"speaker":"","original":"Die Bediensteten","ipa":"/di bədinstətən/","zh":"仆役","en":"The servants","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-05-002","lineIndex":2,"speaker":"","original":"Blitz-blank blinkt das Besteck","ipa":"/blɪtsblaŋk blɪŋkt das bəʃtɛk/","zh":"闪闪发亮的餐具","en":"The cutlery flashes brilliantly","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-05-003","lineIndex":3,"speaker":"","original":"Silberleuchter, Meißner Gedeck","ipa":"/zɪlbɜlɔøçtɜ maɪsnɜ ɡədɛk/","zh":"银烛台，名贵的瓷器","en":"Silver candlesticks, Meissen place settings","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-05-004","lineIndex":4,"speaker":"","original":"Manche Leute lernen niemals Pünktlichkeit (Gold, Samt, Spiegelparkett)","ipa":"/mançə lɔøtə lɛɾnən nimɑls pʏŋktlɪçkaɪt ɡɔlt zamt ʃpiɡəlpaɾkɛt/","zh":"有些人从来不懂守时（金饰，天鹅绒，锃亮的地板）","en":"Some people never learn punctuality (gold, velvet, mirror parquet)","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-05-005","lineIndex":5,"speaker":"","original":"Und sie bilden sich viel zu viel ein (ES ist alles da)","ipa":"/ʊnt zi bɪldən zɪç fil tsu fil aɪn ɛsɪst aləs dɑ/","zh":"自高自大，自吹自擂（一切均已备齐）","en":"And they imagine way too much (IT'S all there)","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-05-007","lineIndex":6,"speaker":"Graf Arco","original":"Wo bleibt Mozart?","ipa":"/vo blaɪpt motsaɾt/","zh":"莫扎特在哪儿？","en":"Where is Mozart?","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-05-008","lineIndex":7,"speaker":"","original":"Gleich kommt der Fürst, um sich selbst zu überzeugen (Sie fahren in die Welt, sie scheffeln Geld)","ipa":"/ɡlaɪç kɔmt dɛɾ fyɾst ʊm zɪç zɛlpst tsu ybɜtsɔøɡən zi fɑrən ɪn di vɛlt zi ʃɛfəln ɡɛlt/","zh":"主教大人马上就来亲自巡视（就会满世界跑，四处索取钱财）","en":"The prince is about to come to see for himself (they go out into the world, they make money)","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-05-009","lineIndex":8,"speaker":"","original":"dass alles vorbereitet ist für den Abend (und behaupten, ihr Kind würd ein Wunderkind sein)","ipa":"/das aləs foɾbəraɪtət ɪst fyɾ den ɑbənt ʊnt bəhaʊptən iɾ kɪnt vʏɾt aɪn vʊndɜkɪnt zaɪn/","zh":"查看今晚宴会的一切是否都已准备妥当（号称自己的儿子是个神童）","en":"that everything is prepared for the evening (and claim that their child will be a child prodigy)","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-05-010","lineIndex":9,"speaker":"","original":"Die Weine, Die Gläser, die Kerzen, die Musik (Manche Leute lernen niemals Höflichkeit)","ipa":"/di vaɪnə di ɡlɛzɜ di kɛɾtsən di muzik mançə lɔøtə lɛɾnən nimɑls høflɪçkaɪt/","zh":"美酒，酒杯，蜡烛，音乐（有些人从来不懂规矩）","en":"The wines, the glasses, the candles, the music (some people never learn politeness)","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-05-011","lineIndex":10,"speaker":"","original":"Es ist alles da, nur nicht Mozart (Wird man ihnen verzeihn)","ipa":"/ɛsɪst aləs dɑ nuɾ nɪçt motsaɾt vɪɾt man inən fɛɾtsaɪhn/","zh":"一切都已备齐，只有莫扎特没到（谁会原谅这种人）","en":"Everything is there except Mozart (Will they be forgiven)","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-05-012","lineIndex":11,"speaker":"","original":"Wo bleibt Mozart?","ipa":"/vo blaɪpt motsaɾt/","zh":"莫扎特在哪儿？","en":"Where is Mozart?","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-05-014","lineIndex":12,"speaker":"Fürsterzbischof Colloredo","original":"Macht weiter mit der Arbeit!","ipa":"/maxt vaɪtɜ mɪt dɛɾ aɾbaɪt/","zh":"继续干活儿！","en":"Get on with the work!","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-05-015","lineIndex":13,"speaker":"","original":"Steht nicht faul herum!","ipa":"/ʃtet nɪçt faʊl hɛrʊm/","zh":"别懒洋洋地站着！","en":"Don't just stand around!","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-05-016","lineIndex":14,"speaker":"","original":"Mein Palast ist kein Elysium","ipa":"/maɪn pɑlast ɪst kaɪn elyziʊm/","zh":"我的宫殿不是游乐园","en":"My palace is no Elysium","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-05-017","lineIndex":15,"speaker":"","original":"Ich fordre Demut, Fleiss und Disziplin","ipa":"/ɪç fɔɾdɾə demut flaɪs ʊnt dɪstsɪplin/","zh":"我要求谦恭顺从，认真勤恳，循规蹈矩","en":"I demand humility, hard work and discipline","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-05-018","lineIndex":16,"speaker":"","original":"Der dem das nicht passt","ipa":"/dɛɾ dem das nɪçt past/","zh":"做不到的人","en":"Anyone who doesn't like it","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-05-019","lineIndex":17,"speaker":"","original":"soll ins Armenhaus ziehn","ipa":"/zɔl ɪns aɾmənhaʊs tsin/","zh":"都给我赶到济贫院去","en":"should move into the poorhouse","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-05-020","lineIndex":18,"speaker":"","original":"Ist alles vorbereitet?","ipa":"/ɪst aləs foɾbəraɪtət/","zh":"一切都备齐了吗？","en":"Is everything prepared?","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-05-021","lineIndex":19,"speaker":"","original":"Ist der Wein dekantiert?","ipa":"/ɪst dɛɾ vaɪn dekantiɾt/","zh":"酒都斟好了吗？","en":"Is the wine decanted?","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-05-022","lineIndex":20,"speaker":"","original":"Sind alle Köche und die Diener instruiert?","ipa":"/zɪnt alə kœçə ʊnt di dinɜ ɪnstɾuiɾt/","zh":"厨子和仆人都吩咐好了吗？","en":"Are all the cooks and servants instructed?","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-05-023","lineIndex":21,"speaker":"","original":"Haben die Musikanten etwas neues einstudiert?","ipa":"/hɑbən di muzikantən ɛtvɑs nɔøəs aɪnʃtudiɾt/","zh":"乐师们有没有新练的曲子？","en":"Have the musicians rehearsed something new?","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-05-024","lineIndex":22,"speaker":"","original":"Wo ist Mozart?","ipa":"/vo ɪst motsaɾt/","zh":"莫扎特在哪？","en":"Where is Mozart?","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-05-026","lineIndex":23,"speaker":"Leopold","original":"Exzellenz, wir sind da!","ipa":"/ɛkstsəlɛnts viɾ zɪnt dɑ/","zh":"主教大人，我们在这！","en":"Excellency, we are here!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-05-028","lineIndex":24,"speaker":"Wolfgang","original":"Ich habe etwas komponiert für Sie","ipa":"/ɪç hɑbə ɛtvɑs kɔmponiɾt fyɾ zi/","zh":"我为您写了些新曲子","en":"I have composed something for you","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-05-029","lineIndex":25,"speaker":"","original":"wie man es bestenfalls im Himmel hört","ipa":"/vi man ɛs bɛstənfals ɪm hɪməl hœɾt/","zh":"这是天堂里才能听到的音乐","en":"the likes of which can only be heard in heaven","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-05-030","lineIndex":26,"speaker":"","original":"Ein Fürst wie Sie","ipa":"/aɪn fyɾst vi zi/","zh":"像您这样的主教","en":"A prince like you","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-05-031","lineIndex":27,"speaker":"","original":"bekam so etwas noch nie","ipa":"/bəkɑm zo ɛtvɑs nɔx ni/","zh":"以前肯定都闻所未闻","en":"has never received anything like it","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-05-032","lineIndex":28,"speaker":"","original":"So eine herrliche Musik wäre mindestens einen Kaiser wert!","ipa":"/zoː ˌaɪnə hˈɛɾlɪçə muːzˈiːk vˈɛːrə mˈɪndəstəns ˌaɪnən kˈaɪzɜ vˈɛɾt/","zh":"这样动听的仙乐至少得是皇帝才能配得上","en":"Such wonderful music would be worth at least an emperor!","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-05-035","lineIndex":29,"speaker":"Fürsterzbischof Colloredo","original":"Halt er gefälligst seinen Mund bis man ihn fragt.","ipa":"/halt ɛɾ ɡəfɛlɪçst zaɪnən mʊnt bɪs man in frɑkt/","zh":"还没轮到他说话，让他把嘴闭上","en":"Please keep your mouth shut until you ask him.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-05-037","lineIndex":30,"speaker":"Leopold","original":"Er meint es nicht so","ipa":"/ɛɾ maɪnt ɛs nɪçt zo/","zh":"他并不是这个意思","en":"He doesn't mean it like that","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-05-039","lineIndex":31,"speaker":"Wolfgang","original":"Doch, doch, so mein' ich's!","ipa":"/dɔx dɔx zo maɪn ɪçs/","zh":"不，不，我就是这个意思","en":"Yes, yes, that's what I mean!","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-05-041","lineIndex":32,"speaker":"Fürsterzbischof Colloredo","original":"Ihr Sohn, Herr Mozart, vergreift sich im Ton (Fex, Narr, Dalk, dummer Bub!)","ipa":"/iɾ zon hɛɾ motsaɾt fɛɾɡɾaɪft zɪç ɪm ton fɛks naɾ dalk dʊmɜ bup/","zh":"你的儿子，莫扎特先生，真是满嘴胡言（傻瓜，疯子，笨蛋，智障）","en":"Your son, Mr. Mozart, uses a wrong tone (Fex, fool, Dalk, stupid boy!)","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-05-042","lineIndex":33,"speaker":"","original":"Lehr'n Sie ihm Anstand und Subordination! (Schafskopf, eitler Tropf, ungezogner Lümmel!)","ipa":"/leɾn zi im anʃtant ʊnt zubɔɾdinatsjon ʃafskɔpf aɪtlɜ tɾɔpf ʊnɡətsɔɡnɜ lʏməl/","zh":"请教会他什么叫规矩和服从（笨猪，脑子进水的蠢货，没教养的臭流氓）","en":"Teach him decency and subordination! (Sheep's head, vain idiot, naughty lout!)","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-05-043","lineIndex":34,"speaker":"","original":"Ich bin ein Fürst, und wenn ich die Geduld verlier' dann ist sein Talent nur ein Fetzen Papier!","ipa":"/ɪç bɪn aɪn fˈyːɾst ʊnt vˌɛn ɪç diː ɡədˈʊlt fɛɾlˈiːɾ dan ɪst zaɪn talˈɛnt nˈuːɾ aɪn fˈɛtsən papˈiːɾ/","zh":"我是掌管他的主教，如果我失去耐心（骂人话重复上述）那他的才华就不过是一张废纸","en":"I am a prince, and if I lose patience then his talent is just a scrap of paper!","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-05-046","lineIndex":35,"speaker":"Wolfgang","original":"Das vergess' ich Ihnen nie!","ipa":"/das fɛɾɡɛs ɪç inən ni/","zh":"您真让我永生难忘！","en":"I'll never forget that!","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-05-048","lineIndex":36,"speaker":"Leopold","original":"Sei still, mein Junge!","ipa":"/zaɪ ʃtɪl maɪn jʊŋə/","zh":"孩子，冷静点！","en":"Be quiet, my boy!","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-05-050","lineIndex":37,"speaker":"Wolfgang","original":"Was fällt Ihnen ein!","ipa":"/vas fɛlt inən aɪn/","zh":"您凭什么指手画脚！","en":"What do you think of!","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-05-051","lineIndex":38,"speaker":"","original":"Auf meine Art bin ich ein Fürst so gut wie Sie","ipa":"/aʊf maɪnə ɑɾt bɪn ɪç aɪn fyɾst zo ɡut vi zi/","zh":"在我看来我和您一样高贵","en":"In my own way, I'm as good a prince as you are","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-05-052","lineIndex":39,"speaker":"","original":"und mir zu schade Ihr Lakai zu sein","ipa":"/ʊnt miɾ tsu ʃɑdə iɾ lɑkaɪ tsu zaɪn/","zh":"我才不愿听您摆布","en":"and it's too bad for me to be your lackey","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-05-054","lineIndex":40,"speaker":"Fürsterzbischof Colloredo","original":"Dann geht er fort!","ipa":"/dan ɡet ɛɾ fɔɾt/","zh":"那他可以滚了！","en":"Then he goes away!","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-05-055","lineIndex":41,"speaker":"","original":"Ich brauch' ihn nicht","ipa":"/ɪç bɾaʊx in nɪçt/","zh":"我不需要他","en":"I don't need him","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-05-056","lineIndex":42,"speaker":"","original":"Musikanten gibt's wie Sand am Meer","ipa":"/muzikantən ɡɪpts vi zant am meɾ/","zh":"乐师就像海边的沙子一样数不胜数","en":"Musicians are a dime a dozen","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-05-057","lineIndex":43,"speaker":"","original":"Ich stelle ihn nicht wieder ein und käme er auf den Knien her.","ipa":"/ɪç ʃtˈɛlə iːn nˈɪçt vˈiːdɜ aɪn ʊnt kˈɛːmə ɛɾ aʊf deːn knˈiːn hˈeːɾ/","zh":"我不会再召见他哪怕他跪着求我也不行","en":"I won't hire him again and he came over on his knees.","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-05-060","lineIndex":44,"speaker":"Leopold","original":"Wolfgang! Entschuldige dich. Sofort!","ipa":"/vɔlfɡaŋ ɛntʃʊldɪɡə dɪç zofɔɾt/","zh":"沃尔夫冈！道歉！马上！","en":"Wolfgang! Apologize. Immediately!","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-05-062","lineIndex":45,"speaker":"Wolfgang","original":"Nein! Der muss sich entschuldigen!","ipa":"/naɪn dɛɾ mʊs zɪç ɛntʃʊldɪɡən/","zh":"不！他才要道歉！","en":"No! He has to apologize!","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-05-064","lineIndex":46,"speaker":"Fürsterzbischof Colloredo","original":"Graf Arco, sorgen Sie für einen andern Notenkleckser!","ipa":"/ɡɾɑf aɾko zɔɾɡən zi fyɾ aɪnən andɜn notənklɛkzɜ/","zh":"阿尔科伯爵，去找别的人来写曲子！","en":"Count Arco, provide another piece of music!","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-05-065","lineIndex":47,"speaker":"","original":"Und nun, genug davon.","ipa":"/ʊnt nun ɡənuk dɑfɔn/","zh":"真是够了！","en":"And now, enough of that.","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-05-067","lineIndex":48,"speaker":"Leopold","original":"Dein Jähzorn bringt mich noch ins Grab!","ipa":"/daɪn jɛhtsɔɾn bɾɪŋt mɪç nɔx ɪns ɡɾɑp/","zh":"你的急脾气把我也葬送了！","en":"Your anger will take me to the grave!","note":"","sourceLineIndex":67},{"id":"mozart-das-musical-05-069","lineIndex":49,"speaker":"Fürsterzbischof Colloredo","original":"Ich will den Namen Mozart nicht mehr hören.","ipa":"/ɪç vɪl den nɑmən motsaɾt nɪçt meɾ hœɾn/","zh":"我不想再听到莫扎特这个名字","en":"I don't want to hear the name Mozart anymore.","note":"","sourceLineIndex":69},{"id":"mozart-das-musical-05-070","lineIndex":50,"speaker":"","original":"Nicht den vom Vater und schon gar nicht den vom Sohn!","ipa":"/nˈɪçt deːn fɔm fˈɑːtɜ ʊnt ʃˌoːn ɡˌɑːɾnˈɪçt deːn fɔm zˈoːn/","zh":"不想听到那位父亲的更不想听到那位儿子的！","en":"Not my father's and certainly not from his son!","note":"","sourceLineIndex":70},{"id":"mozart-das-musical-05-072","lineIndex":51,"speaker":"","original":"(Der Krug geht an den Brunnen, bis er bricht.)","ipa":"/dɛɾ kɾuk ɡet an den bɾʊnən bɪs ɛɾ bɾɪçt/","zh":"（是可忍，孰不可忍）","en":"(The jug goes to the well until it breaks.)","note":"","sourceLineIndex":72},{"id":"mozart-das-musical-05-073","lineIndex":52,"speaker":"","original":"(Mit Mozart ist es aus!)","ipa":"/mɪt motsaɾt ɪst ɛs aʊs/","zh":"（莫扎特家完蛋啦！）","en":"(It's over with Mozart!)","note":"","sourceLineIndex":73},{"id":"mozart-das-musical-05-075","lineIndex":53,"speaker":"Fürsterzbischof Colloredo","original":"Graf Arco, heben Sie das auf.","ipa":"/ɡɾɑf aɾko hebən zi das aʊf/","zh":"阿尔科伯爵，请把谱子捡起来","en":"Count Arco, pick that up.","note":"","sourceLineIndex":75},{"id":"mozart-das-musical-05-076","lineIndex":54,"speaker":"","original":"Grossartig","ipa":"/ɡɾɔsaɾtɪç/","zh":"真是精妙绝伦！","en":"Great","note":"","sourceLineIndex":76},{"id":"mozart-das-musical-05-078","lineIndex":55,"speaker":"Graf Arco","original":"Exzellenz?","ipa":"/ɛkstsəlɛnts/","zh":"大人？","en":"Excellence?","note":"","sourceLineIndex":78},{"id":"mozart-das-musical-05-080","lineIndex":56,"speaker":"Fürsterzbischof Colloredo","original":"Die Musiker sollen es einstudieren.","ipa":"/di muzikɜ zɔlən ɛs aɪnʃtudirən/","zh":"让乐师们练习演奏这些曲子","en":"The musicians should rehearse it.","note":"","sourceLineIndex":80}],"sourceOrder":5,"displayOrder":5},{"order":6,"id":"06-niemand-liebt-dich-so-wie-ich","title":"Niemand liebt dich so wie ich","titleZh":"没人比我更爱你","lines":[{"id":"mozart-das-musical-06-001","lineIndex":1,"speaker":"WOLFGANG","original":"Warten Sie Papa!","ipa":"/vɔlfɡaŋ vaɾtən zi pɑpɑ/","zh":"等等，爸爸！","en":"Wait, Dad!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-06-002","lineIndex":2,"speaker":"","original":"Der Mufti entlässt Sie nicht.","ipa":"/dɛɾ mʊfti ɛntl ɑ ɛsɛste zi nɪçt/","zh":"主教不会解雇您的","en":"The mufti won't release you.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-06-003","lineIndex":3,"speaker":"","original":"Das hat er nur so in der Hitze gesagt der Schwanz.","ipa":"/das hat ɛɾ nuɾ zo ɪn dɛɾ hɪtsə ɡəzɑkt dɛɾ ʃvants/","zh":"他只是因为在气头上才这么说的，那个混蛋","en":"He just said that in the heat of the cock.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-06-004","lineIndex":4,"speaker":"","original":"Jetzt warten Sie doch allerbester Herr Vater.","ipa":"/jˌɛtst vˈaɾtən ziː dɔx ˈalɜbəstɜ hˈɛɾ fˈɑːtɜ/","zh":"等等我嘛天底下最棒的父亲大人","en":"Now just wait best Mr. Father.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-06-006","lineIndex":5,"speaker":"","original":"Mir ist federleicht um's Herz weil ich die Schikane los bin.","ipa":"/miːɾ ɪst fˈeːdɜlˌaɪçt ˈuːms hˈɛɾts vˌaɪl ɪç diː ʃiːkˈɑːnə lˈoːs bɪn/","zh":"现在我的心就如同羽毛一般轻盈欢快因为再也没有谁能够刁难我了","en":"My heart feels as light as a feather because I'm free of the harassment.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-06-008","lineIndex":6,"speaker":"","original":"Jetzt reise ich in die grossen Städte ganz auf mich allein gestellt...","ipa":"/jˌɛtst rˈaɪzə ɪç ɪn diː ɡɾˈɔsən ʃtˈɛtə ɡˌants aʊf mɪç alˈaɪn ɡəʃtˈɛlt/","zh":"现在我要到那些大城市去就我自己一个人！","en":"Now I'm traveling to the big cities all on my own...","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-06-010","lineIndex":7,"speaker":"","original":"TB falling over...","ipa":"/tebe falɪŋ ovɜ/","zh":"TB规定动作平地摔1/1","en":"TB falling over...","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-06-011","lineIndex":8,"speaker":"LEOPOLD","original":"Lass mich!","ipa":"/leopɔlt las mɪç/","zh":"利奥波德：别管我！","en":"Let me!","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-06-012","lineIndex":9,"speaker":"","original":"Deine Hitzigkeit","ipa":"/daɪnə hɪtsɪçkaɪt/","zh":"你的冲动和鲁莽","en":"Your hot temper","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-06-013","lineIndex":10,"speaker":"","original":"wird mich eines Tages noch töten","ipa":"/vɪɾt mɪç aɪnəs tɑɡəs nɔx tøtən/","zh":"迟早有一天你要把我害死","en":"will kill me one day","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-06-014","lineIndex":11,"speaker":"","original":"Du willst allein verreisen?","ipa":"/du vɪlst alaɪn fɛɾraɪzən/","zh":"你还想一个人出门？","en":"You want to travel alone?","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-06-015","lineIndex":12,"speaker":"","original":"Nicht einmal die Schuhe binden kannst du allein.","ipa":"/nɪçt aɪnmɑl di ʃuə bɪndən kanst du alaɪn/","zh":"你自己连鞋带都不会系","en":"You can't even tie your shoes alone.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-06-016","lineIndex":13,"speaker":"WOLFGANG","original":"Aber ich habe ein Talent wie keiner unter Millionen!","ipa":"/vɔlfɡaŋ ɑbɜ ɪç hɑbə aɪn talɛnt vi kaɪnɜ ʊntɜ mɪljonən/","zh":"但我拥有万里挑一的天赋","en":"But I have a talent like no other in a million!","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-06-017","lineIndex":14,"speaker":"LEOPOLD","original":"Und so viel Hochmut? Und Eigenleben?","ipa":"/leopɔlt ʊnt zo fil hoxmut ʊnt aɪɡənlebən/","zh":"利奥波德：还这么傲气？还想一个人生活？","en":"And so much arrogance? And life of its own?","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-06-018","lineIndex":15,"speaker":"","original":"Das ist es was mir das Herz abnagt.","ipa":"/das ɪst ɛs vas miɾ das hɛɾts apnɑkt/","zh":"你的话让我的心如同被噬咬般痛苦","en":"This is what breaks my heart.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-06-019","lineIndex":16,"speaker":"","original":"Herumzigeunern willst du?","ipa":"/hɛrʊmtsiɡɔønɜn vɪlst du/","zh":"你想到处漂泊？","en":"Do you want to gypsy around?","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-06-020","lineIndex":17,"speaker":"","original":"Zerstören was ich ausgebaut habe?","ipa":"/tsɛɾʃtørən vas ɪç aʊsɡəbaʊt hɑbə/","zh":"你想让我对你的栽培毁于一旦？","en":"Destroy what I have expanded?","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-06-021","lineIndex":18,"speaker":"","original":"Dein Talent vergeuden!","ipa":"/daɪn talɛnt fɛɾɡəudən/","zh":"你的天赋会被浪费的！","en":"Wasting your talent!","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-06-022","lineIndex":19,"speaker":"WOLFGANG","original":"Abernein, jetzt wird alles vielbesser!","ipa":"/vɔlfɡaŋ apɛɾnaɪn jɛtst vɪɾt aləs filbɛsɜ/","zh":"不！一切都会变好的","en":"No, everything will be much better now!","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-06-023","lineIndex":20,"speaker":"","original":"Ich komm raus aus dem Nest in dem man mich verkümmern lässt","ipa":"/ɪç kɔm raʊs aʊs dem nɛst ɪn dem man mɪç fɛɾkʏmən lɛst/","zh":"我会离开这座黄金巢，离开这片让我枯萎的土地","en":"I'm coming out of the nest in which I'm left to wither","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-06-024","lineIndex":21,"speaker":"LEOPOLD","original":"Mit Fürsten ist nicht zu spassen.","ipa":"/leopɔlt mɪt fyɾstən ɪst nɪçt tsu ʃpasən/","zh":"利奥波德：别试着去戏弄主教","en":"Princes are not to be trifled with.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-06-025","lineIndex":22,"speaker":"WOLFGANG","original":"Es wird schon gut geh'n.","ipa":"/vɔlfɡaŋ ɛs vrit ʃon ɡut ɡen/","zh":"会好起来的","en":"It'll be fine.","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-06-026","lineIndex":23,"speaker":"","original":"Bald kommt Ihr nach.","ipa":"/balt kɔmt iɾnax/","zh":"很快就会","en":"You're coming soon.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-06-027","lineIndex":24,"speaker":"","original":"Ich schreib grosse Sinfonien Konzerte und Opern!","ipa":"/ɪç ʃrˈaɪp ɡɾˈɔsə zˈɪnfoːnˌɪən kɔntsˈɛɾtə ʊnt ˈoːpɜn/","zh":"我将会谱写宏大的交响乐协奏曲，还有歌剧！","en":"I write great symphonies concerts and operas!","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-06-029","lineIndex":25,"speaker":"LEOPOLD","original":"Aber wer passt auf dich auf wenn ich nicht bei dir bin?","ipa":"/ˌɑːbɜ vˈeːɾ pˈast aʊf dɪç aʊf vˌɛn ɪç nˈɪçt baɪ diːɾ bɪn/","zh":"利奥波德：但没有我在身边谁来照顾你呢？","en":"But who looks after you when I'm not with you?","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-06-031","lineIndex":26,"speaker":"","original":"Niemand, niemand liebt dich so wie ich.","ipa":"/nimant nimant lipt dɪç zo vi ɪç/","zh":"没有人，没有人如我这般爱你","en":"Nobody, nobody loves you like I do.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-06-032","lineIndex":27,"speaker":"WOLFGANG","original":"Ich liebe dich auch, Papa.","ipa":"/vɔlfɡaŋ ɪç libə dɪç aʊx pɑpɑ/","zh":"我也爱你，爸爸","en":"I love you too, dad.","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-06-033","lineIndex":28,"speaker":"LEOPOLD","original":"Du bist zu kindlich und zu ungeschickt","ipa":"/leopɔlt du bɪst tsu kɪntlɪç ʊnt tsu ʊnɡəʃɪkt/","zh":"利奥波德：面对这残酷狡诈的人生游戏","en":"You're too childlike and too clumsy","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-06-034","lineIndex":29,"speaker":"LEOPOLD","original":"für das kalte, schlaue Spiel des Lebens.","ipa":"/leopɔlt fyɾ das kaltə ʃlaʊə ʃpil dɛs lebəns/","zh":"利奥波德：你太幼小，太稚嫩","en":"for the cold, clever game of life.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-06-035","lineIndex":30,"speaker":"WOLFGANG","original":"Nach dem lieben Gott kommst gleich du.","ipa":"/vɔlfɡaŋ nɑx dem libən ɡɔt kɔmst ɡlaɪç du/","zh":"除了上帝之外我最爱的就是你","en":"You're coming after God.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-06-036","lineIndex":31,"speaker":"LEOPOLD","original":"Ich hab Angst um dich.","ipa":"/leopɔlt ɪç hɑp aŋst ʊm dɪç/","zh":"利奥波德：父亲为你而担忧","en":"I'm afraid for you.","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-06-037","lineIndex":32,"speaker":"WOLFGANG","original":"Nie enttäusch ich dich.","ipa":"/vɔlfɡaŋ ni ɛnttɔøʃ ɪç dɪç/","zh":"我从未让你失望","en":"I will never disappoint you.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-06-038","lineIndex":33,"speaker":"LEOPOLD","original":"Du brauchst mich","ipa":"/leopɔlt du bɾaʊxst mɪç/","zh":"利奥波德：你需要我","en":"You need me","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-06-039","lineIndex":34,"speaker":"LEOPOLD ＆ WOLFGANG","original":"denn niemand liebt dich so wie ich.","ipa":"/leopɔlt vɔlfɡaŋ dɛn nimant lipt dɪç zo vi ɪç/","zh":"利奥波德 ＆ 沃尔夫冈：因为没有人如我这般爱你","en":"because no one loves you like I do.","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-06-040","lineIndex":35,"speaker":"LEOPOLD","original":"Wolfgang, uhh, Wolfgang...","ipa":"/leopɔlt vɔlfɡaŋ u vɔlfɡaŋ/","zh":"利奥波德：沃尔夫冈，唉，沃尔夫冈……","en":"Wolfgang, uhh, Wolfgang...","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-06-041","lineIndex":36,"speaker":"ANNA","original":"Was ist passiert?","ipa":"/anɑ vas ɪst pasiɾt/","zh":"安娜：发生什么了？","en":"What happened?","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-06-042","lineIndex":37,"speaker":"WOLFGANG","original":"Colloredo gibt mir frei, Mama.","ipa":"/vɔlfɡaŋ kɔloredo ɡipt miɾ fraɪ mɑmɑ/","zh":"妈妈，科洛雷多不再约束我了","en":"Colloredo gives me the day off, mom.","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-06-043","lineIndex":38,"speaker":"","original":"Endlich kann ich fort!","ipa":"/ɛntlɪç kan ɪç fɔɾt/","zh":"我终于自由了！","en":"Finally I can leave!","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-06-044","lineIndex":39,"speaker":"LEOPOLD","original":"Er muss eine andere Anstellung finden.","ipa":"/leopɔlt ɛɾ mʊs aɪnə andərə anʃtɛlʊŋ fɪndən/","zh":"利奥波德：他必须找到一个新工作","en":"He has to find another job.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-06-045","lineIndex":40,"speaker":"ANNA","original":"Macht nichts.","ipa":"/anɑ maxt nɪçts/","zh":"安娜：没关系的","en":"Never mind.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-06-046","lineIndex":41,"speaker":"","original":"Jeder Fürst wird sich reißen um ihn.","ipa":"/jedɜ fyɾst vɪɾt zɪç raɪsən ʊm in/","zh":"所有的王侯都会争着雇佣他的","en":"Every prince will fight for him.","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-06-047","lineIndex":42,"speaker":"WOLFGANG","original":"Bravo, Mama!","ipa":"/vɔlfɡaŋ bɾɑvo mɑmɑ/","zh":"太棒了，妈妈！","en":"Bravo, mom!","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-06-048","lineIndex":43,"speaker":"LEOPOLD","original":"Ich kann hier nicht weg","ipa":"/leopɔlt ɪç kan hiɾ nɪçt vɛk/","zh":"利奥波德：我没法离开这儿","en":"I can't leave here","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-06-049","lineIndex":44,"speaker":"","original":"Du must ihn begleiten, Anna Maria.","ipa":"/du mʊst in bəɡlaɪtən anɑ mariɑ/","zh":"你得陪着她，安娜玛利亚","en":"You have to accompany him, Anna Maria.","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-06-050","lineIndex":45,"speaker":"ANNA","original":"Wann?","ipa":"/anɑ van/","zh":"安娜：什么时候走？","en":"When?","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-06-051","lineIndex":46,"speaker":"WOLFGANG","original":"Prestissimo, Mama!","ipa":"/vɔlfɡaŋ pɾɛstɪsimo mɑmɑ/","zh":"越快越好呀，妈妈！","en":"Prestissimo, Mom!","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-06-052","lineIndex":47,"speaker":"","original":"Hurrah!","ipa":"/hʊrɑ/","zh":"万岁！！！","en":"Hurray!","note":"","sourceLineIndex":52}],"sourceOrder":6,"displayOrder":6},{"order":7,"id":"07-ah-das-fraulein-mozart","title":"Ah, das Fräulein Mozart!","titleZh":"啊，莫扎特小姐！","lines":[{"id":"mozart-das-musical-07-002","lineIndex":1,"speaker":"Blumenhändlerin","original":"Ah, das Fräulein Mozart!","ipa":"/ɑ das frɔølaɪn motsaɾt/","zh":"您好，莫扎特小姐！","en":"Ah, Miss Mozart!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-07-004","lineIndex":2,"speaker":"Nannerl","original":"Grüss Sie Gott.","ipa":"/ɡɾʏs zi ɡɔt/","zh":"您好","en":"Greetings.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-07-006","lineIndex":3,"speaker":"Gemüsefrau","original":"Na, wie geht's?","ipa":"/nɑ vi ɡets/","zh":"最近还好吗？","en":"So, how's it going?","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-07-008","lineIndex":4,"speaker":"Nannerl","original":"Gut.","ipa":"/ɡut/","zh":"挺好！","en":"Good.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-07-010","lineIndex":5,"speaker":"Gewürzhändlerin","original":"Guten Morgen.","ipa":"/ɡutən mɔɾɡɑn/","zh":"早上好","en":"Good Morgan.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-07-012","lineIndex":6,"speaker":"Obstfrau","original":"Was darf's denn sein?","ipa":"/vas daɾfs dɛn zaɪn/","zh":"想要点什么？","en":"What can it be?","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-07-014","lineIndex":7,"speaker":"Gemüsefrau","original":"Ist es zu fassen?","ipa":"/ɪst ɛs tsu fasən/","zh":"谁敢相信啊？","en":"Can it be grasped?","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-07-015","lineIndex":8,"speaker":"","original":"Ihren lieben Bruder hat der Fürst entlassen?!","ipa":"/ˌiːrən lˈiːbən bɾˈuːdɜ hat dɛɾ fˈyːɾst ɛntlˈasən/","zh":"您的弟弟竟然被主教解雇了？！","en":"The prince has released your dear brother?!","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-07-018","lineIndex":9,"speaker":"Blumenhändlerin","original":"Das ist grausam.","ipa":"/das ɪst ɡɾaʊzɑm/","zh":"真是太惨了","en":"This is cruel.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-07-020","lineIndex":10,"speaker":"Gewürzhändlerin","original":"Indischer Curry!","ipa":"/ɪndɪʃɜ kʊri/","zh":"印度咖喱！","en":"Indian curry!","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-07-022","lineIndex":11,"speaker":"Gemüsefrau","original":"Fisolen!","ipa":"/fizolən/","zh":"豌豆！","en":"Fisolen!","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-07-024","lineIndex":12,"speaker":"Obstfrau","original":"Zitronen!","ipa":"/tsɪtɾonən/","zh":"柠檬！","en":"Lemons!","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-07-026","lineIndex":13,"speaker":"Blumenhändlerin","original":"Ein Rosenstock!","ipa":"/aɪn rozənstɔk/","zh":"一束玫瑰！","en":"A rose bush!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-07-028","lineIndex":14,"speaker":"Gewürzhändlerin","original":"Spanischer Pfeffer!","ipa":"/ʃpɑnɪʃɜ pfɛfɜ/","zh":"西班牙胡椒！","en":"Spanish pepper!","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-07-029","lineIndex":15,"speaker":"","original":"Feines Obst!","ipa":"/faɪnəs opst/","zh":"新鲜水果！","en":"Fine fruit!","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-07-031","lineIndex":16,"speaker":"Blumenhändlerin","original":"Ist der Vater bei ihm?","ipa":"/ɪst dɛɾ fɑtɜ baɪ im/","zh":"您的父亲跟他一起吗？","en":"Is his father with him?","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-07-033","lineIndex":17,"speaker":"Nannerl","original":"Nein, er blieb zu Haus","ipa":"/naɪn ɛɾ blip tsu haʊs/","zh":"不，他留在家里","en":"No, he stayed at home","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-07-034","lineIndex":18,"speaker":"","original":"Doch er gab Wolfgang sein ganzes Geld","ipa":"/dɔx ɛɾ ɡɑp vɔlfɡaŋ zaɪn ɡantsəs ɡɛlt/","zh":"但他给了沃尔夫冈他全部的积蓄","en":"But he gave Wolfgang all his money","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-07-036","lineIndex":19,"speaker":"Gewürzhändlerin","original":"Dann reist er alleine?","ipa":"/dan raɪst ɛɾ alaɪnə/","zh":"那他一个人走的？","en":"Then he travels alone?","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-07-038","lineIndex":20,"speaker":"Nannerl","original":"Nein, mit seiner Mutter.","ipa":"/naɪn mɪt zaɪnɜ mʊtɜ/","zh":"不，和母亲一起","en":"No, with his mother.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-07-040","lineIndex":21,"speaker":"Gemüsefrau","original":"Und? Fand er schon eine neue Stellung?","ipa":"/ʊnt fant ɛɾ ʃon aɪnə nɔøə ʃtɛlʊŋ/","zh":"然后呢？他谋到了什么新职位吗？","en":"And? Has he already found a new position?","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-07-042","lineIndex":22,"speaker":"Nannerl","original":"Leider war in München","ipa":"/laɪdɜ vɑɾ ɪn mʏnçən/","zh":"很可惜在慕尼黑","en":"Unfortunately there was no vacatur available in Munich","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-07-043","lineIndex":23,"speaker":"","original":"keine Vacatur frei","ipa":"/kaɪnə vɑkatuɾ fraɪ/","zh":"并没有闲职","en":"no vacancy is free","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-07-044","lineIndex":24,"speaker":"","original":"Jetzt ist er in Mannheim wo man ihn liebt.","ipa":"/jˌɛtst ɪst ɛɾ ɪn mˈanhaɪm vˌoː man iːn lˈiːpt/","zh":"现在他到了曼海姆那儿的人都很喜欢他","en":"Now he is in Mannheim where he is loved.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-07-046","lineIndex":25,"speaker":"","original":"Sicher stellt man ihn ein","ipa":"/zɪçɜ ʃtɛlt man in aɪn/","zh":"当然也有人聘用了他","en":"They'll definitely hire him","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-07-047","lineIndex":26,"speaker":"","original":"Mannheims Kurfürst schätzt ihn sehr","ipa":"/manhaɪms kʊɐfyɾst ʃɛtst in zeɾ/","zh":"曼海姆的选帝侯对他关爱有加","en":"Mannheim's elector values him very much","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-07-048","lineIndex":27,"speaker":"","original":"Sein Gehalt wird fürstlich sein Was wir brauchen und noch mehr","ipa":"/zaɪn ɡəhˈalt vˌɪɾt fˈʏɾstlɪç zaɪn vˈas viːɾ bɾˈaʊxən ʊnt nɔx mˈeːɾ/","zh":"他的薪金非常丰厚能让我们衣食无忧还绰绰有余","en":"His salary will be princely What we need and more","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-07-050","lineIndex":28,"speaker":"","original":"Ich pack schon die Koffer ein","ipa":"/ɪç pak ʃon di kɔfɜ aɪn/","zh":"我已经把行李收拾好了","en":"I'm already packing my suitcases","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-07-051","lineIndex":29,"speaker":"","original":"bald ziehn wir ihm hinterher","ipa":"/balk tsin viɾ im hɪntɜhɜ/","zh":"很快我们就去跟他团聚","en":"Soon we follow him","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-07-052","lineIndex":30,"speaker":"","original":"Und wir leben froh und glücklich","ipa":"/ʊnt viɾ lebən fro ʊnt ɡlʏklɪç/","zh":"我们会像在梦中的王国里一样","en":"And we live happily","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-07-053","lineIndex":31,"speaker":"","original":"in dem Königreich unsrer Träume","ipa":"/ɪn dem kønɪɡɾaɪç ʊnsrɜ tɾɔømə/","zh":"活得快乐而幸福","en":"in the kingdom of our dreams","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-07-054","lineIndex":32,"speaker":"","original":"Er ist ein Schicksalsprinz","ipa":"/ɛɾ ɪst aɪn ʃɪkzalʃpɾɪnts/","zh":"他是命运的宠儿","en":"He is a prince of fate","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-07-055","lineIndex":33,"speaker":"","original":"den nie das Glück verlässt","ipa":"/den ni das ɡlʏk fɛɾlɛst/","zh":"幸运从来就不会弃他而去","en":"whose luck never leaves him","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-07-057","lineIndex":34,"speaker":"Graf Arco","original":"Die wird sich noch wundern!","ipa":"/di vɪɾt zɪç nɔx vʊndɜn/","zh":"您肯定会感到惊讶","en":"She'll be surprised!","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-07-058","lineIndex":35,"speaker":"","original":"Ihren feinen Bruder stellt in ganz Europa niemand an.","ipa":"/ˌiːrən fˈaɪnən bɾˈuːdɜ ʃtˈɛlt ɪn ɡˌants ɔørˈoːpɑː nˈiːmant ˈan/","zh":"其实全欧洲都没有人会雇佣令弟","en":"No one in the whole of Europe employs your fine brother.","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-07-062","lineIndex":36,"speaker":"Nannerl","original":"Wie woll'n Sie das wissen?","ipa":"/vi vɔln zi das vɪsən/","zh":"您怎么知道的？","en":"How do you know that?","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-07-064","lineIndex":37,"speaker":"Graf Arco","original":"Ich sag nur: Ich weiß es","ipa":"/ɪç zɑk nuɾ ɪç vaɪs ɛs/","zh":"我就是知道","en":"I'm just saying: I know","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-07-065","lineIndex":38,"speaker":"","original":"Bald wird er vermissen was er aufgab.","ipa":"/bˈalt vˌɪɾt ɛɾ fɛɾmˈɪsən vˈas ɛɾ ˈaʊfɡˌɑːp/","zh":"不久他就会为自己放弃的东西而后悔","en":"Soon he'll miss what he gave up.","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-07-068","lineIndex":39,"speaker":"Nannerl","original":"Mozart wird geschätzt","ipa":"/motsaɾt vɪɾt ɡəʃɛtst/","zh":"莫扎特家的人是受眷顾的","en":"Mozart is valued","note":"","sourceLineIndex":68},{"id":"mozart-das-musical-07-070","lineIndex":40,"speaker":"Graf Arco","original":"Nun, das wird ihm nichts nützen","ipa":"/nun das vɪɾt im nɪçts nʏtsən/","zh":"现在这对他毫无益处","en":"Well, that won't do him any good","note":"","sourceLineIndex":70},{"id":"mozart-das-musical-07-071","lineIndex":41,"speaker":"","original":"wenn ein Fürst und Erzbischof gewisse unsichtbare Drähte zieht.","ipa":"/vˌɛn aɪn fˈyːɾst ʊnt ɛɾtsbˈɪʃoːf ɡəvˈɪsə ˈʊnzˌɪçtbɑːrə dɾˈɛːtə tsˈiːt/","zh":"只要某位主教大人在暗中偷偷地摆布一下","en":"if a prince and archbishop pulls certain invisible wires.","note":"","sourceLineIndex":71},{"id":"mozart-das-musical-07-076","lineIndex":42,"speaker":"Passanten","original":"Einst Wunderkind...","ipa":"/aɪnst vʊndɜkɪnt/","zh":"曾经的神童……","en":"Once a child prodigy...","note":"","sourceLineIndex":76},{"id":"mozart-das-musical-07-077","lineIndex":43,"speaker":"","original":"Mozart!","ipa":"/motsaɾt/","zh":"莫扎特！","en":"Mozart!","note":"","sourceLineIndex":77},{"id":"mozart-das-musical-07-078","lineIndex":44,"speaker":"","original":"Jetzt heimatlos...","ipa":"/jɛtst haɪmatlos/","zh":"如今无家可归……","en":"Now homeless...","note":"","sourceLineIndex":78},{"id":"mozart-das-musical-07-079","lineIndex":45,"speaker":"","original":"Mozart!","ipa":"/motsaɾt/","zh":"莫扎特！","en":"Mozart!","note":"","sourceLineIndex":79},{"id":"mozart-das-musical-07-081","lineIndex":46,"speaker":"Nannerl","original":"Unsinn! Mein Bruder ist jetzt in Mannheim","ipa":"/ʊnzɪn maɪn bɾudɜ ɪst jɛtst ɪn manhaɪm/","zh":"胡说八道！我的弟弟现在在曼海姆","en":"Nonsense! My brother is now in Mannheim","note":"","sourceLineIndex":81},{"id":"mozart-das-musical-07-082","lineIndex":47,"speaker":"","original":"und verkehrt dort in den höchst......","ipa":"/ʊnt fɛɾkeɾt dɔɾt ɪn den hœkst/","zh":"也走进上等……","en":"and moves there in the highest......","note":"","sourceLineIndex":82},{"id":"mozart-das-musical-07-083","lineIndex":48,"speaker":"","original":"in den höchsten Kreisen","ipa":"/ɪn den hœkstən kɾaɪzən/","zh":"走进上等人的交际圈了","en":"in the highest circles","note":"","sourceLineIndex":83}],"sourceOrder":7,"displayOrder":7},{"order":8,"id":"08-eine-ehrliche-familie","title":"Eine ehrliche Familie","titleZh":"一个正直的家庭","lines":[{"id":"mozart-das-musical-08-001","lineIndex":1,"speaker":"Aloysia","original":"Ich sang dem Grafen vor...","ipa":"/ɑlɔøziɑ ɪç zaŋ dɑm ɡɾɑfən fɔɾ/","zh":"阿洛伊西娅我为伯爵唱歌了..","en":"AloysiaI sang to the counts...","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-08-002","lineIndex":2,"speaker":"Cäcilia","original":"Und dann?","ipa":"/kɛkiliɑ ʊnt dan/","zh":"韦伯夫人然后呢？","en":"CäciliaAnd then?","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-08-003","lineIndex":3,"speaker":"Aloysia","original":"...rief er \"Venez!\" Er sah mir in die Augen","ipa":"/ɑlɔøziɑ rif ɛɾ venets ɛɾ zɑ miɾ ɪn di aʊɡən/","zh":"阿洛伊西娅..他大声叫着“过来！”，然后直勾勾地看着我的眼睛","en":"Aloysia...he shouted \"Venez!\" He looked into my eyes","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-08-004","lineIndex":4,"speaker":"Aloysia","original":"In's Dekolleté. Er griff mir untern Rock","ipa":"/ɑlɔøziɑ ins dekɔlete ɛɾ ɡɾɪf miɾ ʊntɛɾn rɔk/","zh":"他看到我衣服里面去了，还把手伸进了我的裙子里","en":"AloysiaInto my cleavage. He reached under my skirt","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-08-005","lineIndex":5,"speaker":"Cäcilia","original":"Und dann?","ipa":"/kɛkiliɑ ʊnt dan/","zh":"韦伯夫人然后？","en":"CäciliaAnd then?","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-08-006","lineIndex":6,"speaker":"Aloysia","original":"Ich ging.","ipa":"/ɑlɔøziɑ ɪç ɡɪŋ/","zh":"阿洛伊西娅我走开了","en":"AloysiaI left.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-08-007","lineIndex":7,"speaker":"Cäcilia","original":"Warum?","ipa":"/kɛkiliɑ vɑrʊm/","zh":"韦伯夫人为啥？","en":"CäciliaWhy?","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-08-008","lineIndex":8,"speaker":"Aloysia","original":"Er war mir widerlich","ipa":"/ɑlɔøziɑ ɛɾ vɑɾ miɾ vidɜlɪç/","zh":"阿洛伊西娅他让我觉得恶心","en":"AloysiaHe was disgusting to me","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-08-009","lineIndex":9,"speaker":"Cäcilia","original":"Was sind meine Töchter doch dumm!","ipa":"/kɛkiliɑ vas zɪnt maɪnə tœçtɜ dɔx dʊm/","zh":"阿洛伊西娅他让我觉得恶心","en":"CäciliaHow stupid my daughters are!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-08-010","lineIndex":10,"speaker":"Aloysia","original":"Au!","ipa":"/ɑlɔøziɑ aʊ/","zh":"阿洛伊西娅哎哟！","en":"AloysiaOw!","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-08-011","lineIndex":11,"speaker":"Cäcilia","original":"Keiner, der uns noch was leiht","ipa":"/kɛkiliɑ kaɪnɜ dɛɾ ʊns nɔx vas laɪht/","zh":"韦伯夫人没有人会借钱给我们","en":"CäciliaNobody to lend us anything","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-08-012","lineIndex":12,"speaker":"","original":"Kein Geld mehr fürs Kartenspiel","ipa":"/kaɪn ɡɛlt meɾ fyɾs kaɾtənʃpil/","zh":"没余钱能拿去打牌赌博","en":"No more money for playing cards","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-08-013","lineIndex":13,"speaker":"","original":"Und die Kinder haben kein Familiengefühl","ipa":"/ʊnt di kɪndɜ hɑbən kaɪn familɪəŋefyl/","zh":"这些孩子没有半点儿家庭荣誉感","en":"And the children have no sense of family","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-08-014","lineIndex":14,"speaker":"","original":"(pointing at Aloysia)","ipa":"/poɪntɪŋ ɑt ɑlɔøziɑ/","zh":"（指向阿洛伊西娅）","en":"(pointing at Aloysia)","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-08-015","lineIndex":15,"speaker":"","original":"Die eine singt, doch setzt sie ihr Talent nicht um","ipa":"/di aɪnə zɪŋt dɔx zɛtst zi iɾ talɛnt nɪçt ʊm/","zh":"这位能唱歌，但不会用她的才能做本钱","en":"One sings, but sets She doesn't use her talent to","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-08-016","lineIndex":16,"speaker":"","original":"(pointing at Constanze)","ipa":"/poɪntɪŋ ɑt kɔnstantsə/","zh":"（指康斯坦茨）","en":"(pointing at Constanze)","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-08-017","lineIndex":17,"speaker":"","original":"Die andre faul die dritte hässlich die vierte zu dumm.","ipa":"/diː ˈandɾə fˈaʊl diː dɾˈɪtə hˈɛslɪç diː fˈiːɾtə tsuː dˈʊm/","zh":"另一位是懒虫第三个是丑八怪第四个是蠢货","en":"The other is lazy the third is ugly the fourth is too stupid.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-08-020","lineIndex":18,"speaker":"Ensemble","original":"Eine ehrliche Familie hat es nicht leicht","ipa":"/ɑ̃sɑ̃bəl aɪnə eɾlɪçə familɪə hat ɛs nɪçt laɪçt/","zh":"众人老实巴交的一家活得真不容易","en":"EnsembleAn honest family doesn't have it easy","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-08-021","lineIndex":19,"speaker":"","original":"denn mit Fleiß und Anstand wird nur wenig erreicht","ipa":"/dɛn mɪt flaɪs ʊnt anʃtant vɪɾt nuɾ venɪç ɛɾraɪçt/","zh":"勤勤恳恳，老老实实谋生所挣的又屈指可数","en":"because with hard work and decency only little is achieved","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-08-022","lineIndex":20,"speaker":"","original":"Unschuldig verarmt erwartet sie einen Mann der die ehrliche Familie retten kann.","ipa":"/ˈʊnʃˌʊldɪç fɛɾˈaɾmt ɛɾvˈaɾtət ziː ˌaɪnən mˈan dɛɾ diː ˈeːɾlɪçə famˈiːlɪə rˈɛtən kˌan/","zh":"一穷二白的他们就会等着有人出现能给这实诚的一家人雪中送炭","en":"Innocently impoverished, she awaits a man who can save the honest family.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-08-024","lineIndex":21,"speaker":"Herr Weber","original":"Mein Weib, wir sind saniert!","ipa":"/hɛɾ vebɜ maɪn vaɪp viɾ zɪnt zaniɾt/","zh":"韦伯先生老婆，我们有救咯！","en":"Mr. WeberMy wife, we have been renovated!","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-08-025","lineIndex":22,"speaker":"Cäcilia","original":"Wie das?","ipa":"/kɛkiliɑ vi das/","zh":"韦伯夫人怎么有救？","en":"CäciliaHow so?","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-08-026","lineIndex":23,"speaker":"Herr Weber","original":"Hört alle her! Gleich kommt ein neues Opfer.","ipa":"/hɛɾ vebɜ hœɾt alə heɾ ɡlaɪç kɔmt aɪn nɔøəs ɔpfɜ/","zh":"韦伯先生大家听好！马上就有条新来的鱼要咬钩了","en":"Mr. WeberListen up everyone! A new victim is coming soon.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-08-027","lineIndex":24,"speaker":"Ensemble","original":"War?","ipa":"/ɑ̃sɑ̃bəl vɑɾ/","zh":"众人谁呀？","en":"EnsembleWas?","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-08-028","lineIndex":25,"speaker":"Herr Weber","original":"Dukatenschwer, arglos und leichtsinnig.","ipa":"/hɛɾ vebɜ dukatɛnʃveɾ aɾɡlos ʊnt laɪçtsɪnɪç/","zh":"韦伯先生一个又有钱，又容易上当的毛头小子","en":"Mr. Weber Ducat-heavy, guileless and careless.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-08-029","lineIndex":26,"speaker":"Cäcilia","original":"Aloysia!","ipa":"/kɛkiliɑ ɑlɔøziɑ/","zh":"韦伯夫人让阿洛伊西娅去！","en":"CäciliaAloysia!","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-08-030","lineIndex":27,"speaker":"Aloysia","original":"Warum ich?!","ipa":"/ɑlɔøziɑ vɑrʊm ɪç/","zh":"阿洛伊西娅为什么是我啊？！","en":"AloysiaWhy me?!","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-08-031","lineIndex":28,"speaker":"Herr Weber","original":"Mann! Ein junger Komponist...","ipa":"/hɛɾ vebɜ man aɪn jʊŋɜ kɔmponɪst/","zh":"韦伯先生拜托！是一个年轻的作曲家...","en":"Mr. WeberMann! A young composer...","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-08-032","lineIndex":29,"speaker":"Cäcilia","original":"...ist einfache Beute für dich!","ipa":"/kɛkiliɑ ɪst aɪnfaxə bɔøtə fyɾ dɪç/","zh":"韦伯夫人...对你来说拿下他轻而易举！","en":"Cäcilia...is easy prey for you!","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-08-033","lineIndex":30,"speaker":"Herr Weber","original":"(to Mozart) Ah, da ist mein lieber Freund!","ipa":"/hɛɾ vebɜ tʊ motsaɾt ɑ dɑ ɪst maɪn libɜ frɔønt/","zh":"韦伯先生（对莫扎特）啊，我亲爱的朋友！","en":"Mr. Weber (to Mozart) Ah, there is my dear friend!","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-08-034","lineIndex":31,"speaker":"Wolfgang","original":"Guten Tag, Herr Weber!","ipa":"/vɔlfɡaŋ ɡutən tɑk hɛɾ vebɜ/","zh":"沃尔夫冈您好，韦伯先生！","en":"WolfgangHello, Mr. Weber!","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-08-035","lineIndex":32,"speaker":"Herr Weber","original":"Nennen Sie mich doch einfach 'Mon Ami'!","ipa":"/hɛɾ vebɜ nɛnən zi mɪç dɔx aɪnfax mon ɑmi/","zh":"韦伯先生直接叫我‘老伙计’就行！","en":"Mr. WeberJust call me 'Mon Ami'!","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-08-036","lineIndex":33,"speaker":"","original":"Und fühlen Sie sich wie zuhaus bei uns","ipa":"/ʊnt fylən zi zɪç vi tsuhaʊs baɪ ʊns/","zh":"在我们这儿就像在您自个儿家里一样","en":"And feel at home with us","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-08-037","lineIndex":34,"speaker":"Wolfgang","original":"Ach wie gemütlich Mon Ami, Sie sind zu beneiden.","ipa":"/vɔlfɡaŋ ax vi ɡəmytlɪç mon ɑmi zi zɪnt tsu bənaɪdən/","zh":"沃尔夫冈哎呀，老伙计，您的好福气真让人艳羡","en":"WolfgangOh how cozy Mon Ami, you are to be envied.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-08-038","lineIndex":35,"speaker":"Herr Weber","original":"Wir leben glücklich wenn auch arm und bescheiden.","ipa":"/hɛɾ vebɜ viɾ lebən ɡlʏklɪʃ vɛn aʊx aɾm ʊnt bəʃaɪdən/","zh":"韦伯先生我们过得很幸福，只不过清贫又卑微","en":"Mr. WeberWe live happily, albeit poor and modest.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-08-039","lineIndex":36,"speaker":"Cäcilia","original":"Schuldlos und elend.","ipa":"/kɛkiliɑ ʃʊldlos ʊnt elɛnt/","zh":"韦伯夫人又善良又穷苦","en":"CäciliaGuiltless and miserable.","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-08-040","lineIndex":37,"speaker":"Wolfgang","original":"Die Welt ist voll Fallen.","ipa":"/vɔlfɡaŋ di vɛlt ɪst fɔl falən/","zh":"沃尔夫冈这个世道到处都是诱惑","en":"WolfgangThe world is full of traps.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-08-041","lineIndex":38,"speaker":"Herr Weber","original":"Doch sauber und fleißig","ipa":"/hɛɾ vebɜ dɔx zaʊbɜ ʊnt flaɪsɪç/","zh":"韦伯先生但我们清白又勤恳","en":"Mr. WeberBut clean and hardworking","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-08-042","lineIndex":39,"speaker":"Cäcilia","original":"Und ehrlich zu allen.","ipa":"/kɛkiliɑ ʊnt eɾlɪç tsu alən/","zh":"韦伯夫人对所有人都诚实守信","en":"CäciliaAnd honest with everyone.","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-08-043","lineIndex":40,"speaker":"Wolfgang","original":"Wie wir","ipa":"/vɔlfɡaŋ vi viɾ/","zh":"沃尔夫冈就像我们","en":"WolfgangLike us","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-08-044","lineIndex":41,"speaker":"Herr Weber","original":"Das ist mein armes Weib, Cäcilia Weber.","ipa":"/hɛɾ vebɜ das ɪst maɪnaɾmə vaɪp kɛkiliɑ vebɜ/","zh":"韦伯先生这是贱内，采齐莉娅·韦伯","en":"Mr WeberThis is my poor wife, Cecilia Weber.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-08-045","lineIndex":42,"speaker":"Wolfgang","original":"Bonjour, Madame.","ipa":"/vɔlfɡaŋ bɔnjuɾ mɑdɑmə/","zh":"沃尔夫冈夫人，您好","en":"WolfgangBonjour, Madame.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-08-046","lineIndex":43,"speaker":"Herr Weber","original":"Herr, mein lieben Töchter","ipa":"/hɛɾ vebɜ hɛɾ maɪn libən tœçtɜ/","zh":"韦伯先生先生，这是我亲爱的女儿们","en":"Mr. WeberLord, my dear daughters","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-08-047","lineIndex":44,"speaker":"","original":"Das ist Josepha","ipa":"/das ɪst jozefɑ/","zh":"这是约瑟芬","en":"This is Josepha","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-08-048","lineIndex":45,"speaker":"Cäcilia","original":"Ein Engelchen","ipa":"/kɛkiliɑ aɪn ɛŋəlçən/","zh":"韦伯夫人像天使般可爱动人","en":"CäciliaA little angel","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-08-049","lineIndex":46,"speaker":"Herr Weber","original":"Constanze","ipa":"/hɛɾ vebɜ kɔnstantsə/","zh":"韦伯先生康斯坦茨","en":"Mr. WeberConstanze","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-08-050","lineIndex":47,"speaker":"Cäcilia","original":"Niemand ist so fleißig","ipa":"/kɛkiliɑ nimant ɪst zo flaɪsɪç/","zh":"韦伯夫人没人像她这么勤奋好学","en":"CäciliaNo one is so hard-working","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-08-051","lineIndex":48,"speaker":"Herr Weber","original":"Das ist Sophie","ipa":"/hɛɾ vebɜ das ɪst zofi/","zh":"韦伯先生这是索菲","en":"Mr. WeberThis is Sophie","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-08-052","lineIndex":49,"speaker":"Cäcilia","original":"Sie ist blitzgescheit.","ipa":"/kɛkiliɑ zi ɪst blɪtsɡɛʃaɪt/","zh":"韦伯夫人她聪明绝顶","en":"CäciliaShe is extremely clever.","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-08-053","lineIndex":50,"speaker":"Herr Weber","original":"Und hier Aloysia...","ipa":"/hɛɾ vebɜ ʊnt hiɾ ɑlɔøziɑ/","zh":"韦伯先生还有阿洛伊西娅..","en":"Mr. WeberAnd here Aloysia...","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-08-054","lineIndex":51,"speaker":"Cäcilia","original":"...schwärmt für Sie!","ipa":"/kɛkiliɑ ʃvɛɾmt fyɾ zi/","zh":"韦伯夫人..她对您仰慕有加","en":"Cäcilia...raves for you!","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-08-055","lineIndex":52,"speaker":"Herr Weber","original":"Ja Wie Sie, Mon Ami, liebt sie die Musik.","ipa":"/hɛɾ vebɜ jɑ vi zi mon ɑmi lipt zi di muzik/","zh":"韦伯先生她就像您一样喜欢音乐","en":"Mr WeberYes Like you, Mon Ami, she loves music.","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-08-056","lineIndex":53,"speaker":"Cäcilia","original":"Sie bewundert ihr Genie","ipa":"/kɛkiliɑ zi bəvʊndɜt iɾ ɡəni/","zh":"韦伯夫人她简直才华惊人","en":"CäciliaShe admires her genius","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-08-057","lineIndex":54,"speaker":"Wolfgang","original":"Enchanté, Mademoiselle.","ipa":"/vɔlfɡaŋ ɛnçante mɑdemoizɛlə/","zh":"沃尔夫冈小姐，幸会幸会","en":"WolfgangEnchanté, Mademoiselle.","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-08-058","lineIndex":55,"speaker":"Herr Weber","original":"Aloysia, singt...","ipa":"/hɛɾ vebɜ ɑlɔøziɑ zɪŋt/","zh":"韦伯先生阿洛伊西娅会唱歌","en":"Mr. WeberAloysia, sings...","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-08-059","lineIndex":56,"speaker":"Cäcilia","original":"Mit einer göttlichen Stimme.","ipa":"/kɛkiliɑ mɪt aɪnɜ ɡœtlɪçən ʃtɪmə/","zh":"韦伯夫人她的歌喉惊为天人","en":"CäciliaWith a divine voice.","note":"","sourceLineIndex":59},{"id":"mozart-das-musical-08-060","lineIndex":57,"speaker":"Wolfgang","original":"Wie interessant!","ipa":"/vɔlfɡaŋ vi ɪntərɛsant/","zh":"沃尔夫冈这太有意思了！","en":"WolfgangHow interesting!","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-08-061","lineIndex":58,"speaker":"Herr Weber","original":"Sie müssen sie h? ren!","ipa":"/hɛɾ vebɜ zi mʏsən zi hɑren/","zh":"韦伯先生您得听听她唱！","en":"Mr. WeberYou have to hear them!","note":"","sourceLineIndex":61},{"id":"mozart-das-musical-08-062","lineIndex":59,"speaker":"Cäcilia","original":"Aloysia, sing unser'm Freund etwas vor!","ipa":"/kɛkiliɑ ɑlɔøziɑ zɪŋ ʊnzeɾm frɔønt ɛtvɑs fɔɾ/","zh":"韦伯夫人阿洛伊西娅，快为我们的朋友唱一曲","en":"CäciliaAloysia, sing something to our friend!","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-08-063","lineIndex":60,"speaker":"Wolfgang","original":"O ja, das wäre wirklich reizend!","ipa":"/vɔlfɡaŋ o jɑ das vɛrə vɪɾklɪç raɪtsənt/","zh":"沃尔夫冈啊，这真是令人兴奋！","en":"WolfgangOh yes, that would be really lovely!","note":"","sourceLineIndex":63},{"id":"mozart-das-musical-08-064","lineIndex":61,"speaker":"Herr Weber","original":"Zeig dem Herrn Mozart was du kannst!","ipa":"/hɛɾ vebɜ tsaɪk dem hɛɾn motsaɾt vas du kanst/","zh":"韦伯先生快向莫扎特先生展示下你的才能！","en":"Mr. WeberShow Mr. Mozart what you can do!","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-08-065","lineIndex":62,"speaker":"","original":"(singing)","ipa":"/zɪŋɪŋ/","zh":"（花腔各种秀）","en":"(singing)","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-08-066","lineIndex":63,"speaker":"Wolfgang","original":"Buono!","ipa":"/vɔlfɡaŋ buono/","zh":"沃尔夫冈不错！","en":"WolfgangBuono!","note":"","sourceLineIndex":66},{"id":"mozart-das-musical-08-067","lineIndex":64,"speaker":"","original":"(singing)","ipa":"/zɪŋɪŋ/","zh":"（花腔各种秀）","en":"(singing)","note":"","sourceLineIndex":67},{"id":"mozart-das-musical-08-068","lineIndex":65,"speaker":"","original":"Bella!","ipa":"/bɛlɑ/","zh":"真妙！","en":"Bella!","note":"","sourceLineIndex":68},{"id":"mozart-das-musical-08-069","lineIndex":66,"speaker":"","original":"(singing)","ipa":"/zɪŋɪŋ/","zh":"（花腔各种秀）","en":"(singing)","note":"","sourceLineIndex":69},{"id":"mozart-das-musical-08-070","lineIndex":67,"speaker":"","original":"Brava! Brava!","ipa":"/bɾɑvɑ bɾɑvɑ/","zh":"精彩绝伦！精彩绝伦！","en":"Brava! Brava!","note":"","sourceLineIndex":70},{"id":"mozart-das-musical-08-071","lineIndex":68,"speaker":"Ensemble","original":"Können Sie für Aloysia was tun?","ipa":"/ɑ̃sɑ̃bəl kœnən zi fyɾ ɑlɔøziɑ vas tun/","zh":"众人您能为阿洛伊西娅做点什么吗？","en":"EnsembleCan you do something for Aloysia?","note":"","sourceLineIndex":71},{"id":"mozart-das-musical-08-072","lineIndex":69,"speaker":"Wolfgang","original":"O ja, mit Freuden!","ipa":"/vɔlfɡaŋ o jɑ mɪt frɔødən/","zh":"沃尔夫冈当然，乐意效劳！","en":"WolfgangOh yes, with pleasure!","note":"","sourceLineIndex":72},{"id":"mozart-das-musical-08-073","lineIndex":70,"speaker":"","original":"Erstens singt sie phantastisch","ipa":"/eɾstəns zɪŋt zi fantastɪʃ/","zh":"第一，她的歌声美妙动听","en":"Firstly, she sings fantastically","note":"","sourceLineIndex":73},{"id":"mozart-das-musical-08-074","lineIndex":71,"speaker":"","original":"Zweitens kann ich sie leiden","ipa":"/tsvaɪtəns kan ɪç zi laɪdən/","zh":"第二，我非常喜欢她","en":"Secondly, I like her","note":"","sourceLineIndex":74},{"id":"mozart-das-musical-08-075","lineIndex":72,"speaker":"","original":"Ich geh bei allen Höfen aus und ein und kriege, was ich begehre","ipa":"/ɪç ɡˈeː baɪ ˈalən hˈøːfən ˌaʊs ʊnt aɪn ʊnt kɾˈiːɡə vˈas ɪç bəɡəhrˈeː/","zh":"我常在宫廷出入想要做什么都能办到","en":"I go out to all the courts and and get what I want","note":"","sourceLineIndex":75},{"id":"mozart-das-musical-08-077","lineIndex":73,"speaker":"","original":"Erstens werd ich sie fördern","ipa":"/eɾstəns veɾt ɪç ziɾ fœɾdɜn/","zh":"首先我要引荐她","en":"Firstly, I will encourage sir","note":"","sourceLineIndex":77},{"id":"mozart-das-musical-08-078","lineIndex":74,"speaker":"","original":"zweitens mach sie Karriere","ipa":"/tsvaɪtəns max zi karɪerə/","zh":"然后我会为她谋一个前程","en":"secondly, make her a career","note":"","sourceLineIndex":78},{"id":"mozart-das-musical-08-079","lineIndex":75,"speaker":"Cäcilia","original":"Aloysia, wollt ihr zwei nicht in den Garten gehn?","ipa":"/kɛkiliɑ ɑlɔøziɑ vɔlt iɾ tsvaɪ nɪçt ɪn den ɡaɾtən ɡen/","zh":"韦伯夫人阿洛伊西娅，你们俩不去花园里走走吗？","en":"CäciliaAloysia, don't you two want to go into the garden?","note":"","sourceLineIndex":79},{"id":"mozart-das-musical-08-080","lineIndex":76,"speaker":"Herr Weber","original":"Erzähl ihm mehr von dir!","ipa":"/hɛɾ vebɜ ɛɾtsɛl im meɾ fɔn diɾ/","zh":"韦伯先生让他多了解了解你！","en":"Mr. WeberTell him more about yourself!","note":"","sourceLineIndex":80},{"id":"mozart-das-musical-08-081","lineIndex":77,"speaker":"Cäcilia","original":"Der Abend ist so schön","ipa":"/kɛkiliɑ dɛɾ ɑbənt ɪst zo ʃøn/","zh":"韦伯夫人今晚的夜色这么美","en":"CäciliaThe evening is so beautiful","note":"","sourceLineIndex":81},{"id":"mozart-das-musical-08-082","lineIndex":78,"speaker":"Constanze","original":"Es ist saukalt!","ipa":"/kɔnstantsə ɛsɪst zaʊkalt/","zh":"康斯坦茨都快冷死人了！","en":"ConstanzeIt's freezing cold!","note":"","sourceLineIndex":82},{"id":"mozart-das-musical-08-083","lineIndex":79,"speaker":"Cäcilia","original":"Inzwischen koch ich was...","ipa":"/kɛkiliɑ ɪntsvɪʃən kɔx ɪç vas/","zh":"韦伯夫人在这期间我可以烧点儿菜..","en":"CäciliaMeanwhile I'm cooking something...","note":"","sourceLineIndex":83},{"id":"mozart-das-musical-08-084","lineIndex":80,"speaker":"Josepha","original":"Nur was? Der Schrank ist leer.","ipa":"/jozefɑ nuɾ vas dɛɾ ʃraŋk ɪst leɾ/","zh":"约瑟芬烧什么？吃的都没了","en":"JosephaJust what? The cupboard is empty.","note":"","sourceLineIndex":84},{"id":"mozart-das-musical-08-085","lineIndex":81,"speaker":"Herr Weber","original":"Hätten Sie etwas Geld?","ipa":"/hɛɾ vebɜ hɛtən zi ɛtvɑs ɡɛlt/","zh":"韦伯先生您身上带着钱吗？","en":"Mr. WeberDo you have some money?","note":"","sourceLineIndex":85},{"id":"mozart-das-musical-08-086","lineIndex":82,"speaker":"Wolfgang","original":"Soviel Sie woll'n! Ich hab noch mehr.","ipa":"/vɔlfɡaŋ zovil zi vɔln ɪç hɑp nɔx meɾ/","zh":"沃尔夫冈您想要多少都有！我还有呢","en":"WolfgangAs much as you want! I have more.","note":"","sourceLineIndex":86},{"id":"mozart-das-musical-08-087","lineIndex":83,"speaker":"Ensemble","original":"So ein Freund, der uns was leiht mit Sinn für ein edles Ziel.","ipa":"/zoː aɪn frˈɔønt dɛɾ ʊns vˈas lˈaɪht mɪt zˈɪn fyːɾ aɪn ˈɛdləs tsˈiːl/","zh":"沃尔夫冈您想要多少都有！我还有呢他怀着一颗高尚的心","en":"EnsembleSuch a friend who lends us something with a sense of a noble goal.","note":"","sourceLineIndex":87},{"id":"mozart-das-musical-08-089","lineIndex":84,"speaker":"","original":"stärkt in Kind und Eltern das Familiengefühl","ipa":"/ʃtɛɾkt ɪn kɪnt ʊnt ɛltɜn das familɪəŋefyl/","zh":"维系了双亲和儿女间的家庭和谐","en":"strengthens the family feeling in child and parents","note":"","sourceLineIndex":89},{"id":"mozart-das-musical-08-090","lineIndex":85,"speaker":"","original":"Weil... eine ehrliche Familie hat es nicht leicht","ipa":"/vaɪl aɪnə eɾlɪçə familɪə hat ɛs nɪçt laɪçt/","zh":"毕竟...一个老实巴交的家庭活得太不容易","en":"Because... an honest family doesn't have it easy","note":"","sourceLineIndex":90},{"id":"mozart-das-musical-08-091","lineIndex":86,"speaker":"","original":"denn mit Fleiß und Anstand wird nur wenig erreicht","ipa":"/dɛn mɪt flaɪs ʊnt anʃtant vɪɾt nuɾ venɪç ɛɾraɪçt/","zh":"勤勤恳恳，老老实实谋生所挣的又屈指可数","en":"because with hard work and decency only little is achieved","note":"","sourceLineIndex":91},{"id":"mozart-das-musical-08-092","lineIndex":87,"speaker":"","original":"Doch mit etwas Chuzpe findet sie einen Mann der die ehrliche und neidliche, tugendhaft-gemütliche christ-katholisch-friedliche Familie......retten kann!","ipa":"/dɔx mɪt ˈɛtvɑːs çˈʊtspə fˈɪndət ziː ˌaɪnən mˈan dɛɾ diː ˈeːɾlɪçə ʊnt nˈaɪtlɪçə tˈuːɡənthˌaftɡəmˈyːtlɪçə kɾˈɪstkatˈoːlɪʃfrˈiːtlɪçə famˈiːlɪə rˈɛtən kˌan/","zh":"他们厚着脸皮抓住了一个人他能为这诚恳老实的，可亲可爱的，道德端正的，平易近人的与世无争的一家...韦伯夫人...雪中送炭！","en":"But with a little chutzpah she finds a man who is honest and envious, virtuous and comfortable Christian-Catholic-peaceful family... Cäcilia...can save!","note":"","sourceLineIndex":92}],"sourceOrder":8,"displayOrder":8},{"order":11,"id":"11-niemand-applaudiert","title":"Niemand applaudiert","titleZh":"无人鼓掌","lines":[{"id":"mozart-das-musical-11-001","lineIndex":1,"speaker":"","original":"Sieben...mehr kamen nicht.","ipa":"/zibən meɾ kɑmən nɪçt/","zh":"七个，再也没有人愿意前来","en":"Seven...no more came.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-11-002","lineIndex":2,"speaker":"","original":"Sieben...kein freundliches Gesicht.","ipa":"/zibən kaɪn frɔøtlɪçəs ɡəzɪçt/","zh":"七个，没有一张友善面孔","en":"Seven...not a happy face.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-11-003","lineIndex":3,"speaker":"","original":"Trotzdem besieg ich sie, krieg ich sie durch die Musik.","ipa":"/tɾɔtsdem bəzik ɪç zi kɾik ɪç zi dʊɐç di muzik/","zh":"尽管如此，我的音乐一定可以征服他们","en":"Nevertheless, I beat them, I get them through the music.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-11-004","lineIndex":4,"speaker":"","original":"Ich klag nicht, verzag nicht.","ipa":"/ɪç klɑk nɪçt fɛɾtsɑk nɪçt/","zh":"我不会沮丧，也不会抱怨","en":"I'm not complaining, don't despair.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-11-005","lineIndex":5,"speaker":"","original":"Auch in Paris lernt ich noch:","ipa":"/aʊx ɪn pɑrɪs lɛɾnt ɪç nɔx/","zh":"就算是在这巴黎，人们也会很快发现","en":"Even in Paris I'm still learning:","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-11-006","lineIndex":6,"speaker":"","original":"Lieben muss man mich doch.","ipa":"/libən mʊs man mɪç dɔx/","zh":"他们爱我的音乐","en":"You have to love me.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-11-007","lineIndex":7,"speaker":"","original":"Wie geht es dir, Mama?","ipa":"/vi ɡet ɛs diɾ mɑmɑ/","zh":"您感觉如何，妈妈","en":"How are you, mom?","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-11-008","lineIndex":8,"speaker":"","original":"Es geht schon, Wolferl.","ipa":"/ɛs ɡet ʃon vɔlfɜl/","zh":"还好，孩子","en":"It's okay, Wolferl.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-11-009","lineIndex":9,"speaker":"","original":"Vier nur, das ist ein Hohn.","ipa":"/fiɾ nuɾ das ɪst aɪn hon/","zh":"四个，多么嘲讽","en":"Only four, that's a mockery.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-11-010","lineIndex":10,"speaker":"","original":"Vier nur, und einer schlicht davon.","ipa":"/fiɾ nuɾ ʊnt aɪnɜ ʃlɪçt dɑfɔn/","zh":"就四个，还有人中途退场","en":"Just four, and one just like that.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-11-011","lineIndex":11,"speaker":"","original":"Trotzdem kommt bald mein Tag.","ipa":"/tɾɔtsdem kɔmt balt maɪn tɑk/","zh":"可我很快就会时来运转","en":"Nevertheless, my day is coming soon.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-11-012","lineIndex":12,"speaker":"","original":"Jeder mag meine Musik.","ipa":"/jedɜ mɑk maɪnə muzik/","zh":"人人都会爱我的音乐！","en":"Everyone likes my music.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-11-013","lineIndex":13,"speaker":"","original":"Ich groll nicht, ich schmoll nicht.","ipa":"/ɪç ɡɾɔl nɪçt ɪç ʃmɔl nɪçt/","zh":"我不会怨恨，也不会恼怒","en":"I don't grudge, I don't sulk.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-11-014","lineIndex":14,"speaker":"","original":"Ich bin nicht schlecht, und kann noch mehr!","ipa":"/ɪç bɪn nɪçt ʃlɛçt ʊnt kan nɔx meɾ/","zh":"我不比谁差，我还有天赋与才华","en":"I'm not bad, and I can do even more!","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-11-015","lineIndex":15,"speaker":"","original":"Hier nur habe ich es schwer.","ipa":"/hiɾ nuɾ hɑbə ɪç ɛs ʃveɾ/","zh":"不过是在这里我时运不济","en":"It's just difficult for me here.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-11-016","lineIndex":16,"speaker":"","original":"Niemand, der applaudiert.","ipa":"/nimant dɛɾ aplaʊdiɾt/","zh":"没人愿意喝彩","en":"No one applauding.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-11-017","lineIndex":17,"speaker":"","original":"Ich werde ignoriert.","ipa":"/ɪç vɛɾdə ɪɡnoriɾt/","zh":"我被无视忽略","en":"I'm being ignored.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-11-018","lineIndex":18,"speaker":"","original":"Ich merke es viel zu spat.","ipa":"/ɪç mɛɾkə ɛs fil tsu ʃpɑt/","zh":"时至如今我才明白","en":"I notice it way too late.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-11-019","lineIndex":19,"speaker":"","original":"Man verschmäht meine Musik.","ipa":"/man fɛɾʃmɛht maɪnə muzik/","zh":"人们对我的音乐嗤之以鼻","en":"People despise my music.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-11-020","lineIndex":20,"speaker":"","original":"Lass uns gehen, Mama.","ipa":"/las ʊns ɡeən mɑmɑ/","zh":"我们走吧，妈妈","en":"Let's go, mom.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-11-021","lineIndex":21,"speaker":"","original":"Mama.","ipa":"/mɑmɑ/","zh":"妈妈","en":"Mom.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-11-022","lineIndex":22,"speaker":"","original":"Mama.","ipa":"/mɑmɑ/","zh":"妈妈","en":"Mom.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-11-023","lineIndex":23,"speaker":"","original":"O Gott, nein.","ipa":"/o ɡɔt naɪn/","zh":"天呐，不。","en":"Oh God, no.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-11-024","lineIndex":24,"speaker":"","original":"Ausgelöscht.","ipa":"/aʊsɡəlœʃt/","zh":"像蜡烛熄灭一样","en":"Obliterated.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-11-025","lineIndex":25,"speaker":"","original":"Wie eine Kerze.","ipa":"/vi aɪnə kɛɾtsə/","zh":"就这样没了","en":"Like a candle.","note":"","sourceLineIndex":25}],"sourceOrder":11,"displayOrder":9},{"order":12,"id":"12-was-fur-ein-grausames-leben","title":"Was für ein grausames Leben","titleZh":"多么残酷的人生","lines":[{"id":"mozart-das-musical-12-002","lineIndex":1,"speaker":"Wolfgang","original":"Und alles geht weiter...","ipa":"/ʊnt aləs ɡet vaɪtɜ/","zh":"而世界照常转动......","en":"And everything goes on...","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-12-003","lineIndex":2,"speaker":"","original":"als wäre nichts geschehn...","ipa":"/als vɛrə nɪçts ɡəʃen/","zh":"仿佛什么都没有发生过......","en":"as if nothing had happened...","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-12-004","lineIndex":3,"speaker":"","original":"Der Wind löscht eine Kerze aus","ipa":"/dɛɾ vɪnt lœʃt aɪnə kɛɾtsə aʊs/","zh":"寒风吹熄了蜡烛","en":"The wind extinguishes a candle","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-12-005","lineIndex":4,"speaker":"","original":"und dunkler wird die Nacht","ipa":"/ʊnt dʊŋklɜ vɪɾt di naxt/","zh":"黑夜越发深重","en":"and the night gets darker","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-12-006","lineIndex":5,"speaker":"","original":"Doch in den Kneipen rollt der Würfel und im Theater wird gelacht.","ipa":"/dɔx ɪn deːn knˈaɪpən rˈɔlt dɛɾ vˈʏɾfəl ʊnt ɪm teːˈɑːtɜ vˌɪɾt ɡəlˈaxt/","zh":"酒馆里人们掷骰豪赌剧院中人们放声大笑","en":"But in the bars the dice rolls and there is laughter in the theater.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-12-008","lineIndex":6,"speaker":"","original":"Die wartenden Kutscher gähnen und vom Turm herab schlägt die Uhr.","ipa":"/diː vˈaɾtəndən kˈʊtʃɜ ɡˈɛːnən ʊnt fɔm tˈʊɐm hɛrˈap ʃlˈɛːkt diː ˈuːɾ/","zh":"钟楼落下午夜的钟声等待的车夫昏昏欲睡","en":"The waiting Kurschers yawn and the clock chimes from the tower.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-12-010","lineIndex":7,"speaker":"","original":"Die Brunnen spei'n Fontänen und die Verliebten machen l'amour.","ipa":"/diː bɾˈʊnən ʃpˈaɪn fˈɔntɛːnən ʊnt diː fɛɾlˈiːptən mˈaxən ˈɛlˈɑmuːɾ/","zh":"喷泉之中水声潺潺相爱的人们耳鬓厮磨","en":"The fountains spew fountains and the lovers make l'amour.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-12-012","lineIndex":8,"speaker":"","original":"Irgendwo wird ein Kind geboren irgendwo wird die Zukunft beschworen.","ipa":"/ɪɾɡˈɛndvoː vˌɪɾt aɪn kˈɪnt ɡəbˈoːrən ɪɾɡˈɛndvoː vˌɪɾt diː tsuːkˈʊnft bəʃvˈoːrən/","zh":"在世界的某处新生命诞生神应许的未来就此展开","en":"A child is born somewhere somewhere the future is conjured up.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-12-014","lineIndex":9,"speaker":"","original":"Das Herz kriegt Narben, und die Seele Flecken bis wir am Schluss unter Schmerzen verrecken.","ipa":"/das hˈɛɾts kɾˈiːkt nˈaɾbən ʊnt diː zˈeːlə flˈɛkən bɪs viːɾ am ʃlˈʊs ˌʊntɜ ʃmˈɛɾtsən fɛɾrˈɛkən/","zh":"心灵覆上伤痕，灵魂沾染污浊直到人生的终点，我们在痛苦中惨死","en":"The heart gets scars and the soul gets stains until we die in pain in the end.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-12-016","lineIndex":10,"speaker":"","original":"Was für ein grausames Leben!","ipa":"/vas fyɾ aɪn ɡɾaʊzɑməs lebən/","zh":"多么残酷的生活","en":"What a cruel life!","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-12-017","lineIndex":11,"speaker":"","original":"Was für eine seltsame Welt!","ipa":"/vas fyɾ aɪnə zɛltzɑmə vɛlt/","zh":"何等怪异的世道","en":"What a strange world!","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-12-018","lineIndex":12,"speaker":"","original":"Wozu wird uns Hoffnung gegeben wenn man dann doch in ein Meer von Dunkelheit fällt?","ipa":"/vˈoːtsuː vˌɪɾt ʊns hˈɔfnʊŋ ɡəɡˈeːbən vˌɛn man dan dɔx ɪn aɪn mˈeːɾ fɔn dˈʊnkəlhˌaɪt fˈɛlt/","zh":"若终将堕入黑暗深渊我们的希望又该寄向何方","en":"Why are we given hope when you then fall into a sea of ​​darkness?","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-12-021","lineIndex":13,"speaker":"","original":"Grad noch hast du geatmet","ipa":"/ɡɾɑt nɔx hast du ɡəatmət/","zh":"就在刚才你还在呼吸","en":"You were just breathing","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-12-022","lineIndex":14,"speaker":"","original":"Du gabst mir Hoffnung und Halt","ipa":"/du ɡɑpst miɾ hɔfnʊŋ ʊnt halt/","zh":"给我希望，给我支持","en":"You gave me hope and support","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-12-023","lineIndex":15,"speaker":"","original":"Du warst voll Wärme und Leben","ipa":"/du vɑɾst fɔl vɛɾmə ʊnt lebən/","zh":"你曾那样温暖有生机","en":"You were full of warmth and life","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-12-024","lineIndex":16,"speaker":"","original":"Und jetzt bist du stumm und kalt","ipa":"/ʊnt jɛtst bɪst du ʃtʊm ʊnt kalt/","zh":"如今却这般冰冷又沉默","en":"And now you are silent and cold","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-12-025","lineIndex":17,"speaker":"","original":"Wir glauben und beten, um nicht zu heulen","ipa":"/viɾ ɡlaʊbən ʊnt betən ʊm nɪçt tsu hɔølən/","zh":"我们虔诚地信仰祈祷，掩盖自己的痛苦","en":"We believe and pray so as not to cry","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-12-026","lineIndex":18,"speaker":"","original":"Wir schlagen und treten holen uns Beulen","ipa":"/viɾ ʃlɑɡən ʊnt tɾetən holən ʊns bɔølən/","zh":"我们徒劳地搏斗命运却落得遍体鳞伤","en":"We hit and kick ourselves with bumps","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-12-027","lineIndex":19,"speaker":"","original":"Wir tragen goldene Spangen und Puderzöpfe","ipa":"/viɾ tɾɑɡən ɡɔldənə ʃpaŋən ʊnt pudɜtsœpfə/","zh":"锦衣华服，绫罗绸缎","en":"We wear gold barrettes and powder braids","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-12-028","lineIndex":20,"speaker":"","original":"und sind doch alle schon Totenköpfe","ipa":"/ʊnt zɪnt dɔx alə ʃon totənkœpfə/","zh":"包裹的却只是行尸走肉","en":"and yet we're all already skulls","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-12-029","lineIndex":21,"speaker":"","original":"Was für ein grausames Leben!","ipa":"/vas fyɾ aɪn ɡɾaʊzɑməs lebən/","zh":"多么残酷的生活","en":"What a cruel life!","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-12-030","lineIndex":22,"speaker":"","original":"Was für eine seltsame Welt!","ipa":"/vas fyɾ aɪnə zɛltzɑmə vɛlt/","zh":"多么怪异的世道","en":"What a strange world!","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-12-031","lineIndex":23,"speaker":"","original":"Es setzt jeder auf das Glück","ipa":"/ɛs zɛtst jedɜ aʊf das ɡlʏk/","zh":"人人对幸福孜孜以求","en":"Everyone relies on luck","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-12-032","lineIndex":24,"speaker":"","original":"und jeder wird geprellt","ipa":"/ʊnt jedɜ vɪɾt ɡəpɾɛlt/","zh":"最终人人都头破血流","en":"and everyone gets bruised","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-12-033","lineIndex":25,"speaker":"","original":"Was für ein sinnloses Fragen wenn man niemals Antwort erhält!","ipa":"/vˈas fyːɾ aɪn zˈɪnloːzəs frˈɑːɡən vˌɛn man nˈiːmɑːls ˈantvɔɾt ɛɾhˈɛlt/","zh":"如果永远得不到回答我们的追问又有何意义","en":"What a pointless question if you never get an answer!","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-12-035","lineIndex":26,"speaker":"","original":"Du glaubst, irgendwo","ipa":"/du ɡlaʊpst ɪɾɡɛndvo/","zh":"你坚信无论到哪里","en":"You think there has to be love somewhere","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-12-036","lineIndex":27,"speaker":"","original":"muss Liebe sein","ipa":"/mʊs libə zaɪn/","zh":"总会有爱","en":"must be love","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-12-037","lineIndex":28,"speaker":"","original":"Doch zuletzt bist du allein","ipa":"/dɔx tsulɛtst bɪst du alaɪn/","zh":"最后你却依旧孤单","en":"But in the end you're alone","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-12-038","lineIndex":29,"speaker":"","original":"Und wir lernen, bis wir dumm sind","ipa":"/ʊnt viɾ lɛɾnən bɪs viɾ dʊm zɪnt/","zh":"博览群书，直到混沌不分","en":"And we learn until we're stupid","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-12-039","lineIndex":30,"speaker":"","original":"und wir reden, bis wir stumm sind","ipa":"/ʊnt viɾ redən bɪs viɾ ʃtʊm zɪnt/","zh":"口若悬河，直到唇焦口燥","en":"and we talk until we're dumb","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-12-040","lineIndex":31,"speaker":"","original":"und wir fressen, bis wir kotzen!","ipa":"/ʊnt viɾ frɛsən bɪs viɾ kɔtsən/","zh":"狼吞虎咽，直到食欲索然","en":"and we eat, until we puke!","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-12-041","lineIndex":32,"speaker":"","original":"Was für ein grausames Leben!","ipa":"/vas fyɾ aɪn ɡɾaʊzɑməs lebən/","zh":"多么残酷的生活","en":"What a cruel life!","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-12-042","lineIndex":33,"speaker":"","original":"Was für eine seltsame Welt!","ipa":"/vas fyɾ aɪnə zɛltzɑmə vɛlt/","zh":"多么怪异的世道","en":"What a strange world!","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-12-043","lineIndex":34,"speaker":"","original":"Es setzt jeder auf das Glück","ipa":"/ɛs zɛtst jedɜ aʊf das ɡlʏk/","zh":"人人对幸福孜孜以求","en":"Everyone relies on luck","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-12-044","lineIndex":35,"speaker":"","original":"und jeder wird geprellt","ipa":"/ʊnt jedɜ vɪɾt ɡəpɾɛlt/","zh":"最终人人都头破血流","en":"and everyone gets bruised","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-12-045","lineIndex":36,"speaker":"","original":"Was für ein sinnloses Fragen wenn man niemals Antwort erhält!","ipa":"/vˈas fyːɾ aɪn zˈɪnloːzəs frˈɑːɡən vˌɛn man nˈiːmɑːls ˈantvɔɾt ɛɾhˈɛlt/","zh":"如果永远得不到回答我们的追问又有何意义","en":"What a pointless question if you never get an answer!","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-12-047","lineIndex":37,"speaker":"","original":"Du glaubst, irgendwo","ipa":"/du ɡlaʊpst ɪɾɡɛndvo/","zh":"你坚信无论到哪里","en":"You think there has to be love somewhere","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-12-048","lineIndex":38,"speaker":"","original":"muss Liebe sein","ipa":"/mʊs libə zaɪn/","zh":"总会有爱","en":"must be love","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-12-049","lineIndex":39,"speaker":"","original":"Erst willst du vor Verzweiflung schrein","ipa":"/ˈeːɾst vɪlst duː fˌɔɾ fɛɾtsvˈaɪflʊŋ ʃrˈaɪn/","zh":"遭遇绝望仰天长啸","en":"First you want to scream in despair in cry out in despair","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-12-051","lineIndex":40,"speaker":"","original":"dann lässt du dich auf Lügen ein und zuletzt bist du allein","ipa":"/dan lˈɛst duː dɪç aʊf lˈyːɡən aɪn ʊnt tsuːlˈɛtst bɪst duː alˈaɪn/","zh":"面对谎言自我欺骗最后你却依旧这样的孤单","en":"then you let go on lies and in the end you are alone","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-12-054","lineIndex":41,"speaker":"","original":"So verflucht allein!","ipa":"/zo fɛɾflʊxt alaɪn/","zh":"这样该死的孤单","en":"So damn alone!","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-12-055","lineIndex":42,"speaker":"","original":"So verflucht allein!","ipa":"/zo fɛɾflʊxt alaɪn/","zh":"这样该死的孤单","en":"So damn alone!","note":"","sourceLineIndex":55}],"sourceOrder":12,"displayOrder":10},{"order":13,"id":"13-in-salzburg-ist-winter","title":"In Salzburg ist Winter","titleZh":"萨尔茨堡正值寒冬","lines":[{"id":"mozart-das-musical-13-001","lineIndex":1,"speaker":"","original":"Ach, Herr Mozart, wieder da!","ipa":"/ax hɛɾ motsaɾt vidɜ dɑ/","zh":"哎呀，莫扎特先生又回来了！","en":"Oh, Mr. Mozart, back!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-13-002","lineIndex":2,"speaker":"","original":"Endlich bescheiden.","ipa":"/ɛntlɪç bəʃaɪdən/","zh":"终于学乖啦","en":"Finally humble.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-13-003","lineIndex":3,"speaker":"","original":"Schluss mit dem Hallodria.","ipa":"/ʃlʊs mɪt dem halɔdɾiɑ/","zh":"浪了一圈回来啦！","en":"Stop the Hallodria.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-13-004","lineIndex":4,"speaker":"","original":"Ja!","ipa":"/jɑ/","zh":"是啊！","en":"Yes!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-13-005","lineIndex":5,"speaker":"","original":"Hochmut kommt bekanntlich vor dem Fall.","ipa":"/hoxmut kɔmt bəkantlɪç fɔɾ dem fal/","zh":"骄傲自满就会摔个狗吃呀！","en":"As we all know, pride comes before a fall.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-13-006","lineIndex":6,"speaker":"","original":"In Salzburg ist Winter.","ipa":"/ɪn zaltsbʊɐk ɪst vɪntɜ/","zh":"萨尔茨堡已是严冬","en":"It's winter in Salzburg.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-13-007","lineIndex":7,"speaker":"","original":"Da darf man nicht empfindlich sein.","ipa":"/dɑ daɾf man nɪçt ɛmpfɪntlɪç zaɪn/","zh":"在这儿你可不能这么矫情","en":"You can't be sensitive about that.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-13-008","lineIndex":8,"speaker":"","original":"In Salzburg ist Winter.","ipa":"/ɪn zaltsbʊɐk ɪst vɪntɜ/","zh":"萨尔茨堡已是严冬","en":"It's winter in Salzburg.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-13-009","lineIndex":9,"speaker":"","original":"Das ist kein Ort für Spinnerein.","ipa":"/das ɪst kaɪn ɔɾt fyɾ ʃpɪneraɪn/","zh":"这儿没地儿给你胡思乱想","en":"This is no place for weirdos.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-13-010","lineIndex":10,"speaker":"","original":"Es ist viel gesünder dem Ärger aus dem Weg zu gehn","ipa":"/ɛsɪst fil ɡəzʏndɜ dem ɛɾɡɜ aʊs dem vek tsu ɡen/","zh":"不要生气，这样身体才会更健康","en":"It is much healthier to avoid trouble","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-13-011","lineIndex":11,"speaker":"","original":"als so wie ein Sünder, um Gnade und Verzeih'n zu flehn.","ipa":"/als zo vi aɪn zʏndɜ ʊm ɡənɑdə ʊnt bɛɾtsaɪhn tsu flen/","zh":"要学会认错，向主教大人求个宽恕","en":"than to beg for mercy and forgiveness like a sinner.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-13-012","lineIndex":12,"speaker":"","original":"In Salzburg ist Winter.","ipa":"/ɪn zaltsbʊɐk ɪst vɪntɜ/","zh":"萨尔茨堡已是严冬","en":"It's winter in Salzburg.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-13-013","lineIndex":13,"speaker":"","original":"Da braucht der mensch ein dickes fell","ipa":"/dɑ bɾaʊxt dɛɾ mɛnʃ aɪn dɪkəs fɛl/","zh":"大家要裹上暖和的毛皮","en":"People need thick skin","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-13-014","lineIndex":14,"speaker":"","original":"In Salzburg ist Winter.","ipa":"/ɪn zaltsbʊɐk ɪst vɪntɜ/","zh":"萨尔茨堡已是严冬","en":"It's winter in Salzburg.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-13-015","lineIndex":15,"speaker":"","original":"Da rennt man besser nicht zu schnell.","ipa":"/dɑ rɛnt man bɛsɜ nɪçt tsu ʃnɛl/","zh":"在外面不要跑得太快","en":"It's better not to run too fast.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-13-016","lineIndex":16,"speaker":"","original":"Das Eis ist glatt, der Schnee ist harsch.","ipa":"/das aɪs ɪst ɡlat dɛɾ ʃne ɪst haɾʃ/","zh":"结的冰很滑，积的雪很厚","en":"The ice is slippery, the snow is harsh.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-13-017","lineIndex":17,"speaker":"","original":"Der Frost ist streng, der Fürst ist harsch.","ipa":"/dɛɾ frɔst ɪst ʃtɾɛŋ dɛɾ fyɾst ɪst haɾʃ/","zh":"霜冻那么冷，主教又那么苛刻","en":"The frost is severe, the prince is harsh.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-13-018","lineIndex":18,"speaker":"","original":"Und wer sich für was Bess'res hält rutscht aus und fällt auf seinen Arsch.","ipa":"/ʊnt vˈeːɾ zɪç fyːɾ vˈas bˈɛsrəs hˈɛlt rˈʊtʃt ˌaʊs ʊnt fˈɛlt aʊf zˌaɪnən ˈaɾʃ/","zh":"觉得自己高人一等的人啊冲出去肯定会摔得开花！","en":"And whoever thinks they're better will slip and fall on their ass.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-13-020","lineIndex":19,"speaker":"Schikaneder","original":"Bravo! Ich sehe, man liebt das Theater in dieser Stadt.","ipa":"/ʃikanedɜ bɾɑvo ɪç zeə man lipt das teɑtɜ ɪn dizɜ ʃtat/","zh":"席卡内德太好了，太好了，太好了，看来这座城市里的人都很爱看戏嘛","en":"SchikanederBravo! I see that people love the theater in this city.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-13-021","lineIndex":20,"speaker":"","original":"Vorzüglich! Benissimo! Ausgezeichnet, ausgezeichnet!","ipa":"/foɾtsyklɪç bənɪsimo aʊsɡətsaɪçnət aʊsɡətsaɪçnət/","zh":"精彩绝伦！异彩纷呈！无与伦比！","en":"Excellent! Benissimo! Excellent, excellent!","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-13-022","lineIndex":21,"speaker":"","original":"Freunde, Mitbürger, Römer","ipa":"/frɔøndə mɪtbʏɾɡɜ rømɜ/","zh":"“各位朋友，各位同胞，各位罗马人”","en":"Friends, fellow citizens, Romans","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-13-023","lineIndex":22,"speaker":"","original":"Ich verkünde Euch große Freude.","ipa":"/ɪç fɛɾkʏndə ɔøç ɡɾosə frɔødə/","zh":"我有一件大好事要宣布","en":"I announce to you great joy.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-13-024","lineIndex":23,"speaker":"","original":"Ich habe mich entschlossen heute Abend in Salzburg ein Gastspiel zu geben.","ipa":"/ɪç hɑːbə mɪç ɛntʃlˈɔsən hˈɔøtə ˈɑːbənt ɪn zˈaltsbʊɐk aɪn ɡˈastʃpiːl tsuː ɡˈeːbən/","zh":"我已经决定今晚，在萨尔茨堡这儿，给你们举办一场友情演出","en":"I have decided to give a guest performance in Salzburg this evening.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-13-026","lineIndex":24,"speaker":"Wolfgang","original":"Bravo!","ipa":"/vɔlfɡaŋ bɾɑvo/","zh":"沃尔夫冈太棒了！","en":"WolfgangBravo!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-13-027","lineIndex":25,"speaker":"Schikaneder","original":"Was ist? Ach so! Ihr wisst nicht, wer ich bin.","ipa":"/ʃikanedɜ vas ɪst ax zo iɾ vɪst nɪçt veɾ ɪç bɪn/","zh":"席卡内德怎么了？哦！你们还不知道我是谁","en":"SchikanederWhat is it? Oh right! You don't know who I am.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-13-028","lineIndex":26,"speaker":"","original":"Nun, vor Euch steht kein Geringerer, als der große Emanuel Schikaneder.","ipa":"/nun fɔɾ ɔøç ʃtet kaɪn ɡərɪŋərɜ als dɛɾ ɡɾosə emanuəl ʃikanedɜ/","zh":"现在，站在你们面前的，正是伟大的埃曼纽埃尔·席卡内德","en":"Well, before you stands none other than the great Emanuel Schikaneder.","note":"","sourceLineIndex":28}],"sourceOrder":13,"displayOrder":11},{"order":14,"id":"14-ein-bissel-fur-s-hirn-und-ein-bissel-fur-s-herz","title":"Ein bissel für's Hirn und ein bissel für's Herz","titleZh":"给头脑一点，也给心一点","lines":[{"id":"mozart-das-musical-14-002","lineIndex":1,"speaker":"Emanuel Schikaneder","original":"Meine Kunst liebt den Applaus","ipa":"/maɪnə kʊnst lipt den aplaʊs/","zh":"我的艺术热爱掌声","en":"My art loves applause","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-14-003","lineIndex":2,"speaker":"","original":"Sie will allen gefallen","ipa":"/zi vɪl alən ɡəfalən/","zh":"渴望的是大众喜爱","en":"It wants to please everyone","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-14-004","lineIndex":3,"speaker":"","original":"Mein Ehrgeiz ist","ipa":"/maɪn eɾɡaɪts ɪst/","zh":"我的抱负是","en":"My ambition is","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-14-005","lineIndex":4,"speaker":"","original":"ein volles Haus","ipa":"/aɪn fɔləs haʊs/","zh":"座无虚席","en":"a full house","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-14-006","lineIndex":5,"speaker":"","original":"Mir geht es um das Publikum","ipa":"/miːɾ ɡˈeːt ɛs ʊm das pˈʊbliːkˌʊm/","zh":"我的追求是叫好叫座","en":"I care about the audience","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-14-008","lineIndex":6,"speaker":"","original":"Man sagt, Unterhaltung","ipa":"/man zɑkt ʊntɜhaltʊŋ/","zh":"人们说，伟大的艺术家","en":"They say that entertainment","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-14-009","lineIndex":7,"speaker":"","original":"sei nicht das Hehrste","ipa":"/zaɪ nɪçt das heɾstə/","zh":"创作不应是","en":"is not the highest","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-14-010","lineIndex":8,"speaker":"","original":"für einen grossen Künstler","ipa":"/fyɾ aɪnən ɡɾɔsən kʏnstlɜ/","zh":"为了消遣","en":"for a great artist","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-14-011","lineIndex":9,"speaker":"","original":"Doch glauben Sie mir:","ipa":"/dɔx ɡlaʊbən zi miɾ/","zh":"但请您相信我：","en":"But believe me:","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-14-012","lineIndex":10,"speaker":"","original":"Es ist das Schwerste","ipa":"/ɛsɪst das ʃveɾstə/","zh":"这才是最难达到的目标","en":"It's the hardest thing","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-14-013","lineIndex":11,"speaker":"","original":"Selbst wenn man versteht","ipa":"/zɛlpst vɛn man fɛɾʃtet/","zh":"哪怕已经知道","en":"Even if you understand","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-14-014","lineIndex":12,"speaker":"","original":"wie es geht","ipa":"/vi ɛs ɡet/","zh":"其中的诀窍","en":"how it works","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-14-015","lineIndex":13,"speaker":"","original":"Ein bissel für's Hirn und ein bissel für's Herz","ipa":"/aɪn bɪsəl fyɾs hɪɾn ʊnt aɪn bɪsəl fyɾs hɛɾts/","zh":"有点思想深度，有点心灵震撼","en":"A little bit for your brain and a little bit for your heart","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-14-016","lineIndex":14,"speaker":"","original":"ein bissel Krawall und Spektakel","ipa":"/aɪn bɪsəl kɾɑval ʊnt ʃpɛktakəl/","zh":"写点热热闹闹的场面，轰轰烈烈的事件","en":"a bit of riot and spectacle","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-14-017","lineIndex":15,"speaker":"","original":"Ein heftiger Schmäh, ein deftiger Scherz","ipa":"/aɪn hɛftɪɡɜ ʃmɛ aɪn dɛftɪɡɜ ʃɛɾts/","zh":"有天花乱坠的客套，也有原汁原味的土话","en":"A violent insult, a hearty joke","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-14-018","lineIndex":16,"speaker":"","original":"Ein Schurke und ein Held.","ipa":"/aɪn ʃʊɐkə ʊnt aɪn hɛlt/","zh":"来一个反派，来一位英雄","en":"A villain and a hero.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-14-019","lineIndex":17,"speaker":"","original":"Ein bissel für's Aug, und ein bissel für's Ohr","ipa":"/aɪn bɪsəl fyɾs aʊk ʊnt aɪn bɪsəl fyɾs oɾ/","zh":"给点视觉盛宴，给点听觉享受","en":"A little for the eye, and a little for the ear","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-14-020","lineIndex":18,"speaker":"","original":"Ein bissel Klamauk und Mirakel","ipa":"/aɪn bɪsəl klɑmaʊk ʊnt mirakəl/","zh":"来点轰动和奇迹","en":"A little slapstick and miracle","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-14-021","lineIndex":19,"speaker":"","original":"Kulissen, Kostüme, Licht und Dekor","ipa":"/kulɪsən kɔʃtymə lɪçt ʊnt dekoɾ/","zh":"布景，戏服，灯光，装饰","en":"Sets, costumes, lighting and decor","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-14-022","lineIndex":20,"speaker":"","original":"und ein Schauspieler, der gefällt","ipa":"/ʊnt aɪn ʃaʊʃpilɜ dɛɾ ɡəfɛlt/","zh":"还有一位广受喜爱的演员","en":"and an actor who likes","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-14-023","lineIndex":21,"speaker":"","original":"Wie ich!","ipa":"/vi ɪç/","zh":"就像我！","en":"Like me!","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-14-024","lineIndex":22,"speaker":"","original":"Liebe, Lüge, Leid und List","ipa":"/libə lyɡə laɪt ʊnt lɪst/","zh":"爱情，谎言，痛苦，诡计","en":"Love, lies, suffering and cunning","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-14-025","lineIndex":23,"speaker":"","original":"und Wunder, die geschehn","ipa":"/ʊnt vʊndɜ di ɡəʃen/","zh":"和成真了的奇迹","en":"and miracles that happen","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-14-026","lineIndex":24,"speaker":"","original":"Wie das Leben wirklich ist","ipa":"/vi das lebən vɪɾklɪç ɪst/","zh":"若只是生活原原本本的模样","en":"What life is really like","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-14-027","lineIndex":25,"speaker":"","original":"das will doch keiner sehn","ipa":"/das vɪl dɔx kaɪnɜ zen/","zh":"才不会有人想看","en":"no one wants to see that","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-14-028","lineIndex":26,"speaker":"","original":"Der Saal versinkt im Dunkeln","ipa":"/dɛɾ zɑl fɛɾzɪŋkt ɪm dʊnkəln/","zh":"坐席灯光变暗","en":"The hall sinks into darkness","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-14-029","lineIndex":27,"speaker":"","original":"Die Rampenlichter funkeln","ipa":"/di rampənlɪçtɜ fʊŋkəln/","zh":"舞台灯光闪耀","en":"The spotlights sparkle","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-14-030","lineIndex":28,"speaker":"","original":"Und dann fängt das Theater an!","ipa":"/ʊnt dan fˈɛŋt das teːˈɑːtɜ ˈan/","zh":"好戏就此拉开序幕！","en":"And then the drama begins!","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-14-032","lineIndex":29,"speaker":"","original":"Ein bissel für's Hirn und ein bissel für's Herz","ipa":"/aɪn bɪsəl fyɾs hɪɾn ʊnt aɪn bɪsəl fyɾs hɛɾts/","zh":"有点思想深度，有点心灵震撼","en":"A little bit for your brain and a little bit for your heart","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-14-033","lineIndex":30,"speaker":"","original":"ein bissel Triumph und Debakel","ipa":"/aɪn bɪsəl tɾiʊmf ʊnt debakəl/","zh":"有大获全胜，有一败千里","en":"a bit of triumph and debacle","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-14-034","lineIndex":31,"speaker":"","original":"Ein Sommernachtstraum und die Iden des März","ipa":"/aɪn zɔmɜnaxtstɾaʊm ʊnt di idən dɛs mɛɾts/","zh":"仲夏夜之幻梦，三月望日之预言","en":"A Midsummer Night's Dream and the Ides of March","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-14-035","lineIndex":32,"speaker":"Kurz","original":"Was euch unterhält","ipa":"/kʊɐts vas ɔøç ʊntɜhɛlt/","zh":"总之，能让你们得到消遣","en":"In short: What entertains you","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-14-036","lineIndex":33,"speaker":"","original":"Ein schauriger Spuk und ein trauriger Prinz","ipa":"/aɪn ʃaʊrɪɡɜ ʃpuk ʊnt aɪn tɾaʊrɪɡɜ pɾɪnts/","zh":"可怕的幽灵，忧郁的王子","en":"A spooky ghost and a sad prince","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-14-037","lineIndex":34,"speaker":"","original":"Verheissung und dunkles Orakel","ipa":"/fɛɾhaɪsʊŋ ʊnt dʊŋkləs orakəl/","zh":"吉兆及凶兆","en":"Promise and dark oracle","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-14-038","lineIndex":35,"speaker":"","original":"Ein Mischung aus Pfeffer und Pfefferminz","ipa":"/aɪn mɪʃʊŋ aʊs pfɛfɜ ʊnt pfɛfɜmɪnts/","zh":"胡椒和薄荷混杂的气味","en":"A mixture of pepper and peppermint","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-14-039","lineIndex":36,"speaker":"","original":"So wie es euch gefällt für's Geld","ipa":"/zoː viː ɛs ɔøç ɡəfˈɛlt fˈyːɾs ɡˈɛlt/","zh":"真是“皆大欢喜”能赚得盆满钵满","en":"The way you like it for the money","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-14-041","lineIndex":37,"speaker":"","original":"Ich erzähl euch ja nur","ipa":"/ɪç ɛɾtsɛl ɔøç jɑ nuɾ/","zh":"我只是描述了","en":"I'm just telling you","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-14-042","lineIndex":38,"speaker":"","original":"was ihr alle längst wisst","ipa":"/vas iɾ alə lɛŋst vɪst/","zh":"你们都耳熟能详的事","en":"what you all have known for a long time","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-14-043","lineIndex":39,"speaker":"","original":"Denn sicher habt ihr so wie ich den Verdacht","ipa":"/dɛn zˈɪçɜ hˈɑːpt iːɾ zoː viː ɪç deːn fɛɾdˈaxt/","zh":"因为你们肯定和我一样持有这般想法","en":"Because I'm sure you have the same suspicion as I do","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-14-045","lineIndex":40,"speaker":"","original":"dass die Welt","ipa":"/das di vɛlt/","zh":"世界是一个","en":"that the world","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-14-046","lineIndex":41,"speaker":"","original":"eine riesige Bühne ist","ipa":"/aɪnə rizɪɡə bynə ɪst/","zh":"巨大的舞台","en":"is a huge stage","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-14-047","lineIndex":42,"speaker":"","original":"auf der nur Erfolg hat","ipa":"/aʊf dɛɾ nuɾ ɛɾfɔlk hat/","zh":"站在上面","en":"on which only success","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-14-048","lineIndex":43,"speaker":"","original":"der weiss, wie man's macht","ipa":"/dɛɾ vaɪs vi mɑns maxt/","zh":"只有知道门道的人才能功成名就","en":"who knows how to do it","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-14-049","lineIndex":44,"speaker":"","original":"Drum gebt acht:","ipa":"/dɾʊm ɡept axt/","zh":"那就留心了：","en":"So be careful:","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-14-050","lineIndex":45,"speaker":"","original":"Sie woll'n ein bissel für's Hirn und ein bissel für's Herz","ipa":"/ziː vˈɔln aɪn bˈɪsəl fˈyːɾs hˈɪɾn ʊnt aɪn bˈɪsəl fˈyːɾs hˈɛɾts/","zh":"他们想要点思想深度有点心灵震撼","en":"You want a little for your brain and a little for your heart","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-14-052","lineIndex":46,"speaker":"","original":"ein bissel Krawall und Spektakel","ipa":"/aɪn bɪsəl kɾɑval ʊnt ʃpɛktakəl/","zh":"要点轰动和奇迹","en":"a bit of riot and spectacle","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-14-053","lineIndex":47,"speaker":"","original":"Ein bissel für's Aug, und ein bissel für's Ohr","ipa":"/aɪn bɪsəl fyɾs aʊk ʊnt aɪn bɪsəl fyɾs oɾ/","zh":"来点视觉盛宴，来点听觉享受","en":"A little for the eye, and a little for the ear","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-14-054","lineIndex":48,"speaker":"","original":"Kulissen, Kostüme, Licht und Dekor","ipa":"/kulɪsən kɔʃtymə lɪçt ʊnt dekoɾ/","zh":"布景，戏服，灯光，装饰","en":"Sets, costumes, lighting and decor","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-14-055","lineIndex":49,"speaker":"","original":"ein heftiger Schmäh, ein deftiger Scherz","ipa":"/aɪn hɛftɪɡɜ ʃmɛ aɪn dɛftɪɡɜ ʃɛɾts/","zh":"天花乱坠的客套，原汁原味的土话","en":"a violent insult, a hearty joke","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-14-056","lineIndex":50,"speaker":"","original":"ein bissel für's Hirn und für's Herz","ipa":"/aɪn bɪsəl fyɾs hɪɾn ʊnt fyɾs hɛɾts/","zh":"有点思想深度，有点心灵震撼","en":"a little for the brain and for the heart","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-14-057","lineIndex":51,"speaker":"Kurzum","original":"Alles, was für gutes Geld","ipa":"/kʊɐtsʊm aləs vas fyɾ ɡutəs ɡɛlt/","zh":"总之，一切能票房大卖的","en":"In short: everything that entertains for good money","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-14-058","lineIndex":52,"speaker":"","original":"unterhält, und ein Schauspieler","ipa":"/ʊntɜhɛlt ʊnt aɪn ʃaʊʃpilɜ/","zh":"元素，还有一位","en":"and an actor","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-14-059","lineIndex":53,"speaker":"","original":"der der Welt gefällt","ipa":"/dɛɾ dɛɾ vɛlt ɡəfɛlt/","zh":"人见人爱的演员","en":"who pleases the world","note":"","sourceLineIndex":59},{"id":"mozart-das-musical-14-060","lineIndex":54,"speaker":"","original":"Wie ich!","ipa":"/vi ɪç/","zh":"就像我！","en":"Like me!","note":"","sourceLineIndex":60}],"sourceOrder":14,"displayOrder":12},{"order":16,"id":"16-gold-von-den-sternen","title":"Gold von den Sternen","titleZh":"来自群星的黄金","lines":[{"id":"mozart-das-musical-16-001","lineIndex":1,"speaker":"","original":"Es war einmal ein König der lebte mit seinem Sohn in einem Schloss das lag in einem Zaubergarten.","ipa":"/ɛs vɑːɾ ˈaɪnmˌɑːl aɪn kˈøːnɪç dɛɾ lˈeːptə mɪt zˌaɪnəm zˈoːn ɪn ˌaɪnəm ʃlˈɔs das lˈɑːk ɪn ˌaɪnəm tsˈaʊbɜɡˌaɾtən/","zh":"从前有一位国王他和他的儿子一起住在城堡里城堡里还有魔法花园。","en":"Once upon a time there was a king who lived with his son in a castle that was in a magical garden.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-16-005","lineIndex":2,"speaker":"","original":"Und weil der König alt und von der Welt enttäuscht war","ipa":"/ʊnt vaɪl dɛɾ kønɪç alt ʊnt fɔn dɛɾ vɛlt ɛnttɔøʃt vɑɾ/","zh":"因为国王年事已高，且对外界大失所望","en":"And because the king was old and disappointed with the world","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-16-006","lineIndex":3,"speaker":"","original":"war die Mauer sehr hoch","ipa":"/vɑɾ di maʊɜ zeɾ hox/","zh":"所以宫殿院墙高耸","en":"the wall was very high","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-16-007","lineIndex":4,"speaker":"","original":"und das Tor immer zugesperrt.","ipa":"/ʊnt das toɾ ɪmɜ tsuɡɛʃpɜt/","zh":"大门也长年紧锁。","en":"and the gate was always locked.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-16-008","lineIndex":5,"speaker":"","original":"Es gibt, sprach er König keinen besseren Ort.","ipa":"/ɛs ɡˈiːpt ʃpɾˈɑːx ɛɾ kˈøːnɪç kˈaɪnən bˈɛsərən ˈɔɾt/","zh":"“世上再没有，” 国王说“再没有比这更好的地方了。”","en":"There is, said he king no better place.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-16-010","lineIndex":6,"speaker":"","original":"Doch die Sehnsucht sprach zum Prinzen:","ipa":"/dɔx di zenzuxt ʃpɾɑx tsʊm pɾɪntsən/","zh":"但是内心的渴望告诉王子：","en":"But the longing spoke to the prince:","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-16-011","lineIndex":7,"speaker":"","original":"Du musst hier fort!","ipa":"/du mʊst hiɾ fɔɾt/","zh":"你必须前进！","en":"You have to leave here!","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-16-012","lineIndex":8,"speaker":"","original":"Manchmal nachts fällt Gold von den Sternen.","ipa":"/mançmɑl naxts fɛlt ɡɔlt fɔn den ʃtɛɾnən/","zh":"有时夜晚 星星会洒落金子","en":"Manchmal nachts fällt Gold von den Sternen.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-16-013","lineIndex":9,"speaker":"","original":"Du kannst es finden da draußen, wo noch keiner war.","ipa":"/duː kˌanst ɛs fˈɪndən dɑː dɾˈaʊsən vˌoː nɔx kˈaɪnɜ vɑːɾ/","zh":"你会找到它们在那远方，那些未有人涉足的地方。","en":"Du kannst es finden da draußen, wo noch keiner war.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-16-015","lineIndex":10,"speaker":"","original":"Sein heißt Werden, Leben heißt Lernen.","ipa":"/zaɪn haɪst vɛɾdən lebən haɪst lɛɾnən/","zh":"想生存，须成长，欲生活，须学习","en":"Sein heißt Werden, Leben heißt Lernen.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-16-016","lineIndex":11,"speaker":"","original":"Wenn du das Gold von den Sternen suchst muss du allein hinaus in die Gefahr.","ipa":"/vˌɛn duː das ɡˈɔlt fɔn deːn ʃtˈɛɾnən zˈuːxst mˈʊs duː alˈaɪn hɪnˈaʊs ɪn diː ɡəfˈɑːɾ/","zh":"若你想寻得星星上的金子你必须独自踏上旅程，面对危险。","en":"Wenn du das Gold von den Sternen suchst muss du allein hinaus in die Gefahr.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-16-018","lineIndex":12,"speaker":"","original":"Da draußen wirst du scheitern sprach der Vater zum Sohn.","ipa":"/dɑː dɾˈaʊsən vˌɪɾst duː ʃˈaɪtɜn ʃpɾˈɑːx dɛɾ fˈɑːtɜ tsʊm zˈoːn/","zh":"“你在外面会一无所获，”父亲对儿子说道","en":"Da draußen wirst du scheitern sprach der Vater zum Sohn.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-16-020","lineIndex":13,"speaker":"","original":"Genau wie ich.","ipa":"/ɡənaʊ vi ɪç/","zh":"“像我一样","en":"Just like me.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-16-021","lineIndex":14,"speaker":"","original":"Drum bleib in unserm Zaubergarten!","ipa":"/dɾʊm blaɪp ɪn ʊnzɜm tsaʊbɜɡaɾtən/","zh":"留在我们的魔法花园吧！”","en":"Drum bleib in unserm Zaubergarten!","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-16-022","lineIndex":15,"speaker":"","original":"Ich geb dir Sicherheit.","ipa":"/ɪç ɡep diɾ zɪçɜhaɪt/","zh":"“我会保护你","en":"I give you security.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-16-023","lineIndex":16,"speaker":"","original":"Nur um dich zu beschützen ist die Mauer so hoch und das Tor immer zugesperrt.","ipa":"/nˈuːɾ ʊm dɪç tsuː bəʃˈʏtsən ɪst diː mˈaʊɜ zoː hˈoːx ʊnt das tˈoːɾ ˈɪmɜ tsˈuːɡɛʃpɜt/","zh":"为了给你安全感我把围墙砌得这么高大门也一直紧锁。”","en":"Just to protect you the wall is so high and the gate was always locked.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-16-026","lineIndex":17,"speaker":"","original":"Die Liebe des Königs sprach aus jedem Wort.","ipa":"/diː lˈiːbə dɛs kˈøːnɪçs ʃpɾˈɑːx ˌaʊs jˈeːdəm vˈɔɾt/","zh":"国王的爱在他的字里行间流露着。","en":"The love of the king spoke in every word.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-16-028","lineIndex":18,"speaker":"","original":"Doch die Sehnsucht sprach zum Prinzen:","ipa":"/dɔx di zenzuxt ʃpɾɑx tsʊm pɾɪntsən/","zh":"但是内心的渴望告诉王子：","en":"But the longing spoke to the prince:","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-16-029","lineIndex":19,"speaker":"","original":"Du musst hier fort!","ipa":"/du mʊst hiɾ fɔɾt/","zh":"你必须前进！","en":"You have to leave here!","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-16-030","lineIndex":20,"speaker":"","original":"Am Rand der Welt fällt Gold von den Sternen.","ipa":"/am rant dɛɾ vɛlt fɛlt ɡɔlt fɔn den ʃtɛɾnən/","zh":"在世界的尽头星星上会洒落金子","en":"Am Rand der Welt fällt Gold von den Sternen.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-16-031","lineIndex":21,"speaker":"","original":"Und wer es findet erreicht, was unerreichbar war.","ipa":"/ʊnt vˈeːɾ ɛs fˈɪndət ɛɾrˈaɪçt vˈas ˈʊnɛɾrˌaɪçbɑːɾ vɑːɾ/","zh":"若要找到它们便要到达那还未有人涉足的远方。","en":"Und wer es findet erreicht, was unerreichbar war.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-16-033","lineIndex":22,"speaker":"","original":"Sein heißt Werden, Leben heißt Lernen.","ipa":"/zaɪn haɪst vɛɾdən lebən haɪst lɛɾnən/","zh":"想生存，须成长，欲生活，须学习","en":"Sein heißt Werden, Leben heißt Lernen.","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-16-034","lineIndex":23,"speaker":"","original":"Wenn du das Gold von den Sternen suchst musst du allein hinaus in die Gefahr.","ipa":"/vˌɛn duː das ɡˈɔlt fɔn deːn ʃtˈɛɾnən zˈuːxst mˈʊst duː alˈaɪn hɪnˈaʊs ɪn diː ɡəfˈɑːɾ/","zh":"若你想寻得星星上的金子你必须独自踏上旅程，面对危险。","en":"Wenn du das Gold von den Sternen suchst you have to go out into danger alone.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-16-036","lineIndex":24,"speaker":"","original":"Lieben heißt manchmal loslassen können.","ipa":"/libən haɪst mançmɑl lɔslasən kœnən/","zh":"爱，是有时能够放手","en":"Sometimes loving means being able to let go.","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-16-037","lineIndex":25,"speaker":"","original":"Lieben heißt manchmal vom Geliebten sich trennen.","ipa":"/libən haɪst mançmɑl fɔm ɡəliptən zɪç tɾɛnən/","zh":"爱，是有时要与珍爱之人分离","en":"Lieben heißt manchmal vom Geliebten sich trennen.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-16-038","lineIndex":26,"speaker":"","original":"Lieben heißt, nicht nach dem eigen Glück fragen.","ipa":"/libən haɪst nɪçt nɑx dem aɪɡən ɡlʏk frɑɡən/","zh":"爱，是不止考虑自己的幸福","en":"Loving means not asking about your own happiness.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-16-039","lineIndex":27,"speaker":"","original":"Lieben heißt unter Tränen zu sagen:","ipa":"/libən haɪst ʊntɜ tɾɛnən tsu zɑɡən/","zh":"爱，是含着泪说：","en":"Lieben heißt unter Tränen zu sagen:","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-16-040","lineIndex":28,"speaker":"","original":"Weit von hier fällt Gold von den Sternen.","ipa":"/vaɪt fɔn hiɾ fɛlt ɡɔlt fɔn den ʃtɛɾnən/","zh":"遥远的彼方，会有星星上的金子落下","en":"Weit von hier fällt Gold von den Sternen.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-16-041","lineIndex":29,"speaker":"","original":"Du kannst es finden da draußen, wo noch keiner war.","ipa":"/duː kˌanst ɛs fˈɪndən dɑː dɾˈaʊsən vˌoː nɔx kˈaɪnɜ vɑːɾ/","zh":"你若要寻得它们便要到达那还未有人涉足的远方。","en":"Du kannst es finden da draußen, wo noch keiner war.","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-16-043","lineIndex":30,"speaker":"","original":"Sein heißt Werden, Leben heißt Lernen.","ipa":"/zaɪn haɪst vɛɾdən lebən haɪst lɛɾnən/","zh":"想生存，须成长，欲生活，须学习","en":"Sein heißt Werden, Leben heißt Lernen.","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-16-044","lineIndex":31,"speaker":"","original":"Wenn du das Gold von den Sternen suchst","ipa":"/vɛn du das ɡɔlt fɔn den ʃtɛɾnən zuxst/","zh":"若你想寻得星星上的金子","en":"Wenn du das Gold von den Sternen suchst","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-16-045","lineIndex":32,"speaker":"","original":"musst du fort von Zuhaus und nur auf dich gestellt allein hinaus in die Welt voll Gefahr.","ipa":"/mˈʊst duː fˈɔɾt fɔn tsuːhˈaʊs ʊnt nˈuːɾ aʊf dɪç ɡəʃtˈɛlt alˈaɪn hɪnˈaʊs ɪn diː vˈɛlt fˈɔl ɡəfˈɑːɾ/","zh":"你必须离家远行摆在你面前的只有一条路那就是独自踏上充满荆棘的冒险之路","en":"you have to leave home and leave yourself alone out into the world full of danger.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-16-048","lineIndex":33,"speaker":"","original":"In die Welt voll Gefahr.","ipa":"/ɪn di vɛlt fɔl ɡəfɑɾ/","zh":"充满荆棘的冒险之路。","en":"Into the world full of danger.","note":"","sourceLineIndex":48}],"sourceOrder":16,"displayOrder":13},{"order":17,"id":"17-niemand-liebt-dich-so-wie-ich-reprise","title":"Niemand liebt dich so wie ich (Reprise)","titleZh":"没人比我更爱你（重唱）","lines":[{"id":"mozart-das-musical-17-001","lineIndex":1,"speaker":"Wolfgang","original":"Du bleibst!","ipa":"/vɔlfɡaŋ du blaɪpst/","zh":"你给我留下！","en":"WolfgangYou stay!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-17-002","lineIndex":2,"speaker":"Leopold","original":"Du hast mir einen Schuldvertrag unterschrieben.","ipa":"/leopɔlt du hast miɾ aɪnən ʃʊldfɜtɾɑk ʊntɜʃribən/","zh":"你已经签下了一份债券契约！","en":"LeopoldYou signed a contract of debt to me.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-17-003","lineIndex":3,"speaker":"Wolfgang","original":"Aber in Wien verdiene ich in einem Monat mehr als hier in einem Jahr.","ipa":"/vɔlfɡaŋ ɑbɜ ɪn vin fɛɾdinə ɪç ɪn aɪnəm monɑt meɾ als hiɾ ɪn aɪnəm jɑɾ/","zh":"但是我在维也纳一个月挣的钱比在这里一年挣得都要多啊！","en":"WolfgangBut in Vienna I earn more in a month than I earn here in a year.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-17-004","lineIndex":4,"speaker":"Leopold","original":"Das hast du auch von Paris gedacht.","ipa":"/leopɔlt das hast du aʊx fɔn pɑrɪs ɡədaxt/","zh":"你去巴黎的时候也是这么认为的","en":"LeopoldThat's what you thought of Paris too.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-17-005","lineIndex":5,"speaker":"爸爸","original":"Und dann hat es deine Mutter das Leben gekostet","ipa":"/ʊnt dan hat ɛs daɪnə mʊtɜ das lebən ɡəkɔstət/","zh":"但是你却赔上了你妈的性命！","en":"And then it cost your mother her life","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-17-006","lineIndex":6,"speaker":"爸爸","original":"mich meine Ersparnisse","ipa":"/mɪç maɪnə ɛɾʃpaɾnɪsə/","zh":"和我的积蓄","en":"me my savings","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-17-007","lineIndex":7,"speaker":"爸爸","original":"und unsere Familie den guten Ruf!","ipa":"/ʊnt ʊnzrə familɪə den ɡutən ruf/","zh":"还有我们家族的名誉！","en":"and our family's good reputation!","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-17-008","lineIndex":8,"speaker":"Wolfgang","original":"Nur in Wien kann ich groß werden, Papa","ipa":"/vɔlfɡaŋ nuɾ ɪn vin kan ɪç ɡɾos vɛɾdən pɑpɑ/","zh":"只有在维也纳我才能出人头地啊爸爸！","en":"WolfgangOnly in Vienna can I grow up, dad","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-17-009","lineIndex":9,"speaker":"莫扎特","original":"Ich werde, dass du Stolz sein kannst auf mich.","ipa":"/ɪç vɛɾdə das du ʃtɔlts zaɪn kanst aʊf mɪç/","zh":"你会为我而感到骄傲的","en":"I will so that you can be proud of me.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-17-010","lineIndex":10,"speaker":"Leopold","original":"Du bleibst hier!","ipa":"/leopɔlt du blaɪpst hiɾ/","zh":"你就给我呆在萨尔茨堡！","en":"LeopoldYou stay here!","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-17-011","lineIndex":11,"speaker":"Wolfgang","original":"Ich hasse Salzburg.","ipa":"/vɔlfɡaŋ ɪç hasə zaltsbʊɐk/","zh":"我恨萨尔茨堡！","en":"WolfgangI hate Salzburg.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-17-012","lineIndex":12,"speaker":"Nannerl","original":"Bitte, Wolfgang, sag das nicht.","ipa":"/nanɜl bɪtə vɔlfɡaŋ zɑk das nɪçt/","zh":"沃夫冈，别这么说...","en":"NannerlPlease, Wolfgang, don't say that.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-17-013","lineIndex":13,"speaker":"Wolfgang","original":"Und wenn ich doch abreise?","ipa":"/vɔlfɡaŋ ʊnt vɛn ɪç dɔx apɾaɪzə/","zh":"如果我一定要去呢？","en":"WolfgangAnd if I do leave?","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-17-014","lineIndex":14,"speaker":"Leopold","original":"Das würde mich töten.","ipa":"/leopɔlt das vʏɾdə mɪç tøtən/","zh":"你这和杀了我有什么区别？","en":"LeopoldThat would kill me.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-17-015","lineIndex":15,"speaker":"Nannerl","original":"Weißt du noch? Du hast immer gesagt:","ipa":"/nanɜl vaɪst du nɔx du hast ɪmɜ ɡəzɑkt/","zh":"你还记得吗？你以前一直说","en":"NannerlDo you remember? You always said:","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-17-016","lineIndex":16,"speaker":"姐姐","original":"Nach dem lieben Gott kommt gleich der Papa","ipa":"/nɑx dem libən ɡɔt kɔmt ɡlaɪç dɛɾ pɑpɑ/","zh":"除了上帝最爱你的人就是爸爸","en":"After God comes daddy","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-17-017","lineIndex":17,"speaker":"Leopold","original":"Niemand, niemand","ipa":"/leopɔlt nimant nimant/","zh":"没有人，没有人","en":"LeopoldNo one, no one","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-17-018","lineIndex":18,"speaker":"爸爸","original":"liebt dich so wie ich.","ipa":"/lipt dɪç zo vi ɪç/","zh":"会像我这样爱护你","en":"loves you like I do.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-17-019","lineIndex":19,"speaker":"爸爸","original":"Du bist zu kindlich und zu ungeschickt","ipa":"/du bɪst tsu kɪntlɪç ʊnt tsu ʊnɡəʃɪkt/","zh":"你太天真，太稚嫩","en":"You are too childlike and too clumsy","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-17-020","lineIndex":20,"speaker":"爸爸","original":"für das kalte, schlaue Spiel des Lebens.","ipa":"/fyɾ das kaltə ʃlaʊə ʃpil dɛs lebəns/","zh":"不足以面对人生的诡谲","en":"for the cold, clever game of life.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-17-021","lineIndex":21,"speaker":"爸爸","original":"Ich habe Angst um dich.","ipa":"/ɪç hɑbə aŋst ʊm dɪç/","zh":"我很担心你","en":"I'm afraid for you.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-17-022","lineIndex":22,"speaker":"爸爸","original":"Du brauchst mich.","ipa":"/du bɾaʊxst mɪç/","zh":"你需要我","en":"You need me.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-17-023","lineIndex":23,"speaker":"爸爸","original":"Denn niemand","ipa":"/dɛn nimant/","zh":"因为没有人","en":"Because no one","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-17-024","lineIndex":24,"speaker":"爸爸","original":"liebt dich so wie ich.","ipa":"/lipt dɪç zo vi ɪç/","zh":"像我这样爱护你","en":"loves you like I do.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-17-025","lineIndex":25,"speaker":"爸爸","original":"Sei froh","ipa":"/zaɪ fro/","zh":"开心点","en":"Be happy","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-17-026","lineIndex":26,"speaker":"Nannerl","original":"Unser Vater ist sehr erfahren.","ipa":"/nanɜl ʊnzɜ fɑtɜ ɪst zeɾ ɛɾfɑrən/","zh":"Nannerl我们的父亲非常有经验。","en":"NannerlOur father is very experienced.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-17-027","lineIndex":27,"speaker":"Leopold","original":"dass ich mich sorge um dich.","ipa":"/leopɔlt das ɪç mɪç zɔɾɡə ʊm dɪç/","zh":"我这是为你好","en":"Leopoldthat I care about you.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-17-028","lineIndex":28,"speaker":"Leopold","original":"Denn sagt mir","ipa":"/leopɔlt dɛn zɑkt miɾ/","zh":"你告诉我","en":"LeopoldFor tell me","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-17-029","lineIndex":29,"speaker":"Leopold","original":"wo wärst du ohne mich?","ipa":"/leopɔlt vo vɛɾst du onə mɪç/","zh":"利奥波德wo wärst du ohne mich？","en":"Leopoldwhere would you be without me?","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-17-030","lineIndex":30,"speaker":"Nannerl","original":"Er will uns beiden Leid ersparen.","ipa":"/nanɜl ɛɾ vɪl ʊns baɪdən laɪt ɛɾʃpɑrən/","zh":"他只想让我们避免遭遇不幸","en":"NannerlHe wants to spare us both suffering.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-17-031","lineIndex":31,"speaker":"Leopold","original":"Alle andern sind Feinde.","ipa":"/leopɔlt alə andɜn zɪnt faɪndə/","zh":"其他人都是敌人","en":"LeopoldAll others are enemies.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-17-032","lineIndex":32,"speaker":"Wolfgang","original":"Kommt ein besserer Augenblick geh ich doch.","ipa":"/vɔlfɡaŋ kɔmt aɪn bɛsərɜ aʊɡənblɪk ɡe ɪç dɔx/","zh":"沃尔夫冈Kommt ein besserer Augenblick geh ich doch。","en":"WolfgangIf a better moment comes, I'll go.","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-17-033","lineIndex":33,"speaker":"Nannerl","original":"Außerdem grämt er sich ohne dich zu Tode.","ipa":"/nanɜl aʊsɜdem ɡɾɛmt ɛɾ zɪç onə dɪç tsu todə/","zh":"看着我们受苦会让他会生不如死","en":"NannerlBesides, he's worried to death without you.","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-17-034","lineIndex":34,"speaker":"Leopold","original":"Auf mich kannst du bauen.","ipa":"/leopɔlt aʊf mɪç kanst du baʊən/","zh":"我可以信任我依靠我","en":"LeopoldYou can rely on me.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-17-035","lineIndex":35,"speaker":"Wolfgang","original":"Ich muss weg hier, sonst ersticke ich noch.","ipa":"/vɔlfɡaŋ ɪç mʊs vɛk hiɾ zɔnst ɛɾʃtɪkə ɪç nɔx/","zh":"我必须离开，在这里我不能自由地呼吸","en":"WolfgangI have to get out of here, otherwise I'll suffocate.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-17-036","lineIndex":36,"speaker":"Leopold","original":"Ich erlaube es nicht","ipa":"/leopɔlt ɪç ɛɾlaʊbə ɛs nɪçt/","zh":"我绝不允许","en":"LeopoldI will not allow","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-17-037","lineIndex":37,"speaker":"爸爸","original":"dass unsere Familie zerbricht.","ipa":"/das ˌʊnzrə famˈiːlɪə tsɛɾbɾˈɪçt/","zh":"我们的家庭支离破碎","en":"our family to break up.","note":"","sourceLineIndex":37}],"sourceOrder":17,"displayOrder":14},{"order":18,"id":"18-wien-wird-mich-um-ihn-beneiden","title":"Wien wird mich um ihn beneiden","titleZh":"维也纳会因他而嫉妒我","lines":[{"id":"mozart-das-musical-18-001","lineIndex":1,"speaker":"Colloredo","original":"So der Vater lässt seinen Sohn nicht nach Wien reisen.","ipa":"/kɔloredo zo dɛɾ fɑtɜ lɛst zaɪnən zon nɪçt nɑx vin raɪzən/","zh":"科洛雷多：所以那位父亲并不允许他的儿子前往维也纳","en":"So the father won't let his son travel to Vienna.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-18-002","lineIndex":2,"speaker":"","original":"Ich hoffe Graf Arco, Sie haben ihn mitgezählt dass ich es befehle.","ipa":"/ɪç hˈɔfə ɡɾˈɑːf ˈaɾkoː ziː hˌɑːbən iːn mˈɪtɡətsˌɛːlt das ɪç ɛs bəfˈeːlə/","zh":"阿尔科伯爵，我希望您告诉他这是我吩咐的","en":"I hope Count Arco, you have counted him that I will order it.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-18-004","lineIndex":3,"speaker":"Graf Arco","original":"Selbstverständlich, Euer Gnaden.","ipa":"/ɡɾɑf aɾko zɛlpstfɛɾʃtɛntlɪç ɔøɜ ɡənɑdən/","zh":"阿尔科：那是自然，主教大人","en":"Of course, Your Grace.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-18-005","lineIndex":4,"speaker":"","original":"Obwohl, wenn Sie die Bemerkung erlauben es ist ein Wagnis.","ipa":"/ɔpvˈoːl vˌɛn ziː diː bəmˈɛɾkʊŋ ɛɾlˈaʊbən ɛsɪst aɪn vˈaɡnɪs/","zh":"尽管如此，恕在下直言这未免冒险了些","en":"Although, if you don't mind me remarking it's a risk.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-18-007","lineIndex":5,"speaker":"","original":"Wolfgang Mozart weiß sich nicht zu benehmen.","ipa":"/vɔlfɡaŋ motsaɾt vaɪs zɪç nɪçt tsu bənemən/","zh":"沃尔夫冈·莫扎特从来不知道举止得体","en":"Wolfgang Mozart doesn't know how to behave.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-18-008","lineIndex":6,"speaker":"Colloredo","original":"Aber er ist ein guter Musiker, Graf Arco.","ipa":"/kɔloredo ɑbɜ ɛɾ ɪst aɪn ɡutɜ muzikɜ ɡɾɑf aɾko/","zh":"可他确实是个不错的音乐家，阿尔科伯爵","en":"But he's a good musician, Count Arco.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-18-009","lineIndex":7,"speaker":"Graf Arco","original":"Der bayerische Kurfürst ist Seiner Durchlaucht außerordentlich dankbar dass Sie ihm Mozart ausgeliehen haben.","ipa":"/dɛɾ bˈaɪərˌɪʃə kˈʊɐfyːɾst ɪst zˌaɪnɜ dʊɐçlˈaʊxt ˈaʊseːrˌɔɾdəntlɪç dˈaŋkbɑːɾ das ziː iːm mˈoːtsaɾt ˈaʊsɡəlˌiːən hˈɑːbən/","zh":"阿尔科伯爵：巴伐利亚选帝侯因您把莫扎特借给他因您把莫扎特借给他至今对主教阁下感激不尽","en":"The Bavarian Elector is extremely grateful to His Serene Highness extraordinarily grateful for lending him Mozart.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-18-012","lineIndex":8,"speaker":"Colloredo","original":"Also hat er sich bewert.","ipa":"/kɔloredo alzo hat ɛɾ zɪç bəvɛɾt/","zh":"科洛雷多：这证明了莫扎特还有点用处","en":"So he evaluated himself.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-18-013","lineIndex":9,"speaker":"Graf Arco","original":"Seine Oper war ein glänzender Erfolg.","ipa":"/ɡɾɑf aɾko zaɪnə opɜ vɑɾ aɪn ɡlɛntsəndɜ ɛɾfɔlk/","zh":"他的歌剧大获成功","en":"His opera was a brilliant success.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-18-014","lineIndex":10,"speaker":"","original":"Der Kurfürst war begeistert.","ipa":"/dɛɾ kʊɐfyɾst vɑɾ bəɡaɪstət/","zh":"选帝侯更是激动万分","en":"The Elector was enthusiastic.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-18-016","lineIndex":11,"speaker":"Colloredo","original":"Ich hoffe er hielt sich an sein Versprechen","ipa":"/ɪç hɔfə ɛɾ hilt zɪç an zaɪn fɛɾʃpɾɛçən/","zh":"我只希望他遵守承诺","en":"I hope he kept his promise","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-18-017","lineIndex":12,"speaker":"","original":"Den Musikus gut zu bewachen","ipa":"/den muzikʊs ɡut tsu bəvaxən/","zh":"好好盯着点那个音乐家","en":"to guard the musician well","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-18-018","lineIndex":13,"speaker":"","original":"und hat nicht versucht, ihn mit Lob zu bestechen","ipa":"/ʊnt hat nɪçt fɛɾzuxt in mɪt lop tsu bəʃtɛçən/","zh":"不要用赞美收买他","en":"and didn't try to bribe him with praise","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-18-019","lineIndex":14,"speaker":"","original":"oder ihm Avancen zu machen...","ipa":"/odɜ im ɑvankən tsu maxən/","zh":"更不要提拔他","en":"or make advances towards him...","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-18-020","lineIndex":15,"speaker":"Graf Arco","original":"Der Kurfürst gibt Mozart immer die gleiche Antwort:","ipa":"/ɡɾɑf aɾko dɛɾ kʊɐfyɾst ɡipt motsaɾt ɪmɜ di ɡlaɪçə antvɔɾt/","zh":"阿尔科：选帝侯给莫扎特的答复始终如一：","en":"The Elector always gives Mozart the same answer:","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-18-021","lineIndex":16,"speaker":"","original":"Keine Vacatur frei!","ipa":"/kaɪnə vɑkatuɾ fraɪ/","zh":"没有闲职！","en":"No Vacatur released!","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-18-022","lineIndex":17,"speaker":"Colloredo","original":"Wann wird Mozart in Wien sien?","ipa":"/kɔloredo van vɪɾt motsaɾt ɪn vin zin/","zh":"科洛雷多：莫扎特什么时候才能到维也纳？","en":"When will Mozart be in Vienna?","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-18-023","lineIndex":18,"speaker":"Graf Arco","original":"Ich habe ihn aufgefordert sich sofort auf die Reise zu machen.","ipa":"/ɪç hɑːbə iːn ˈaʊfɡəfˌɔɾdɜt zɪç zoːfˈɔɾt aʊf diː rˈaɪzə tsuː mˈaxən/","zh":"阿尔科：我已经敦促他即刻启程了","en":"I asked him to to set off on your journey immediately.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-18-025","lineIndex":19,"speaker":"Colloredo","original":"Die Wiener werden sich wundern was für Musikanten wir in Salzburg haben!","ipa":"/diː vˈiːnɜ vˌɛɾdən zɪç vˈʊndɜn vˈas fyːɾ muːziːkˈantən viːɾ ɪn zˈaltsbʊɐk hˈɑːbən/","zh":"科洛雷多：维也纳人一定会大吃一惊：我们萨尔茨堡竟有这样的音乐家","en":"The Viennese will be amazed what kind of musicians we have in Salzburg!","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-18-027","lineIndex":20,"speaker":"Graf Arco","original":"Ich hoffe nur, er macht nicht wieder Ärger.","ipa":"/ɡɾɑf aɾko ɪç hɔfə nuɾ ɛɾ maxt nɪçt vidɜ ɛɾɡɜ/","zh":"阿尔科：我只希望他别再惹出什么麻烦","en":"I just hope he doesn't cause any trouble again.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-18-029","lineIndex":21,"speaker":"Colloredo","original":"Wien wird mich um ihn beneiden","ipa":"/vin vɪɾt mɪç ʊm in bənaɪdən/","zh":"维也纳将因他而嫉妒我","en":"Vienna will envy me for him","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-18-030","lineIndex":22,"speaker":"","original":"und ich werde dann und wann","ipa":"/ʊnt ɪç vɛɾdə dan ʊnt van/","zh":"当我时不时地","en":"and I will now and then","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-18-031","lineIndex":23,"speaker":"","original":"mich am Wiener Staunen weiden","ipa":"/mɪç am vinɜ ʃtaʊnən vaɪdən/","zh":"向维也纳人展示他的才华","en":"delight in the Viennese amazement","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-18-032","lineIndex":24,"speaker":"","original":"wenn ich vorführ, was er kann...","ipa":"/vɛn ɪç foɾfyɾ vas ɛɾ kan/","zh":"他们的震惊将使我满足","en":"when I demonstrate what he can do...","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-18-033","lineIndex":25,"speaker":"Graf Arco","original":"Arrêtez.","ipa":"/ɡɾɑf aɾko aretets/","zh":"阿尔科：停车！","en":"Arrêtez.","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-18-034","lineIndex":26,"speaker":"","original":"Mozart ist ein schlechter Diener, Durchlaucht.","ipa":"/motsaɾt ɪst aɪn ʃlɛçtɜ dinɜ dʊɐçlaʊxt/","zh":"莫扎特真是个差劲的仆从，阁下","en":"Mozart is a bad servant, Your Highness.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-18-035","lineIndex":27,"speaker":"","original":"Wenn er Erfolg hat in Wien, würde es ihn zu Kopf steigen.","ipa":"/vɛn ɛɾ ɛɾfɔlk hat ɪn vin vʏɾdə ɛs in tsu kɔpf ʃtaɪɡən/","zh":"在维也纳取得的成功会冲昏他的头脑","en":"If he succeeds in Vienna, it would go to his head.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-18-036","lineIndex":28,"speaker":"","original":"Er darf keine Gelegenheit haben sich um eine neue Anstellung zu bewerben.","ipa":"/ɛɾ dˈaɾf kˈaɪnə ɡəlˈeːɡənhˌaɪt hˌɑːbən zɪç ʊm ˌaɪnə nˈɔøə ˈanʃtˌɛlʊŋ tsuː bəvˈɛɾbən/","zh":"决不能给他任何谋求新职位的机会","en":"He must not have the opportunity to apply for a new job.","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-18-038","lineIndex":29,"speaker":"","original":"Ich werde jedem sagen dass Sie es als ein persönlicher Affront betrachten wenn ihn jemand ab wird.","ipa":"/ɪç vˌɛɾdə jˈeːdəm zˈɑːɡən das ziː ɛs als aɪn pɛɾzˈøːnlɪçɜ ˈafrɔnt bətɾˈaxtən vˌɛn iːn jˈeːmant ap vˌɪɾt/","zh":"我会放出话去如果有人胆敢把他从您这里挖走就是对您本人的直接冒犯","en":"I will tell everyone that you will consider someone turning him down as a personal affront.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-18-041","lineIndex":30,"speaker":"","original":"Niemand wird es sich mit Ihnen verdarben wegen eines Musikanten.","ipa":"/nimant vɪɾt ɛs zɪç mɪt inən fɛɾdaɾbən veɡən aɪnəs muzikantən/","zh":"没人会为了一个小小的音乐家得罪大人您的","en":"Nobody will mess with you because of a musician.","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-18-042","lineIndex":31,"speaker":"","original":"Ich habe Mozart vorsorglich in Ihrer Wiener Residenz einquartiert dort habe ich immer ein Auge auf ihn.","ipa":"/ɪç hɑːbə mˈoːtsaɾt fˈoːɾzˌɔɾklɪç ɪn ˌiːrɜ vˈiːnɜ rˌeːziːdˈɛnts ˈaɪnkvaɾtˌiːɾt dˈɔɾt hɑːbə ɪç ˈɪmɜ aɪn ˈaʊɡə aʊf ˈiːn/","zh":"我早有安排，让莫扎特住进您在维也纳的府邸这样我可以一直监视他的动向","en":"As a precaution, I put Mozart in your Vienna residence I always keep an eye on him there.","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-18-044","lineIndex":32,"speaker":"","original":"Einsperren kann ich ihn freilich nicht.","ipa":"/aɪnʃpɛrən kan ɪç in fraɪlɪç nɪçt/","zh":"但我没法限制他的行动","en":"Of course I can't lock him up.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-18-045","lineIndex":33,"speaker":"","original":"Er wird in die Weinhäuser gehn und in den Prater...","ipa":"/ɛɾ vɪɾt ɪn di vaɪnhɔøzɜ ɡen ʊnt ɪn den pɾɑtɜ/","zh":"他总要去酒馆或者普拉特公园的集市上逍遥的……","en":"He will go to the wine houses and the Prater...","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-18-046","lineIndex":34,"speaker":"Colloredo","original":"Das verbiete ich!","ipa":"/kɔloredo das fɛɾbitə ɪç/","zh":"科洛雷多：这我决不允许！","en":"I forbid that!","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-18-047","lineIndex":35,"speaker":"","original":"Keine Weinhäuser!","ipa":"/kaɪnə vaɪnhɔøzɜ/","zh":"不能让他去酒馆！","en":"No wine houses!","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-18-048","lineIndex":36,"speaker":"","original":"Und schon gar nicht in den Prater!","ipa":"/ʊnt ʃon ɡɑɾnɪçt ɪn den pɾɑtɜ/","zh":"市集就更不行了！","en":"And certainly not in the Prater!","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-18-049","lineIndex":37,"speaker":"","original":"Auf gar keinen Fall in den Prater!","ipa":"/aʊf ɡɑɾ kaɪnən fal ɪn den pɾɑtɜ/","zh":"绝对不能让他去市集上游荡！","en":"Under no circumstances should you go to the Prater!","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-18-050","lineIndex":38,"speaker":"","original":"Mir ist er anvertraut von Gott, dem Herrn.","ipa":"/miɾ ɪst ɛɾ anfɛɾtɾaʊt fɔn ɡɔt dem hɛɾn/","zh":"我主将他托付给我","en":"It has been entrusted to me by the Lord God.","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-18-051","lineIndex":39,"speaker":"","original":"Ich sorg dafür, dass er sich fügt und kuscht vor meinem Blick.","ipa":"/ɪç zˈɔɾk dɑːfˈyːɾ das ɛɾ zɪç fˈyːkt ʊnt kˈʊʃt fˌɔɾ mˌaɪnəm blˈɪk/","zh":"我必须确保他俯首帖耳顺从于我","en":"I make sure he submits and avoids my gaze.","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-18-053","lineIndex":40,"speaker":"","original":"Nie darf es sein, dass die Vernunft die diese Welt erhellen soll besiegt wird vom Zauber der Musik.","ipa":"/nˈiː dˈaɾf ɛs zaɪn das diː fɛɾnˈʊnft diː dˌiːzə vˈɛlt ɛɾhˈɛlən zˌɔl bəzˈiːkt vˌɪɾt fɔm tsˈaʊbɜ dɛɾ muːzˈiːk/","zh":"那照亮世界的理性绝不可能臣服于这音乐的魔力","en":"It must never be the case that reason, which is supposed to illuminate this world is defeated by the magic of music.","note":"","sourceLineIndex":53}],"sourceOrder":18,"displayOrder":15},{"order":19,"id":"19-halten-sie-den-atem-an","title":"Halten sie den Atem an!","titleZh":"请屏住呼吸！","lines":[{"id":"mozart-das-musical-19-001","lineIndex":1,"speaker":"","original":"Wo gibt's was zu gaffen?","ipa":"/vo ɡɪpts vas tsu ɡafən/","zh":"往哪儿瞧？","en":"Where's there to gawk at?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-19-002","lineIndex":2,"speaker":"","original":"Wo gibt's was zu sehen?","ipa":"/vo ɡɪpts vas tsu zeən/","zh":"往哪儿瞅？","en":"Where can you see?","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-19-003","lineIndex":3,"speaker":"","original":"Im Pratertheater der Illusionen.","ipa":"/ɪm pɾɑtɜteɑtɜ dɛɾ ɪluzjonən/","zh":"在变幻莫测的普拉特剧院","en":"In the Prater Theater of Illusions.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-19-004","lineIndex":4,"speaker":"","original":"Wo kann man vor Staunen die Augen verdreh'n?","ipa":"/vo kan man fɔɾ ʃtaʊnən di aʊɡən fɛɾdɾen/","zh":"哪里可以遇到惊喜迷人眼","en":"Where can you roll your eyes in amazement?","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-19-005","lineIndex":5,"speaker":"","original":"Auf dem Jahrmarkt der Sensationen.","ipa":"/aʊf dem jɑɾmaɾkt dɛɾ zɛnzatsjonən/","zh":"在炙手可热的年度集市上","en":"At the fair of sensations.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-19-006","lineIndex":6,"speaker":"","original":"Die Frau mit zwei Köpfen.","ipa":"/di fraʊ mɪt tsvaɪ kœpfən/","zh":"双头女人","en":"The woman with two heads.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-19-007","lineIndex":7,"speaker":"","original":"Der Mann mit dem magischen Blick.","ipa":"/dɛɾ man mɪt dem mɑɡɪʃən blɪk/","zh":"魔眼大汉","en":"The man with the magical look.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-19-008","lineIndex":8,"speaker":"","original":"Die Welt ist voll Wunder und jedes ist irgendein Trick.","ipa":"/di vɛlt ɪst fɔl vʊndɜ ʊnt jedəs ɪst ɪɾɡəndaɪn tɾɪk/","zh":"世界充满奇迹，而奇迹不过是骗局","en":"The world is full of wonders and each one is a trick.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-19-009","lineIndex":9,"speaker":"","original":"Alles Schwindel! Alles Betrug!","ipa":"/aləs ʃvɪndəl aləs bətɾuk/","zh":"人人使诈，处处机关！","en":"It's all bogus! All fraud!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-19-010","lineIndex":10,"speaker":"","original":"Ist heute einer ehrlich, dann ist er nicht klug.","ipa":"/ɪst hɔøtə aɪnɜ eɾlɪç dan ɪst ɛɾ nɪçt kluk/","zh":"诚实在今天等于愚蠢","en":"If someone is honest today, then they are not smart.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-19-011","lineIndex":11,"speaker":"","original":"Im Handeln und Reden belügt jeder jeden zum eigenen Vorteil und weil's jeder so macht.","ipa":"/ɪm hˈandəln ʊnt rˈeːdən bəlˈyːkt jˈeːdɜ jˈeːdən tsʊm ˈaɪɡənən fˈoːɾtˌaɪl ʊnt vˈaɪls jˈeːdɜ zoː mˈaxt/","zh":"巧舌如簧，坑蒙拐骗中饱私囊，唯利是图","en":"When acting and speaking, everyone lies to everyone for their own benefit and because everyone does it that way.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-19-013","lineIndex":12,"speaker":"","original":"Wir kommen zum sensationellen Höhepunkt unseres Programms zur öffentlichen Hinrichtung!","ipa":"/viːɾ kˈɔmən tsʊm zˌɛnzatsjˌoːnˈɛlən hˈøːeːpˌʊŋkt ˌʊnzərəs pɾoːɡɾˈams tsuːɾ ˈœfəntlɪçən hˈɪnrɪçtˌʊŋ/","zh":"接下来就是我们今天演出最激动人心的环节公开处决！","en":"We are coming to the sensational climax of our program the public execution!","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-19-015","lineIndex":13,"speaker":"","original":"Wer lässt sich freiwillig enthaupten?","ipa":"/veɾ lɛst zɪç fraɪvɪlɪç ɛnthaʊptən/","zh":"谁想来体验一下被处决的感觉？","en":"Who will allow themselves to be beheaded voluntarily?","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-19-016","lineIndex":14,"speaker":"","original":"Nur Mut, meine Herren!","ipa":"/nuɾ mut maɪnə hɛrən/","zh":"勇敢点啊先生们！","en":"Have courage, gentlemen!","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-19-017","lineIndex":15,"speaker":"","original":"Wer wagt es?","ipa":"/veɾ vɑkt ɛs/","zh":"谁敢来试试？","en":"Who dares?","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-19-018","lineIndex":16,"speaker":"","original":"Der Edelmann da hinten?","ipa":"/dɛɾ edəlman dɑ hɪntən/","zh":"后面那位高贵的先生？","en":"That nobleman back there?","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-19-019","lineIndex":17,"speaker":"","original":"Ja, Sie!","ipa":"/jɑ zi/","zh":"对，就是你","en":"Yes, you!","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-19-020","lineIndex":18,"speaker":"","original":"Kommen Sie auf die Bühne!","ipa":"/kɔmən zi aʊf di bynə/","zh":"上台来","en":"Come on stage!","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-19-021","lineIndex":19,"speaker":"","original":"Meine Damen und Herren, einen kräftigen Applaus für diesen mutigen Herrn!","ipa":"/maɪnə dɑmən ʊnt hɛrən aɪnən kɾɛftɪɡən aplaʊs fyɾ dizən mutɪɡən hɛɾn/","zh":"女士们先生们，掌声送给这位勇士","en":"Ladies and gentlemen, a big round of applause for this courageous gentleman!","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-19-022","lineIndex":20,"speaker":"","original":"Zehn! Neun! Acht!","ipa":"/tsen nɔøn axt/","zh":"十！九！八！","en":"Ten! Nine! Eight!","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-19-023","lineIndex":21,"speaker":"","original":"Sieben!","ipa":"/zibən/","zh":"七！","en":"Seven!","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-19-024","lineIndex":22,"speaker":"","original":"Sechs! Fünf! Vier! Drei! Zwei! Eins!","ipa":"/zɛks fʏnf fiɾ dɾaɪ tsvaɪ aɪns/","zh":"六！五！四！三！二！一！","en":"Six! Five! Four! Three! Two! One!","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-19-025","lineIndex":23,"speaker":"","original":"Mozart!","ipa":"/motsaɾt/","zh":"莫扎特！","en":"Mozart!","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-19-026","lineIndex":24,"speaker":"","original":"Hat man ihm nicht ausdrücklich verboten, sich herumzutreiben?","ipa":"/hat man im nɪçt aʊsdɾʏklɪç fɛɾbotən zɪç hɛrʊmtsutɾaɪbən/","zh":"我不是和你特别强调过不要随便乱跑吗！","en":"Wasn't he expressly forbidden from hanging around?","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-19-027","lineIndex":25,"speaker":"","original":"Doch, Graf Arco!","ipa":"/dɔx ɡɾɑf aɾko/","zh":"呐！阿尔克伯爵！","en":"Yes, Count Arco!","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-19-028","lineIndex":26,"speaker":"","original":"Pflichtvergess'ner Bursche.","ipa":"/pflɪçtfɛɾɡɛsnɜ bʊɐʃə/","zh":"毫无责任心的臭小子！","en":"Oblivious guy.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-19-029","lineIndex":27,"speaker":"","original":"Es ist eine Schande!","ipa":"/ɛsɪst aɪnə ʃandə/","zh":"丢人现眼！","en":"It's a shame!","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-19-030","lineIndex":28,"speaker":"","original":"Niemals war ein Diener dreist wie er.","ipa":"/nimɑls vɑɾ aɪn dinɜ dɾaɪst vi ɛɾ/","zh":"没见过这么厚颜无处的仆从","en":"Never was a servant as bold as he was.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-19-031","lineIndex":29,"speaker":"","original":"Ich hab' den Kopf verloren.","ipa":"/ɪç hɑp den kɔpf fɛɾlorən/","zh":"我好歹脑袋都丢了呢","en":"I lost my head.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-19-032","lineIndex":30,"speaker":"","original":"Nun, das Witzemachen wird ihm bald vergehen","ipa":"/nun das vɪtsemaxən vɪɾt im balt fɛɾɡeən/","zh":"你还能开玩笑到什么时候","en":"Well, he'll soon stop making jokes","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-19-033","lineIndex":31,"speaker":"","original":"Er muss heimfahr'n!","ipa":"/ɛɾ mʊs haɪmfɑɾn/","zh":"他老实回家去","en":"He has to go home!","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-19-034","lineIndex":32,"speaker":"","original":"Wien gefällt mir gut.","ipa":"/vin ɡəfɛlt miɾ ɡut/","zh":"我很喜欢维也纳","en":"I like Vienna.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-19-035","lineIndex":33,"speaker":"","original":"Das wird ihm wenig nützen wenn sein Herr von mir erfährt wie ehrlos sich sein Diener hier benimmt.","ipa":"/das vˌɪɾt iːm vˈeːnɪç nˈʏtsən vˌɛn zaɪn hˈɛɾ fɔn miːɾ ɛɾfˈɛːɾt viː ˈeːɾloːs zɪç zaɪn dˈiːnɜ hˈiːɾ bənˈɪmt/","zh":"那也无济于事只要我告诉他的主教他的莫扎特是如此这么不知廉耻","en":"That will be of little use to him if his master finds out from me how dishonorably his servant is behaving here.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-19-038","lineIndex":34,"speaker":"","original":"Ehrlos?","ipa":"/eɾlos/","zh":"不知廉耻？","en":"Dishonorable?","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-19-039","lineIndex":35,"speaker":"","original":"Wenn ich ehrlos bin dann sind Sie...?","ipa":"/vˌɛn ɪç ˈeːɾloːs bɪn dan zɪnt ziː/","zh":"如果我是“不知廉耻”的话那么您...","en":"If I'm dishonorable then you...?","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-19-041","lineIndex":36,"speaker":"","original":"Ach was...","ipa":"/ax vas/","zh":"啊算了。","en":"Oh no...","note":"","sourceLineIndex":41}],"sourceOrder":19,"displayOrder":16},{"order":20,"id":"20-ich-bin-extraordinar","title":"Ich bin extraordinär","titleZh":"我非同凡响","lines":[{"id":"mozart-das-musical-20-001","lineIndex":1,"speaker":"","original":"Ich bin fein, mein Herz ist rein","ipa":"/ɪç bɪn faɪn maɪn hɛɾts ɪst raɪn/","zh":"我很好，我的心很纯洁","en":"I'm fine, my heart is pure","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-20-002","lineIndex":2,"speaker":"","original":"Drin wohnt ein kleines dickes Schw—","ipa":"/dɾin vont aɪn klaɪnəs dɪkəs ʃf/","zh":"里面住着一个大鸡巴-","en":"There's a big little dick inside that lives -","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-20-003","lineIndex":3,"speaker":"","original":"Trotzdem bin ich weiser als manch greiser Hosenschei—","ipa":"/tɾɔtsdem bɪn ɪç vaɪzɜ als manç ɡɾaɪzɜ hozənʃaɪ/","zh":"不过，我比一些老混蛋聪明-","en":"Nevertheless, I'm wiser than some old bastards—","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-20-004","lineIndex":4,"speaker":"","original":"Leck mich, ich bin extraordinär!","ipa":"/lɛk mɪç ɪç bɪn ɛkstɾaɔɾdinɛɾ/","zh":"操我，我很了不起！","en":"Fuck me, I'm extraordinary!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-20-005","lineIndex":5,"speaker":"","original":"Ich hab ganz viel Toleranz mit jeder Gans und jedem Schw—","ipa":"/ɪç hɑp ɡants fil tolerants mɪt jedɜ ɡɑns ʊnt jedəm ʃf/","zh":"Ich hab ganz viel Toleranz mit jeder Gans und jedem Schw—","en":"I have a lot of tolerance for every goose and every pig—","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-20-006","lineIndex":6,"speaker":"","original":"Ja, ja.","ipa":"/jɑ jɑ/","zh":"是的，是的。","en":"Yes, yes.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-20-007","lineIndex":7,"speaker":"","original":"In der Kürze liegt der Würze meiner Für— Leck mich, ich bin extraordinär!","ipa":"/ɪn dɛɾ kˈʏɾtsə lˈiːkt dɛɾ vˈʏɾtsə mˌaɪnɜ fˈyːɾ lˈɛk mɪç ɪç bɪn ˌɛkstɾaˌɔɾdiːnˈɛːɾ/","zh":"简洁是我的调味品-操我，我很了不起！","en":"Brevity is the spice of my for- Fuck me, I'm extraordinary!","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-20-009","lineIndex":8,"speaker":"","original":"Jeder Edeldödel will mich belehren","ipa":"/jedɜ edəldødəl vɪl mɪç bəlerən/","zh":"每个高贵的白痴都想教我","en":"Every noble idiot wants to teach me","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-20-010","lineIndex":9,"speaker":"","original":"Jeder Knödelschädel schreibt mir was vor","ipa":"/jedɜ knødɛʃɛdəl ʃraɪpt miɾ vas fɔɾ/","zh":"每个饺子头骨都告诉我一些东西","en":"Every dumpling skull tells me something","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-20-011","lineIndex":10,"speaker":"","original":"Jede Trachtelwachtel soll ich verehren","ipa":"/jedə tɾaxtəlvaxtəl zɔl ɪç fɛɾerən/","zh":"我应该喜欢每一个传统的鹌鹑","en":"I should adore every traditional quail","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-20-012","lineIndex":11,"speaker":"","original":"Jede Sprachtelschachtel schmatzt mit was vor","ipa":"/jedə ʃpɾɑxtəlʃaxtəl ʃmatst mɪt vas fɔɾ/","zh":"每个语言框都在前面打上一些东西","en":"Every language box smacks something in front of","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-20-013","lineIndex":12,"speaker":"","original":"Doch ist wer barsch zu mir und harsch kriech ich ihm nicht marsch in den Ar—","ipa":"/dɔx ɪst veɾ baɾʃ tsu miɾ ʊnt haɾʃ kɾiç ɪç im nɪçt maɾʃ ɪn den ɑɾ/","zh":"但如果有人对我很严厉，我不会爬进他的屁股里—","en":"But if someone is harsh to me and harshly I won't crawl into his ass—","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-20-014","lineIndex":13,"speaker":"","original":"Jedoch… Ich wahr die Sitten","ipa":"/jedɔx ɪç vɑɾ di zɪtən/","zh":"不过……我尊重习俗","en":"However... I respect the customs","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-20-015","lineIndex":14,"speaker":"","original":"Nur auf Bitten fass ich an Ti—","ipa":"/nuɾ aʊf bɪtən fas ɪç an ti/","zh":"如果有人问我，我只会碰 Ti -","en":"I only touch Ti if asked -","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-20-016","lineIndex":15,"speaker":"","original":"Leck mich, ich bin extraordinär!","ipa":"/lɛk mɪç ɪç bɪn ɛkstɾaɔɾdinɛɾ/","zh":"操我，我很了不起！","en":"Fuck me, I'm extraordinary!","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-20-017","lineIndex":16,"speaker":"","original":"Jedem Rammelhammel zaus ich die Mähne","ipa":"/jedəm raməlhaməl tsaʊs ɪç di mɛnə/","zh":"我会弄乱每只公羊的鬃毛","en":"I ruffle the mane of every ram","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-20-018","lineIndex":17,"speaker":"","original":"Jeder Stammelschrammel fall ich ins Wort","ipa":"/jedɜ ʃtaməlʃraməl fal ɪç ɪns vɔɾt/","zh":"结巴者我停止","en":"I stop every stammerer","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-20-019","lineIndex":18,"speaker":"","original":"Jedem Grummelpummel zeig ich die Zähne","ipa":"/jedəm ɡɾʊməlpʊməl tsaɪk ɪç di tsɛnə/","zh":"每一个抱怨者我都会露出牙齿","en":"I show my teeth to every grumpy bumblebee","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-20-020","lineIndex":19,"speaker":"","original":"Jeder Stummelhummel flieg ich fort","ipa":"/jedɜ ʃtʊməlhʊməl flik ɪç fɔɾt/","zh":"每只大黄蜂我都会飞走","en":"I send every bumbling bumblebee flying away","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-20-021","lineIndex":20,"speaker":"","original":"Und will mich wer zum Teufel schicken","ipa":"/ʊnt vɪl mɪç veɾ tsʊm tɔøfəl ʃɪkən/","zh":"谁想把我送进地狱","en":"And who wants to send me to hell","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-20-022","lineIndex":21,"speaker":"","original":"und mir in den Hintern kicken","ipa":"/ʊnt miɾ ɪn den hɪntɜn kɪkən/","zh":"并踢我的屁股","en":"and kick my ass","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-20-023","lineIndex":22,"speaker":"","original":"nur um mir am Zeug Zu flicken","ipa":"/nuɾ ʊm miɾ am tsɔøk tsu flɪkən/","zh":"nur um mir am Zeug Zu轻拂","en":"just to mend my stuff","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-20-024","lineIndex":23,"speaker":"","original":"und um meinen Stolz zu knicken.","ipa":"/ʊnt ʊm maɪnən ʃtɔlts tsu knɪkən/","zh":"和 um meinen Stolz zu knicken。","en":"and to crush my pride.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-20-025","lineIndex":24,"speaker":"","original":"Sag ich ihm nicht nur mit Blicken er soll sich selber…","ipa":"/zˈɑːk ɪç iːm nˈɪçt nˈuːɾ mɪt blˈɪkən ɛɾ zˌɔl zɪç zˈɛlbɜ/","zh":"我不只是用眼神告诉他他应该照顾好自己......","en":"I don't just tell him with looks he should take care of himself...","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-20-027","lineIndex":25,"speaker":"","original":"Hundsfott! Das soll er mir bereuen!","ipa":"/hʊntsfɔt das zɔl ɛɾ miɾ bərɔøən/","zh":"愚蠢！我要让他后悔！","en":"Stupid! I want him to regret that!","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-20-028","lineIndex":26,"speaker":"","original":"ficken!","ipa":"/fɪkən/","zh":"操！","en":"fuck!","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-20-029","lineIndex":27,"speaker":"","original":"Ab mit ihm in die Kulissen","ipa":"/ap mɪt im ɪn di kulɪsən/","zh":"Ab mit ihm in die Kulissen","en":"Off to the scenes with him","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-20-030","lineIndex":28,"speaker":"","original":"Warum droht er so beflissen mit gewissen Ärgernissen?","ipa":"/vɑrʊm dɾot ɛɾ zo bəflɪsən mɪt ɡəvɪsən ɛɾɡɜnɪsən/","zh":"为什么他如此急切地威胁某些烦恼？","en":"Why is he so eager to threaten certain annoyances?","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-20-031","lineIndex":29,"speaker":"","original":"Schliesslich müsste er doch wissen","ipa":"/ʃlislɪç mʏstə ɛɾ dɔx vɪsən/","zh":"毕竟，他应该知道","en":"After all, he should know","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-20-032","lineIndex":30,"speaker":"","original":"Dass wir ihn hier nicht vermissen","ipa":"/das viɾ in hiɾ nɪçt fɛɾmɪsən/","zh":"我们在这里不会想念他","en":"That we don't miss him here","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-20-033","lineIndex":31,"speaker":"","original":"Auf den Grafen ist gesch—","ipa":"/aʊf den ɡɾɑfən ɪst ɡɛʃ/","zh":"计数已完成 -","en":"The count is shot -","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-20-034","lineIndex":32,"speaker":"","original":"Leck mich x8","ipa":"/lɛk mɪç ɪks axt/","zh":"舔我 x8","en":"Lick me x8","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-20-035","lineIndex":33,"speaker":"","original":"Ich bin extraordinär!","ipa":"/ɪç bɪn ɛkstɾaɔɾdinɛɾ/","zh":"我很出色！","en":"I'm extraordinary!","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-20-036","lineIndex":34,"speaker":"","original":"Extraordinär!","ipa":"/ɛkstɾaɔɾdinɛɾ/","zh":"非凡！","en":"Extraordinary!","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-20-037","lineIndex":35,"speaker":"","original":"Na potzblitz, die Frau Weber aus Mannheim! Das ist gelungen!","ipa":"/nɑ pɔtsblɪts di fraʊ vebɜ aʊs manhaɪm das ɪst ɡəlʊŋən/","zh":"来吧，来自曼海姆的韦伯女士！就这样成功了！","en":"Come on, Ms. Weber from Mannheim! That was successful!","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-20-038","lineIndex":36,"speaker":"","original":"(Was ist klar?)","ipa":"/vas ɪst klɑɾ/","zh":"（什么是清楚的？）","en":"(What is clear?)","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-20-039","lineIndex":37,"speaker":"","original":"Gute Freunde treffen sich immer wieder!","ipa":"/ɡutə frɔøndə tɾɛfən zɪç ɪmɜ vidɜ/","zh":"好朋友总会重逢！","en":"Good friends always meet again!","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-20-040","lineIndex":38,"speaker":"","original":"(Was trügt?)","ipa":"/vas tɾykt/","zh":"（什么是欺骗？）","en":"(What is deceiving?)","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-20-041","lineIndex":39,"speaker":"","original":"Ich hoffe, du kriegst keinen Ärger mit deinem Fürsten.","ipa":"/ɪç hɔfə du kɾikst kaɪnən ɛɾɡɜ mɪt daɪnəm fyɾstən/","zh":"我希望你不要给你的王子带来麻烦。","en":"I hope you don't get into trouble with your prince.","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-20-042","lineIndex":40,"speaker":"","original":"Ach, was!","ipa":"/ax vas/","zh":"哦，什么！","en":"Oh, what!","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-20-043","lineIndex":41,"speaker":"","original":"(Wer sagt schon, was er meint?)","ipa":"/veɾ zɑkt ʃon vas ɛɾ maɪnt/","zh":"（谁说的是什么意思？）","en":"(Who says what he means?)","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-20-044","lineIndex":42,"speaker":"","original":"Wo ist Aloysia?","ipa":"/vo ɪst ɑlɔøziɑ/","zh":"阿洛伊西亚在哪里？","en":"Where is Aloysia?","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-20-045","lineIndex":43,"speaker":"","original":"Hat geheiratet.","ipa":"/hat ɡəhaɪrɑtət/","zh":"结婚了。","en":"Got married.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-20-046","lineIndex":44,"speaker":"","original":"(Was ist wahr?)","ipa":"/vas ɪst vɑɾ/","zh":"（什么是真的？）","en":"(What is true?)","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-20-047","lineIndex":45,"speaker":"","original":"Sie ist eine berühmte Sängerin geworden.","ipa":"/zi ɪst aɪnə bərymtə zɛŋərɪn ɡəvɔɾdən/","zh":"她已成为一名著名歌手。","en":"She has become a famous singer.","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-20-048","lineIndex":46,"speaker":"","original":"(Wer lügt?)","ipa":"/veɾ lykt/","zh":"（谁在撒谎？）","en":"(Who is lying?)","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-20-049","lineIndex":47,"speaker":"","original":"Herr Weber?","ipa":"/hɛɾ vebɜ/","zh":"韦伯先生？","en":"Mr. Weber?","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-20-050","lineIndex":48,"speaker":"","original":"Mein armer Mann, tot.","ipa":"/maɪn aɾmɜ man tot/","zh":"我可怜的丈夫死了。","en":"My poor husband, dead.","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-20-051","lineIndex":49,"speaker":"","original":"Johann Thorwart, ein guter Freund.","ipa":"/johan tɔɾvaɾt aɪn ɡutɜ frɔønt/","zh":"约翰·索瓦特，一个好朋友。","en":"Johann Thorwart, a good friend.","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-20-052","lineIndex":50,"speaker":"","original":"(Wer ist schon, was er scheint?)","ipa":"/veɾ ɪst ʃon vas ɛɾ ʃaɪnt/","zh":"（他看起来是谁？）","en":"(Who is what he seems?)","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-20-053","lineIndex":51,"speaker":"","original":"Wo wohnst du?","ipa":"/vo vonst du/","zh":"你住在哪里？","en":"Where do you live?","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-20-054","lineIndex":52,"speaker":"","original":"In Colloredos Wiener Residenz.","ipa":"/ɪn kɔloredos vinɜ rezidɛnts/","zh":"在科洛雷多的维也纳住所。","en":"In Colloredo's Vienna residence.","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-20-055","lineIndex":53,"speaker":"","original":"(Was ist falsch?)","ipa":"/vas ɪst falʃ/","zh":"（出了什么问题？）","en":"(What's wrong?)","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-20-056","lineIndex":54,"speaker":"","original":"Du ziehst zu uns. Zu deinen Freunden.","ipa":"/du tsist tsu ʊns tsu daɪnən frɔøndən/","zh":"您要搬来和我们一起住。给你的朋友。","en":"You're moving in with us. To your friends.","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-20-057","lineIndex":55,"speaker":"","original":"(Was echt?)","ipa":"/vas ɛçt/","zh":"（真的是什么？）","en":"(Really what?)","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-20-058","lineIndex":56,"speaker":"","original":"Ich würde schon wollen, wenn ich dürfte.","ipa":"/ɪç vʏɾdə ʃon vɔlən vɛn ɪç dʏɾftə/","zh":"如果可以的话，我愿意。","en":"I would want to if I could.","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-20-059","lineIndex":57,"speaker":"","original":"Bist du ein Gefangener?","ipa":"/bɪst du aɪn ɡəfaŋənɜ/","zh":"你是囚犯吗？","en":"Are you a prisoner?","note":"","sourceLineIndex":59},{"id":"mozart-das-musical-20-060","lineIndex":58,"speaker":"","original":"Nein, aber mein Vater…","ipa":"/naɪn ɑbɜ maɪn fɑtɜ/","zh":"不，但是我的父亲...","en":"No, but my father...","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-20-061","lineIndex":59,"speaker":"","original":"(Wer spielt nicht gern Versteck.)","ipa":"/veɾ ʃpilt nɪçt ɡɛɾn fɛɾʃtɛk/","zh":"（谁不喜欢玩捉迷藏。）","en":"(Who doesn't like to play hide-and-seek.)","note":"","sourceLineIndex":61},{"id":"mozart-das-musical-20-062","lineIndex":60,"speaker":"","original":"Du bist doch kein Kind mehr.","ipa":"/du bɪst dɔx kaɪn kɪnt meɾ/","zh":"你不再是孩子了。","en":"You're not a child anymore.","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-20-063","lineIndex":61,"speaker":"","original":"Nein.","ipa":"/naɪn/","zh":"不。","en":"No.","note":"","sourceLineIndex":63},{"id":"mozart-das-musical-20-064","lineIndex":62,"speaker":"","original":"Na also.","ipa":"/nɑ alzo/","zh":"好吧。","en":"Well then.","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-20-065","lineIndex":63,"speaker":"","original":"(Was ist gut?)","ipa":"/vas ɪst ɡut/","zh":"（什么好？）","en":"(What's good?)","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-20-066","lineIndex":64,"speaker":"","original":"Willkommen!","ipa":"/vɪlkɔmən/","zh":"欢迎！","en":"Welcome!","note":"","sourceLineIndex":66},{"id":"mozart-das-musical-20-067","lineIndex":65,"speaker":"","original":"Es wird dir gefallen bei uns.","ipa":"/ɛs vɪɾt diɾ ɡəfalən baɪ ʊns/","zh":"您一定会喜欢我们的。","en":"You will like it with us.","note":"","sourceLineIndex":67},{"id":"mozart-das-musical-20-068","lineIndex":66,"speaker":"","original":"(Was schlecht?)","ipa":"/vas ʃlɛçt/","zh":"（什么不好？）","en":"(What bad?)","note":"","sourceLineIndex":68},{"id":"mozart-das-musical-20-069","lineIndex":67,"speaker":"","original":"Ganz sicher, Constanze.","ipa":"/ɡants zɪçɜ kɔnstantsə/","zh":"当然，康斯坦兹。","en":"Absolutely, Constanze.","note":"","sourceLineIndex":69},{"id":"mozart-das-musical-20-070","lineIndex":68,"speaker":"","original":"Hilfst du mir beim Aufräumen?","ipa":"/hɪlfst du miɾ baɪm aʊfrɔømən/","zh":"你能帮我清理一下吗？","en":"Can you help me clean up?","note":"","sourceLineIndex":70},{"id":"mozart-das-musical-20-071","lineIndex":69,"speaker":"","original":"(Die Maus lockt man mit Speck.)","ipa":"/di maʊs lɔkt man mɪt ʃpɛk/","zh":"（你用培根引诱老鼠。）","en":"(You lure the mouse with bacon.)","note":"","sourceLineIndex":71},{"id":"mozart-das-musical-20-072","lineIndex":70,"speaker":"","original":"Alles Schwindel! Alles Betrug!","ipa":"/aləs ʃvɪndəl aləs bətɾuk/","zh":"这都是骗局！都是诈骗！","en":"It's all bogus! All fraud!","note":"","sourceLineIndex":72},{"id":"mozart-das-musical-20-073","lineIndex":71,"speaker":"","original":"Ist heut einer ehrlich, dann ist er nicht klug.","ipa":"/ɪst hɔøt aɪnɜ eɾlɪç dan ɪst ɛɾ nɪçt kluk/","zh":"如果今天有人诚实，那么他们就不聪明。","en":"If someone is honest today, then they are not smart.","note":"","sourceLineIndex":73},{"id":"mozart-das-musical-20-074","lineIndex":72,"speaker":"","original":"Im Handeln und Reden belügt jeder jeden zum eigenen Vorteil und weil's jeder so macht","ipa":"/ɪm handəln ʊnt redən bəlykt jedɜ jedən tsʊm aɪɡənən foɾtaɪl ʊnt vaɪls jedɜ zo maxt/","zh":"在行动和说话时，每个人都会为了自己的利益而向其他人撒谎，因为每个人都这样做","en":"When acting and speaking, everyone lies to everyone else for their own benefit and because everyone does it that way","note":"","sourceLineIndex":74},{"id":"mozart-das-musical-20-075","lineIndex":73,"speaker":"","original":"Das hat mir gefallen, wie du's dem Herrn Grafen gegeben hast.","ipa":"/das hat miɾ ɡəfalən vi dus dem hɛɾn ɡɾɑfən ɡəɡebən hast/","zh":"我喜欢你把它交给伯爵的方式。","en":"I liked the way you gave it to the Count.","note":"","sourceLineIndex":75},{"id":"mozart-das-musical-20-076","lineIndex":74,"speaker":"","original":"Hätt' ich schon früher machen sollen.","ipa":"/hɛt ɪç ʃon fryɜ maxən zɔlən/","zh":"我应该早点做的。","en":"I should have done it sooner.","note":"","sourceLineIndex":76},{"id":"mozart-das-musical-20-077","lineIndex":75,"speaker":"","original":"Aber besser später als zu früh","ipa":"/ɑbɜ bɛsɜ ʃpɛtɜ als tsu fry/","zh":"但晚点总比早点好","en":"But better later than too soon","note":"","sourceLineIndex":77},{"id":"mozart-das-musical-20-078","lineIndex":76,"speaker":"","original":"und besser zu früh als nie","ipa":"/ʊnt bɛsɜ tsu fry als ni/","zh":"早点总比不早点好","en":"and better too soon than never","note":"","sourceLineIndex":78},{"id":"mozart-das-musical-20-079","lineIndex":77,"speaker":"","original":"der eine hat Macht und der andre Genie und wer beides nicht hat, hat nichts","ipa":"/dɛɾ aɪnə hat maxt ʊnt dɛɾ andɾə ɡəni ʊnt veɾ baɪdəs nɪçt hat hat nɪçts/","zh":"一个拥有力量，另一个拥有天赋，而两者都没有的人则一无所有","en":"one has power and the other has genius and whoever has neither has nothing","note":"","sourceLineIndex":79},{"id":"mozart-das-musical-20-080","lineIndex":78,"speaker":"","original":"und nichts ist so viel wie sehr wenig und wenig ist nicht viel","ipa":"/ʊnt nɪçts ɪst zo fil vi zeɾ venɪç ʊnt venɪç ɪst nɪçt fil/","zh":"没有什么是微乎其微的，一点也不算多","en":"and nothing is as much as very little and a little is not much","note":"","sourceLineIndex":80},{"id":"mozart-das-musical-20-081","lineIndex":79,"speaker":"","original":"folglich ist nichts immer weniger als wenig, und wenig immer mehr als nicht viel…","ipa":"/fɔlklɪç ɪst nɪçts ɪmɜ venɪɡɜ als venɪç ʊnt venɪç ɪmɜ meɾ als nɪçt fil/","zh":"因此，没有什么总是比少少，而少总是比不多多……","en":"Consequently, nothing is always less than little, and little is always more than not much...","note":"","sourceLineIndex":81}],"sourceOrder":20,"displayOrder":17},{"order":21,"id":"21-weil-du-so-bist-wie-du-bist","title":"Weil du so bist, wie du bist","titleZh":"因为你就是你","lines":[{"id":"mozart-das-musical-21-001","lineIndex":1,"speaker":"康斯坦斯","original":"Höre auf! Ich verstehe kein Wort!","ipa":"/hørə aʊf ɪç fɛɾʃteə kaɪn vɔɾt/","zh":"瞧你说的！我一个字儿也听不懂！","en":"Stop it! I don't understand a word!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-21-002","lineIndex":2,"speaker":"康斯坦斯","original":"Du bist wirklich ein komischer Kauz.","ipa":"/du bɪst vɪɾklɪç aɪn komɪʃɜ kaʊts/","zh":"你真是个有趣的怪人","en":"You really are an oddball.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-21-003","lineIndex":3,"speaker":"Schaut's","original":"Ein Kauz, pardauz, mir graut's.","ipa":"/ʃaʊts aɪn kaʊts paɾdaʊts miɾ ɡɾaʊts/","zh":"看呐：一个怪人，哎呦，我好怕怕哦！","en":"a weirdo, pardauz, I'm shuddering.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-21-004","lineIndex":4,"speaker":"沃尔夫冈","original":"Ich bin, o Mist, ein Pianist, und Komponist","ipa":"/ɪç bɪn o mɪst aɪn pianɪst ʊnt kɔmponɪst/","zh":"我是，啊讨厌，一个钢琴家，还是一个作曲家","en":"I am, oh crap, a pianist and composer","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-21-005","lineIndex":5,"speaker":"沃尔夫冈","original":"ein Musikus mit einem Schuss, von Genius.","ipa":"/aɪn muzikʊs mɪt aɪnəm ʃʊs fɔn ɡəniʊs/","zh":"我是迸发的天赋驱动着的音乐家！","en":"a musician with a shot, of genius.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-21-006","lineIndex":6,"speaker":"康斯坦斯","original":"Von Musik versteh' ich nichts. Aber weißt du?","ipa":"/fɔn muzik fɛɾʃte ɪç nɪçts ɑbɜ vaɪst du/","zh":"我对音乐一窍不通。但是你可知道？","en":"I don't know anything about music. But do you know?","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-21-007","lineIndex":7,"speaker":"康斯坦斯","original":"Du bist ganz anders als die andern, die ich traf.","ipa":"/du bɪst ɡants andɜs als di andɜn di ɪç tɾɑf/","zh":"你与我遇到的其他人完全不同","en":"You are completely different from the others I met.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-21-008","lineIndex":8,"speaker":"康斯坦斯","original":"Nicht so schrecklich erwachsen.","ipa":"/nɪçt zo ʃrɛklɪç ɛɾvaxzən/","zh":"没有令人作呕的圆滑世故","en":"Not terribly grown up.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-21-009","lineIndex":9,"speaker":"康斯坦斯","original":"Ein Feuerkopf.","ipa":"/aɪn fɔøɜkɔpf/","zh":"性情率真","en":"A firehead.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-21-010","lineIndex":10,"speaker":"康斯坦斯","original":"Du spuckst gegen den Wind.","ipa":"/du ʃpʊkst ɡeɡən den vɪnt/","zh":"你会迎着风吐痰（啊哈哈哈多么天真孩子气）","en":"You spit against the wind.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-21-011","lineIndex":11,"speaker":"康斯坦斯","original":"Immer lustig, niemals brav.","ipa":"/ɪmɜ lʊstɪç nimɑls bɾɑf/","zh":"总是幽默风趣，从不偏安一隅","en":"Always funny, never well-behaved.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-21-012","lineIndex":12,"speaker":"康斯坦斯","original":"voller Späße und Faxen.","ipa":"/fɔlɜ ʃpɛsə ʊnt fɑksən/","zh":"涌动着无尽的欢乐","en":"full of jokes and faxes.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-21-013","lineIndex":13,"speaker":"康斯坦斯","original":"Kein Sauertopf.","ipa":"/kaɪn zaʊɜtɔpf/","zh":"不会满腹牢骚","en":"No sour pot.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-21-014","lineIndex":14,"speaker":"康斯坦斯","original":"Andre sind reicher und schön're gibt es auch.","ipa":"/andɾə zɪnt raɪçɜ ʊnt ʃønrə ɡipt ɛs aʊx/","zh":"多得是比你有钱而帅气的人。","en":"Others are richer and there are more beautiful ones too.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-21-015","lineIndex":15,"speaker":"康斯坦斯","original":"Doch was du hast, hab' ich oft vermisst.","ipa":"/dɔx vas du hast hɑp ɪç ɔft fɛɾmɪst/","zh":"但你所拥有的秉性，才是我的魂牵梦萦","en":"But I often missed what you have.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-21-016","lineIndex":16,"speaker":"康斯坦斯","original":"Na, kurz und gut:","ipa":"/nɑ kʊɐts ʊnt ɡut/","zh":"简而言之","en":"Well, in short:","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-21-017","lineIndex":17,"speaker":"康斯坦斯","original":"du gefällst mir, weil du so bist, wie du bist.","ipa":"/du ɡəfɛlst miɾ vaɪl du zo bɪst vi du bɪst/","zh":"我喜欢你，因你是你。","en":"I like you because you are the way you are.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-21-018","lineIndex":18,"speaker":"沃尔夫冈","original":"Ich mag dich auch.","ipa":"/ɪç mɑk dɪç aʊx/","zh":"我也喜欢你","en":"I like you too.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-21-019","lineIndex":19,"speaker":"沃尔夫冈","original":"Und nur deshalb, weil du so bist, wie du bist.","ipa":"/ʊnt nuɾ dɛshalp vaɪl du zo bɪst vi du bɪst/","zh":"也只是因为你就是你。","en":"And only because you are who you are.","note":"","sourceLineIndex":19}],"sourceOrder":21,"displayOrder":18},{"order":22,"id":"22-wir-zwei-zusammen","title":"Wir zwei zusammen","titleZh":"我们两人在一起","lines":[{"id":"mozart-das-musical-22-001","lineIndex":1,"speaker":"","original":"Dich könnt ich gut ertragen.","ipa":"/dɪç kœnt ɪç ɡut ɛɾtɾɑɡən/","zh":"我能接受你的一切","en":"I can tolerate you well.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-22-002","lineIndex":2,"speaker":"","original":"Mit dir würd ich mich gut verstehn.","ipa":"/mɪt diɾ vʏɾt ɪç mɪç ɡut fɛɾʃten/","zh":"在你身边我能更好地认识自己","en":"I would get along well with you.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-22-003","lineIndex":3,"speaker":"","original":"Wir zwei zusammen das könnte gehn.","ipa":"/viːɾ tsvˈaɪ tsuːzˈamən das kˈœntə ɡˈeːn/","zh":"只要我们在一起什么都有可能","en":"The two of us together that could work.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-22-005","lineIndex":4,"speaker":"","original":"Ich stell dir keine Fragen.","ipa":"/ɪç ʃtɛl diɾ kaɪnə frɑɡən/","zh":"我不用向你询问","en":"I'm not asking you any questions.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-22-006","lineIndex":5,"speaker":"","original":"Und kann doch deine Träume sehn.","ipa":"/ʊnt kan dɔx daɪnə tɾɔømə zen/","zh":"也能看懂你的梦想","en":"And yet I can see your dreams.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-22-007","lineIndex":6,"speaker":"","original":"Wir zwei zusammen das könnte gehn.","ipa":"/viːɾ tsvˈaɪ tsuːzˈamən das kˈœntə ɡˈeːn/","zh":"只要我们在一起什么都有可能","en":"The two of us together that could work.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-22-009","lineIndex":7,"speaker":"","original":"Ich möchte frei sein frei von jeder Fessel.","ipa":"/ɪç mˈœçtə frˈaɪ zaɪn frˈaɪ fɔn jˈeːdɜ fˈɛsəl/","zh":"我想自由自在摆脱所有枷锁的桎梏","en":"I want to be free free from every bondage.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-22-011","lineIndex":8,"speaker":"","original":"Willst du dabei sein wenn es mir gelingt?","ipa":"/vɪlst duː dɑːbˈaɪ zaɪn vˌɛn ɛs miːɾ ɡəlˈɪŋt/","zh":"你是否愿意和我一同将自由追寻？","en":"Do you want to be there if I succeed?","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-22-013","lineIndex":9,"speaker":"","original":"Ich wollt mich nie verlieben.","ipa":"/ɪç vɔlt mɪç ni fɛɾlibən/","zh":"我从未想过坠入爱河","en":"I never wanted to fall in love.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-22-014","lineIndex":10,"speaker":"","original":"Jedoch mit dir könnt es geschehn.","ipa":"/jedɔx mɪt diɾ kœnt ɛs ɡəʃen/","zh":"然而我愿与你相恋","en":"However, with you it can happen.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-22-015","lineIndex":11,"speaker":"","original":"Wir zwei zusammen das könnte gehn.","ipa":"/viːɾ tsvˈaɪ tsuːzˈamən das kˈœntə ɡˈeːn/","zh":"我们在一起什么都有可能","en":"The two of us together that could work.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-22-017","lineIndex":12,"speaker":"","original":"Ich würd gern da sein wenn du morgens aufstehst und dir gern nah sein wenn die Nacht beginnt.","ipa":"/ɪç vˈʏɾt ɡˈɛɾn dɑː zaɪn vˌɛn duː mˈɔɾɡəns ˈaʊfʃtˌeːst ʊnt diːɾ ɡˈɛɾn nˈɑː zaɪn vˌɛn diː nˈaxt bəɡˈɪnt/","zh":"我愿在你身边看着你从清晨醒来我想同你一起迎接夜幕降临","en":"I would like to be there when you get up in the morning and be close to you when the night begins.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-22-021","lineIndex":13,"speaker":"","original":"Und wenn ich Hilfe brauche","ipa":"/ʊnt vɛn ɪç hɪlfə bɾaʊxə/","zh":"若我感到无助","en":"And if I need help","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-22-022","lineIndex":14,"speaker":"","original":"(Und wenn ich Hilfe brauche, )","ipa":"/ʊnt vɛn ɪç hɪlfə bɾaʊxə/","zh":"若我感到无助","en":"(And if I need help, )","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-22-023","lineIndex":15,"speaker":"","original":"ich glaub, du würdest zu mir stehn.","ipa":"/ɪç ɡlaʊp du vʏɾdəst tsu miɾ ʃten/","zh":"我想你一定会站在我身边","en":"I think you would stand by me.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-22-024","lineIndex":16,"speaker":"","original":"(ich glaub, du würdest zu mir stehn.)","ipa":"/ɪç ɡlaʊp du vʏɾdəst tsu miɾ ʃten/","zh":"我想你一定会站在我身边","en":"(I think you would stand by me.)","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-22-025","lineIndex":17,"speaker":"","original":"Wir zwei zusammen","ipa":"/viɾ tsvaɪ tsuzamən/","zh":"我们在一起","en":"The two of us together","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-22-026","lineIndex":18,"speaker":"","original":"(Wir zwei zusammen, )","ipa":"/viɾ tsvaɪ tsuzamən/","zh":"我们在一起","en":"(The two of us together, )","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-22-027","lineIndex":19,"speaker":"","original":"das könnte gehn.","ipa":"/das kœntə ɡen/","zh":"什么都有可能","en":"that could work.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-22-028","lineIndex":20,"speaker":"","original":"Wir zwei zusammen das könnte gehn.","ipa":"/viːɾ tsvˈaɪ tsuːzˈamən das kˈœntə ɡˈeːn/","zh":"我们在一起什么都有可能","en":"The two of us together that could work.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-22-030","lineIndex":21,"speaker":"","original":"Das könnte gehn.","ipa":"/das kœntə ɡen/","zh":"什么都有可能","en":"That could work.","note":"","sourceLineIndex":30}],"sourceOrder":22,"displayOrder":19},{"order":23,"id":"23-ich-bleibe-in-wien","title":"Ich bleibe in Wien!","titleZh":"我要留在维也纳！","lines":[{"id":"mozart-das-musical-23-001","lineIndex":1,"speaker":"Graf Arco","original":"Halt! Wohin?","ipa":"/ɡɾɑf aɾko halt vohin/","zh":"阿尔科伯爵站住！去哪儿？","en":"Count ArcoStop! Where?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-23-002","lineIndex":2,"speaker":"Wolfgang","original":"Zum Erzbischof!","ipa":"/vɔlfɡaŋ tsʊm ɛɾtsbɪʃof/","zh":"沃尔夫冈我要去找大主教！","en":"WolfgangTo the Archbishop!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-23-003","lineIndex":3,"speaker":"Graf Arco","original":"Hier hast du nichts mehr zu suchen!","ipa":"/ɡɾɑf aɾko hiɾ hast du nɪçts meɾ tsu zuxən/","zh":"阿尔科伯爵在这儿找他你想都别想！","en":"Count ArcoYou have no business being here anymore!","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-23-004","lineIndex":4,"speaker":"Wolfgang","original":"Ich lasse mich nicht einfach wegschicken.","ipa":"/vɔlfɡaŋ ɪç lasə mɪç nɪçt aɪnfax vɛkʃɪkən/","zh":"沃尔夫冈你也想都别想就这么把我打发走","en":"WolfgangI won't just let myself be sent away.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-23-005","lineIndex":5,"speaker":"","original":"Heute Abend spiele ich vor dem Kaiser.","ipa":"/hɔøtə ɑbənt ʃpilə ɪç fɔɾ dem kaɪzɜ/","zh":"今天晚上我要为皇帝演出","en":"Tonight I'm playing for the emperor.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-23-006","lineIndex":6,"speaker":"Graf Arco","original":"Nein! Das hast du dir verscherzt.","ipa":"/ɡɾɑf aɾko naɪn das hast du diɾ fɛɾʃɛɾtst/","zh":"阿尔科伯爵不行，你不能去！","en":"Count ArcoNo! You missed that.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-23-007","lineIndex":7,"speaker":"Wolfgang","original":"Gift und Galle!","ipa":"/vɔlfɡaŋ ɡɪft ʊnt ɡalə/","zh":"沃尔夫冈气死我了！","en":"WolfgangPoison and bile!","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-23-008","lineIndex":8,"speaker":"","original":"Colloredo hat es versprochen.","ipa":"/kɔloredo hat ɛs fɛɾʃpɾɔxən/","zh":"科洛雷多答应过的","en":"Colloredo promised.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-23-009","lineIndex":9,"speaker":"","original":"Er hat es versprochen!","ipa":"/ɛɾ hat ɛs fɛɾʃpɾɔxən/","zh":"他答应过我—","en":"He promised!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-23-010","lineIndex":10,"speaker":"Graf Arco","original":"Ab nach Salzburg mit dir!","ipa":"/ɡɾɑf aɾko ap nɑx zaltsbʊɐk mɪt diɾ/","zh":"阿尔科伯爵前提是你要回萨尔茨堡去！","en":"Graf Arco Off to Salzburg with you!","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-23-011","lineIndex":11,"speaker":"","original":"Was fällt dir ein?","ipa":"/vas fɛlt diɾ aɪn/","zh":"这有你什么说话的地方？","en":"What comes to mind?","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-23-012","lineIndex":12,"speaker":"","original":"Seiner Exzellenz darf nicht gestört werden.","ipa":"/zaɪnɜ ɛkstsəlɛnts daɾf nɪçt ɡəʃtœɾt vɛɾdən/","zh":"主教大人说不要打扰他","en":"His Excellency must not be disturbed.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-23-013","lineIndex":13,"speaker":"Wolfgang","original":"Ich muss mit ihm reden.","ipa":"/vɔlfɡaŋ ɪç mʊs mɪt im redən/","zh":"沃尔夫冈我必须得跟他谈谈","en":"WolfgangI have to talk to him.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-23-014","lineIndex":14,"speaker":"Graf Arco","original":"Aber… Er ist beschäftigt!","ipa":"/ɡɾɑf aɾko ɑbɜ ɛɾ ɪst bəʃɛftɪçt/","zh":"阿尔科伯爵可是……他现在忙得很","en":"Count ArcoBut... He's busy!","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-23-015","lineIndex":15,"speaker":"Fürsterzbischof","original":"Verflucht, was ist das!?","ipa":"/fʏɾstɜtsbɪʃof fɛɾflʊxt vas ɪst das/","zh":"主教大人该死的，这是做什么？","en":"Prince ArchbishopCursed, what is this!?","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-23-016","lineIndex":16,"speaker":"Graf Arco","original":"Er drang einfach ein","ipa":"/ɡɾɑf aɾko ɛɾ dɾaŋ aɪnfax aɪn/","zh":"阿尔科伯爵是他闯进来的","en":"Count ArcoHe just invaded","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-23-017","lineIndex":17,"speaker":"Fürsterzbischof","original":"Raus hier, sonst lass ich ihn prügeln!","ipa":"/fʏɾstɜtsbɪʃof raʊs hiɾ zɔnst las ɪç in pɾyɡəln/","zh":"主教大人给我出去！不然休怪我动手打人！","en":"Prince ArchbishopGet out of here, otherwise I'll have him beaten!","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-23-018","lineIndex":18,"speaker":"Graf Arco","original":"Verschwinden Sie, Mozart!","ipa":"/ɡɾɑf aɾko fɛɾʃvɪndən zi motsaɾt/","zh":"阿尔科伯爵走吧，莫扎特！","en":"Count ArcoGo away, Mozart!","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-23-019","lineIndex":19,"speaker":"Wolfgang","original":"Was sein muss, muss sein!","ipa":"/vɔlfɡaŋ vas zaɪn mʊs mʊs zaɪn/","zh":"沃尔夫冈该是什么就是什么！","en":"WolfgangWhat has to be, has to be!","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-23-020","lineIndex":20,"speaker":"Fürsterzbischof","original":"Ich werd seine Frechheit scho zügeln","ipa":"/fʏɾstɜtsbɪʃof ɪç veɾt zaɪnə frɛçhaɪt ʃo tsyɡəln/","zh":"主教大人我倒要治治他这般傲慢无礼","en":"Prince ArchbishopI'll curb his impudence","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-23-021","lineIndex":21,"speaker":"Wolfgang","original":"Ich beug mich nicht mehr","ipa":"/vɔlfɡaŋ ɪç bɔøk mɪç nɪçt meɾ/","zh":"沃尔夫冈我不再卑躬屈膝","en":"WolfgangI won't bow down any more","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-23-022","lineIndex":22,"speaker":"Graf Arco","original":"Das ist wohl ein Scherz","ipa":"/ɡɾɑf aɾko das ɪst vol aɪn ʃɛɾts/","zh":"阿尔科伯爵真是无稽之谈！","en":"Count ArcoThat's probably a joke","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-23-023","lineIndex":23,"speaker":"Wolfgang","original":"Menschen adelt nur das Herz","ipa":"/vɔlfɡaŋ mɛnʃən ɑdəlt nuɾ das hɛɾts/","zh":"沃尔夫冈一颗真心才能使人高尚","en":"WolfgangOnly the heart ennobles people","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-23-024","lineIndex":24,"speaker":"Fürsterzbischof","original":"Ich hab ihm befohlen","ipa":"/fʏɾstɜtsbɪʃof ɪç hɑp im bəfolən/","zh":"主教大人我早就命令过他","en":"Prince ArchbishopI ordered him","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-23-025","lineIndex":25,"speaker":"","original":"nach Salzburg zu ziehn","ipa":"/nɑx zaltsbʊɐk tsu tsin/","zh":"回萨尔茨堡去","en":"to move to Salzburg","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-23-026","lineIndex":26,"speaker":"Wolfgang","original":"Adieu, Fürst, ich bleibe in Wien!","ipa":"/vɔlfɡaŋ ɑdiu fyɾst ɪç blaɪbə ɪn vin/","zh":"沃尔夫冈再见啦大人，我要留在维也纳！","en":"WolfgangAdieu, prince, I'm staying in Vienna!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-23-027","lineIndex":27,"speaker":"Fürsterzbischof","original":"So, der Lump gehorcht nicht mehr?","ipa":"/fʏɾstɜtsbɪʃof zo dɛɾ lʊmp ɡəhɔɾçt nɪçt meɾ/","zh":"主教大人这无赖倒先顶起了嘴","en":"Prince ArchbishopSo, the scoundrel no longer obeys?","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-23-028","lineIndex":28,"speaker":"","original":"Möchte mir gar drohn?","ipa":"/mœçtə miɾ ɡɑɾ dɾon/","zh":"是要威胁我吗？","en":"Do you even want to threaten me?","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-23-029","lineIndex":29,"speaker":"","original":"Hier in Wien verhungert er","ipa":"/hˈiːɾ ɪn vˈiːn fɛɾhˈʊŋɜt ɛɾ/","zh":"在维也纳他会忍饥挨饿","en":"Here in Vienna he's starving","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-23-031","lineIndex":30,"speaker":"","original":"Dafür sorg ich schon","ipa":"/dɑryɾ zɔɾk ɪç ʃon/","zh":"这我早有预料","en":"I'll take care of that","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-23-032","lineIndex":31,"speaker":"Wolfgang","original":"Ja, Sie sind mächtig (Hört!)","ipa":"/vɔlfɡaŋ jɑ zi zɪnt mɛçtɪç hœɾt/","zh":"沃尔夫冈 没错您有权有势（你们听听！）","en":"WolfgangYes, you are powerful (Listen!)","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-23-033","lineIndex":32,"speaker":"","original":"Ein Fürst der Provinz (Unverschämt! Jetzt geht zu weit!)","ipa":"/aɪn fyɾst dɛɾ pɾovɪnts ʊnfɛɾʃɛmt jɛtst ɡet tsu vaɪt/","zh":"是个掌管领地的王爷（恬不知耻！真是放肆！）","en":"A prince of the province (Outrageous! Now it's going too far!)","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-23-034","lineIndex":33,"speaker":"","original":"Doch mich können Sie nicht erschrecken (Welch ein Benehmen!)","ipa":"/dɔx mɪç kœnən zi nɪçt ɛɾʃrɛkən vɛlç aɪn bənemən/","zh":"可您也一样吓不倒我（这都什么态度！）","en":"But you can't scare me (What behavior!)","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-23-035","lineIndex":34,"speaker":"","original":"Denn ich hab Talent (Das ist verrückt)","ipa":"/dɛn ɪç hɑp talɛnt das ɪst fɛɾrʏkt/","zh":"我有的是才华（简直疯了！）","en":"Because I have talent (That's crazy)","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-23-036","lineIndex":35,"speaker":"","original":"darum bin ich ein Prinz (Das tut ihm noch leid!)","ipa":"/dɑrʊm bɪn ɪç aɪn pɾɪnts das tut im nɔx laɪt/","zh":"所以我也算是个王子（他会后悔的！）","en":"That's why I'm a prince (He's still sorry!)","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-23-037","lineIndex":36,"speaker":"","original":"Ich muss mich vor keinem verstecken (Das ist zuviel! Seht Colloredo bebt!)","ipa":"/ɪç mʊs mɪç fɔɾ kaɪnəm fɛɾʃtɛkən das ɪst tsufil zet kɔloredo bept/","zh":"我无需屈居人后，躲躲藏藏（太过分了！看看，科洛雷多一片好心！）","en":"I don't have to hide from anyone (That's too much! See Colloredo shaking!)","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-23-038","lineIndex":37,"speaker":"","original":"Sie stahlen mir Zeit (Hört!)","ipa":"/zi ʃtɑlən miɾ tsaɪt hœɾt/","zh":"您霸占了我的时间（听听，）","en":"They stole my time (Listen!)","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-23-039","lineIndex":38,"speaker":"","original":"Sie stahlen mir Geld (wie er lügt! Das ist impertinent!)","ipa":"/zi ʃtɑlən miɾ ɡɛlt vi ɛɾ lykt das ɪst ɪmpɛɾtinɛnt/","zh":"偷走了我的金钱（他信口开河！厚颜无耻！）","en":"They stole my money (like he lies! That's impertinent!)","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-23-040","lineIndex":39,"speaker":"","original":"sperrten mich in ihre Welt (Hört euch das an! Irr! Wirr!)","ipa":"/ʃpɛɾtən mɪç ɪn irə vɛlt hœɾt ɔøç das an ɪɾ vɪɾ/","zh":"把我圈禁在您的世界（你们听听这话！真是一派胡言！）","en":"locked me in their world (Listen to this! Crazy! Crazy!)","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-23-041","lineIndex":40,"speaker":"","original":"Nie war ich Ihr Knecht (Hört!)","ipa":"/ni vɑɾ ɪç iɾ knɛçt hœɾt/","zh":"我从不是您的奴仆（听听，）","en":"I was never your servant (Listen!)","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-23-042","lineIndex":41,"speaker":"","original":"auch wenn es so schien (euch das an! Mozart kennt ihn noch nicht.)","ipa":"/aʊx vɛn ɛs zo ʃin ɔøç das an motsaɾt kɛnt in nɔx nɪçt/","zh":"尽管看上去确实如此（听听这话！这个莫扎特根本不知道自己几斤几两！）","en":"even if it seemed that way (look at that! Mozart doesn't know him yet.)","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-23-043","lineIndex":42,"speaker":"","original":"Adieu, Fürst, ich bleibe in Wien!","ipa":"/ɑdiu fyɾst ɪç blaɪbə ɪn vin/","zh":"再见啦大人，我就留在维也纳！","en":"Farewell, Prince, I'm staying in Vienna!","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-23-044","lineIndex":43,"speaker":"Fürsterzbischof","original":"Mir tut nur sein Vater leid","ipa":"/fʏɾstɜtsbɪʃof miɾ tut nuɾ zaɪn fɑtɜ laɪt/","zh":"主教大人我真为他的父亲感到遗憾","en":"Prince ArchbishopI just feel sorry for his father","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-23-045","lineIndex":44,"speaker":"","original":"Sein Sohn ist ein Erzlump!","ipa":"/zaɪn zon ɪst aɪn ɛɾtslʊmp/","zh":"他的儿子就是个十恶不赦的混蛋！","en":"His son is a rascal!","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-23-046","lineIndex":45,"speaker":"Wolfgang","original":"Ein Lump war ich nur (Fex, Narr, Dalk, dummer Bub!)","ipa":"/vɔlfɡaŋ aɪn lʊmp vɑɾ ɪç nuɾ fɛks naɾ dalk dʊmɜ bup/","zh":"沃尔夫冈我要是追求（傻瓜，疯子，笨蛋，智障！）","en":"WolfgangI was just a scoundrel (Fex, fool, Dalk, stupid boy!)","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-23-047","lineIndex":46,"speaker":"","original":"würd ich danach geh'n (Soll er eben ziehn!)","ipa":"/vʊɐt ɪç danax ɡen zɔl ɛɾ ebən tsin/","zh":"稳定与安逸（他生来如此！）","en":"I would go for it (Let him just go!)","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-23-048","lineIndex":47,"speaker":"","original":"was sicher und möglichst bequem ist (Fex, Narr, Dalk, Lümmel, Erzlump!)","ipa":"/vas zɪçɜ ʊnt mœɡlɪkst bəkvem ɪst fɛks naɾ dalk lʏməl ɛɾtslʊmp/","zh":"那我才真是个混蛋（傻瓜，疯子，笨蛋，流氓，混蛋！）","en":"what was safe and as comfortable as possible (Fex, fool, Dalk, lout, arch rogue!)","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-23-049","lineIndex":48,"speaker":"","original":"Ein Künstler wie ich (Fex, Narr, Dalk, dummer Erzlump!)","ipa":"/aɪn kʏnstlɜ vi ɪç fɛks naɾ dalk dʊmɜ ɛɾtslʊmp/","zh":"像我一样的艺术家（傻瓜，疯子，笨蛋，智障！）","en":"An artist like me (fex, fool, Dalk, stupid rogue!)","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-23-050","lineIndex":49,"speaker":"","original":"darf nicht danach sehn (Wien ist sein Ruin!)","ipa":"/daɾf nɪçt danax zen vin ɪst zaɪn ruɪn/","zh":"才不会迁就（他完了！）","en":"must not look for it (Vienna is his ruin!)","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-23-051","lineIndex":50,"speaker":"","original":"was Fürsten und Vätern genehm ist (Fex, Narr, Dalk, Lümmel, Erzlump, Wicht!)","ipa":"/vas fyɾstən ʊnt fɛtɜn ɡənem ɪst fɛks naɾ dalk lʏməl ɛɾtslʊmp vɪçt/","zh":"王爷或者父亲的意见喜好（傻瓜，疯子，笨蛋，流氓，混蛋，小恶棍！）","en":"what is acceptable to princes and fathers (Fex, fool, Dalk, lout, rascal, wretch!)","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-23-052","lineIndex":51,"speaker":"","original":"Gibt es auf die Zukunft (Fex, Narr, Dalk, dummer Bub!)","ipa":"/ɡipt ɛs aʊf di tsukʊnft fɛks naɾ dalk dʊmɜ bup/","zh":"就算前路（傻瓜，疯子，笨蛋，智障！）","en":"Does the future exist (Fex, fool, Dalk, stupid boy!)","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-23-053","lineIndex":52,"speaker":"","original":"auch keine Gewähr (Das bricht ihm seinen Hals!)","ipa":"/aʊx kaɪnə ɡəvɛɾ das bɾɪçt im zaɪnən hɑls/","zh":"没有任何保障（他会一败涂地的！）","en":"also no guarantee (That will break his neck!)","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-23-054","lineIndex":53,"speaker":"","original":"ich brauch keinen Vormund mehr!","ipa":"/ɪç bɾaʊx kaɪnən foɾmʊnt meɾ/","zh":"我也不再需要什么监护人","en":"I don't need a guardian anymore!","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-23-055","lineIndex":54,"speaker":"","original":"Niemand wird mich zum Sklaven erziehn! (Fex, Narr, Dalk, dummer Bub!)","ipa":"/nimant vɪɾt mɪç tsʊm sklɑvən ɛɾtsin fɛks naɾ dalk dʊmɜ bup/","zh":"没人能迫使我成为奴隶！（傻瓜，疯子，笨蛋，智障！）","en":"Nobody will raise me to be a slave! (Fex, fool, Dalk, stupid boy!)","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-23-056","lineIndex":55,"speaker":"","original":"(Dieser Mozart muss verrückt sein)","ipa":"/dizɜ motsaɾt mʊs fɛɾrʏkt zaɪn/","zh":"（这莫扎特一定是疯了）","en":"(This Mozart must be crazy)","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-23-057","lineIndex":56,"speaker":"","original":"(Wie kann er so ungeschickt sein)","ipa":"/vi kan ɛɾ zo ʊnɡəʃɪkt zaɪn/","zh":"（他怎么这么蠢）","en":"(How can he be so clumsy)","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-23-058","lineIndex":57,"speaker":"","original":"Adieu, Fürst, Ich bleibe in Wien! (und dem Fürsten offen sagen er bleibt in Wien?)","ipa":"/ɑdiu fyɾst ɪç blaɪbə ɪn vin ʊnt dem fyɾstən ɔfən zɑɡən ɛɾ blaɪpt ɪn vin/","zh":"再见啦大人，我就留在维也纳！","en":"Farewell, prince, I'm staying in Vienna! (and openly tell the prince he is staying in Vienna?)","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-23-059","lineIndex":58,"speaker":"Fürsterzbischof","original":"Keiner hat mich je so schlecht bedient wie er.","ipa":"/fʏɾstɜtsbɪʃof kaɪnɜ hat mɪç je zo ʃlɛçt bədint vi ɛɾ/","zh":"主教大人我从未见过这么差劲的仆从！","en":"Prince ArchbishopNo one has ever served me as badly as he did.","note":"","sourceLineIndex":59},{"id":"mozart-das-musical-23-060","lineIndex":59,"speaker":"","original":"Liederlicher Bursche.","ipa":"/lidɜlɪçɜ bʊɐʃə/","zh":"随随便便的家伙","en":"Dissolute fellow.","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-23-061","lineIndex":60,"speaker":"","original":"Ich will nichts mehr zu tun haben mit ihm!","ipa":"/ɪç vɪl nɪçts meɾ tsu tun hɑbən mɪt im/","zh":"我不想跟他再有任何瓜葛","en":"I don't want anything to do with him anymore!","note":"","sourceLineIndex":61},{"id":"mozart-das-musical-23-062","lineIndex":61,"speaker":"Wolfgang","original":"Ich mit Ihnen auch nicht.","ipa":"/vɔlfɡaŋ ɪç mɪt inən aʊx nɪçt/","zh":"沃尔夫冈我也不想和您再打交道了","en":"WolfgangMe neither with you.","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-23-063","lineIndex":62,"speaker":"Fürsterzbischof","original":"Komm er mir noch einmal angewinselt...!","ipa":"/fʏɾstɜtsbɪʃof kɔm ɛɾ miɾ nɔx aɪnmɑl anɡəvɪnzəlt/","zh":"主教大人就算他再来求我一次，我也……","en":"Prince ArchbishopCome whine to me again...!","note":"","sourceLineIndex":63},{"id":"mozart-das-musical-23-064","lineIndex":63,"speaker":"Wolfgang","original":"Ich scheiss auf Sie!","ipa":"/vɔlfɡaŋ ɪç ʃaɪs aʊf zi/","zh":"沃尔夫冈我呸！","en":"WolfgangI shit on you!","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-23-065","lineIndex":64,"speaker":"Fürsterzbischof","original":"Graf Arco!","ipa":"/fʏɾstɜtsbɪʃof ɡɾɑf aɾko/","zh":"主教大人阿尔科伯爵","en":"Prince ArchbishopCount Arco!","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-23-066","lineIndex":65,"speaker":"","original":"Schmeissen Sie ihn raus. Mit einem Fußtritt!","ipa":"/ʃmaɪsən zi in raʊs mɪt aɪnəm fʊsʃtɾɪt/","zh":"把他扔出去。给我TM补两脚！","en":"Kick him out. With a kick!","note":"","sourceLineIndex":66},{"id":"mozart-das-musical-23-067","lineIndex":66,"speaker":"Graf Arco","original":"Schade um Sie, Mozart.","ipa":"/ɡɾɑf aɾko ʃɑdə ʊm zi motsaɾt/","zh":"阿尔科伯爵真是遗憾啊，莫扎特","en":"Count ArcoIt's a shame about you, Mozart.","note":"","sourceLineIndex":67},{"id":"mozart-das-musical-23-068","lineIndex":67,"speaker":"","original":"Jetzt ist es aus mit Ihnen","ipa":"/jɛtst ɪst ɛs aʊs mɪt inən/","zh":"您现在算是玩完了","en":"It's over with you now","note":"","sourceLineIndex":68},{"id":"mozart-das-musical-23-069","lineIndex":68,"speaker":"Wolfgang","original":"Nein!","ipa":"/vɔlfɡaŋ naɪn/","zh":"沃尔夫冈不！","en":"WolfgangNo!","note":"","sourceLineIndex":69},{"id":"mozart-das-musical-23-070","lineIndex":69,"speaker":"","original":"Ich fange erst an Jetzt bin ich frei!","ipa":"/ɪç fˈaŋə ˈeːɾst an jˌɛtst bɪn ɪç frˈaɪ/","zh":"我这才刚刚开始呢现在我……自由了！","en":"I'm just getting started Now I'm free!","note":"","sourceLineIndex":70}],"sourceOrder":23,"displayOrder":20},{"order":24,"id":"24-wie-wird-man-seinen-schatten-los","title":"Wie wird man seinen Schatten los?","titleZh":"如何逃离自己的阴影？","lines":[{"id":"mozart-das-musical-24-001","lineIndex":1,"speaker":"","original":"Auf Fürstengunst verzichte ich.","ipa":"/aʊf fʏɾstənɡʊnst fɛɾtsɪçtə ɪç/","zh":"我摒弃蒙赐于主教的一切","en":"I renounce royal favor.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-24-002","lineIndex":2,"speaker":"","original":"Und auch auf die Puderlocken.","ipa":"/ʊnt aʊx aʊf di pudɜlɔkən/","zh":"及所有声色荣华。","en":"And also on the powder curls.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-24-003","lineIndex":3,"speaker":"","original":"Der Muff von Staub und Weihrauchduft genügt mir nicht mehr.","ipa":"/dɛɾ mʊf fɔn ʃtaʊp ʊnt vaɪhraʊxdʊft ɡənykt miɾ nɪçt meɾ/","zh":"我不满足于粉饰与熏缭下的空气","en":"The mustiness of dust and the smell of incense is no longer enough for me.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-24-004","lineIndex":4,"speaker":"","original":"Ich will das wahre Leben spür'n.","ipa":"/ɪç vɪl das vɑrə lebən ʃpyɾn/","zh":"只渴求感受真正的生活。","en":"I want to feel real life.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-24-005","lineIndex":5,"speaker":"","original":"Es hat dicke, rote Lippen es riecht nach Wein und wärmt mich in der Nacht.","ipa":"/ɛs hat dˈɪkə rˈoːtə lˈɪpən ɛs rˈiːçt nɑːx vˈaɪn ʊnt vˈɛɾmt mɪç ɪn dɛɾ nˈaxt/","zh":"夜幕下的红唇和美酒让我感受到几分温度","en":"It has thick, red lips it smells like wine and warms me at night.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-24-008","lineIndex":6,"speaker":"","original":"Es flüstert, weint und lacht.","ipa":"/ɛs flʏstɜt vaɪnt ʊnt laxt/","zh":"那是耳语，交之悲泣与哗笑。","en":"It whispers, cries and laughs.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-24-009","lineIndex":7,"speaker":"","original":"Die Frage ist bloss:","ipa":"/di frɑɡə ɪst blɔs/","zh":"而问题只是","en":"The question is just:","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-24-010","lineIndex":8,"speaker":"","original":"Wie wird man seinen Schatten los?","ipa":"/vi vɪɾt man zaɪnən ʃatən los/","zh":"你要如何逃离自己的影子？","en":"How do you get rid of your shadow?","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-24-011","lineIndex":9,"speaker":"","original":"Wie sagt man seinem Schicksal Nein?","ipa":"/vi zɑkt man zaɪnəm ʃɪkzɑl naɪn/","zh":"如何反叛命运？","en":"How do you say no to your fate?","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-24-012","lineIndex":10,"speaker":"","original":"Wie kriecht man aus der eignen Haut?","ipa":"/vi kɾiçt man aʊs dɛɾ aɪɡnən haʊt/","zh":"又要如何冲破桎梏？","en":"How do you crawl out of your own skin?","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-24-013","lineIndex":11,"speaker":"","original":"Wie kann man je ein andrer sein?","ipa":"/vi kan man je aɪn andɾɜ zaɪn/","zh":"如何得到重生？","en":"How can you ever be someone else?","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-24-014","lineIndex":12,"speaker":"","original":"Wen soll man fragen wenn man sich selber nicht versteht?","ipa":"/vˈeːn zˌɔl man frˈɑːɡən vˌɛn man zɪç zˈɛlbɜ nˈɪçt fɛɾʃtˈeːt/","zh":"如果你不曾了解过自己又能向谁寻得答案？","en":"Who should you ask if you don't understand yourself?","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-24-016","lineIndex":13,"speaker":"","original":"Wie kann man frei sein wenn man seinem eignen Schatten nie entgeht?","ipa":"/viː kˌan man frˈaɪ zaɪn vˌɛn man zˌaɪnəm ˈaɪɡnən ʃˈatən nˈiː ɛntɡˈeːt/","zh":"如果你不曾摆脱自己的影子又能如何得到自由？","en":"How can you be free if you never escape your own shadow?","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-24-018","lineIndex":14,"speaker":"","original":"Was soll mir die Unsterblichkeit!","ipa":"/vas zɔl miɾ di ʊnʃtɛɾplɪçkaɪt/","zh":"我看不到不朽有任何意义","en":"What's the use of immortality for me!","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-24-019","lineIndex":15,"speaker":"","original":"Vor dem Sterben will ich leben.","ipa":"/fɔɾ dem ʃtɛɾbən vɪl ɪç lebən/","zh":"我要的是全然尽致地活。","en":"Before I die, I want to live.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-24-020","lineIndex":16,"speaker":"","original":"Der Grabgeruch der Lorbeergruft betäubt mich nicht mehr.","ipa":"/dɛɾ ɡɾabɡerʊx dɛɾ lɔɾbeɾɡɾʊft bətɔøpt mɪç nɪçt meɾ/","zh":"腐墓沉着，而我不再受之蛊惑。","en":"The grave smell of the laurel tomb no longer intoxicates me.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-24-021","lineIndex":17,"speaker":"","original":"Was ist die schönste Sinfonie gegen einen weichen Busen?","ipa":"/vˈas ɪst diː ʃˈøːnstə zˌɪnfoːnˈiː ɡˌeːɡən ˌaɪnən vˈaɪçən bˈʊsən/","zh":"与柔软的胸膛相比能有什么交响曲更为美妙？","en":"What is the most beautiful symphony compared to a soft breast?","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-24-023","lineIndex":18,"speaker":"","original":"Kein Geigenklang kann je so zärtlich sein wie eine Hand im Haar.","ipa":"/kˈaɪn ɡˈaɪɡənklˌaŋ kˌan jeː zoː tsˈɛɾtlɪç zaɪn viː ˌaɪnə hˈant ɪm hˈɑːɾ/","zh":"也没有什么小提琴的旋律柔冶且怀情比指尖穿过发丝更为动人","en":"No violin sound can ever be as tender as a hand in your hair.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-24-026","lineIndex":19,"speaker":"","original":"Die Frage ist bloss:","ipa":"/di frɑɡə ɪst blɔs/","zh":"而问题只是","en":"The question is just:","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-24-028","lineIndex":20,"speaker":"Wolfgang & Chor","original":"Wie wird man seinen Schatten los?","ipa":"/vi vɪɾt man zaɪnən ʃatən los/","zh":"你要如何逃离自己的影子？","en":"How do you get rid of your shadow?","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-24-029","lineIndex":21,"speaker":"","original":"Wie lässt man alles hinter sich?","ipa":"/vi lɛst man aləs hɪntɜ zɪç/","zh":"如何舍弃一切？","en":"How do you leave everything behind?","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-24-030","lineIndex":22,"speaker":"","original":"Wie jagt man sein Gewissen fort?","ipa":"/vi jɑkt man zaɪn ɡəvɪsən fɔɾt/","zh":"又要如何追寻自己的内心？","en":"How do you drive away your conscience?","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-24-031","lineIndex":23,"speaker":"","original":"Wie flieht man vor dem eignen Ich?","ipa":"/vi flit man fɔɾ dem aɪɡnən ɪç/","zh":"如何摆脱自我？","en":"How do you escape from your own self?","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-24-032","lineIndex":24,"speaker":"","original":"Wie kann man flüchten wenn man sich selbst im Wege steht?","ipa":"/viː kˌan man flˈʏçtən vˌɛn man zɪç zˈɛlpst ɪm vˈeːɡə ʃtˈeːt/","zh":"如果你从来安守牢笼如何可能逃脱？","en":"How can you escape when you're standing in your own way?","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-24-034","lineIndex":25,"speaker":"","original":"Wie kann man frei sein wenn man seinen eignen Schatten nie entgeht?","ipa":"/viː kˌan man frˈaɪ zaɪn vˌɛn man zˌaɪnən ˈaɪɡnən ʃˈatən nˈiː ɛntɡˈeːt/","zh":"如果你不曾摆脱自己的影子如何可能自由？","en":"How can you be free when you never escape your own shadows?","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-24-037","lineIndex":26,"speaker":"Wolfgang (Chor)","original":"Angst, die mir den Atem raubt (Neben dir steht ein Dämon)","ipa":"/aŋst di miɾ den ɑtəm raʊpt nebən diɾ ʃtet aɪn dɑmon/","zh":"恐惧夺取着我的呼吸，（你身旁站着一个恶魔）","en":"Fear that takes my breath away (A demon stands next to you)","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-24-038","lineIndex":27,"speaker":"","original":"Blei auf meinen Schultern (in Gestalt eines Knaben.)","ipa":"/blaɪ aʊf maɪnən ʃʊltɜn ɪn ɡəʃtalt aɪnəs knɑbən/","zh":"压迫如千钧，（孩童模样）","en":"Lead on my shoulders (in the shape of a boy.)","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-24-039","lineIndex":28,"speaker":"","original":"Schweigen, das mir Fragen stellt (Ihm allein sollst du dienen.)","ipa":"/ʃvaɪɡən das miɾ frɑɡən ʃtɛlt im alaɪn zɔlst du dinən/","zh":"我向沉默发问，（你只能向他交奉臣服）","en":"Silence that asks me questions (Him alone you shall have serve.)","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-24-040-a","lineIndex":29,"speaker":"","original":"und keine Antwort gibt auf mein Warum","ipa":"/ʊnt kaɪnə antvɔɾt ɡipt aʊf maɪn vɑrʊm vas du bɪst vɪl ɛɾ hɑbən nuɾ fyɾ in alaɪn bɪst du ɡəboɾn/","zh":"却迎来更震耳欲聋的沉默。","en":"and there is no answer to my why (What you are, he wants to have. You were born for him alone.).","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-24-040-b","lineIndex":30,"speaker":"","original":"(Was du bist, will er haben. Nur für ihn allein bist du gebor'n.).","ipa":"/ʊnt kaɪnə antvɔɾt ɡipt aʊf maɪn vɑrʊm vas du bɪst vɪl ɛɾ hɑbən nuɾ fyɾ in alaɪn bɪst du ɡəboɾn/","zh":"（你为他而生，而他将夺走你的一切）","en":"and there is no answer to my why (What you are, he wants to have. You were born for him alone.).","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-24-041","lineIndex":31,"speaker":"","original":"Unsichtbare Blicke (Hinter die steht ein Dämon) an denen ich ersticke (in Gestalt eines Knaben).","ipa":"/ˈʊnzˌɪçtbɑːrə blˈɪkə hˈɪntɜ diː ʃtˈeːt aɪn dˈɛːmoːn an deːnən ɪç ɛɾʃtˈɪkə ɪn ɡəʃtˈalt ˌaɪnəs knˈɑːbən/","zh":"无声无迹的窥视，（你身后站着一个恶魔）陷我于窒息；（孩童模样）","en":"Invisible looks (behind them stands a demon) that make me suffocate (in the form of a boy).","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-24-043","lineIndex":32,"speaker":"","original":"Der Schatten, der mir folgt – ich glaub (Tag und Nacht ist er bei dir.)","ipa":"/dɛɾ ʃatən dɛɾ miɾ fɔlkt ɪç ɡlaʊp tɑk ʊnt naxt ɪst ɛɾ baɪ diɾ/","zh":"那影子缠缚着我，（日夜如附骨之疽）","en":"The shadow that follows me - I believe (he is with you day and night.)","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-24-044","lineIndex":33,"speaker":"","original":"eines Tages","ipa":"/aɪnəs tɑɡəs/","zh":"总有一天","en":"one day","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-24-045","lineIndex":34,"speaker":"","original":"bringt er mich noch um.","ipa":"/bɾɪŋt ɛɾ mɪç nɔx ʊm/","zh":"将杀死我。","en":"he will kill me.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-24-047","lineIndex":35,"speaker":"Wolfgang & Chor","original":"Wie wird man seinen Schatten los?","ipa":"/vi vɪɾt man zaɪnən ʃatən los/","zh":"你要如何逃离自己的影子？","en":"How do you get rid of your shadow?","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-24-048","lineIndex":36,"speaker":"","original":"Wie sagt man seinem Schicksal nein?","ipa":"/vi zɑkt man zaɪnəm ʃɪkzɑl naɪn/","zh":"如何反叛命运？","en":"How do you say no to your fate?","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-24-049","lineIndex":37,"speaker":"","original":"Wie kriecht man aus der eignen Haut?","ipa":"/vi kɾiçt man aʊs dɛɾ aɪɡnən haʊt/","zh":"又要如何冲破桎梏？","en":"How do you crawl out of your own skin?","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-24-050","lineIndex":38,"speaker":"","original":"Wie kann man je ein andrer sein?","ipa":"/vi kan man je aɪn andɾɜ zaɪn/","zh":"如何得到重生？","en":"How can you ever be someone else?","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-24-051","lineIndex":39,"speaker":"","original":"Wen soll man fragen wenn man sich selber nicht versteht?","ipa":"/vˈeːn zˌɔl man frˈɑːɡən vˌɛn man zɪç zˈɛlbɜ nˈɪçt fɛɾʃtˈeːt/","zh":"如果你不曾了解过自己又能向谁寻得答案？","en":"Who should you ask if you don't understand yourself?","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-24-053","lineIndex":40,"speaker":"","original":"Wie kann man frei sein wenn man seinem eignen Schatten nie entgeht?","ipa":"/viː kˌan man frˈaɪ zaɪn vˌɛn man zˌaɪnəm ˈaɪɡnən ʃˈatən nˈiː ɛntɡˈeːt/","zh":"如果你不曾摆脱自己的影子又能如何得到自由？","en":"How can you be free if you never escape your own shadow?","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-24-056","lineIndex":41,"speaker":"Chor (Wolfgang)","original":"Wie wird man seinen Schatten los?","ipa":"/vi vɪɾt man zaɪnən ʃatən los/","zh":"你要如何逃离自己的影子？","en":"How do you get rid of your shadow?","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-24-057","lineIndex":42,"speaker":"","original":"Wie lasst man alles hinter sich? (Wie kann ich leben, )","ipa":"/vi last man aləs hɪntɜ zɪç vi kan ɪç lebən/","zh":"如何舍弃一切？（若我屈服于命运，）","en":"How do you leave everything behind? (How can I live?","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-24-058","lineIndex":43,"speaker":"","original":"Wie jagt man sein Gewissen fort? (solang ich nur dem Schicksal dien'?)","ipa":"/vi jɑkt man zaɪn ɡəvɪsən fɔɾt zolaŋ ɪç nuɾ dem ʃɪkzɑl din/","zh":"又要如何追寻自己的内心？（我如何能求得生活？）","en":"How do you drive away your conscience? (As long as I only serve fate'?)","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-24-059","lineIndex":44,"speaker":"","original":"Wie flieht man vor dem eignen Ich? (Kann ich denn nie, )","ipa":"/vi flit man fɔɾ dem aɪɡnən ɪç kan ɪç dɛn ni/","zh":"如何摆脱自我？（我永远不能—）","en":"How do you flee from it own me? (Can I never, )","note":"","sourceLineIndex":59},{"id":"mozart-das-musical-24-060","lineIndex":45,"speaker":"","original":"Wie kann man flüchten, (kann ich denn nie, ) wenn man sich selbst im Wege steht?","ipa":"/viː kˌan man flˈʏçtən kˌan ɪç dɛn nˈiː vˌɛn man zɪç zˈɛlpst ɪm vˈeːɡə ʃtˈeːt/","zh":"如果你从来安守牢笼，（永远都不能—）如何可能逃脱？","en":"How can one escape, (can I never, ) when you're standing in your own way?","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-24-062","lineIndex":46,"speaker":"","original":"Vor deinem Schicksal (nie, niemals)","ipa":"/fɔɾ daɪnəm ʃɪkzɑl ni nimɑls/","zh":"我是否永远、（不能，永远不能—）","en":"From your fate (never, never)","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-24-063","lineIndex":47,"speaker":"","original":"kannst du nicht fliehn! (vor meinem eignen Schatten fliehn?)","ipa":"/kanst du nɪçt flin fɔɾ maɪnəm aɪɡnən ʃatən flin/","zh":"永远无法逃离我的命运！（逃离自己的影子？）","en":"can you not flee! (flee from my own shadow?)","note":"","sourceLineIndex":63}],"sourceOrder":24,"displayOrder":21},{"order":25,"id":"25-entr-acte","title":"Entr'acte","titleZh":"幕间曲","lines":[{"id":"mozart-das-musical-25-001","lineIndex":1,"speaker":"Schauspieler","original":"Silentium! Seine Majestät, der Kaiser!","ipa":"/ʃaʊʃpilɜ zilɛntiʊm zaɪnə mɑjɛʃtɛt dɛɾ kaɪzɜ/","zh":"演员肃静！皇帝陛下驾到！","en":"ActorSilentium! His Majesty, the Emperor!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-25-002","lineIndex":2,"speaker":"Kaiser","original":"Keine Honneurs, Herrschaften.","ipa":"/kaɪzɜ kaɪnə hɔnøɾs hɛɾʃaftən/","zh":"皇帝各位不必拘礼","en":"KaiserNo honors, reigns.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-25-003","lineIndex":3,"speaker":"","original":"Ich bin nur hier um der Kunst meine Referenz zu erweisen.","ipa":"/ɪç bɪn nuɾ hiɾ ʊm dɛɾ kʊnst maɪnə referɛnts tsu ɛɾvaɪzən/","zh":"我只是前来向艺术致敬","en":"I'm just here to pay tribute to art.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-25-004","lineIndex":4,"speaker":"","original":"Brav gesungen, und brav gespielt.","ipa":"/bɾɑf ɡəzʊŋən ʊnt bɾɑf ɡəʃpilt/","zh":"唱得很好，表演也很好","en":"Well sung and well played.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-25-005","lineIndex":5,"speaker":"","original":"Wo ist der Kompositeur?","ipa":"/vo ɪst dɛɾ kɔmpozitøɾ/","zh":"作曲家呢？","en":"Where is the composer?","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-25-006","lineIndex":6,"speaker":"","original":"Ah, noch so jung ist er?","ipa":"/ɑ nɔx zo jʊŋ ɪst ɛɾ/","zh":"啊，还如此年轻","en":"Ah, is he still that young?","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-25-007","lineIndex":7,"speaker":"","original":"Seine Musik ist schön.","ipa":"/zaɪnə muzik ɪst ʃøn/","zh":"您的音乐很优美","en":"His music is beautiful.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-25-008","lineIndex":8,"speaker":"","original":"Zu schön für unsere Ohren.","ipa":"/tsu ʃøn fyɾ ʊnzrə orən/","zh":"对于我们而言却有些太过优美","en":"Too beautiful for our ears.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-25-009","lineIndex":9,"speaker":"","original":"Und gewaltig viele Noten, mein lieber Herr Mozart.","ipa":"/ʊnt ɡəvaltɪç filə notən maɪn libɜ hɛɾ motsaɾt/","zh":"并且音符也太多了，亲爱的莫扎特先生","en":"And a lot of notes, my dear Mr. Mozart.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-25-010","lineIndex":10,"speaker":"Mozart","original":"Grade so viel wie nötig, euer Majestät.","ipa":"/motsaɾt ɡɾɑdə zo fil vi nøtɪç ɔøɜ mɑjɛʃtɛt/","zh":"莫扎特这些音符都是必要的，陛下","en":"MozartJust as much as necessary, your majesty.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-25-011","lineIndex":11,"speaker":"","original":"Na bravo.","ipa":"/nɑ bɾɑvo/","zh":"演得不错","en":"Well bravo.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-25-012","lineIndex":12,"speaker":"","original":"Ich gratuliere allen zum erfolg!","ipa":"/ɪç ɡɾɑtulirə alən tsʊm ɛɾfɔlk/","zh":"我向大家的成功表示祝贺！","en":"I congratulate everyone on their success!","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-25-013","lineIndex":13,"speaker":"","original":"Und jetzt... Feier es schön!","ipa":"/ʊnt jɛtst faɪɜ ɛs ʃøn/","zh":"那么现在...好好庆祝一番吧！","en":"And now...celebrate it!","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-25-014","lineIndex":14,"speaker":"Salieri","original":"Der Kaiser hat Recht, junger Mann.","ipa":"/zɑliri dɛɾ kaɪzɜ hat rɛçt jʊŋɜ man/","zh":"萨列里皇帝所言极是啊年轻人","en":"SalieriThe emperor is right, young man.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-25-015","lineIndex":15,"speaker":"","original":"Zu viele Noten.","ipa":"/tsu filə notən/","zh":"音符过多了","en":"Too many notes.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-25-016","lineIndex":16,"speaker":"Mozart","original":"Ach, wenn es die richtigen sind, Herr Salieri.","ipa":"/motsaɾt ax vɛn ɛs di rɪçtɪɡən zɪnt hɛɾ zɑliri/","zh":"莫扎特啊，萨列里先生，如果这些音符是正确的","en":"MozartOh, if they are the right ones, Mr. Salieri.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-25-017","lineIndex":17,"speaker":"","original":"Können es gar nicht genug sein.","ipa":"/kœnən ɛs ɡɑɾnɪçt ɡənuk zaɪn/","zh":"那自然是多多益善","en":"It can't be enough.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-25-018","lineIndex":18,"speaker":"Schauspieler","original":"Lass uns den Erfolg feiern!","ipa":"/ʃaʊʃpilɜ las ʊns den ɛɾfɔlk faɪɜn/","zh":"让我们为今晚的成功庆祝吧！","en":"ActorsLet's celebrate the success!","note":"","sourceLineIndex":18}],"sourceOrder":25,"displayOrder":22},{"order":26,"id":"26-hier-in-wien","title":"Hier In Wien!","titleZh":"就在维也纳！","lines":[{"id":"mozart-das-musical-26-001","lineIndex":1,"speaker":"","original":"Ihr Urteil, Herr Schikaneder?","ipa":"/iɾ ʊɐtaɪl hɛɾ ʃikanedɜ/","zh":"您怎么看，席卡内德先生？","en":"Your verdict, Mr. Schikaneder?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-26-002","lineIndex":2,"speaker":"","original":"Mozart ist der kommende Mann.","ipa":"/motsaɾt ɪst dɛɾ kɔməndə man/","zh":"莫扎特是冉冉升起的明星","en":"Mozart is the coming man.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-26-003","lineIndex":3,"speaker":"","original":"Ich bin beeindruckt.","ipa":"/ɪç bɪn bəaɪndɾʊkt/","zh":"我非常感动","en":"I'm impressed.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-26-004","lineIndex":4,"speaker":"","original":"Wie alle hier.","ipa":"/vi alə hiɾ/","zh":"我们都这么认为","en":"Like everyone here.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-26-005","lineIndex":5,"speaker":"","original":"Höchst originell.","ipa":"/hœkst orɪɡinɛl/","zh":"非常独特","en":"Highly original.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-26-006","lineIndex":6,"speaker":"","original":"Sehr beachtlich.","ipa":"/zeɾ bəaxtlɪç/","zh":"卓越非凡","en":"Very remarkable.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-26-007","lineIndex":7,"speaker":"","original":"Gut.","ipa":"/ɡut/","zh":"好！","en":"Good.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-26-008","lineIndex":8,"speaker":"","original":"Welch ein Gespür für Effekt.","ipa":"/vɛlç aɪn ɡəʃpyɾ fyɾ ɛfɛkt/","zh":"如此有舞台触觉","en":"What a sense of effect.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-26-009","lineIndex":9,"speaker":"","original":"Ein Komponist mit Theaterblut.","ipa":"/aɪn kɔmponɪst mɪt teatɜblut/","zh":"一个血液里流淌着戏剧的作曲家","en":"A composer with theater blood.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-26-010","lineIndex":10,"speaker":"","original":"Nicht übel.","ipa":"/nɪçt ybəl/","zh":"不能...","en":"Not bad.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-26-011","lineIndex":11,"speaker":"","original":"Beinah perfekt.","ipa":"/baɪnɑ pɛɾfɛkt/","zh":"更完美！","en":"Almost perfect.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-26-012","lineIndex":12,"speaker":"","original":"Schön ist er nicht…","ipa":"/ʃøn ɪst ɛɾ nɪçt/","zh":"他长得虽然不咋样...","en":"He's not pretty...","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-26-013","lineIndex":13,"speaker":"","original":"doch er kann etwas.","ipa":"/dɔx ɛɾ kan ɛtvɑs/","zh":"但他才华出众","en":"but he can do something.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-26-014","lineIndex":14,"speaker":"","original":"(Plump und blass)","ipa":"/plʊmp ʊnt blas/","zh":"（面色苍白，举止粗鲁）","en":"(plump and pale)","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-26-015","lineIndex":15,"speaker":"","original":"über ihn spricht schon toute Wien.","ipa":"/ybɜ in ʃpɾɪçt ʃon tutə vin/","zh":"整个维也纳都在谈论他","en":"all over Vienna is already talking about him.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-26-016","lineIndex":16,"speaker":"","original":"(Eintagsfliege!)","ipa":"/aɪntaksfliɡə/","zh":"（昙花一现！）","en":"(a flash in the pan!)","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-26-017","lineIndex":17,"speaker":"Sein Geschick","original":"Virtuos. (Falschspielerei!)","ipa":"/zaɪn ɡəʃɪk vɪɾtuos falʃʃpileraɪ/","zh":"他的天赋：堪称大师。（只是唬人的把戏！）","en":"His skill: virtuoso. (Misplay!)","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-26-018","lineIndex":18,"speaker":"Die Musik","original":"Tadellos. (Ein Zirkusnarr)","ipa":"/di muzik tɑdəlos aɪn tsɪɾkʊsnaɾ/","zh":"他的音乐：完美无瑕！（像那马戏团小丑！）","en":"The music: Impeccable. (A circus jester)","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-26-019","lineIndex":19,"speaker":"","original":"Mozart wird berühmt. (ohne Kunstsinn)","ipa":"/motsaɾt vɪɾt bərymt onə kʊnstsɪn/","zh":"莫扎特将扬名立万（毫无艺术性！）","en":"Mozart becomes famous. (without artistic sense)","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-26-020","lineIndex":20,"speaker":"","original":"Als Pianist akzeptier ich ihn","ipa":"/als pianɪst aktsɛptiɾ ɪç in/","zh":"作为钢琴演奏家他还算不错","en":"I accept him as a pianist","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-26-021","lineIndex":21,"speaker":"","original":"(Wer kommt ihn gleich?)","ipa":"/veɾ kɔmt in ɡlaɪç/","zh":"（谁能比肩？）","en":"(Who can equal him?)","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-26-022","lineIndex":22,"speaker":"","original":"doch er kann nicht komponieren.","ipa":"/dɔx ɛɾ kan nɪçt kɔmponirən/","zh":"作为作曲家他还不够格","en":"but he can't compose.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-26-023","lineIndex":23,"speaker":"","original":"(Er wird ganz groß.)","ipa":"/ɛɾ vɪɾt ɡants ɡɾos/","zh":"（他会非常伟大）","en":"(He's getting really big.)","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-26-024","lineIndex":24,"speaker":"","original":"Jetzt ist er neu","ipa":"/jɛtst ɪst ɛɾ nɔø/","zh":"他在这里还是个新人","en":"Now he's new","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-26-025","lineIndex":25,"speaker":"","original":"aber kennt man ihn","ipa":"/ɑbɜ kɛnt man in/","zh":"当人们都认识了他","en":"but if you know him","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-26-026","lineIndex":26,"speaker":"","original":"(Ein Phänomen!)","ipa":"/aɪn fɛnomen/","zh":"（一个奇迹）","en":"(A phenomenon!)","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-26-027","lineIndex":27,"speaker":"","original":"wird er nicht mehr interessieren.","ipa":"/vɪɾt ɛɾ nɪçt meɾ ɪntərɛsirən/","zh":"就会对他失去兴趣","en":"he won't be of interest anymore.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-26-028","lineIndex":28,"speaker":"","original":"(So hochbegabt!)","ipa":"/zo hoxbəɡɑpt/","zh":"（天赋卓绝）","en":"(So highly talented!)","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-26-029","lineIndex":29,"speaker":"","original":"Ihn unterstützt manche Gönnerin.","ipa":"/in ʊntɜʃtʏtst mançə ɡœnərɪn/","zh":"他有很多女主顾","en":"Some patrons support him.","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-26-030","lineIndex":30,"speaker":"","original":"(Sein Stern geht auf!)","ipa":"/zaɪn ʃtɛɾn ɡet aʊf/","zh":"（他的星光日益璀璨）","en":"(His star is rising!)","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-26-031","lineIndex":31,"speaker":"","original":"Er ist bei Hof gern gesehen.","ipa":"/ɛɾ ɪst baɪ hof ɡɛɾn ɡəzeən/","zh":"他在宫廷备受欢迎","en":"He is welcome at court.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-26-032","lineIndex":32,"speaker":"","original":"(Er braucht Hilfe.)","ipa":"/ɛɾ bɾaʊxt hɪlfə/","zh":"（他需要帮助）","en":"(He needs help.)","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-26-033","lineIndex":33,"speaker":"Dieses Spiel","original":"Voll Talent… (Rosstäuscherei!)","ipa":"/dizəs ʃpil fɔl talɛnt rɔsʃtɔøʃeraɪ/","zh":"如此表演：充满天赋（小把戏罢了！）","en":"This game: full of talent... (horse-trading!)","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-26-034","lineIndex":34,"speaker":"","original":"Und sein Still: Exzellent! (Ein Zirkusnarr)","ipa":"/ʊnt zaɪn ʃtɪl ɛkstsəlɛnt aɪn tsɪɾkʊsnaɾ/","zh":"他的风格：非凡卓著（马戏团小丑！））","en":"And his style: excellent! (A circus jester)","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-26-035","lineIndex":35,"speaker":"","original":"Mozart wird berühmt. (ohne Kunstsinn.)","ipa":"/motsaɾt vɪɾt bərymt onə kʊnstsɪn/","zh":"莫扎特将扬名立万（毫无艺术性！）","en":"Mozart becomes famous. (without artistic sense.)","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-26-036","lineIndex":36,"speaker":"","original":"Doch was heißt das schon hier, in Wien","ipa":"/dɔx vas haɪst das ʃon hiɾ ɪn vin/","zh":"但这在维也纳意味着什么","en":"But what does that mean here, in Vienna","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-26-037","lineIndex":37,"speaker":"","original":"wo schon die Kinder beginnen, Intrigen zu spinnen weil es unterhält.","ipa":"/vo ʃon di kɪndɜ bəɡɪnən ɪntɾɪɡən tsu ʃpɪnən vaɪl ɛs ʊntɜhɛlt/","zh":"就连这里的孩子，都会为了取乐尔虞我诈","en":"where the children are already starting to spin intrigues because it's entertaining.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-26-038","lineIndex":38,"speaker":"","original":"Hier, in Wien wo man diebisch freut, sobald einer, der oben ist, runterfällt.","ipa":"/hˈiːɾ ɪn vˈiːn vˌoː man dˈiːbɪʃ frˈɔøt zˈoːbalt ˌaɪnɜ dɛɾ ˈoːbən ɪst rˈʊntɜfˌɛlt/","zh":"这里，在维也纳这里的人会为了一个伟人的倒下而幸灾乐祸","en":"Here, in Vienna where people are delighted when someone on top falls down.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-26-040","lineIndex":39,"speaker":"","original":"Was heißt das schon in Wien wo die äußerste Höflichkeit darin besteht, dass man sich verstellt.","ipa":"/vˈas hˈaɪst das ʃˌoːn ɪn vˈiːn vˌoː diː ˈɔøsɜstə hˈøːflɪçkˌaɪt dɑːrˈɪn bəʃtˈeːt das man zɪç fɛɾʃtˈɛlt/","zh":"在维也纳，这意味着什么这里极端的礼仪下就是虚伪","en":"What does that mean in Vienna where the utmost politeness is to pretend.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-26-042","lineIndex":40,"speaker":"","original":"Weil man ein Wunder nicht vergibt…","ipa":"/vaɪl man aɪn vʊndɜ nɪçt fɛɾɡipt/","zh":"因为大家容不得奇迹…","en":"Because you don't forgive a miracle...","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-26-043","lineIndex":41,"speaker":"","original":"(Nur tote Künstler sind beliebt…)","ipa":"/nuɾ totə kʏnstlɜ zɪnt bəlipt/","zh":"（只有死了的的艺术家受到欢迎）","en":"(Only dead artists are popular...)","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-26-044","lineIndex":42,"speaker":"","original":"Totes liebt man sehr…","ipa":"/totəs lipt man zeɾ/","zh":"大家都爱逝者","en":"People love dead people very much...","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-26-045","lineIndex":43,"speaker":"","original":"…hier in Wien.","ipa":"/hiɾ ɪn vin/","zh":"…在这维也纳城","en":"...here in Vienna.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-26-046","lineIndex":44,"speaker":"","original":"Ihn berührt euer Urteil nicht, (Was dieser Mozart komponiert, )","ipa":"/in bəryɾt ɔøɜ ʊɐtaɪl nɪçt vas dizɜ motsaɾt kɔmponiɾt/","zh":"他并不在意你的评价，（莫扎特作的曲，）","en":"Your judgment does not affect him, (What this Mozart composes)","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-26-047","lineIndex":45,"speaker":"","original":"denn er ist wirklich ein Genie. (ist alles gestohlen, schlecht kopiert.)","ipa":"/dɛn ɛɾ ɪst vɪɾklɪç aɪn ɡəni ɪst aləs ɡəʃtolən ʃlɛçt kopiɾt/","zh":"他是个真正的天才。（都是无耻的剽窃，拙劣的抄袭。）","en":"because he is really a genius. (everything is stolen, badly copied.)","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-26-048","lineIndex":46,"speaker":"","original":"Doch was heißt das schon hier, in Wien","ipa":"/dɔx vas haɪst das ʃon hiɾ ɪn vin/","zh":"但这在维也纳意味着什么","en":"But what does that mean here, in Vienna","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-26-049","lineIndex":47,"speaker":"","original":"wo man vor einem Messerstich in deinen Rücken die Hände dir küsst.","ipa":"/vo man fɔɾ aɪnəm mɛsɜstɪç ɪn daɪnən rʏkən di hɛndə diɾ kʏst/","zh":"人们当面友好寒暄背后却无情捅刀","en":"where they kiss your hands before a knife stabs you in the back.","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-26-050","lineIndex":48,"speaker":"","original":"Hier, in Wien wo man alles verzeiht, nur nicht, dass irgendwer hier erfolgreich ist.","ipa":"/hˈiːɾ ɪn vˈiːn vˌoː man ˈaləs fɛɾtsˈaɪht nˈuːɾ nˈɪçt das ˈɪɾɡɛndvɜ hˈiːɾ ɛɾfˈɔlɡɾaɪç ɪst/","zh":"这里，在维也纳人们除了他人的成功外容忍一切","en":"Here, in Vienna where you forgive everything except that someone is successful here.","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-26-052","lineIndex":49,"speaker":"","original":"Was heißt das schon in Wien","ipa":"/vas haɪst das ʃon ɪn vin/","zh":"在维也纳这意味着什么","en":"What does that mean in Vienna","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-26-053","lineIndex":50,"speaker":"","original":"wo man leidet an allem, was schön ist, weil jeden der Neid zerfrisst.","ipa":"/vo man laɪdət an aləm vas ʃøn ɪst vaɪl jedən dɛɾ naɪt tsɛɾfrɪst/","zh":"人们见不得那些光鲜亮丽因为每个人都深藏嫉妒","en":"where you suffer from everything that is beautiful because everyone is consumed by envy.","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-26-054","lineIndex":51,"speaker":"","original":"Weil man ein Wunder nicht vergibt…","ipa":"/vaɪl man aɪn vʊndɜ nɪçt fɛɾɡipt/","zh":"因为人们容不得奇迹…","en":"Because you don't forgive a miracle...","note":"","sourceLineIndex":54},{"id":"mozart-das-musical-26-055","lineIndex":52,"speaker":"","original":"(Nur tote Künstler sind beliebt…)","ipa":"/nuɾ totə kʏnstlɜ zɪnt bəlipt/","zh":"（只有死了的的艺术家受到欢迎）","en":"(Only dead artists are popular...)","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-26-056","lineIndex":53,"speaker":"","original":"Totes liebt man sehr…","ipa":"/totəs lipt man zeɾ/","zh":"大家都爱逝者","en":"People love dead people very much...","note":"","sourceLineIndex":56},{"id":"mozart-das-musical-26-057","lineIndex":54,"speaker":"","original":"...hier in Wien.","ipa":"/hiɾ ɪn vin/","zh":"…在这维也纳城","en":"...here in Vienna.","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-26-058","lineIndex":55,"speaker":"","original":"Wien bleibt Wien.","ipa":"/vin blaɪpt vin/","zh":"维也纳就是维也纳","en":"Vienna remains Vienna.","note":"","sourceLineIndex":58},{"id":"mozart-das-musical-26-059","lineIndex":56,"speaker":"","original":"Das ist eine Drohung!","ipa":"/das ɪst aɪnə dɾoʊŋ/","zh":"这是个警告！","en":"That's a threat!","note":"","sourceLineIndex":59},{"id":"mozart-das-musical-26-060","lineIndex":57,"speaker":"","original":"Wien bleibt Wien.","ipa":"/vin blaɪpt vin/","zh":"维也纳就是维也纳","en":"Vienna remains Vienna.","note":"","sourceLineIndex":60},{"id":"mozart-das-musical-26-061","lineIndex":58,"speaker":"","original":"Das ist eine Drohung!","ipa":"/das ɪst aɪnə dɾoʊŋ/","zh":"这是个警告！","en":"That's a threat!","note":"","sourceLineIndex":61},{"id":"mozart-das-musical-26-062","lineIndex":59,"speaker":"","original":"Wien bleibt, Wien bleibt, Wien bleibt Wien!","ipa":"/vin blaɪpt vin blaɪpt vin blaɪpt vin/","zh":"维也纳就是，维也纳就是，维也纳就是维也纳！","en":"Vienna remains, Vienna remains, Vienna remains Vienna!","note":"","sourceLineIndex":62}],"sourceOrder":26,"displayOrder":23},{"order":27,"id":"27-du-hast-ihn-an-der-angel","title":"Du Hast Ihn An Der Angel","titleZh":"你把他钓到手了","lines":[{"id":"mozart-das-musical-27-001","lineIndex":1,"speaker":"Mama","original":"Moment! Was hast du vor?","ipa":"/mɑmɑ momɛnt vas hast du fɔɾ/","zh":"母亲等等！你要去哪儿？","en":"Wait a minute! What are you up to?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-27-002","lineIndex":2,"speaker":"Constance","original":"Ich sag ihm 'Gute Nacht'!","ipa":"/kɒnstəns ɪç zɑk im ɡutə naxt/","zh":"小康我去和他说声“晚安”","en":"I'll say goodnight to him!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-27-003","lineIndex":3,"speaker":"","original":"Gehst du mit ihm ins Bett?","ipa":"/ɡest du mɪt im ɪns bɛt/","zh":"母亲晚安说到了床上？","en":"Are you going to bed with him?","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-27-004","lineIndex":4,"speaker":"","original":"Werd ich von dir bewacht?","ipa":"/veɾt ɪç fɔn diɾ bəvaxt/","zh":"小康你难道要这么防着我？","en":"Am I being guarded by you?","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-27-005","lineIndex":5,"speaker":"","original":"Halt ihn ein bisschen kurz bis er tut, was du verlangst.","ipa":"/hˈalt iːn aɪn bˈɪsçən kˈʊɐts bɪs ɛɾ tˈuːt vˈas duː fɛɾlˈaŋst/","zh":"母亲对他玩欲擒故纵直到他对你言听计从","en":"Hold him for a bit until he does what you ask.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-27-007","lineIndex":6,"speaker":"","original":"Mach ihm so einen Trottel der nach deiner Pfeife tanzt.","ipa":"/mˈax iːm zoː ˌaɪnən tɾˈɔtəl dɛɾ nɑːx dˌaɪnɜ pfˈaɪfə tˈantst/","zh":"让他成为一个傻子只知道随着你的哨声起舞","en":"Make him such a fool that dances to your tune.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-27-009","lineIndex":7,"speaker":"","original":"Nein! Keine Lügen! Er mag mich sehr!","ipa":"/naɪn kaɪnə lyɡən ɛɾ mɑk mɪç zeɾ/","zh":"小康不！没有欺骗！他很喜欢我！","en":"No! No lies! He likes me very much!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-27-010","lineIndex":8,"speaker":"","original":"Und so leichter tappt er in die Falle.","ipa":"/ʊnt zo laɪçtɜ tapt ɛɾ ɪn di falə/","zh":"母亲那你就更容易诱他进陷阱了","en":"And it's easier for him to fall into the trap.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-27-011","lineIndex":9,"speaker":"","original":"Du kannst sagen, was du sagen willst, Mama.","ipa":"/du kanst zɑɡən vas du zɑɡən vɪlst mɑmɑ/","zh":"小康你可以说你想说的，母亲","en":"You can say whatever you want to say, mom.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-27-012","lineIndex":10,"speaker":"","original":"Ich hör auf dich nicht mehr.","ipa":"/ɪç hoɾ aʊf dɪç nɪçt meɾ/","zh":"但我不会再听你的了！","en":"I'm not listening to you anymore.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-27-013","lineIndex":11,"speaker":"","original":"Sei nicht frech, und halt den Rand!","ipa":"/zaɪ nɪçt frɛç ʊnt halt den rant/","zh":"母亲别不懂事，不要越界","en":"Don't be cheeky and hold your tongue!","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-27-014","lineIndex":12,"speaker":"","original":"Du undankbare Ratte, ohne Arger zu Verstand.","ipa":"/du ʊndaŋkbɑrə ratə onə aɾɡɜ tsu fɛɾʃtant/","zh":"你这不知感恩的老鼠，胸无大志（Ehrgeiz）","en":"You ungrateful rat, with no anger in your mind.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-27-015","lineIndex":13,"speaker":"","original":"Ich hab' dich angesetzt auf ihn.","ipa":"/ɪç hɑp dɪç anɡəzɛtst aʊf in/","zh":"我让你去勾引他","en":"I put you on him.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-27-016","lineIndex":14,"speaker":"","original":"Er ist dir nachgerannt.","ipa":"/ɛɾ ɪst diɾ naxɡerant/","zh":"他现在巴巴追在你后头了","en":"He ran after you.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-27-017","lineIndex":15,"speaker":"","original":"Du hast ihn an der Angel.","ipa":"/du hast in an dɛɾ anɡɛl/","zh":"他已然上钩","en":"You've got him on the hook.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-27-018","lineIndex":16,"speaker":"","original":"Los! Zieh jetzt an Land!","ipa":"/los tsi jɛtst an lant/","zh":"现在！该你收网了！","en":"Go! Move ashore now!","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-27-019","lineIndex":17,"speaker":"","original":"Ich will das nicht.","ipa":"/ɪç vɪl das nɪçt/","zh":"小康我不愿这么做","en":"I don't want this.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-27-020","lineIndex":18,"speaker":"","original":"Er hat mich gern.","ipa":"/ɛɾ hat mɪç ɡɛɾn/","zh":"他喜欢我","en":"He likes me.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-27-021","lineIndex":19,"speaker":"","original":"Dann kann es nicht so schwer sein Ihn zum Traualtar zu zerren.","ipa":"/dan kˌan ɛs nˈɪçt zoː ʃvˈeːɾ zaɪn iːn tsʊm tɾˌaʊaltˈɑːɾ tsuː tsˈɛrən/","zh":"母亲那你做起来应该更轻松了把他拖到教堂祭坛前","en":"Then it can't be that hard to drag him to the altar.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-27-023","lineIndex":20,"speaker":"","original":"Ich lass ihm Zeit!","ipa":"/ɪç las im tsaɪt/","zh":"小康我给他时间","en":"I'll give him time!","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-27-024","lineIndex":21,"speaker":"","original":"Das ist verkehrt!","ipa":"/das ɪst fɛɾkeɾt/","zh":"母亲你这样是错的！","en":"That's wrong!","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-27-025","lineIndex":22,"speaker":"","original":"Ich drange nicht.","ipa":"/ɪç dɾaŋə nɪçt/","zh":"小康我不会逼他","en":"I didn't push.","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-27-026","lineIndex":23,"speaker":"","original":"Ich warte, bis er selbst die Frage stellt.","ipa":"/ɪç vaɾtə bɪs ɛɾ zɛlpst di frɑɡə ʃtɛlt/","zh":"我愿意等，等他自己来跟我说","en":"I'll wait for him to ask the question himself.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-27-027","lineIndex":24,"speaker":"","original":"Heirate jetzt, nicht wann's ihn gefallt.","ipa":"/haɪrɑtə jɛtst nɪçt vans in ɡəfalt/","zh":"母亲现在就结婚，别等他自己愿意","en":"Get married now, not when he pleases.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-27-028","lineIndex":25,"speaker":"","original":"Wir sind glücklich ohne Ring und Trauschein.","ipa":"/viɾ zɪnt ɡlʏklɪç onə rɪŋ ʊnt tɾaʊshaɪn/","zh":"小康即使没有指环和结婚证（Trauschein） 我们也很幸福","en":"We are happy without a ring and a wedding ceremony.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-27-029","lineIndex":26,"speaker":"","original":"Mein Gott! Bist du zu blöd, um zu kapieren?","ipa":"/maɪn ɡɔt bɪst du tsu blot ʊm tsu kapirən/","zh":"母亲上帝啊！你怎么傻成这样还不懂？","en":"My God! Are you too stupid to understand?","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-27-030","lineIndex":27,"speaker":"","original":"Wir wollen an sein Geld!","ipa":"/viɾ vɔlən an zaɪn ɡɛlt/","zh":"我们要的是他的钱！","en":"We want his money!","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-27-031","lineIndex":28,"speaker":"","original":"Lug ihn rein. Es wird Zeit.","ipa":"/luk in raɪn ɛs vɪɾt tsaɪt/","zh":"哄骗他！就趁现在！","en":"Lue him in. It's about time.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-27-032","lineIndex":29,"speaker":"","original":"Solange er ehrlich will","ipa":"/zolaŋə ɛɾ eɾlɪç vɪl/","zh":"只要他还真心实意","en":"As long as he honestly wants to","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-27-033","lineIndex":30,"speaker":"","original":"Mach nicht umsonst die Beine breit.","ipa":"/max nɪçt ʊmzɔnst di baɪnə bɾaɪt/","zh":"就别白白大张双腿","en":"Don't spread your legs for nothing.","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-27-034","lineIndex":31,"speaker":"","original":"Stell' ich doch nicht so nämlich an Er frisst dir aus der Hand","ipa":"/ʃtˈɛl ɪç dɔx nˈɪçt zoː nˈɛːmlɪç an ɛɾ frˈɪst diːɾ ˌaʊs dɛɾ hˈant/","zh":"我不觉得他能抵抗得了他现在很吃你的一套（Er frisst dir aus der Hand）","en":"I'm not going to pretend like that He'll ever eat out of your hand","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-27-036","lineIndex":32,"speaker":"","original":"Du hast ihn an der Angel","ipa":"/du hast in an dɛɾ anɡɛl/","zh":"他已然上钩","en":"You've got him on the hook","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-27-037","lineIndex":33,"speaker":"","original":"Los! Zieh jetzt an Land!","ipa":"/los tsi jɛtst an lant/","zh":"现在！该你收网了！","en":"Go! Move ashore now!","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-27-038","lineIndex":34,"speaker":"","original":"Ich kann nicht.","ipa":"/ɪç kan nɪçt/","zh":"小康我不能—","en":"I can't.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-27-039","lineIndex":35,"speaker":"","original":"Was ich verlang, das ist nicht viel.","ipa":"/vas ɪç fɛɾlaŋ das ɪst nɪçt fil/","zh":"母亲我的要求并不过分","en":"What I'm asking for isn't much.","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-27-040","lineIndex":36,"speaker":"","original":"Ich will nicht.","ipa":"/ɪç vɪl nɪçt/","zh":"小康我不愿！","en":"I don't want to.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-27-041","lineIndex":37,"speaker":"","original":"Schliesslich bist du schon fast am Ziel.","ipa":"/ʃlislɪç bɪst du ʃon fast am tsil/","zh":"母亲毕竟你都快要达到目的了","en":"Finally, you're almost there.","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-27-042","lineIndex":38,"speaker":"","original":"Nein, du verstehst mich nicht.","ipa":"/naɪn du fɛɾʃtest mɪç nɪçt/","zh":"小康不，你不明白","en":"No, you don't understand me.","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-27-043","lineIndex":39,"speaker":"","original":"Ich liebe ihn!","ipa":"/ɪç libə in/","zh":"我爱他！","en":"I love him!","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-27-044","lineIndex":40,"speaker":"","original":"Ach was, bild dir nichts ein, du dumme Gans!","ipa":"/ax vas bɪlt diɾ nɪçts aɪn du dʊmə ɡɑns/","zh":"母亲哈，还是算了吧，你这只蠢鹅","en":"Oh no, don't imagine anything, you stupid goose!","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-27-045","lineIndex":41,"speaker":"","original":"Liebe? Gott, mir wird schlecht!","ipa":"/libə ɡɔt miɾ vɪɾt ʃlɛçt/","zh":"爱？上帝啊！我受不了了","en":"Love? God, I'm sick!","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-27-046","lineIndex":42,"speaker":"","original":"Ich will dass er blecht!","ipa":"/ɪç vɪl das ɛɾ blɛçt/","zh":"我要的是他的钱！","en":"I want him to blow!","note":"","sourceLineIndex":46}],"sourceOrder":27,"displayOrder":24},{"order":28,"id":"28-dich-kennen-heisst-dich-lieben","title":"Dich Kennen Heisst Dich Lieben","titleZh":"认识你就是爱上你","lines":[{"id":"mozart-das-musical-28-002","lineIndex":1,"speaker":"Wolfgang","original":"Meine arme Constanze, ich muss dich retten!","ipa":"/maɪnə aɾmə kɔnstantsə ɪç mʊs dɪç rɛtən/","zh":"我可怜的康斯坦茨，我必须拯救你！","en":"My poor Constanze, I have to save you!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-28-003","lineIndex":2,"speaker":"","original":"Deine Mutter ist ein...ein Ungeheuer. Und du...?","ipa":"/daɪnə mʊtɜ ɪst aɪn aɪn ʊnɡəhɔøɜ ʊnt du/","zh":"你的母亲是个恶棍，但你…","en":"Your mother is a...a monster. And you...?","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-28-004","lineIndex":3,"speaker":"","original":"So stell ich mir Engel vor: Noch wenn sie weinen, stolz und stark.","ipa":"/zoː ʃtˈɛl ɪç miːɾ ˈɛŋəl fˈɔɾ nɔx vˌɛn ziː vˈaɪnən ʃtˈɔlts ʊnt ʃtˈaɾk/","zh":"你就是我想象中的天使即使哭泣，也骄傲而坚强","en":"This is how I imagine angels: Even when they cry, proud and strong.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-28-006","lineIndex":4,"speaker":"","original":"Von welchem Stern bist du aus deiner Nacht in meinen Traum gefallen?","ipa":"/fɔn vˈɛlçəm ʃtˈɛɾn bɪst duː ˌaʊs dˌaɪnɜ nˈaxt ɪn mˌaɪnən tɾˈaʊm ɡəfˈalən/","zh":"在黑夜中，你从哪颗星星坠落到我的梦中？","en":"From which star did you fall from your night into my dream?","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-28-008","lineIndex":5,"speaker":"","original":"Du weiß, wie ich wirklich bin.","ipa":"/du vaɪs vi ɪç vɪɾklɪç bɪn/","zh":"你了解我真实的模样","en":"You know what I'm really like.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-28-009","lineIndex":6,"speaker":"","original":"Denn du hast Augen die mir in die Seele sehn.","ipa":"/dɛn duː hast ˈaʊɡən diː miːɾ ɪn diː zˈeːlə zˈeːn/","zh":"因为你的眼睛看透我灵魂深处","en":"Because you have eyes that see into my soul.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-28-011","lineIndex":7,"speaker":"","original":"Was ich fühl für dich wird nicht vergehn.","ipa":"/vˈas ɪç fˈyːl fyːɾ dɪç vˌɪɾt nˈɪçt fɛɾɡˈeːn/","zh":"我对你的感觉永不消逝","en":"What I feel for you will not go away.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-28-013","lineIndex":8,"speaker":"","original":"Dich kennen heißt dich lieben.","ipa":"/dɪç kɛnən haɪst dɪç libən/","zh":"遇见你就爱上你","en":"Knowing you means loving you.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-28-014","lineIndex":9,"speaker":"","original":"Du bist mir so nah.","ipa":"/du bɪst miɾ zo nɑ/","zh":"你我如此亲近","en":"You are so close to me.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-28-015","lineIndex":10,"speaker":"","original":"Ich weiß, dass ich zu dir gehör seitdem ich dich sah.","ipa":"/ɪç vˈaɪs das ɪç tsuː diːɾ ɡəhˈøːɾ zˈaɪtdəm ɪç dɪç zˈɑː/","zh":"从看见你的第一眼起我就已属于你","en":"I know I belong to you ever since I saw you.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-28-017","lineIndex":11,"speaker":"","original":"Ich will dich nicht besitzen nur vor der Welt beschützen.","ipa":"/ɪç vɪl dɪç nˈɪçt bəzˈɪtsən nˈuːɾ fˌɔɾ dɛɾ vˈɛlt bəʃˈʏtsən/","zh":"我不想占有你只想保护你不受外界侵扰","en":"I don't want to own you just protect you from the world.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-28-019","lineIndex":12,"speaker":"","original":"Ich möchte für dich da sein Tag und Nacht.","ipa":"/ɪç mœçtə fyɾ dɪç dɑ zaɪn tɑk ʊnt naxt/","zh":"我愿日夜与你相伴","en":"I want to be there for you day and night.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-28-020","lineIndex":13,"speaker":"Constanze","original":"Wolfgang, ich...","ipa":"/kɔnstantsə vɔlfɡaŋ ɪç/","zh":"康斯坦茨：沃尔夫冈，我…","en":"Wolfgang, I...","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-28-021","lineIndex":14,"speaker":"Wolfgang","original":"Alles wird gut. Ich beschütz' dich.","ipa":"/vɔlfɡaŋ aləs vɪɾt ɡut ɪç bəʃʏts dɪç/","zh":"没关系，我会保护你的","en":"Everything will be fine. I'll protect you.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-28-023","lineIndex":15,"speaker":"Constanze","original":"Ich hasse es, schwach zu sein.","ipa":"/ɪç hasə ɛs ʃvax tsu zaɪn/","zh":"我讨厌软弱","en":"I hate being weak.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-28-024","lineIndex":16,"speaker":"","original":"Wenn ich mal weine, dann für mich.","ipa":"/vɛn ɪç mɑl vaɪnə dan fyɾ mɪç/","zh":"即使哭泣我也只为自己","en":"If I ever cry, it's for me.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-28-025","lineIndex":17,"speaker":"","original":"Ich hab schon früh gelernt dass man bereut wenn man zu viel Vertraun hat.","ipa":"/ɪç hˈɑːp ʃˌoːn frˈyː ɡəlˈɛɾnt das man bərˈɔøt vˌɛn man tsuː fˈiːl fɛɾtɾˈaʊn hat/","zh":"我早就学到人人都会后悔太过相信别人","en":"I learned early on that you regret when you have too much trust.","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-28-028","lineIndex":18,"speaker":"","original":"Doch du bist nicht wie andre sind.","ipa":"/dɔx du bɪst nɪçt vi andɾə zɪnt/","zh":"但你与众不同","en":"But you are not like others are.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-28-029","lineIndex":19,"speaker":"","original":"Wenn ich nicht weiter weiß halt ich mich fest an dir.","ipa":"/vˌɛn ɪç nˈɪçt vˈaɪtɜ vˈaɪs hˈalt ɪç mɪç fˈɛst an dˈiːɾ/","zh":"如果我不知所措我会紧紧抓住你","en":"If I don't know what to do next I hold on to you tightly.","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-28-031","lineIndex":20,"speaker":"","original":"Es war niemand je so gut zu mir.","ipa":"/ɛs vɑɾ nimant je zo ɡut tsu miɾ/","zh":"从来没有人对我这么好","en":"No one has ever been so good to me.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-28-032","lineIndex":21,"speaker":"","original":"Dich kennen heiß dich lieben.","ipa":"/dɪç kɛnən haɪs dɪç libən/","zh":"遇见你就爱上你","en":"Knowing you means loving you.","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-28-033","lineIndex":22,"speaker":"","original":"Du bist mir so nah.","ipa":"/du bɪst miɾ zo nɑ/","zh":"你我如此亲近","en":"You are so close to me.","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-28-034","lineIndex":23,"speaker":"Wolfgang","original":"An dich denken heiß sich sehnen.","ipa":"/vɔlfɡaŋ an dɪç dɛŋkən haɪs zɪç zenən/","zh":"想你意味着思念","en":"Thinking about you makes me long.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-28-035","lineIndex":24,"speaker":"Constanze","original":"Ich weiß, dass ich zu dir gehör seitdem ich dich sah.","ipa":"/ɪç vˈaɪs das ɪç tsuː diːɾ ɡəhˈøːɾ zˈaɪtdəm ɪç dɪç zˈɑː/","zh":"康斯坦茨：从看见你的第一眼起我就已属于你","en":"I know that I belong to you ever since I saw you.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-28-037","lineIndex":25,"speaker":"Wolfgang","original":"Dich sehn ist wir Musik.","ipa":"/vɔlfɡaŋ dɪç zen ɪst viɾ muzik/","zh":"你就如同音乐","en":"Seeing you is music.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-28-038","lineIndex":26,"speaker":"Constanze","original":"Ich möchte dir vertrauen","ipa":"/kɔnstantsə ɪç mœçtə diɾ fɛɾtɾaʊən/","zh":"康斯坦茨：我愿意依靠你","en":"I want to trust you","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-28-039","lineIndex":27,"speaker":"Wolfgang","original":"Ich möchte dein Beschützer sein.","ipa":"/vɔlfɡaŋ ɪç mœçtə daɪn bəʃʏtsɜ zaɪn/","zh":"我想做你的保护伞","en":"I want to be your protector.","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-28-040","lineIndex":28,"speaker":"Constanze","original":"mein Leben auf dich bauen.","ipa":"/kɔnstantsə maɪn lebən aʊf dɪç baʊən/","zh":"康斯坦茨：向你托付人生","en":"build my life on you.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-28-041","lineIndex":29,"speaker":"Constanze & Wolfgang","original":"Ich möchte für dich da sein Tag und Nacht.","ipa":"/kɔnstantsə ʊnt vɔlfɡaŋ ɪç mœçtə fyɾ dɪç dɑ zaɪn tɑk ʊnt naxt/","zh":"康斯坦茨＆沃尔夫冈：我愿日夜与你相伴","en":"I want to be there for you day and night.","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-28-042","lineIndex":30,"speaker":"Wolfgang","original":"Versprich mir...","ipa":"/vɔlfɡaŋ fɛɾʃpɾɪç miɾ/","zh":"答应我…","en":"Promise me...","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-28-043","lineIndex":31,"speaker":"Constanze","original":"Versprich mir....","ipa":"/kɔnstantsə fɛɾʃpɾɪç miɾ/","zh":"康斯坦茨：答应我…","en":"Promise me...","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-28-044","lineIndex":32,"speaker":"Constanze & Wolfgang","original":"Was immer kommen mag:","ipa":"/kɔnstantsə ʊnt vɔlfɡaŋ vas ɪmɜ kɔmən mɑk/","zh":"康斯坦茨＆沃尔夫冈：无论发生什么","en":"Whatever may come:","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-28-045","lineIndex":33,"speaker":"","original":"Wir bleiben stolz und stark.","ipa":"/viɾ blaɪbən ʃtɔlts ʊnt ʃtaɾk/","zh":"我们要骄傲且坚强","en":"We remain proud and strong.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-28-046","lineIndex":34,"speaker":"","original":"Dich kennen heiß dich lieben.","ipa":"/dɪç kɛnən haɪs dɪç libən/","zh":"遇见你就爱上你","en":"Knowing you means loving you.","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-28-047","lineIndex":35,"speaker":"","original":"Du bist mir so nah.","ipa":"/du bɪst miɾ zo nɑ/","zh":"你我如此亲近","en":"You are so close to me.","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-28-048","lineIndex":36,"speaker":"","original":"Ich weiß, dass ich zu dir gehör seitdem ich dich sah.","ipa":"/ɪç vˈaɪs das ɪç tsuː diːɾ ɡəhˈøːɾ zˈaɪtdəm ɪç dɪç zˈɑː/","zh":"从看见你的第一眼起我就已属于你","en":"I know I belong to you ever since I saw you.","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-28-050","lineIndex":37,"speaker":"","original":"Ich möchte für dich leben","ipa":"/ɪç mœçtə fyɾ dɪç lebən/","zh":"我愿为你而活","en":"I want to live for you","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-28-051","lineIndex":38,"speaker":"","original":"mit dir auf Wolken schweben","ipa":"/mɪt diɾ aʊf vɔlkən ʃvebən/","zh":"一起在云中飘荡","en":"floating on clouds with you","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-28-052","lineIndex":39,"speaker":"","original":"Ich möchte für dich da sein Tag und Nacht.","ipa":"/ɪç mœçtə fyɾ dɪç dɑ zaɪn tɑk ʊnt naxt/","zh":"我愿与你相伴","en":"I want to be there for you day and night.","note":"","sourceLineIndex":52}],"sourceOrder":28,"displayOrder":25},{"order":29,"id":"29-ha-ein-liebesnest","title":"Ha! Ein Liebesnest!","titleZh":"哈！一个爱巢！","lines":[{"id":"mozart-das-musical-29-001","lineIndex":1,"speaker":"","original":"(CÄCILIA WEBER) Ha! Ein Liebesnest.","ipa":"/kɛkiliɑ vebɜ hɑ aɪn libɛsnəst/","zh":"（采齐利娅·韦伯） 哈！好一个爱巢。","en":"(CÄCILIA WEBER) Ha! A love nest.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-29-002","lineIndex":2,"speaker":"","original":"(THORWART) Lump!","ipa":"/tɔɾvaɾt lʊmp/","zh":"（托瓦特） 无赖！","en":"(THORWART) Lump!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-29-003","lineIndex":3,"speaker":"","original":"(CÄCILIA WEBER) Mein armes Kind! Geschändet, entehrt!","ipa":"/kɛkɪlɑ vebɜ maɪn aɾməs kɪnt ɡəʃɛndət ɛnteɾt/","zh":"（采齐利娅·韦伯） 我可怜的孩子！被玷污了！","en":"(CÄCILLA WEBER) My poor child! Defiled, dishonored!","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-29-004","lineIndex":4,"speaker":"","original":"(WOLFGANG) Aber nein, Sie irren sich!","ipa":"/vɔlfɡaŋ ɑbɜ naɪn zi ɪrən zɪç/","zh":"（沃尔夫冈） 不是这样的，您搞错了！","en":"(WOLFGANG) But no, you're wrong!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-29-005","lineIndex":5,"speaker":"","original":"(CONSTANZE) Es war mein freier Wille.","ipa":"/kɔnstantsə ɛs vɑɾ maɪn fraɪɜ vɪlə/","zh":"（康斯坦丝） 这是我自己的意思。","en":"(CONSTANZE) It was my free will.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-29-006","lineIndex":6,"speaker":"","original":"(THORWART) Sittenstrolch!","ipa":"/tɔɾvaɾt zɪtənstɾɔlç/","zh":"（托瓦特） 流氓！","en":"(THORWART) Mischief!","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-29-007","lineIndex":7,"speaker":"","original":"(WOLFGANG) Bitte! Ich hab viel zuviel ehrliche Gesinnung","ipa":"/vɔlfɡaŋ bɪtə ɪç hɑp fil tsufil eɾlɪçə ɡəzɪnʊŋ/","zh":"（沃尔夫冈） 求求你们！我很正直","en":"(WOLFGANG) Please! I have far too much honesty","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-29-008","lineIndex":8,"speaker":"","original":"um ein unschuldiges Mädchen zu verführen.","ipa":"/ʊm aɪn ʊnʃʊldɪɡəs mɛdçən tsu fɛɾfyrən/","zh":"绝不会诱骗无辜少女。","en":"to seduce an innocent girl.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-29-009","lineIndex":9,"speaker":"","original":"(CÄCILIA WEBER) Lügner!","ipa":"/kɛkiliɑ vebɜ lʏɡnɜ/","zh":"（采齐利娅·韦伯） 骗子！","en":"(CÄCILIA WEBER) Liar!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-29-010","lineIndex":10,"speaker":"","original":"(CONSTANZE) Er kann nichts dafür!","ipa":"/kɔnstantsə ɛɾ kan nɪçts dɑfyɾ/","zh":"（康斯坦丝） 这不是他的错！","en":"(CONSTANZE) He can't help it!","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-29-011","lineIndex":11,"speaker":"","original":"(THORWART) Ins Gefängnis mit ihm!","ipa":"/tɔɾvaɾt ɪns ɡəfɛŋnɪs mɪt im/","zh":"（托瓦特） 坐牢去吧！","en":"(THORWART) To prison with him!","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-29-012","lineIndex":12,"speaker":"","original":"(WOLFGANG) Ich bin unschuldig. Darauf kann ich leben und sterben!","ipa":"/vɔlfɡaŋ ɪç bɪn ʊnʃʊldɪç dɑraʊf kan ɪç lebən ʊnt ʃtɛɾbən/","zh":"（沃尔夫冈） 我是无辜的。我用性命担保！","en":"(WOLFGANG) I am innocent. I can live and die on this!","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-29-013","lineIndex":13,"speaker":"","original":"(CÄCILIA WEBER) Nein, nicht in das Gefängnis.","ipa":"/kɛkiliɑ vebɜ naɪn nɪçt ɪn das ɡəfɛŋnɪs/","zh":"（采齐利娅·韦伯） 不行，不能进监狱。","en":"(CÄCILIA WEBER) No, not in prison.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-29-014","lineIndex":14,"speaker":"","original":"Soll denn die Schande offenbar werden? Heiraten muss er sie!","ipa":"/zɔl dɛn di ʃandə ɔfənbɑɾ vɛɾdən haɪrɑtən mʊs ɛɾ zi/","zh":"难道要把这丑事公开吗？你必须和她结婚！","en":"Should the shame be revealed? He has to marry her!","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-29-015","lineIndex":15,"speaker":"","original":"(WOLFGANG) Heiraten?","ipa":"/vɔlfɡaŋ haɪrɑtən/","zh":"（沃尔夫冈） 结婚？","en":"(WOLFGANG) Getting married?","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-29-016","lineIndex":16,"speaker":"","original":"(CÄCILIA WEBER) Heiraten!","ipa":"/kɛkiliɑ vebɜ haɪrɑtən/","zh":"（采齐利娅·韦伯） 结婚！","en":"(CÄCILIA WEBER) Getting married!","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-29-017","lineIndex":17,"speaker":"","original":"(CONSTANZE) Heiraten?","ipa":"/kɔnstantsə haɪrɑtən/","zh":"（康斯坦丝） 结婚？","en":"(CONStanze) Getting married?","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-29-018","lineIndex":18,"speaker":"","original":"(THORWART) Nun denn, nur des missbrauchten Kindes wegen soll Gnade vor Recht ergehen.","ipa":"/tɔɾvaɾt nun dɛn nuɾ dɛs mɪsbɾaʊxtən kɪndəs veɡən zɔl ɡənɑdə fɔɾ rɛçt ɛɾɡeən/","zh":"（托瓦特） 那么，为了这受害的孩子，应当抛弃公正饶恕于他。","en":"(THORWART) Well then, only because of the abused child should mercy come before justice.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-29-019","lineIndex":19,"speaker":"","original":"Unterschreibe er das.","ipa":"/ʊntɜʃraɪbə ɛɾ das/","zh":"在这儿签名。","en":"He sign this.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-29-020","lineIndex":20,"speaker":"","original":"(WOLFGANG) Was ist das?","ipa":"/vɔlfɡaŋ vas ɪst das/","zh":"（沃尔夫冈） 这是什么？","en":"(WOLFGANG) What is that?","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-29-021","lineIndex":21,"speaker":"","original":"(THORWART) Ich, Wolfgang Mozart, verpflichte mich","ipa":"/tɔɾvaɾt ɪç vɔlfɡaŋ motsaɾt fɛɾpflɪçtə mɪç/","zh":"（托瓦特） 我，沃尔夫冈·莫扎特，承诺","en":"(THORWART) I, Wolfgang Mozart, undertake to","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-29-022","lineIndex":22,"speaker":"","original":"die Mademoiselle Constanze Weber zu ehelichen","ipa":"/di mɑdemoizɛlə kɔnstantsə vebɜ tsu eəlɪçən/","zh":"与康斯坦丝·韦伯小姐结婚","en":"marry Mademoiselle Constanze Weber","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-29-023","lineIndex":23,"speaker":"","original":"und für den Unterhalt ihrer mittellosen Mutter zu sorgen.","ipa":"/ʊnt fyɾ den ʊntɜhalt irɜ mɪtəlozən mʊtɜ tsu zɔɾɡən/","zh":"并赡养她贫穷的母亲。","en":"and to provide for the maintenance of her destitute mother.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-29-024","lineIndex":24,"speaker":"","original":"Wofern sich die Unmöglichkeit ereignen sollte","ipa":"/vofɜn zɪç di ʊnmøklɪçkaɪt ɛɾaɪɡnən zɔltə/","zh":"一旦由于本人毁约","en":"If the impossibility should occur","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-29-025","lineIndex":25,"speaker":"","original":"dass ich meine Absichten andere","ipa":"/das ɪç maɪnə apzɪçtən andərə/","zh":"而发生变故","en":"that my intentions are different","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-29-026","lineIndex":26,"speaker":"","original":"sollen Mutter und Tochter eine Pension von jährlich 300 Gulden von mir erhalten.","ipa":"/zɔlən mʊtɜ ʊnt tɔxtɜ aɪnə pɛnzjon fɔn jɛɾlɪç dɾaɪhʊndɜt ɡʊldən fɔn miɾ ɛɾhaltən/","zh":"母女二人每年要从我这里收到300古尔登的赡养金。","en":"mother and daughter should receive an annual pension of 300 guilders from me.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-29-027","lineIndex":27,"speaker":"","original":"(WOLFGANG) Aber...","ipa":"/vɔlfɡaŋ ɑbɜ/","zh":"（沃尔夫冈） 但是...","en":"(WOLFGANG) But...","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-29-028","lineIndex":28,"speaker":"","original":"(THORWART) Cäcilia... Hol die Polizei!","ipa":"/tɔɾvaɾt kɛkiliɑ hol di politsaɪ/","zh":"（托瓦特） 采齐利娅，叫警察来！","en":"(THORWART) Cäcilia... Get the police!","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-29-029","lineIndex":29,"speaker":"","original":"(WOLFGANG) Nein! Ich unterschreibe.","ipa":"/vɔlfɡaŋ naɪn ɪç ʊntɜʃraɪbə/","zh":"（沃尔夫冈） 别！我签。","en":"(WOLFGANG) No! I sign.","note":"","sourceLineIndex":29}],"sourceOrder":29,"displayOrder":26},{"order":30,"id":"30-dich-kennen-heisst-dich-lieben-reprise","title":"Dich Kennen Heisst Dich Lieben (Reprise)","titleZh":"认识你就是爱上你（重唱）","lines":[{"id":"mozart-das-musical-30-001","lineIndex":1,"speaker":"Constanze","original":"Wolfgang! Ich brauche keine schriftliche Versicherung von dir.","ipa":"/kɔnstantsə vɔlfɡaŋ ɪç bɾaʊxə kaɪnə ʃrɪftlɪçə fɛɾzɪçərʊŋ fɔn diɾ/","zh":"康斯坦茨沃尔夫冈！我不需要你的书面保证","en":"Constanze Wolfgang! I don't need any written assurance from you.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-30-002","lineIndex":2,"speaker":"","original":"Wir lieben uns doch du musst mich nicht heiraten, wenn du nicht willst.","ipa":"/viːɾ lˈiːbən ʊns dɔx duː mˈʊst mɪç nˈɪçt haɪrˈɑːtən vˌɛn duː nˈɪçt vɪlst/","zh":"我们是相爱的除非你愿意，不然你不必娶我","en":"We love each other you don't have to marry me if you don't want to.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-30-004","lineIndex":3,"speaker":"","original":"Und du?","ipa":"/ʊnt du/","zh":"你呢？","en":"And you?","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-30-005","lineIndex":4,"speaker":"","original":"Willst du mich heiraten?","ipa":"/vɪlst du mɪç haɪrɑtən/","zh":"你愿意嫁给我吗？","en":"Do you want to marry me?","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-30-006","lineIndex":5,"speaker":"Constanze","original":"Ja, Wolfgang!","ipa":"/kɔnstantsə jɑ vɔlfɡaŋ/","zh":"康斯坦茨当然愿意，沃尔夫冈！","en":"ConstanzeYes, Wolfgang!","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-30-007","lineIndex":6,"speaker":"Wolfgang","original":"Constanze","ipa":"/vɔlfɡaŋ kɔnstantsə/","zh":"沃尔夫冈康斯坦茨...","en":"WolfgangConstanze","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-30-008","lineIndex":7,"speaker":"Constanze","original":"Versprich mir","ipa":"/kɔnstantsə fɛɾʃpɾɪç miɾ/","zh":"康斯坦茨答应我...","en":"ConstanzePromise me","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-30-009","lineIndex":8,"speaker":"Zusammen","original":"Was immer kommen mag","ipa":"/tsuzamən vas ɪmɜ kɔmən mɑk/","zh":"合无论未来会发生什么","en":"TogetherWhatever may come","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-30-010","lineIndex":9,"speaker":"","original":"Wir bleiben stolz und stark","ipa":"/viɾ blaɪbən ʃtɔlts ʊnt ʃtaɾk/","zh":"我们始终相伴，自豪而坚强","en":"We will remain proud and strong","note":"","sourceLineIndex":10}],"sourceOrder":30,"displayOrder":27},{"order":31,"id":"31-wer-ist-wer","title":"Wer Ist Wer?","titleZh":"谁是谁？","lines":[{"id":"mozart-das-musical-31-001","lineIndex":1,"speaker":"","original":"Wer ist wer?","ipa":"/veɾ ɪst veɾ/","zh":"谁是谁？","en":"Who is who?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-31-002","lineIndex":2,"speaker":"","original":"Wer geht als was?","ipa":"/veɾ ɡet als vas/","zh":"谁扮成谁？","en":"Who goes as what?","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-31-003","lineIndex":3,"speaker":"","original":"Die große Redoute:","ipa":"/di ɡɾosə redutə/","zh":"盛大的假面舞会","en":"The Great Redoubt:","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-31-004","lineIndex":4,"speaker":"","original":"Ein göttlicher Spaß.","ipa":"/aɪn ɡœtlɪçɜ ʃpɑs/","zh":"非凡的欢愉","en":"Divine fun.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-31-005","lineIndex":5,"speaker":"","original":"Spott als Spiel.","ipa":"/ʃpɔt als ʃpil/","zh":"嘲讽取乐","en":"Mocking as a game.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-31-006","lineIndex":6,"speaker":"","original":"Leben als Tanz.","ipa":"/lebən als tants/","zh":"舞动人生","en":"Life as a dance.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-31-007","lineIndex":7,"speaker":"","original":"Alles Theater.","ipa":"/aləs teɑtɜ/","zh":"一切都是做戏","en":"All theater.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-31-008","lineIndex":8,"speaker":"","original":"Alles Mummenschanz.","ipa":"/aləs mʊmənʃants/","zh":"一切都是假面游戏","en":"All mummery.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-31-009","lineIndex":9,"speaker":"","original":"Bau auf gar nichts.","ipa":"/baʊ aʊf ɡɑɾ nɪçts/","zh":"一切构于虚无","en":"Build on nothing.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-31-010","lineIndex":10,"speaker":"","original":"Trau, schau wem.","ipa":"/tɾaʊ ʃaʊ vem/","zh":"信任无从交付","en":"Trust, look who.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-31-011","lineIndex":11,"speaker":"","original":"Scherz und Schein.","ipa":"/ʃɛɾts ʊnt ʃaɪn/","zh":"玩笑和幻象","en":"Joke and illusion.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-31-012","lineIndex":12,"speaker":"","original":"Wer fällt drauf rein?","ipa":"/veɾ fɛlt dɾaʊf raɪn/","zh":"谁深陷其中？","en":"Who will fall for this?","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-31-013","lineIndex":13,"speaker":"","original":"Die große Redoute:","ipa":"/di ɡɾosə redutə/","zh":"盛大的假面舞会","en":"The Great Redoubt:","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-31-014","lineIndex":14,"speaker":"","original":"Ein Schieben und Schrein.","ipa":"/aɪn ʃibən ʊnt ʃraɪn/","zh":"狂欢与圣典","en":"A push and shrine.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-31-015","lineIndex":15,"speaker":"","original":"Lob als Hohn.","ipa":"/lop als hon/","zh":"赞美当做嘲弄","en":"Praise rather than mockery.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-31-016","lineIndex":16,"speaker":"","original":"Talmi als Glanz.","ipa":"/talmi als ɡlants/","zh":"假货当做珍宝","en":"Talmi as shine.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-31-017","lineIndex":17,"speaker":"","original":"Alles Theater.","ipa":"/aləs teɑtɜ/","zh":"一切都是做戏","en":"All theater.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-31-018","lineIndex":18,"speaker":"","original":"Alles Mummenschanz.","ipa":"/aləs mʊmənʃants/","zh":"一切都是假面游戏","en":"All mummery.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-31-019","lineIndex":19,"speaker":"","original":"Klar ist gar nichts wahr ist gar nichts.","ipa":"/klˈɑːɾ ɪst ɡˈɑːɾ nˈɪçts vˈɑːɾ ɪst ɡˈɑːɾ nˈɪçts/","zh":"一切皆是迷惘一切皆是虚妄","en":"Nothing is clear nothing is true.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-31-021","lineIndex":20,"speaker":"","original":"Ich hab dir's gegeben.","ipa":"/ɪç hɑp diɾs ɡəɡebən/","zh":"我把它给了你","en":"I gave it to you.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-31-022","lineIndex":21,"speaker":"","original":"Du hast mir's genommen.","ipa":"/du hast miɾs ɡənɔmən/","zh":"你从我这里得到了它","en":"You took it from me.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-31-023","lineIndex":22,"speaker":"","original":"Du hast es aus Trotz zerstört.","ipa":"/du hast ɛs aʊs tɾɔts tsɛɾʃtœɾt/","zh":"然而它却因你的叛逆最终湮灭","en":"You destroyed it out of spite.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-31-024","lineIndex":23,"speaker":"","original":"Nun wirst du es nie wieder bekommen!","ipa":"/nun vɪɾst du ɛs ni vidɜ bəkɔmən/","zh":"如今你再也无处寻找","en":"Now you'll never get it again!","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-31-025","lineIndex":24,"speaker":"","original":"Wovon ich rede ist das Glück!","ipa":"/vovon ɪç redə ɪst das ɡlʏk/","zh":"我说的就是幸福！","en":"What I'm talking about is happiness!","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-31-026","lineIndex":25,"speaker":"","original":"Vater! Bleib!","ipa":"/fɑtɜ blaɪp/","zh":"父亲！别走！","en":"Father! Stay!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-31-027","lineIndex":26,"speaker":"","original":"Wo willst du denn hin, Wolfgang?","ipa":"/vo vɪlst du dɛn hɪn vɔlfɡaŋ/","zh":"你要去哪里，沃尔夫冈？","en":"Where do you want to go, Wolfgang?","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-31-028","lineIndex":27,"speaker":"","original":"Zu… Mein Vater war gerade hier.","ipa":"/tsu maɪn fɑtɜ vɑɾ ɡərɑdə hiɾ/","zh":"去……我父亲刚才在这里……","en":"To... My father was just here.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-31-029","lineIndex":28,"speaker":"","original":"Ich…","ipa":"/ɪç/","zh":"我……","en":"I...","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-31-030","lineIndex":29,"speaker":"","original":"Du bist erwachsen.","ipa":"/du bɪst ɛɾvaxzən/","zh":"你已经长大了","en":"You're an adult.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-31-031","lineIndex":30,"speaker":"","original":"Irgendwann muss man aufhören, seinem Vater hinterherzulaufen.","ipa":"/ɪɾɡəndvan mʊs man aʊfhørən zaɪnəm fɑtɜ hɪntɜhɛɾtsulaʊfən/","zh":"人从生命中的某个时候起，就不应再追逐父亲的背影","en":"At some point you have to stop chasing your father.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-31-032","lineIndex":31,"speaker":"","original":"Scherz und Schein.","ipa":"/ʃɛɾts ʊnt ʃaɪn/","zh":"玩笑和幻象","en":"Joke and illusion.","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-31-033","lineIndex":32,"speaker":"","original":"Wer fällt drauf rein?","ipa":"/veɾ fɛlt dɾaʊf raɪn/","zh":"谁深陷其中？","en":"Who will fall for this?","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-31-034","lineIndex":33,"speaker":"","original":"Die große Redoute:","ipa":"/di ɡɾosə redutə/","zh":"盛大的假面舞会","en":"The Great Redoubt:","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-31-035","lineIndex":34,"speaker":"","original":"Ein Schieben und Schrein.","ipa":"/aɪn ʃibən ʊnt ʃraɪn/","zh":"狂欢与圣典","en":"A push and shrine.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-31-036","lineIndex":35,"speaker":"","original":"Lob als Hohn.","ipa":"/lop als hon/","zh":"赞美当做嘲弄","en":"Praise rather than mockery.","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-31-037","lineIndex":36,"speaker":"","original":"Talmi als Glanz.","ipa":"/talmi als ɡlants/","zh":"假货当做珍宝","en":"Talmi as shine.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-31-038","lineIndex":37,"speaker":"","original":"Alles Theater.","ipa":"/aləs teɑtɜ/","zh":"一切都是做戏","en":"All theater.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-31-039","lineIndex":38,"speaker":"","original":"Alles Mummenschanz.","ipa":"/aləs mʊmənʃants/","zh":"一切都是假面游戏","en":"All mummery.","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-31-040","lineIndex":39,"speaker":"","original":"Gut ist schlecht, und schlecht ist recht, und falsch ist echt, und klar ist gar nichts.","ipa":"/ɡˈuːt ɪst ʃlˈɛçt ʊnt ʃlˈɛçt ɪst rˈɛçt ʊnt fˈalʃ ɪst ˈɛçt ʊnt klˈɑːɾ ɪst ɡˈɑːɾ nˈɪçts/","zh":"指鹿为马黑白颠倒是非不分一切皆模糊","en":"Good is bad, and bad is right, and fake is real, and nothing is clear.","note":"","sourceLineIndex":40}],"sourceOrder":31,"displayOrder":28},{"order":32,"id":"32-der-prinz-ist-fort","title":"Der Prinz Ist Fort","titleZh":"王子走了","lines":[{"id":"mozart-das-musical-32-001","lineIndex":1,"speaker":"","original":"Du warst der Prinz ich die Prinzessin im fernen Königreich unserer Kinderzeit","ipa":"/duː vɑːɾst dɛɾ pɾˈɪnts ɪç diː pɾˌɪntsɛsˈiːn ɪm fˈɛɾnən kˈøːnɪɡɾˌaɪç ˌʊnzərɜ kˈɪndɜtsˌaɪt/","zh":"你曾是王子，而我曾是公主在我们的孩提时代那遥远的王国里","en":"You were the prince and I was the princess in the distant kingdom of our childhood","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-32-004","lineIndex":2,"speaker":"","original":"Und ich dachte","ipa":"/ʊnt ɪç daxtə/","zh":"我曾经幻想","en":"And I thought","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-32-005","lineIndex":3,"speaker":"","original":"so bleibt es immer","ipa":"/zo blaɪpt ɛs ɪmɜ/","zh":"那一刻会是永恒","en":"it will always be like that","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-32-006","lineIndex":4,"speaker":"","original":"Doch jetzt lebst du","ipa":"/dɔx jɛtst lepst du/","zh":"但现在你却生活在","en":"But now you are alive","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-32-007","lineIndex":5,"speaker":"","original":"in einer anderen Welt","ipa":"/ɪn aɪnɜ andərən vɛlt/","zh":"另一个世界","en":"in another world","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-32-008","lineIndex":6,"speaker":"","original":"Ich warte umsonst auf dich","ipa":"/ɪç vaɾtə ʊmzɔnst aʊf dɪç/","zh":"我的等待终成惘然","en":"I wait for you in vain","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-32-009","lineIndex":7,"speaker":"","original":"Die Wunder sind","ipa":"/di vʊndɜ zɪnt/","zh":"我的奇迹","en":"The miracles are","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-32-010","lineIndex":8,"speaker":"","original":"vorbei für mich","ipa":"/foɾbaɪ fyɾ mɪç/","zh":"已经不存在","en":"over for me","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-32-011","lineIndex":9,"speaker":"","original":"Der Prinz ist fort","ipa":"/dɛɾ pɾɪnts ɪst fɔɾt/","zh":"王子远去","en":"The prince is gone","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-32-012","lineIndex":10,"speaker":"","original":"Das Schloss ist leer","ipa":"/das ʃlɔs ɪst leɾ/","zh":"城堡空寂","en":"The castle is empty","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-32-013","lineIndex":11,"speaker":"","original":"Und die Prinzessin lacht nicht mehr","ipa":"/ʊnt di pɾɪntsɛsin laxt nɪçt meɾ/","zh":"公主也不再欢笑","en":"And the princess is no longer laughing","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-32-014","lineIndex":12,"speaker":"","original":"Vom Fenster wächst ein Dornenbusch","ipa":"/fɔm fˈɛnstɜ vˈɛkst aɪn dˈɔɾnənbˌʊʃ/","zh":"窗棂之边荆棘丛生","en":"A thorn bush grows from the window a thorn bush","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-32-016","lineIndex":13,"speaker":"","original":"Ich kann dich nicht mehr sehen","ipa":"/ɪç kan dɪç nɪçt meɾ zeən/","zh":"我再也无法看见你","en":"I can't see you anymore","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-32-017","lineIndex":14,"speaker":"","original":"Auch ich will fort","ipa":"/aʊx ɪç vɪl fɔɾt/","zh":"我也终将走远","en":"I want to leave too","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-32-018","lineIndex":15,"speaker":"","original":"Das ist entschieden","ipa":"/das ɪst ɛntʃidən/","zh":"我意已决","en":"That's decided","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-32-019","lineIndex":16,"speaker":"","original":"Ich weiß mit wem","ipa":"/ɪç vaɪs mɪt vem/","zh":"我知道与何人","en":"I know who with","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-32-020","lineIndex":17,"speaker":"","original":"Ich weiß wohin","ipa":"/ɪç vaɪs vohin/","zh":"我知道去何处","en":"I know where","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-32-021","lineIndex":18,"speaker":"","original":"Doch Vater will es mir verbieten","ipa":"/dɔx fɑtɜ vɪl ɛs miɾ fɛɾbitən/","zh":"但父亲不会同意","en":"But father wants to forbid me","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-32-022","lineIndex":19,"speaker":"","original":"mein Freund ist arm wie ich es bin","ipa":"/maɪn frɔønt ɪst aɾm vi ɪç ɛs bɪn/","zh":"因为我的心上人也像我一样清贫","en":"my friend is poor like I am","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-32-023","lineIndex":20,"speaker":"","original":"Das Geld, das Vater für mir sparte","ipa":"/das ɡɛlt das fɑtɜ fyɾ miɾ ʃpaɾtə/","zh":"父亲说，他为我存下的钱","en":"The money that father saved for me","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-32-024","lineIndex":21,"speaker":"","original":"sagt er, hat er an dich vertan","ipa":"/zɑkt ɛɾ hat ɛɾ an dɪç fɛɾtɑn/","zh":"都被你用来挥霍","en":"he says, has he wasted on you","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-32-025","lineIndex":22,"speaker":"","original":"Kannst du es mir jetzt wieder geben?","ipa":"/kanst du ɛs miɾ jɛtst vidɜ ɡebən/","zh":"你是否可以把它们归还给我？","en":"Can you give it back to me now?","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-32-026","lineIndex":23,"speaker":"","original":"Daran hängt jetzt mein ganzes Leben","ipa":"/dɑran hɛŋt jɛtst maɪn ɡantsəs lebən/","zh":"我的生活和命运都取决于此","en":"My whole life now depends on it","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-32-027","lineIndex":24,"speaker":"","original":"weil ich hier kaum noch atmen kann","ipa":"/vaɪl ɪç hiɾ kaʊm nɔx atmən kan/","zh":"因为在这里我已无法呼吸","en":"because I can hardly breathe here anymore","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-32-028","lineIndex":25,"speaker":"","original":"Der Prinz ist fort (Bei Tag und Nacht)","ipa":"/dɛɾ pɾɪnts ɪst fɔɾt baɪ tɑk ʊnt naxt/","zh":"王子远去（日日夜夜）","en":"The prince is gone (day and night)","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-32-029","lineIndex":26,"speaker":"","original":"Das Schloss ist leer (weint deine Schwester)","ipa":"/das ʃlɔs ɪst leɾ vaɪnt daɪnə ʃvɛstɜ/","zh":"城堡空寂（你的姐姐）","en":"The castle is empty (your sister cries)","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-32-030","lineIndex":27,"speaker":"","original":"Und die Prinzessin","ipa":"/ʊnt di pɾɪntsɛsin/","zh":"公主也","en":"And the princess","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-32-031","lineIndex":28,"speaker":"","original":"lacht nicht mehr (um dich)","ipa":"/laxt nɪçt meɾ ʊm dɪç/","zh":"不再欢笑（为你而哭泣）","en":"is no longer laughing (for you)","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-32-032","lineIndex":29,"speaker":"","original":"Vom Fenster wächst (Sie fühlt genau wie ich)","ipa":"/fɔm fɛnstɜ vɛkst zi fylt ɡənaʊ vi ɪç/","zh":"窗棂之边（我们有同样的感受）","en":"From the window grows (She feels just like me)","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-32-033","lineIndex":30,"speaker":"","original":"ein Dornenbusch (Jetzt lässt du)","ipa":"/aɪn dɔɾnənbʊʃ jɛtst lɛst du/","zh":"灌木丛生（你已经）","en":"a thorn bush (Now you leave)","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-32-034","lineIndex":31,"speaker":"","original":"Ich kann dich nicht mehr sehen (uns im Stich)","ipa":"/ɪç kan dɪç nɪçt meɾ zeən ʊns ɪm ʃtɪç/","zh":"你我二人永远分离（弃我们于不顾）","en":"I can't do you anymore see (let us down)","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-32-035","lineIndex":32,"speaker":"","original":"Der Prinz ist fort (Du bist geflohen, sie hält zu mir)","ipa":"/dɛɾ pɾɪnts ɪst fɔɾt du bɪst ɡəfloən zi hɛlt tsu miɾ/","zh":"王子远去（她对我说，你已远走高飞）","en":"The prince is gone (You fled, she stands by me)","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-32-036","lineIndex":33,"speaker":"","original":"Das Schloss ist leer (Kehr um, sieh ein, dein Platz ist hier)","ipa":"/das ʃlɔs ɪst leɾ keɾ ʊm zi aɪn daɪn plats ɪst hiɾ/","zh":"城堡空寂（回来看看吧，你的家在这里）","en":"The castle is empty (Turn around, see, your place is here)","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-32-037","lineIndex":34,"speaker":"","original":"Wo soviel Zukunft war, (Wie kannst du nur)","ipa":"/vo zovil tsukʊnft vɑɾ vi kanst du nuɾ/","zh":"我们曾幻想的未来究竟在何处？（你怎么忍心就这样）","en":"Where there was so much future, (How can you)","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-32-038","lineIndex":35,"speaker":"","original":"ist gar nicht mehr (so von uns gehen?)","ipa":"/ɪst ɡɑɾnɪçt meɾ zo fɔn ʊns ɡeən/","zh":"这已不再重要（离我们而去？）","en":"is no longer (that of us go?)","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-32-039","lineIndex":36,"speaker":"","original":"Du warst ein Teil von mir","ipa":"/du vɑɾst aɪn taɪl fɔn miɾ/","zh":"你曾是我生命的一部分","en":"You were a part of me","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-32-040","lineIndex":37,"speaker":"","original":"Wenn ich dich ganz verlier'","ipa":"/vɛn ɪç dɪç ɡants fɛɾliɾ/","zh":"若我彻底失去了你","en":"If I lose you completely","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-32-041","lineIndex":38,"speaker":"","original":"dann gibt es keinen mehr","ipa":"/dan ɡipt ɛs kaɪnən meɾ/","zh":"那便再无一人","en":"then there is no one left","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-32-042","lineIndex":39,"speaker":"","original":"der mich erlöst","ipa":"/dɛɾ mɪç ɛɾlœst/","zh":"能拯救我脱离这片苦海","en":"to redeem me","note":"","sourceLineIndex":42}],"sourceOrder":32,"displayOrder":29},{"order":33,"id":"33-freunde","title":"Freunde","titleZh":"朋友","lines":[{"id":"mozart-das-musical-33-001","lineIndex":1,"speaker":"","original":"Nein, Nannerl, nein!","ipa":"/naɪn nanɜl naɪn/","zh":"不，南内尔，不是这样的！","en":"No, Nannerl, no!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-33-002","lineIndex":2,"speaker":"","original":"Niemals lass ich dich im Stich!","ipa":"/nimɑls las ɪç dɪç ɪm ʃtɪç/","zh":"我绝不会抛弃你的！","en":"I'll never let you down!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-33-003","lineIndex":3,"speaker":"","original":"Das Geld vom letzten Akademiekonzert für Nannerl, damit ihren Liebsten heiraten kann.","ipa":"/das ɡˈɛlt fɔm lˈɛtstən ˌɑkadˌeːmiːkɔntsˈɛɾt fyːɾ nˈanɜl dɑːmˈɪt ˌiːrən lˈiːbstən haɪrˈɑːtən kˌan/","zh":"上次学院音乐会的报酬给南内尔的，这样她就能和心爱的人结婚了","en":"The money from the last academy concert for Nannerl so that she can marry her loved one.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-33-005","lineIndex":4,"speaker":"","original":"Das nächste Konzert wird ja noch besser.","ipa":"/das nɛçstə kɔntsɛɾt vɪɾt jɑ nɔx bɛsɜ/","zh":"下次音乐会肯定还会更好。","en":"The next concert will be even better.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-33-006","lineIndex":5,"speaker":"","original":"Ecco...","ipa":"/ɛko/","zh":"看这儿...... （拿起乐谱）","en":"Ecco...","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-33-007","lineIndex":6,"speaker":"","original":"Hey, Wolferl! Was ist?","ipa":"/haɪ vɔlfɜl vas ɪst/","zh":"嘿，沃沃，这是什么？","en":"Hey, Wolferl! What's wrong?","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-33-008","lineIndex":7,"speaker":"","original":"Du hockst hier am Klavier, während wir auf dich warten.","ipa":"/du hɔkst hiɾ am klaviɾ vɛrənt viɾ aʊf dɪç vaɾtən/","zh":"你蹲在钢琴前，而我们等了你半天","en":"You're sitting here at the piano while we wait for you.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-33-009","lineIndex":8,"speaker":"","original":"Das ist nicht richtig!","ipa":"/das ɪst nɪçt rɪçtɪç/","zh":"这可不合适！","en":"That's not right!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-33-010","lineIndex":9,"speaker":"","original":"Nichts ist so wichtig, dass man die Freunde beim Billard vergisst.","ipa":"/nɪçts ɪst zo vɪçtɪç das man di frɔøndə baɪm bɪlaɾt fɛɾɡɪst/","zh":"没有什么比忘记赴朋友的约更重要的事了","en":"Nothing is so important that you forget your friends while playing billiards.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-33-011","lineIndex":10,"speaker":"","original":"Er kommt zu spät, er geht zu früh.","ipa":"/ɛɾ kɔmt tsu ʃpɛt ɛɾ ɡet tsu fry/","zh":"他迟到又早退","en":"He comes too late, he leaves too early.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-33-012","lineIndex":11,"speaker":"","original":"Sagt zu und vergisst das Galamenü.","ipa":"/zɑɡt tsu ʊnt fɛɾɡɪst das ɡɑlamɛny/","zh":"答应来赴宴却又抛在脑后","en":"Say yes and forget about the gala menu.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-33-013","lineIndex":12,"speaker":"","original":"Die Herkunft kann man ihn verzeihn doch sein Benehmen...nein!","ipa":"/diː hˈɛɾkʊnft kˌan man iːn fɛɾtsˈaɪhn dɔx zaɪn bənˈeːmən nˈaɪn/","zh":"他的出身人们可以谅解可他的态度......没门！","en":"You can forgive him for his origins, but his behavior...no!","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-33-015","lineIndex":13,"speaker":"","original":"Freunde sind mehr wert als Ruhm und Musik.","ipa":"/frɔøndə zɪnt meɾ vɛɾt als rum ʊnt muzik/","zh":"名望和音乐比不上一群好友","en":"Friends are worth more than fame and music.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-33-016","lineIndex":14,"speaker":"","original":"Doch Freundschaft muss man sich verdienen.","ipa":"/dɔx frɔøndʃaft mʊs man zɪç fɛɾdinən/","zh":"可交情也须得人们自己去挣","en":"But friendship has to be earned.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-33-017","lineIndex":15,"speaker":"","original":"Ein Mann ohne Freunde dem fehlt das wahre Glück.","ipa":"/aɪn man onə frɔøndə dem felt das vɑrə ɡlʏk/","zh":"一个没有朋友的人不会得到真正的幸福","en":"A man without friends who lacks true happiness.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-33-018","lineIndex":16,"speaker":"","original":"Trägst du auch Samt und Seide und tust du nur, was dir passt.","ipa":"/tɾɛkst du aʊx zamt ʊnt zaɪdə ʊnt tʊst du nuɾ vas diɾ past/","zh":"哪怕你衣着华丽，随心所欲","en":"Do you also wear velvet and silk and only do what suits you.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-33-019","lineIndex":17,"speaker":"","original":"Du bist ein armes Schwein, solang du keine Freunde hast.","ipa":"/du bɪst aɪn aɾməs ʃvaɪn zolaŋ du kaɪnə frɔøndə hast/","zh":"只要你没有朋友，你就是个可怜虫","en":"You're a poor pig as long as you don't have any friends.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-33-020","lineIndex":18,"speaker":"","original":"So ich muss zur Post.","ipa":"/zo ɪç mʊs tsuɾ pɔst/","zh":"我得去趟邮局","en":"So I have to go to the post office.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-33-021","lineIndex":19,"speaker":"","original":"Meine Schwester braucht Geld.","ipa":"/maɪnə ʃvɛstɜ bɾaʊxt ɡɛlt/","zh":"我姐姐需要钱","en":"My sister needs money.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-33-022","lineIndex":20,"speaker":"","original":"Dringend.","ipa":"/dɾɪŋənt/","zh":"急用","en":"Urgent.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-33-023","lineIndex":21,"speaker":"","original":"Ich bin gleich zurück.","ipa":"/ɪç bɪn ɡlaɪç tsurʏk/","zh":"我马上回来","en":"I'll be right back.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-33-024","lineIndex":22,"speaker":"","original":"Du spinnst wohl?","ipa":"/du ʃpɪnst vol/","zh":"你疯了吗？","en":"Are you crazy?","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-33-025","lineIndex":23,"speaker":"","original":"Na komm, spiel doch mal mit!","ipa":"/nɑ kɔm ʃpil dɔx mɑl mɪt/","zh":"来吧，就来玩一局！","en":"Come on, play along!","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-33-026","lineIndex":24,"speaker":"","original":"Moment!","ipa":"/momɛnt/","zh":"等会儿！","en":"Wait a minute!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-33-027","lineIndex":25,"speaker":"","original":"Es geht um was?","ipa":"/ɛs ɡet ʊm vas/","zh":"什么事这么急？","en":"It's about what?","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-33-028","lineIndex":26,"speaker":"","original":"Mach ein Spiel!","ipa":"/max aɪn ʃpil/","zh":"来一局！","en":"Make a game!","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-33-029","lineIndex":27,"speaker":"","original":"Hahaha... Daneben, du bist rausen!","ipa":"/hɑɑɑ dɑnebən du bɪst raʊzən/","zh":"哈哈哈哈打偏了，你出局了！","en":"Hahaha... Besides, you're out!","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-33-030","lineIndex":28,"speaker":"","original":"Was?","ipa":"/vas/","zh":"什么？","en":"What?","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-33-031","lineIndex":29,"speaker":"","original":"Nein, ich erhöhe ein Einsatz.","ipa":"/naɪn ɪç ɛɾhøə aɪn aɪnzats/","zh":"别这样，我再加赌注就是了","en":"No, I'm raising a bet.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-33-032","lineIndex":30,"speaker":"","original":"Um wie viel?","ipa":"/ʊm vi fil/","zh":"加多少？","en":"By how much?","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-33-033","lineIndex":31,"speaker":"","original":"Da","ipa":"/dɑ/","zh":"这些","en":"There","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-33-034","lineIndex":32,"speaker":"","original":"Alles?","ipa":"/aləs/","zh":"全部？","en":"Everything?","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-33-035","lineIndex":33,"speaker":"","original":"Ja, alles. Aber ich muss es fertig machen.","ipa":"/jɑ aləs ɑbɜ ɪç mʊs ɛs fɛɾtɪç maxən/","zh":"是的，全部。但我必须先把乐谱写好","en":"Yes, everything. But I have to finish it.","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-33-036","lineIndex":34,"speaker":"","original":"Trink inzwischen auf meine Rechnung!","ipa":"/tɾɪŋk ɪntsvɪʃən aʊf maɪnə rɛçnʊŋ/","zh":"这期间去买点酒来喝吧，算在我账上","en":"Drink on my bill now!","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-33-037","lineIndex":35,"speaker":"","original":"Freunde sind mehr wert als Liebe und Wein.","ipa":"/frɔøndə zɪnt meɾ vɛɾt als libə ʊnt vaɪn/","zh":"爱情和美酒比不上一群好友","en":"Friends are worth more than love and wine.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-33-038","lineIndex":36,"speaker":"","original":"Sie sind nicht mit Geld zu bezahlen.","ipa":"/zi zɪnt nɪçt mɪt ɡɛlt tsu bətsɑlən/","zh":"他们用金钱可买不来","en":"They cannot be paid for with money.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-33-039","lineIndex":37,"speaker":"","original":"Ein Mann ohne Freunde wird nie zufrieden sein.","ipa":"/aɪn man onə frɔøndə vɪɾt ni tsufridən zaɪn/","zh":"一个没有朋友的人永远不会满足","en":"A man without friends will never be satisfied.","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-33-040","lineIndex":38,"speaker":"","original":"Dann kann er noch so prahlen mit Ruhm und Überfluss.","ipa":"/dan kan ɛɾ nɔx zo pɾɑlən mɪt rum ʊnt ybɜflʊs/","zh":"任他吹嘘声名显赫，生活富裕","en":"Then he can brag about fame and wealth.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-33-041","lineIndex":39,"speaker":"","original":"Er ist ein armer Hund, wenn er sich Freunde kaufen muss.","ipa":"/ɛɾ ɪst aɪn aɾmɜ hʊnt vɛn ɛɾ zɪç frɔøndə kaʊfən mʊs/","zh":"要是他须得用金钱换取友情，他就只是个可怜的家伙","en":"He's a poor dog when he has to buy friends.","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-33-042","lineIndex":40,"speaker":"","original":"Ein Mann ohne Freunde, der ist ein armes Schwein.","ipa":"/aɪn man onə frɔøndə dɛɾ ɪst aɪn aɾməs ʃvaɪn/","zh":"一个没有朋友的人，就是个可怜虫","en":"A man without friends is a poor pig.","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-33-043","lineIndex":41,"speaker":"","original":"Freunde sind mehr wert als Liebe und Wein.","ipa":"/frɔøndə zɪnt meɾ vɛɾt als libə ʊnt vaɪn/","zh":"爱情和美酒比不上一群好友","en":"Friends are worth more than love and wine.","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-33-044","lineIndex":42,"speaker":"","original":"Ganz recht!","ipa":"/ɡants rɛçt/","zh":"没错！","en":"That's right!","note":"","sourceLineIndex":44}],"sourceOrder":33,"displayOrder":30},{"order":34,"id":"34-irgendwo-wird-immer-getanzt","title":"Irgendwo Wird Immer Getanzt","titleZh":"序曲/ 总有一处可尽情起舞","lines":[{"id":"mozart-das-musical-34-001","lineIndex":1,"speaker":"","original":"Mein Gott, dass war gestern wieder spät dabei ging ich zuerst nach Haus.","ipa":"/maɪn ɡˈɔt das vɑːɾ ɡˈɛstɜn vˈiːdɜ ʃpˈɛːt dɑːbˈaɪ ɡˈɪŋ ɪç tsuːˈeːɾst nɑːx hˈaʊs/","zh":"天哪，昨晚又狂欢到半夜还是我先回的家","en":"My God, that was late again yesterday and I went home first.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-34-003","lineIndex":2,"speaker":"","original":"Noch nicht mal 12, aufstehen ist ungesund ich halt' das grelle Licht nicht aus.","ipa":"/nˈɔx nˈɪçt mˈɑːl tsvˈœlf ˈaʊfʃtˌeːən ɪst ˈʊnɡəzˌʊnt ɪç hˈalt das ɡɾˈɛlə lˈɪçt nˈɪçt ˈaʊs/","zh":"还没到中午12点，早起真是有害健康我简直无法忍受白天刺眼的光线","en":"Not even 12 yet, getting up is unhealthy I can't stand the bright light.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-34-005","lineIndex":3,"speaker":"","original":"Oh Gott, wer räumt dieses Chaos auf?","ipa":"/o ɡɔt veɾ rɔømt dizəs ʃɑos aʊf/","zh":"真要命！谁要收拾这一片狼藉？","en":"Oh God, who's going to clean up this mess?","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-34-006","lineIndex":4,"speaker":"","original":"Kaum dass man noch was finden kann.","ipa":"/kaʊm das man nɔx vas fɪndən kan/","zh":"乱七八糟，想找什么都找不到","en":"It's hard to find anything anymore.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-34-007","lineIndex":5,"speaker":"","original":"Für eine Hausfrau hört die Arbeit niemals auf am besten ich fang gar nicht erst an.","ipa":"/fyːɾ ˌaɪnə hˈaʊsfrˌaʊ hˈœɾt diː ˈaɾbaɪt nˈiːmɑːls aʊf am bˈɛstən ɪç fˈaŋ ɡˌɑːɾnˈɪçt ˈeːɾst ˈan/","zh":"对家庭主妇来说，家务永远无休无止要我说，不如干脆就不要开始！","en":"For a housewife, the work never ends it's best not to even start.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-34-009","lineIndex":6,"speaker":"","original":"Denn da mein Mann ein Künstler ist muss ich ihn inspirieren.","ipa":"/dɛn dɑː maɪn mˈan aɪn kˈʏnstlɜ ɪst mˈʊs ɪç iːn ˌɪnspiːrˈiːrən/","zh":"就因为我的丈夫是位艺术家我就得为他创造灵感","en":"Because since my husband is an artist I have to inspire him.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-34-011","lineIndex":7,"speaker":"","original":"Und wenn es draussen dunkel wird muss ich mich wieder amüsieren.","ipa":"/ʊnt vˌɛn ɛs dɾˈaʊsən dˈʊnkəl vˌɪɾt mˈʊs ɪç mɪç vˈiːdɜ ˌɑmyːzˈiːrən/","zh":"而当夜幕降临我却总得自寻欢乐","en":"And when it gets dark outside I have to have fun again.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-34-013","lineIndex":8,"speaker":"","original":"Irgendwo wird immer getanzt und es ware doch zu schad einen Spass zu versäumen.","ipa":"/ɪɾɡˈɛndvoː vˌɪɾt ˈɪmɜ ɡətˈantst ʊnt ɛs vˈɑːrə dɔx tsuː ʃˈɑːt ˌaɪnən ʃpˈas tsuː fɛɾzˈɔømən/","zh":"总有一处能尽情起舞如果错过此等欢愉也未免太过遗憾","en":"There's always dancing and it would be too bad to miss some fun.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-34-016","lineIndex":9,"speaker":"","original":"Ich leb gern', ich gebe gern'","ipa":"/ɪç lep ɡɛɾn ɪç ɡebə ɡɛɾn/","zh":"我纵情生活，倾情付出","en":"I like to live, I like to give","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-34-017","lineIndex":10,"speaker":"","original":"ich schweb gern auf Träumen","ipa":"/ɪç ʃvep ɡɛɾn aʊf tɾɔømən/","zh":"乘着幻梦尽情翱翔","en":"I like to float on dreams","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-34-018","lineIndex":11,"speaker":"","original":"mit Champagner im Blut","ipa":"/mɪt ʃampanjɜ ɪm blut/","zh":"血液中流淌着香槟","en":"with champagne in my blood","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-34-019","lineIndex":12,"speaker":"","original":"und einer Rose aus Papier im Haar","ipa":"/ʊnt aɪnɜ rozə aʊs papiɾ ɪm hɑɾ/","zh":"发鬓间别着一朵纸玫瑰","en":"and a paper rose in my hair","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-34-020","lineIndex":13,"speaker":"","original":"Ich war schon als Kind sehr bescheiden ich hab mich nie nach vorne gedrängt.","ipa":"/ɪç vɑːɾ ʃˌoːn als kˈɪnt zˈeːɾ bəʃˈaɪdən ɪç hˈɑːp mɪç nˈiː nɑːx fˈɔɾnə ɡədɾˈɛŋt/","zh":"我自小就默默无闻我也不会强迫自己去出人头地","en":"I was very modest even as a child I never pushed myself forward.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-34-022","lineIndex":14,"speaker":"","original":"Ich wollte nicht ins Rampenlicht.","ipa":"/ɪç vɔltə nɪçt ɪns rampənlɪçt/","zh":"我也从未想过要活在聚光灯下","en":"I didn't want the spotlight.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-34-023","lineIndex":15,"speaker":"","original":"Denn das lernen und üben das hätt' mich zu sehr angestrengt und Anstrengung bekommt mir nicht.","ipa":"/dɛn das lˈɛɾnən ʊnt ˈyːbən das hˈɛt mɪç tsuː zˈeːɾ ˈanɡəʃtɾˌɛŋt ʊnt ˈanʃtɾˌɛŋʊŋ bəkˈɔmt miːɾ nˈɪçt/","zh":"学习知识和培养技能只会让我觉得精疲力尽而过度劳累对我并无好处","en":"Because learning and practicing would have put too much effort on me and I don't like the effort.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-34-026","lineIndex":16,"speaker":"","original":"Meine Mutter meinte ich lande mal im Armenhaus drauf' sagte ich ihr, dass ist mir egal.","ipa":"/mˌaɪnə mˈʊtɜ mˈaɪntə ɪç lˈandə mˈɑːl ɪm ˈaɾmənhˌaʊs dɾˈaʊf zˈɑːɡtə ɪç iːɾ das ɪst miːɾ eːɡˈɑːl/","zh":"我的母亲曾经断言我只能在济贫院里孤独终老对此我回敬她：我无所谓！","en":"My mother said I would end up in the poorhouse I told her that I didn't care.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-34-028","lineIndex":17,"speaker":"","original":"Vater prophezeite meine Zukunft sehe dunkel aus ich sagte, die Zukunft kann mich mal.","ipa":"/fˈɑːtɜ pɾoːfˈeːtsaɪtə mˌaɪnə tsuːkˈʊnft zˈeːə dˈʊnkəl ˌaʊs ɪç zˈɑːɡtə diː tsuːkˈʊnft kˌan mɪç mˈɑːl/","zh":"父亲曾预言我的前途必然一片黑暗我反驳他说：去他的前途！","en":"Father predicted my future looked dark I said the future can see me.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-34-030","lineIndex":18,"speaker":"","original":"Meine Schwester behauptet ich sei wie sie ungewöhnlich, begabt und gescheit.","ipa":"/mˌaɪnə ʃvˈɛstɜ bəhˈaʊptət ɪç zˈaɪ viː ziː ˈʊnɡəvˌøːnlɪç bəɡˈɑːpt ʊnt ɡəʃˈaɪt/","zh":"我的姐姐声称我和她一样聪颖机敏，天赋才华","en":"My sister says I'm like her unusual, talented and clever.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-34-032","lineIndex":19,"speaker":"","original":"Ich könnte auf Opernbühnen im Beifall stehen doch dazu fehlt mir leider die Zeit.","ipa":"/ɪç kˈœntə aʊf ˈoːpɛɾnbˌyːnən ɪm bˈaɪfal ʃtˈeːən dɔx dɑːtsˈuː fˈeːlt miːɾ lˈaɪdɜ diː tsˈaɪt/","zh":"我能够在歌剧舞台上享受满堂喝彩但我可没有这份闲心","en":"I could be applauded on opera stages but unfortunately I don't have the time for that.","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-34-034","lineIndex":20,"speaker":"","original":"Irgendwo wird immer getanzt und es wäre doch zu dumm auf ein Glück zu verzichten.","ipa":"/ɪɾɡˈɛndvoː vˌɪɾt ˈɪmɜ ɡətˈantst ʊnt ɛs vˈɛːrə dɔx tsuː dˈʊm aʊf aɪn ɡlˈʏk tsuː fɛɾtsˈɪçtən/","zh":"总有一处能尽情起舞如果凭白将幸福舍弃那未免太过愚蠢","en":"There's always dancing and it would be too stupid to forego happiness.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-34-037","lineIndex":21,"speaker":"","original":"Ich geb gern ich schweb gern erleb gern Geschichten mit Champagner im Glas und einer Rose aus Papier…","ipa":"/ɪç ɡˈeːp ɡˈɛɾn ɪç ʃvˈeːp ɡˈɛɾn ɛɾlˈeːp ɡˈɛɾn ɡəʃˈɪçtən mɪt ʃampˈanjɜ ɪm ɡlˈɑːs ʊnt ˌaɪnɜ rˈoːzə ˌaʊs papˈiːɾ/","zh":"我愿自由漂泊，体验生活的刺激尽情享受这缤纷的世界杯中斟满香槟戴着一朵纸玫瑰","en":"I like to give, I like to float I like to experience stories with champagne in a glass and a paper rose...","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-34-041","lineIndex":22,"speaker":"","original":"Und sollte mein Mann, was Gott verhüten mag","ipa":"/ʊnt zɔltə maɪn man vas ɡɔt fɛɾhutən mɑk/","zh":"我那被上天眷顾的丈夫","en":"And should my husband, what God forbid","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-34-042","lineIndex":23,"speaker":"","original":"eines Tages nicht mehr sein","ipa":"/aɪnəs tɑɡəs nɪçt meɾ zaɪn/","zh":"若有一天撒手人寰","en":"will no longer be one day","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-34-043","lineIndex":24,"speaker":"","original":"dann trauere ich um ihn auf meine Art","ipa":"/dan tɾaʊərə ɪç ʊm in aʊf maɪnə ɑɾt/","zh":"我自有我自己的方式来悼念","en":"then I'll mourn him in my own way","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-34-044","lineIndex":25,"speaker":"","original":"glaub bloss nicht, dass ich am Grab steh' und wein.","ipa":"/ɡlaʊp blɔs nɪçt das ɪç am ɡɾɑp ʃte ʊnt vaɪn/","zh":"可别指望我站在他的墓前以泪洗面！","en":"just don't think that I'm standing at the grave and crying.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-34-045","lineIndex":26,"speaker":"","original":"Irgendwo wird immer getanzt und es ware doch zu schad einen Spass zu versäumen.","ipa":"/ɪɾɡˈɛndvoː vˌɪɾt ˈɪmɜ ɡətˈantst ʊnt ɛs vˈɑːrə dɔx tsuː ʃˈɑːt ˌaɪnən ʃpˈas tsuː fɛɾzˈɔømən/","zh":"总有一处能尽情起舞如果错过此等欢愉也未免太过遗憾","en":"There's always dancing and it would be too bad to miss some fun.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-34-048","lineIndex":27,"speaker":"","original":"Ich leb gern', ich gebe gern'","ipa":"/ɪç lep ɡɛɾn ɪç ɡebə ɡɛɾn/","zh":"我纵情生活，倾情付出","en":"I like to live, I like to give","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-34-049","lineIndex":28,"speaker":"","original":"ich schweb gern auf Träumen","ipa":"/ɪç ʃvep ɡɛɾn aʊf tɾɔømən/","zh":"乘着幻梦尽情翱翔","en":"I like to float on dreams","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-34-050","lineIndex":29,"speaker":"","original":"mit Champagner im Blut","ipa":"/mɪt ʃampanjɜ ɪm blut/","zh":"血液中流淌着香槟","en":"with champagne in my blood","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-34-051","lineIndex":30,"speaker":"","original":"und einer Rose aus Papier im Haar","ipa":"/ʊnt aɪnɜ rozə aʊs papiɾ ɪm hɑɾ/","zh":"发鬓间别着一朵纸玫瑰","en":"and a paper rose in my hair","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-34-052","lineIndex":31,"speaker":"","original":"Es ware doch schad einen Spass zu versäumen…","ipa":"/ɛs vɑrə dɔx ʃɑt aɪnən ʃpas tsu fɛɾzɔømən/","zh":"如果错过此等欢愉也未免太过遗憾","en":"It would be a shame to miss out on some fun...","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-34-053","lineIndex":32,"speaker":"","original":"Was immer auch ist oder war!","ipa":"/vas ɪmɜ aʊx ɪst odɜ vɑɾ/","zh":"无论曾经还是现在，都是如此！","en":"Whatever is or was!","note":"","sourceLineIndex":53}],"sourceOrder":34,"displayOrder":31},{"order":35,"id":"35-mozart-zitat-ouverture-titus","title":"Mozart-Zitat (Ouvertüre \"Titus\")","titleZh":"莫扎特引曲（《狄托的仁慈》序曲）","lines":[{"id":"mozart-das-musical-35-001","lineIndex":1,"speaker":"Graf Arco","original":"Wohin soll ich das Gehirn stellen, Durchlaucht?","ipa":"/ɡɾɑf aɾko vohin zɔl ɪç das ɡəhɪɾn ʃtɛlən dʊɐçlaʊxt/","zh":"阿尔科伯爵我应该把这个大脑放到哪里，殿下？","en":"Count ArcoWhere should I put the brain, Your Highness?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-35-002","lineIndex":2,"speaker":"","original":"Bitte, Durchlaucht, wohin?","ipa":"/bɪtə dʊɐçlaʊxt vohin/","zh":"殿下，放到哪里？","en":"Please, Your Highness, where?","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-35-003","lineIndex":3,"speaker":"Fürsterzbischof Colloredo","original":"Unfassbar!","ipa":"/fʏɾstɜtsbɪʃof kɔloredo ʊnfasbɑɾ/","zh":"科洛雷多不可思议！","en":"Prince Archbishop ColloredoIncredible!","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-35-004","lineIndex":4,"speaker":"Graf Arco","original":"Ja, das Gehirn des französischen Malers.","ipa":"/ɡɾɑf aɾko jɑ das ɡəhɪɾn dɛs frantsøzɪʃən mɑlɜs/","zh":"阿尔科伯爵是的，那个法国画家的大脑","en":"Count ArcoYes, the brain of the French painter.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-35-005","lineIndex":5,"speaker":"Fürsterzbischof Colloredo","original":"Vollkommen!","ipa":"/fʏɾstɜtsbɪʃof kɔloredo fɔlkɔmən/","zh":"科洛雷多无可挑剔！","en":"Prince Archbishop ColloredoPerfectly!","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-35-006","lineIndex":6,"speaker":"Graf Arco","original":"Zur medizinische Sammlung oder zu den Raritäten?","ipa":"/ɡɾɑf aɾko tsuɾ meditsinɪʃə zamlʊŋ odɜ tsu den rɑritɛtən/","zh":"阿尔科伯爵放到医学陈列室还是和古董放在一起？","en":"Graf ArcoTo the medical collection or to the rarities?","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-35-007","lineIndex":7,"speaker":"Fürsterzbischof Colloredo","original":"Was?","ipa":"/fʏɾstɜtsbɪʃof kɔloredo vas/","zh":"科洛雷多什么？","en":"Prince Archbishop ColloredoWhat?","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-35-008","lineIndex":8,"speaker":"Graf Arco","original":"Entschuldigen Sie.","ipa":"/ɡɾɑf aɾko ɛntʃʊldɪɡən zi/","zh":"阿尔科伯爵打扰一下，您亲自看看","en":"Count ArcoExcuse me.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-35-009","lineIndex":9,"speaker":"Fürsterzbischof Colloredo","original":"Was ist das?","ipa":"/fʏɾstɜtsbɪʃof kɔloredo vas ɪst das/","zh":"科洛雷多这是什么？","en":"Prince Archbishop ColloredoWhat is that?","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-35-010","lineIndex":10,"speaker":"Graf Arco","original":"Das Präparat, das heute Morgen aus Paris kam, von Dr. Anton Mesmer.","ipa":"/ɡɾɑf aɾko das pɾɛparɑt das hɔøtə mɔɾɡən aʊs pɑrɪs kɑm fɔn deɛɾ anton mɛsmɜ/","zh":"阿尔科伯爵安东 梅斯莫医生今早从巴黎寄来的标本","en":"Graf ArcoThe preparation that came from Paris this morning from Dr. Anton Mesmer.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-35-011","lineIndex":11,"speaker":"Fürsterzbischof Colloredo","original":"Was soll das jetzt?","ipa":"/fʏɾstɜtsbɪʃof kɔloredo vas zɔl das jɛtst/","zh":"科洛雷多现在还管这个干什么？","en":"Prince Archbishop ColloredoWhat's this supposed to mean?","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-35-012","lineIndex":12,"speaker":"","original":"Holen Sie mir den alten Mozart. Sofort!","ipa":"/holən zi miɾ den altən motsaɾt zofɔɾt/","zh":"给我把老莫扎特找来，马上！","en":"Get me the old Mozart. Immediately!","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-35-013","lineIndex":13,"speaker":"Graf Arco","original":"Sehr wohl.","ipa":"/ɡɾɑf aɾko zeɾ vol/","zh":"阿尔科伯爵好的","en":"Count ArcoVery well.","note":"","sourceLineIndex":13}],"sourceOrder":35,"displayOrder":32},{"order":36,"id":"36-wie-kann-es-moglich-sein","title":"Wie Kann Es Möglich Sein?","titleZh":"怎会如此？","lines":[{"id":"mozart-das-musical-36-002","lineIndex":1,"speaker":"Colloredo","original":"Ich habe mein Leben mit Büchern vergeudet um Gott und die Welt zu verstehen.","ipa":"/ɪç hɑːbə maɪn lˈeːbən mɪt bˈyːçɜn fɛɾɡəˈuːdət ʊm ɡˈɔt ʊnt diː vˈɛlt tsuː fɛɾʃtˈeːən/","zh":"我穷尽一生，畅游书海企图以此理解上帝和世界.","en":"I wasted my life on books to understand God and the world.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-36-004","lineIndex":2,"speaker":"","original":"Ich hab die Natur untersucht und gedeutet","ipa":"/ɪç hɑp di natuɾ ʊntɜzuxt ʊnt ɡədɔøtət/","zh":"我探索自然，阐释万物","en":"I examined and interpreted nature","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-36-005","lineIndex":3,"speaker":"","original":"um hinter die Dinge zu sehen","ipa":"/ʊm hɪntɜ di dɪŋə tsu zeən/","zh":"是为寻求世间真相","en":"to see behind things","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-36-006","lineIndex":4,"speaker":"","original":"Doch langsam wird mir klar:","ipa":"/dɔx laŋzɑm vɪɾt miɾ klɑɾ/","zh":"但我慢慢明白：","en":"But slowly I realize:","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-36-007","lineIndex":5,"speaker":"","original":"Ich schein mich wie ein Narr im Kreis zu drehen.","ipa":"/ɪç ʃˈaɪn mɪç viː aɪn nˈaɾ ɪm kɾˈaɪs tsuː dɾˈeːən/","zh":"我就像个傻瓜在圈中原地打转。","en":"I seem like a fool to rotate in circles.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-36-009","lineIndex":6,"speaker":"","original":"Mein Gott, ich bin am Ende mit meinem Griechisch und Latein.","ipa":"/maɪn ɡˈɔt ɪç bɪn am ˈɛndə mɪt mˌaɪnəm ɡɾˈiːçɪʃ ʊnt lˈɑtaɪn/","zh":"主啊，我已无以为继希腊语与拉丁语再无用武之地。","en":"My God, I'm at the end with my Greek and Latin.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-36-011","lineIndex":7,"speaker":"","original":"Mein Verstand läuft gegen Wände was ich seh, seh ich nicht ein.","ipa":"/maɪn fɛɾʃtˈant lˈɔøft ɡˌeːɡən vˈɛndə vˈas ɪç zˈeː zˈeː ɪç nˈɪçt ˈaɪn/","zh":"理智为我筑起高墙遮挡了我看清现实的目光。","en":"My mind is running against walls what I see, I don't understand.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-36-013","lineIndex":8,"speaker":"","original":"Wie kann es möglich sein gerechter Gott?","ipa":"/viː kˌan ɛs mˈøːklɪç zaɪn ɡərˈɛçtɜ ɡˈɔt/","zh":"这怎么可能呢公正的主啊？","en":"How can it be possible righteous God?","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-36-015","lineIndex":9,"speaker":"","original":"Ich dachte, was uns weiterbringt sind Einsicht und Kritik.","ipa":"/ɪç dˈaxtə vˈas ʊns vˈaɪtɜbɾˌɪŋt zɪnt ˈaɪnzˌɪçt ʊnt kɾˈiːtiːk/","zh":"我曾坚信那引领我们前行的是理智与批判。","en":"I thought what would get us further was insight and criticism.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-36-017","lineIndex":10,"speaker":"","original":"Wie kann es sein dass die Vernunft, die diese Welt erhellen soll besiegt wird vom Zauber der Musik?","ipa":"/viː kˌan ɛs zaɪn das diː fɛɾnˈʊnft diː dˌiːzə vˈɛlt ɛɾhˈɛlən zˌɔl bəzˈiːkt vˌɪɾt fɔm tsˈaʊbɜ dɛɾ muːzˈiːk/","zh":"怎么会呢那照亮世界的理性居然会败给那音乐的魔力？","en":"How can it be that reason, which is supposed to illuminate this world is defeated by the magic of music?","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-36-021","lineIndex":11,"speaker":"Karl Joseph Graf Arco","original":"Leopold Mozart, Durchlaucht.","ipa":"/kaɾl jozef ɡɾɑf aɾko leopɔlt motsaɾt dʊɐçlaʊxt/","zh":"卡尔·约瑟夫·阿尔克伯爵：阁下，利奥波德·莫扎特来了。","en":"Leopold Mozart, Serene Highness.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-36-022","lineIndex":12,"speaker":"Colloredo","original":"Er will nach Wien fahren?","ipa":"/kɔloredo ɛɾ vɪl nɑx vin fɑrən/","zh":"科洛雷多：你要去维也纳？","en":"He wants to go to Vienna?","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-36-023","lineIndex":13,"speaker":"Leopold","original":"Sehr Wohl, Exzellenz.","ipa":"/leopɔlt zeɾ vol ɛkstsəlɛnts/","zh":"利奥波德：是的，大人。","en":"Very well, Your Excellency.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-36-024","lineIndex":14,"speaker":"","original":"Ich habe meinen Sohn seit Jahren nicht gesehen.","ipa":"/ɪç hɑbə maɪnən zon zaɪt jɑrən nɪçt ɡəzeən/","zh":"我已经多年没有见到我的儿子了。","en":"I haven't seen my son in years.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-36-025","lineIndex":15,"speaker":"Colloredo","original":"Holen Sie ihn nach Salzburg zurück.","ipa":"/kɔloredo holən zi in nɑx zaltsbʊɐk tsurʏk/","zh":"科洛雷多：带他回萨尔茨堡来。","en":"Bring him back to Salzburg.","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-36-026","lineIndex":16,"speaker":"","original":"Ich habe ihm vergeben.","ipa":"/ɪç hɑbə im fɛɾɡebən/","zh":"我原谅他了。","en":"I have forgiven him.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-36-027","lineIndex":17,"speaker":"Leopold","original":"Ich danke untertänigst!","ipa":"/leopɔlt ɪç daŋkə ʊntɜtɛnɪçst/","zh":"利奥波德：实在太感谢您了！","en":"I humbly thank you!","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-36-028","lineIndex":18,"speaker":"","original":"Wir verdienen Ihre Gnade nicht, Exzellenz.","ipa":"/viɾ fɛɾdinən irə ɡənɑdə nɪçt ɛkstsəlɛnts/","zh":"我们本不应该得到您的宽恕的，主教阁下。","en":"We do not deserve your mercy, Your Excellency.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-36-029","lineIndex":19,"speaker":"Colloredo","original":"Gnade kümmert sich nicht um Verdienst.","ipa":"/kɔloredo ɡənɑdə kʏmɜt zɪç nɪçt ʊm fɛɾdinst/","zh":"科洛雷多：宽恕没有什么应得与否。","en":"Grace doesn't care about merit.","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-36-030","lineIndex":20,"speaker":"Leopold","original":"Seien Sie unbesorgt, Durchlaucht.","ipa":"/leopɔlt zaɪən zi ʊnbəzɔɾkt dʊɐçlaʊxt/","zh":"利奥波德：阁下，您别担心。","en":"Don't worry, Your Highness.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-36-031","lineIndex":21,"speaker":"","original":"Wenn er nicht zurückkommen will er ist leider etwas halsstarrig - schenke ich Ihnen ein neues Wunderkind.","ipa":"/vˌɛn ɛɾ nˈɪçt tsuːrˈʏkkˌɔmən vɪl ɛɾ ɪst lˈaɪdɜ ˈɛtvɑːs hˈalsʃtarˌɪç ʃˈɛŋkə ɪç ˌiːnən aɪn nˈɔøəs vˈʊndɜkˌɪnt/","zh":"要是他还不想回来还那么固执的话 —我就给您带来一个新的神童。","en":"If he doesn't want to come back he's unfortunately a bit stubborn - I'll give you a new prodigy.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-36-034","lineIndex":22,"speaker":"","original":"Mein Enkel Leopold!","ipa":"/maɪn ɛnkəl leopɔlt/","zh":"我的外孙小利奥波德！","en":"My grandson Leopold!","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-36-035","lineIndex":23,"speaker":"Colloredo","original":"Ein neuer Mozart!?","ipa":"/kɔloredo aɪn nɔøɜ motsaɾt/","zh":"科洛雷多：一个新的莫扎特？","en":"A new Mozart!?","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-36-036","lineIndex":24,"speaker":"Leopold","original":"Wie Wolfgang - mein Fleisch und Blut und ebenso begabt.","ipa":"/viː vˈɔlfɡaŋ maɪn flˈaɪʃ ʊnt blˈuːt ʊnt ˈeːbənzˌoː bəɡˈɑːpt/","zh":"利奥波德：和沃尔夫冈一样，是我的亲骨肉。当然也一样是个天才。","en":"Like Wolfgang - my flesh and blood and just as talented.","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-36-038","lineIndex":25,"speaker":"Colloredo","original":"Er soll nach Wien fahren und mir meinen Mozart zurückholen.","ipa":"/ɛɾ zˌɔl nɑːx vˈiːn fˈɑːrən ʊnt miːɾ mˌaɪnən mˈoːtsaɾt tsuːrˈʏkhˌoːlən/","zh":"科洛雷多：你必须去维也纳把“我的”莫扎特带回来。","en":"He should go to Vienna and get my Mozart back for me.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-36-040","lineIndex":26,"speaker":"Leopold","original":"Ich habe einmal ein Genie geschaffen.","ipa":"/leopɔlt ɪç hɑbə aɪnmɑl aɪn ɡəni ɡəʃafən/","zh":"利奥波德：我怕曾经培养过一个天才","en":"I once created a genius.","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-36-041","lineIndex":27,"speaker":"","original":"Ich kann es jederzeit wieder tun!","ipa":"/ɪç kan ɛs jedɜtsaɪt vidɜ tun/","zh":"我随时都能再培养一个出来！","en":"I can do it again anytime!","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-36-042","lineIndex":28,"speaker":"Leopold","original":"Schluss! Ich will den richtigen Mozart! Arco!","ipa":"/leopɔlt ʃlʊs ɪç vɪl den rɪçtɪɡən motsaɾt aɾko/","zh":"科洛雷多：够了！我只要真正的莫扎特！阿尔克！送客！","en":"Over! I want the real Mozart! Arco!","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-36-043","lineIndex":29,"speaker":"Colloredo","original":"Oja, man kann jeden belehr′n und erziehen.","ipa":"/kɔloredo ojɑ man kan jedən bəleɾn ʊnt ɛɾtsiən/","zh":"没错，所有人都能被训导和教育。","en":"Oh yes, you can teach and educate anyone.","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-36-044","lineIndex":30,"speaker":"","original":"Man kann sogar Affen dressieren.","ipa":"/man kan zoɡɑɾ afən dɾɛsirən/","zh":"即便猴子都能被驯化。","en":"You can even train monkeys.","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-36-045","lineIndex":31,"speaker":"","original":"Der Mensch ist ein Same, und soll er erblühen muss man ihn schon früh kultivieren.","ipa":"/dɛɾ mˈɛnʃ ɪst aɪn zˈɑːmə ʊnt zˌɔl ɛɾ ɛɾblˈyːən mˈʊs man iːn ʃˌoːn frˈyː kˌʊltiːvˈiːrən/","zh":"人类是一颗种子，会开花尽早栽培才能成长。","en":"Man is a seed, and if he is to blossom he must be cultivated at an early age.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-36-047","lineIndex":32,"speaker":"","original":"Soviel steht fest für mich, doch Wunder kann auch ich nicht ignorieren.","ipa":"/zˈoːviːl ʃtˈeːt fˈɛst fyːɾ mɪç dɔx vˈʊndɜ kˌan ˌaʊx ɪç nˈɪçt ˌɪɡnoːrˈiːrən/","zh":"这些我已经明了，但我也没法忽视奇迹。","en":"That much is certain for me, but even I can't ignore miracles.","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-36-049","lineIndex":33,"speaker":"","original":"Mein Gott, du weißt, ich machte mir meine Pflichten niemals leicht.","ipa":"/maɪn ɡˈɔt duː vˈaɪst ɪç mˈaxtə miːɾ mˌaɪnə pflˈɪçtən nˈiːmɑːls lˈaɪçt/","zh":"主啊，你知道，我的所作所为一生都辛勤地尽职尽责。","en":"My God, you know I never made my duties easy.","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-36-051","lineIndex":34,"speaker":"","original":"Doch grad der, der mich verlachte hat Vollkommenheit erreicht.","ipa":"/dɔx ɡɾˈɑːt dɛɾ dɛɾ mɪç fɛɾlˈaxtə hat fɔlkˈɔmənhˌaɪt ɛɾrˈaɪçt/","zh":"但这个对我肆意讥笑的人却已登峰造极。","en":"But the very one who laughed at me has achieved perfection.","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-36-053","lineIndex":35,"speaker":"","original":"Wie kann es möglich sein gerechter Gott?","ipa":"/viː kˌan ɛs mˈøːklɪç zaɪn ɡərˈɛçtɜ ɡˈɔt/","zh":"公正的主啊这怎么可能？","en":"How can it be possible righteous God?","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-36-055","lineIndex":36,"speaker":"","original":"Ich dachte, was uns weiterbringt sind Einsicht und Kritik.","ipa":"/ɪç dˈaxtə vˈas ʊns vˈaɪtɜbɾˌɪŋt zɪnt ˈaɪnzˌɪçt ʊnt kɾˈiːtiːk/","zh":"我曾坚信那引领我们前行的是理智与批判。","en":"I thought what would bring us forward was insight and criticism.","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-36-057","lineIndex":37,"speaker":"","original":"Wie kann es sein dass die Vernunft, die diese Welt erhellen soll besiegt wird vom Zauber der Musik?","ipa":"/viː kˌan ɛs zaɪn das diː fɛɾnˈʊnft diː dˌiːzə vˈɛlt ɛɾhˈɛlən zˌɔl bəzˈiːkt vˌɪɾt fɔm tsˈaʊbɜ dɛɾ muːzˈiːk/","zh":"怎么会呢那照亮世界的理性居然会败给那音乐的魔力？","en":"How can it be that reason, which is supposed to illuminate this world would be defeated by the magic of music?","note":"","sourceLineIndex":57},{"id":"mozart-das-musical-36-061","lineIndex":38,"speaker":"","original":"Wie kann es sein","ipa":"/vi kan ɛs zaɪn/","zh":"怎么会呢","en":"How can it be","note":"","sourceLineIndex":61},{"id":"mozart-das-musical-36-062","lineIndex":39,"speaker":"","original":"dass die Vernunft, die diese Welt erhellen soll","ipa":"/das di fɛɾnʊnft di dizə vɛlt ɛɾhɛlən zɔl/","zh":"那照亮世界的理性","en":"that reason, which is supposed to illuminate this world","note":"","sourceLineIndex":62},{"id":"mozart-das-musical-36-063","lineIndex":40,"speaker":"","original":"besiegt wird","ipa":"/bəzikt vɪɾt/","zh":"居然会败给","en":"would be defeated","note":"","sourceLineIndex":63},{"id":"mozart-das-musical-36-064","lineIndex":41,"speaker":"","original":"von einem mir entflognen","ipa":"/fɔn aɪnəm miɾ ɛntflɔɡnən/","zh":"被那离我远去","en":"by someone who escaped from me","note":"","sourceLineIndex":64},{"id":"mozart-das-musical-36-065","lineIndex":42,"speaker":"","original":"ausgestoßenen","ipa":"/aʊsɡəʃtosnən/","zh":"撼我心扉","en":"cast out","note":"","sourceLineIndex":65},{"id":"mozart-das-musical-36-066","lineIndex":43,"speaker":"","original":"ungezognen","ipa":"/ʊnɡətsɔɡnən/","zh":"粗俗无礼","en":"naughty","note":"","sourceLineIndex":66},{"id":"mozart-das-musical-36-067","lineIndex":44,"speaker":"","original":"zügellosen","ipa":"/tsyɡəlozən/","zh":"大胆放肆","en":"self-indulgent","note":"","sourceLineIndex":67},{"id":"mozart-das-musical-36-068","lineIndex":45,"speaker":"","original":"obstinanten","ipa":"/ɔpstinantən/","zh":"顽固执拗","en":"obstinate","note":"","sourceLineIndex":68},{"id":"mozart-das-musical-36-069","lineIndex":46,"speaker":"","original":"gernegrossen","ipa":"/ɡɛɾnɛɡɾɔsən/","zh":"傲慢自大","en":"big","note":"","sourceLineIndex":69},{"id":"mozart-das-musical-36-070","lineIndex":47,"speaker":"","original":"Teufelsbraten","ipa":"/tɔøfəlsbɾɑtən/","zh":"流氓恶徒","en":"devil's roast","note":"","sourceLineIndex":70},{"id":"mozart-das-musical-36-071","lineIndex":48,"speaker":"","original":"und dem Zauber der Musik?","ipa":"/ʊnt dem tsaʊbɜ dɛɾ muzik/","zh":"被他音乐的魔力所征服？","en":"and the magic of music?","note":"","sourceLineIndex":71}],"sourceOrder":36,"displayOrder":33},{"order":38,"id":"38-warum-kannst-du-mich-nicht-lieben","title":"Warum Kannst Du Mich Nicht Lieben?","titleZh":"你为什么不能爱我？","lines":[{"id":"mozart-das-musical-38-001","lineIndex":1,"speaker":"","original":"Ich hab geglaubt","ipa":"/ɪç hɑp ɡəɡlaʊpt/","zh":"我曾经相信","en":"I thought","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-38-002","lineIndex":2,"speaker":"","original":"du wärst hergekommen","ipa":"/du vɛɾst hɛɾɡekɔmən/","zh":"你会来到这里","en":"you had come here","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-38-003","lineIndex":3,"speaker":"","original":"um dich mit mir zu freuen","ipa":"/ʊm dɪç mɪt miɾ tsu frɔøən/","zh":"为我的成就感到欣喜","en":"to rejoice with me","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-38-004","lineIndex":4,"speaker":"","original":"Du hast gedacht","ipa":"/du hast ɡədaxt/","zh":"你曾想过","en":"You thought","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-38-005","lineIndex":5,"speaker":"","original":"ich wär hilflos ohne dich","ipa":"/ɪç vɛɾ hɪlflos onə dɪç/","zh":"没有你我将会多么无助","en":"I would be helpless without you","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-38-006","lineIndex":6,"speaker":"","original":"und alleine würde ich","ipa":"/ʊnt alaɪnə vʏɾdə ɪç/","zh":"我将孤身一人","en":"and alone I would","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-38-007","lineIndex":7,"speaker":"","original":"meinen Mut bald bereuen","ipa":"/maɪnən mut balt bərɔøən/","zh":"会很快后悔自己的鲁莽决定","en":"soon regret my courage","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-38-008","lineIndex":8,"speaker":"","original":"Doch wenn ich dir sage","ipa":"/dɔx vɛn ɪç diɾ zɑɡə/","zh":"可当我对你说","en":"But when I tell you","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-38-009","lineIndex":9,"speaker":"","original":"schau her ich hab dich nicht enttäuscht","ipa":"/ʃaʊ heɾ ɪç hɑp dɪç nɪçt ɛnttɔøʃt/","zh":"看啊，我没让你失望","en":"look here, I didn't disappoint you","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-38-010","lineIndex":10,"speaker":"","original":"siehst du gar nicht richtig hin","ipa":"/zist du ɡɑɾnɪçt rɪçtɪç hɪn/","zh":"你却视而不见","en":"you don't even look properly","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-38-011","lineIndex":11,"speaker":"","original":"und lässt mich stehn","ipa":"/ʊnt lɛst mɪç ʃten/","zh":"徒留我站在原地","en":"and leave me standing","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-38-012","lineIndex":12,"speaker":"","original":"Warum kannst du mich nicht lieben wie ich bin?","ipa":"/vɑrʊm kanst du mɪç nɪçt libən vi ɪç bɪn/","zh":"你为何就不能爱那个真实的我？","en":"Why can't you love me as I am?","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-38-013","lineIndex":13,"speaker":"","original":"Ja, du hast recht","ipa":"/jɑ du hast rɛçt/","zh":"是，你说的没错","en":"Yes, you're right","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-38-014","lineIndex":14,"speaker":"","original":"auf mich ist oft kein Verlass","ipa":"/aʊf mɪç ɪst ɔft kaɪn fɛɾlas/","zh":"我常常那样不可靠","en":"I'm often not reliable","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-38-015","lineIndex":15,"speaker":"","original":"Ich vergess meine Pflichten","ipa":"/ɪç fɛɾɡɛs maɪnə pflɪçtən/","zh":"也会忘记自己的职责","en":"I forget my duties","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-38-016","lineIndex":16,"speaker":"","original":"So bin ich halt","ipa":"/zo bɪn ɪç halt/","zh":"可我本就如此","en":"That's just me","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-38-017","lineIndex":17,"speaker":"","original":"Ich hab' Hunger nach Glück","ipa":"/ɪç hɑp hʊŋɜ nɑx ɡlʏk/","zh":"我渴望幸福","en":"I'm hungry for happiness","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-38-018","lineIndex":18,"speaker":"","original":"Ich greif nach dem Augenblick","ipa":"/ɪç ɡɾaɪf nɑx dem aʊɡənblɪk/","zh":"我要抓住当下","en":"I reach for it the moment","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-38-019","lineIndex":19,"speaker":"","original":"Ich kann nicht verzichten","ipa":"/ɪç kan nɪçt fɛɾtsɪçtən/","zh":"这我无法放弃","en":"I can't give up","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-38-020","lineIndex":20,"speaker":"","original":"Ich will's auch nicht","ipa":"/ɪç vɪls aʊx nɪçt/","zh":"我也不想放弃","en":"I don't want to either","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-38-021","lineIndex":21,"speaker":"","original":"Das Kind, das ich gewesen bin","ipa":"/das kɪnt das ɪç ɡəvezən bɪn/","zh":"那个我曾经是的孩子","en":"The child that I was","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-38-022","lineIndex":22,"speaker":"","original":"steckt noch immer in mir drin","ipa":"/ʃtɛkt nɔx ɪmɜ ɪn miɾ dɾin/","zh":"他仍然住在我心里","en":"is still inside me","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-38-023","lineIndex":23,"speaker":"","original":"Und es fragt wie ich:","ipa":"/ʊnt ɛs frɑkt vi ɪç/","zh":"而且他也在像我一样发问：","en":"And it asks like me:","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-38-024","lineIndex":24,"speaker":"","original":"Warum kannst du mich nicht lieben wie ich bin?","ipa":"/vɑrʊm kanst du mɪç nɪçt libən vi ɪç bɪn/","zh":"为什么你不能爱这样的我？","en":"Why can't you love me as I am?","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-38-025","lineIndex":25,"speaker":"","original":"Ich such nach dir und kann ich dich nicht erreichen","ipa":"/ɪç zux nɑx diɾ ʊnt kan ɪç dɪç nɪçt ɛɾraɪçən/","zh":"我把你追寻却无法触及","en":"I'm looking you and I can't reach you","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-38-026","lineIndex":26,"speaker":"","original":"Ich sprech mit dir Doch du hörst mir nicht zu","ipa":"/ɪç ʃpɾɛç mɪt diɾ dɔx du høɾst miɾ nɪçt tsu/","zh":"我与你交谈你却从不倾听","en":"I'm talking to you But you don't listen to me","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-38-027","lineIndex":27,"speaker":"","original":"Und das schlimmste ist: Ich weiss nicht warum ich dich verloren habe","ipa":"/ʊnt das ʃlɪmstə ɪst ɪç vaɪs nɪçt vɑrʊm ɪç dɪç fɛɾlorən hɑbə/","zh":"而最糟糕的是，我不明白我为何失去了你","en":"And the worst thing is: I don't know why I lost you","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-38-028","lineIndex":28,"speaker":"","original":"Ich kann nicht sein, wie jeder ist","ipa":"/ɪç kan nɪçt zaɪn vi jedɜ ɪst/","zh":"我不能成为别人那样的人","en":"I can't be like everyone is","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-38-029","lineIndex":29,"speaker":"","original":"Und ich kann nicht sein, wie du bist","ipa":"/ʊnt ɪç kan nɪçt zaɪn vi du bɪst/","zh":"我也无法成为你那样的人","en":"And I can't be like you are","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-38-030","lineIndex":30,"speaker":"","original":"Statt allen zu gefallen muss ich werden, der ich bin","ipa":"/ʃtˈat ˈalən tsuː ɡəfˈalən mˈʊs ɪç vˌɛɾdən dɛɾ ɪç bˈɪn/","zh":"我不会去讨得所有人的喜欢而是必须成为我自己","en":"Instead of pleasing everyone to please I have to become who I am","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-38-033","lineIndex":31,"speaker":"","original":"Niemals werd'ich wieder so geborgen sein wie in Kindertagen","ipa":"/nˈiːmɑːls vˈɛɾdɪç vˈiːdɜ zoː ɡəbˈɔɾɡən zaɪn viː ɪn kˈɪndɜtˌɑːɡən/","zh":"我再也无法像小时候那样在保护中生活下去","en":"I will never be as safe again as when I was a child","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-38-035","lineIndex":32,"speaker":"","original":"Solang ich leb'","ipa":"/zolaŋ ɪç lep/","zh":"只要我还活着","en":"As long as I live","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-38-036","lineIndex":33,"speaker":"","original":"werde ich die Erinnerung daran","ipa":"/vɛɾdə ɪç di ɛɾɪnərʊŋ dɑran/","zh":"我都会将那段儿时的记忆","en":"I will remember it","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-38-037","lineIndex":34,"speaker":"","original":"wie einen Schatz in mir tragen","ipa":"/vi aɪnən ʃats ɪn miɾ tɾɑɡən/","zh":"视作珍宝在心底珍藏","en":"like carrying a treasure inside me","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-38-038","lineIndex":35,"speaker":"","original":"Doch es gibt kein zurück","ipa":"/dɔx ɛs ɡipt kaɪn tsurʏk/","zh":"但我们无法回到过去","en":"But there is no going back","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-38-039","lineIndex":36,"speaker":"","original":"Denn ich muss nun meinen eignen Weg gehn","ipa":"/dɛn ɪç mʊs nun maɪnən aɪɡnən vek ɡen/","zh":"因为我必须踏上自己的征程","en":"Because I have to go my own way now","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-38-040","lineIndex":37,"speaker":"","original":"Jetzt umzukehren, wär ohne Sinn","ipa":"/jɛtst ʊmtsukerən vɛɾ onə zɪn/","zh":"现在回头也毫无意义","en":"Turning back now would make no sense","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-38-041","lineIndex":38,"speaker":"","original":"Ist das so schwer zu verstehn?","ipa":"/ɪst das zo ʃveɾ tsu fɛɾʃten/","zh":"这些就那样难以理解？","en":"Is that so difficult to understand?","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-38-042","lineIndex":39,"speaker":"","original":"Warum kannst du mich nicht lieben?","ipa":"/vɑrʊm kanst du mɪç nɪçt libən/","zh":"为什么你不能爱我？","en":"Why can't you love me?","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-38-043","lineIndex":40,"speaker":"","original":"Warum kannst du mich nicht lieben?","ipa":"/vɑrʊm kanst du mɪç nɪçt libən/","zh":"为什么你不能爱这样的我？？","en":"Why can't you love me?","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-38-044","lineIndex":41,"speaker":"","original":"Warum kannst du mich nicht lieben— wie ich bin?","ipa":"/vɑːrˈʊm kˌanst duː mɪç nˈɪçt lˈiːbən viː ɪç bˈɪn/","zh":"为什么你不能爱那个真正的我？？？","en":"Why can't you love me— as I am?","note":"","sourceLineIndex":44}],"sourceOrder":38,"displayOrder":34},{"order":39,"id":"39-mozarts-verwirrung","title":"Mozarts Verwirrung","titleZh":"莫扎特的迷惘","lines":[{"id":"mozart-das-musical-39-001","lineIndex":1,"speaker":"","original":"Armes Bürschlein!","ipa":"/aɾməs bʏɾʃlaɪn/","zh":"可怜的男孩","en":"Poor little boy!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-39-002","lineIndex":2,"speaker":"","original":"Dummes Menschlein!","ipa":"/dʊməs mɛnʃlaɪn/","zh":"愚蠢的小家伙","en":"Stupid human being!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-39-003","lineIndex":3,"speaker":"","original":"Wie verächtlich!","ipa":"/vi fɛɾɛçtlɪç/","zh":"真让人瞧不起","en":"How despicable!","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-39-004","lineIndex":4,"speaker":"","original":"Du bist schwächlich!","ipa":"/du bɪst ʃvɛçlɪç/","zh":"你这么软弱","en":"You are weak!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-39-005","lineIndex":5,"speaker":"","original":"Du bist faul und oberflächlich!","ipa":"/du bɪst faʊl ʊnt obɜflɛçlɪç/","zh":"懒惰又肤浅","en":"You are lazy and superficial!","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-39-006","lineIndex":6,"speaker":"","original":"Beeilung! Beeilung!","ipa":"/bəaɪlʊŋ bəaɪlʊŋ/","zh":"快！快！","en":"Hurry! Hurry!","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-39-007","lineIndex":7,"speaker":"","original":"In der nächsten Abteilung...","ipa":"/ɪn dɛɾ nɛçstən aptaɪlʊŋ/","zh":"进入下一个章节…","en":"In the next section...","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-39-008","lineIndex":8,"speaker":"","original":"Die schwierigsten Fugen","ipa":"/di ʃvirɪçstən fuɡən/","zh":"最难的赋格","en":"The most difficult joints","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-39-009","lineIndex":9,"speaker":"","original":"Erstaunlich! Erstaunlich!","ipa":"/ɛɾʃtaʊnlɪç ɛɾʃtaʊnlɪç/","zh":"妙！妙啊！","en":"Amazing! Astonishing!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-39-010","lineIndex":10,"speaker":"","original":"Dieses Tuch wird seine Schwester über seinen Augen legen","ipa":"/dizəs tʊx vɪɾt zaɪnə ʃvɛstɜ ybɜ zaɪnən aʊɡən leɡən/","zh":"他的姐姐现在将他蒙上眼睛","en":"His sister will put this cloth over his eyes","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-39-011","lineIndex":11,"speaker":"","original":"Blind für gefahren","ipa":"/blɪnt fyɾ ɡəfɑrən/","zh":"让他看不见危险","en":"Blind to danger","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-39-012","lineIndex":12,"speaker":"","original":"Schließ dein Herz in Eisen ein","ipa":"/ʃlis daɪn hɛɾts ɪn aɪzən aɪn/","zh":"冰封你的心","en":"Lock your heart in iron","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-39-013","lineIndex":13,"speaker":"","original":"Wolfgang?","ipa":"/vɔlfɡaŋ/","zh":"沃尔夫冈？","en":"Wolfgang?","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-39-014","lineIndex":14,"speaker":"","original":"Ohne Freunde ist das Leben","ipa":"/onə frɔøndə ɪst das lebən/","zh":"没有朋友的生活","en":"Life is without friends","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-39-015","lineIndex":15,"speaker":"","original":"öd und freilich, unverzeihlich","ipa":"/øt ʊnt fraɪlɪç ʊnfɛɾtsaɪlɪç/","zh":"无趣且难以忍受","en":"dull and, of course, unforgivable","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-39-016","lineIndex":16,"speaker":"","original":"Leider ist er erwachsen.","ipa":"/laɪdɜ ɪst ɛɾ ɛɾvaxzən/","zh":"可惜的是他已经长大了","en":"Unfortunately he is an adult.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-39-017","lineIndex":17,"speaker":"","original":"Alle Wunder sind vorüber.","ipa":"/alə vʊndɜ zɪnt forybɜ/","zh":"一切奇迹已是过去","en":"All miracles are over.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-39-018","lineIndex":18,"speaker":"","original":"Hilflos ohne mich!","ipa":"/hɪlflos onə mɪç/","zh":"没有我你无依无靠","en":"Helpless without me!","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-39-019","lineIndex":19,"speaker":"","original":"Ein Künstler muss streng sein mit sich.","ipa":"/aɪn kʏnstlɜ mʊs ʃtɾɛŋ zaɪn mɪt zɪç/","zh":"艺术家就该对自己吹毛求疵","en":"An artist has to be strict with himself.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-39-020","lineIndex":20,"speaker":"","original":"Alle böse, böse. Böse Wölfe. Schlangen. (Armes Bürschlein!)","ipa":"/alə bøzə bøzə bøzə vœlfə ʃlaŋən aɾməs bʏɾʃlaɪn/","zh":"都是魔鬼，魔鬼，魔鬼，恶狼，毒蛇！（可怜的男孩！）","en":"All evil, evil. Bad wolves. Snakes. (Poor little boy!)","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-39-021","lineIndex":21,"speaker":"","original":"Wolfgang!? Was ist mit dir los?","ipa":"/vɔlfɡaŋ vas ɪst mɪt diɾ los/","zh":"沃尔夫冈？！你怎么了？","en":"Wolfgang!? What's wrong with you?","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-39-022","lineIndex":22,"speaker":"","original":"Alles ist verloren, wenn wir uns verlieren. (Dummes Menschlein!)","ipa":"/aləs ɪst fɛɾlorən vɛn viɾ ʊns fɛɾlirən dʊməs mɛnʃlaɪn/","zh":"如果我们失去自我，那就一无所有（愚蠢的小家伙！）","en":"Everything is lost if we lose each other. (Stupid little human!)","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-39-023","lineIndex":23,"speaker":"","original":"Was redest du für Zeug?","ipa":"/vas redəst du fyɾ tsɔøk/","zh":"你在说什么？","en":"What kind of stuff are you talking about?","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-39-024","lineIndex":24,"speaker":"","original":"Du bist ungeschickt und kindlich.","ipa":"/du bɪst ʊnɡəʃɪkt ʊnt kɪntlɪç/","zh":"你太天真幼稚","en":"You are clumsy and childlike.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-39-025","lineIndex":25,"speaker":"","original":"Du wirst mich zum Wahnsinn treiben. Ich mit dich (All dein Streben ist nur peinlich.)","ipa":"/du vɪɾst mɪç tsʊm vɑnzɪn tɾaɪbən ɪç mɪt dɪç al daɪn ʃtɾebən ɪst nuɾ paɪnlɪç/","zh":"你会让我发狂我求你了！（真让人瞧不起）","en":"You're going to drive me crazy. Me with you (All your striving is just embarrassing.)","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-39-026","lineIndex":26,"speaker":"","original":"Hör auf damit!","ipa":"/høɾ aʊf dɑmɪt/","zh":"快停下！","en":"Stop it!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-39-027-a","lineIndex":27,"speaker":"","original":"Unsere Familie zerbricht.","ipa":"/ʊnzrə familɪə tsɛɾbɾɪçt das ɛɾlaʊp ɪç ɛɾlaʊp ɪç nɪçt du maxst miɾ aŋst høɾ aʊf du bɪst zo ɛɾbɛɾmlɪç klaɪnlɪç/","zh":"我们的家庭要破裂了。","en":"Our family is falling apart. I allow that, I don't allow it. You scare me. Stop it! (You're so pathetically petty.)","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-39-027-b","lineIndex":28,"speaker":"","original":"Das erlaub' ich, erlaub' ich nicht.","ipa":"/ʊnzrə familɪə tsɛɾbɾɪçt das ɛɾlaʊp ɪç ɛɾlaʊp ɪç nɪçt du maxst miɾ aŋst høɾ aʊf du bɪst zo ɛɾbɛɾmlɪç klaɪnlɪç/","zh":"我默许了，不我没有……","en":"Our family is falling apart. I allow that, I don't allow it. You scare me. Stop it! (You're so pathetically petty.)","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-39-027-c","lineIndex":29,"speaker":"","original":"Du machst mir Angst. Hör auf!","ipa":"/ʊnzrə familɪə tsɛɾbɾɪçt das ɛɾlaʊp ɪç ɛɾlaʊp ɪç nɪçt du maxst miɾ aŋst høɾ aʊf du bɪst zo ɛɾbɛɾmlɪç klaɪnlɪç/","zh":"你吓到我了，停！","en":"Our family is falling apart. I allow that, I don't allow it. You scare me. Stop it! (You're so pathetically petty.)","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-39-027-d","lineIndex":30,"speaker":"","original":"(Du bist so erbärmlich kleinlich.)","ipa":"/ʊnzrə familɪə tsɛɾbɾɪçt das ɛɾlaʊp ɪç ɛɾlaʊp ɪç nɪçt du maxst miɾ aŋst høɾ aʊf du bɪst zo ɛɾbɛɾmlɪç klaɪnlɪç/","zh":"（你这么软弱、懒惰又肤浅）","en":"Our family is falling apart. I allow that, I don't allow it. You scare me. Stop it! (You're so pathetically petty.)","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-39-028","lineIndex":31,"speaker":"","original":"Alle böse, böse. Böse Wölfe. Wölfe. Schlangen.","ipa":"/alə bøzə bøzə bøzə vœlfə vœlfə ʃlaŋən/","zh":"都是魔鬼，魔鬼，魔鬼，恶狼，毒蛇…","en":"All evil, evil. Bad wolves. Wolves. Snakes.","note":"","sourceLineIndex":28}],"sourceOrder":39,"displayOrder":35},{"order":40,"id":"40-gold-von-den-sternen-reprise","title":"Gold Von Den Sternen (Reprise)","titleZh":"来自群星的黄金（重唱）","lines":[{"id":"mozart-das-musical-40-001","lineIndex":1,"speaker":"","original":"Wachsen heißt, sich nicht dem Schmerz zu ergeben.","ipa":"/vaxzən haɪst zɪç nɪçt dem ʃmɛɾts tsu ɛɾɡebən/","zh":"成长是不向痛苦屈服。","en":"Growing means not giving in to pain.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-40-002","lineIndex":2,"speaker":"","original":"Wachsen heißt, sich nach einem Sturz zu erheben.","ipa":"/vaxzən haɪst zɪç nɑx aɪnəm ʃtʊɐts tsu ɛɾhebən/","zh":"成长是跌倒后再爬起.","en":"Growing means rising up after a fall.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-40-003","lineIndex":3,"speaker":"","original":"Künstler sein heißt sich selbst überwinden.","ipa":"/kʏnstlɜ zaɪn haɪst zɪç zɛlpst ybɜvɪndən/","zh":"艺术家是能自我战胜。","en":"Being an artist means overcoming yourself.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-40-004","lineIndex":4,"speaker":"","original":"Künstler sein heißt sich an gar nichts zu binden.","ipa":"/kʏnstlɜ zaɪn haɪst zɪç an ɡɑɾ nɪçts tsu bɪndən/","zh":"艺术家是要抛却束缚。","en":"Being an artist means not being tied to anything.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-40-005","lineIndex":5,"speaker":"","original":"Weit von hier fällt Gold von den Sternen.","ipa":"/vaɪt fɔn hiɾ fɛlt ɡɔlt fɔn den ʃtɛɾnən/","zh":"遥远的彼岸，会有星星上的金子落下。","en":"Weit von hier fällt Gold von den Sternen.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-40-006","lineIndex":6,"speaker":"","original":"Du kannst es finden da draußen, wo noch keiner war.","ipa":"/duː kˌanst ɛs fˈɪndən dɑː dɾˈaʊsən vˌoː nɔx kˈaɪnɜ vɑːɾ/","zh":"你若想寻得它们便要到达那还未有人涉足的远方。","en":"Du kannst es finden da draußen, wo noch keiner war.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-40-008","lineIndex":7,"speaker":"","original":"Sein heißt Werden, Leben heißt Lernen.","ipa":"/zaɪn haɪst vɛɾdən lebən haɪst lɛɾnən/","zh":"想生存，须成长，欲生活，须学习","en":"Sein heißt Werden, Leben heißt Lernen.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-40-009","lineIndex":8,"speaker":"","original":"Wenn du das Gold von den Sternen suchst musst du allein hinaus in die Gefahr.","ipa":"/vˌɛn duː das ɡˈɔlt fɔn deːn ʃtˈɛɾnən zˈuːxst mˈʊst duː alˈaɪn hɪnˈaʊs ɪn diː ɡəfˈɑːɾ/","zh":"若你想寻得星星上的金子你必须独自走出家门，向危险迈步。","en":"Wenn du das Gold von den Sternen suchst you have to go out into danger alone.","note":"","sourceLineIndex":9}],"sourceOrder":40,"displayOrder":36},{"order":41,"id":"41-bettelbriefe","title":"Bettelbriefe","titleZh":"乞求信","lines":[{"id":"mozart-das-musical-41-001","lineIndex":1,"speaker":"","original":"Du musst uns Geld geben, Wolfgang!","ipa":"/du mʊst ʊns ɡɛlt ɡebən vɔlfɡaŋ/","zh":"你得给我们钱，沃尔夫冈","en":"You have to give us money, Wolfgang!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-41-002","lineIndex":2,"speaker":"","original":"Spuck was aus!","ipa":"/ʃpʊk vas aʊs/","zh":"拿点什么出来！","en":"Spit something out!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-41-003","lineIndex":3,"speaker":"","original":"Ich hab' leider nur...","ipa":"/ɪç hɑp laɪdɜ nuɾ/","zh":"我不走运，只有......","en":"Unfortunately I only have...","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-41-004","lineIndex":4,"speaker":"","original":"Schulden","ipa":"/ʃʊldən/","zh":"一屁股债","en":"Debts","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-41-005","lineIndex":5,"speaker":"","original":"Red dich nicht raus!","ipa":"/ret dɪç nɪçt raʊs/","zh":"可别说了！","en":"Don't talk yourself out of it!","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-41-006","lineIndex":6,"speaker":"","original":"Leih dir was! Wozu hast du Freunde!","ipa":"/laɪ diɾ vas votsu hast du frɔøndə/","zh":"借点去啊！你交那帮朋友是干嘛的！","en":"Borrow something! Why do you have friends!","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-41-007","lineIndex":7,"speaker":"","original":"Die hab ich schon alle angepumpt","ipa":"/di hɑp ɪç ʃon alə anɡəpʊmpt/","zh":"可是我早都跟他们借过钱了","en":"I've already pumped them all","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-41-008","lineIndex":8,"speaker":"","original":"Wo viel ist, ist auch mehr!","ipa":"/vo fil ɪst ɪst aʊx meɾ/","zh":"他们有钱，还能借更多钱","en":"Where there's a lot, there's more!","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-41-009","lineIndex":9,"speaker":"","original":"Lasst ihn in Ruh!","ipa":"/last in ɪn ru/","zh":"让他安静一下","en":"Leave him alone!","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-41-010","lineIndex":10,"speaker":"","original":"Da! Feder und Papier","ipa":"/dɑ fedɜ ʊnt papiɾ/","zh":"来！羽毛笔和纸","en":"There! Pen and paper","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-41-011","lineIndex":11,"speaker":"","original":"Nicht schon wieder ein Bettelbrief","ipa":"/nɪçt ʃon vidɜ aɪn bɛtəlbɾif/","zh":"别又是要写一封讨钱的信","en":"Not another begging letter","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-41-012","lineIndex":12,"speaker":"","original":"Zier dich nicht","ipa":"/tsiɾ dɪç nɪçt/","zh":"你可别客气","en":"Don't be shy","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-41-013","lineIndex":13,"speaker":"","original":"Schreib, Meine Frau ist totkrank","ipa":"/ʃraɪp maɪnə fraʊ ɪst tɔtkɾaŋk/","zh":"就写：“我的妻子已经病入膏肓","en":"Write, My wife is sick to death","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-41-014","lineIndex":14,"speaker":"","original":"Wir leben in Jammer","ipa":"/viɾ lebən ɪn jamɜ/","zh":"我们的生活困苦不堪","en":"We live in misery","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-41-015","lineIndex":15,"speaker":"","original":"Mein Schicksal liegt in Ihrer Hand","ipa":"/maɪn ʃɪkzɑl likt ɪn irɜ hant/","zh":"我的命运就掌握在您的手中......”","en":"My fate is in your hands","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-41-016","lineIndex":16,"speaker":"","original":"Erwähn auch deine Tränen","ipa":"/ɛɾvɛn aʊx daɪnə tɾɛnən/","zh":"再加点眼泪","en":"Also mention your tears","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-41-017","lineIndex":17,"speaker":"","original":"Mit tränenden Augen flehe ich Sie um weitere Unterstützung an","ipa":"/mɪt tɾɛnəndən aʊɡən fleə ɪç zi ʊm vaɪtərə ʊntɜʃtʏtsʊŋ an/","zh":"“......我眼含泪水，恳求您给予我更多资助。","en":"With watery eyes I beg you for further support","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-41-018","lineIndex":18,"speaker":"","original":"Wenn Sie uns nicht noch einmal fünfhundert Gulden leihen","ipa":"/vɛn zi ʊns nɪçt nɔx aɪnmɑl fʏnfhʊndɜt ɡʊldən laɪən/","zh":"若您再不借给我们500古尔登，\"","en":"If you don't lend us another five hundred guilders","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-41-019","lineIndex":19,"speaker":"","original":"Bleibt mir kein anderer Ausweg als meinem Leben ein Ende zu setzen...","ipa":"/blaɪpt miɾ kaɪn andərɜ aʊsvek als maɪnəm lebən aɪn ɛndə tsu zɛtsən/","zh":"那我也没有其它出路了，只能结束我的生命......\"","en":"I have no other way out than to end my life...","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-41-020","lineIndex":20,"speaker":"","original":"Nein!","ipa":"/naɪn/","zh":"不！","en":"No!","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-41-021","lineIndex":21,"speaker":"","original":"Heut macht er es uns schwer","ipa":"/hɔøt maxt ɛɾ ɛs ʊns ʃveɾ/","zh":"现在他倒是对我们狠起来了","en":"Today he's making it difficult for us","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-41-022","lineIndex":22,"speaker":"","original":"Nein, ich werde nicht mehr lügen für euch","ipa":"/naɪn ɪç vɛɾdə nɪçt meɾ lyɡən fyɾ ɔøç/","zh":"不，我不会在为了你们而谎话连篇了","en":"No, I won't lie for you anymore","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-41-023","lineIndex":23,"speaker":"","original":"Ich lass mich nicht mehr benutzen!","ipa":"/ɪç las mɪç nɪçt meɾ bənʊtsən/","zh":"我再也不会被你们利用了！","en":"I won't let myself be used anymore!","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-41-024","lineIndex":24,"speaker":"","original":"Ich halt nicht mehr still","ipa":"/ɪç halt nɪçt meɾ ʃtɪl/","zh":"我再也无法忍受这样","en":"I won't hold still anymore","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-41-025","lineIndex":25,"speaker":"","original":"Ich tu nicht mehr, was ich nicht will","ipa":"/ɪç tu nɪçt meɾ vas ɪç nɪçt vɪl/","zh":"我再也不会违背我的原则了","en":"I won't do what I don't want to do anymore","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-41-026","lineIndex":26,"speaker":"","original":"Constanze, komm!","ipa":"/kɔnstantsə kɔm/","zh":"康斯坦丝，过来！","en":"Constanze, come on!","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-41-027","lineIndex":27,"speaker":"","original":"Wir gehn","ipa":"/viɾ ɡen/","zh":"我们走","en":"We're leaving","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-41-028","lineIndex":28,"speaker":"","original":"Dein Mann ist schlecht zu dir","ipa":"/daɪn man ɪst ʃlɛçt tsu diɾ/","zh":"你的丈夫对你这么差","en":"Your husband is bad to you","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-41-029","lineIndex":29,"speaker":"","original":"Er hat uns nicht verdient","ipa":"/ɛɾ hat ʊns nɪçt fɛɾdint/","zh":"他配不上我们","en":"He doesn't deserve us","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-41-030","lineIndex":30,"speaker":"","original":"Dein Platz ist nicht mehr hier","ipa":"/daɪn plats ɪst nɪçt meɾ hiɾ/","zh":"你可别再跟着他了","en":"Your place is no longer here","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-41-031","lineIndex":31,"speaker":"","original":"Bitte bleib","ipa":"/bɪtə blaɪp/","zh":"请不要走","en":"Please stay","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-41-032","lineIndex":32,"speaker":"","original":"Er braucht mich","ipa":"/ɛɾ bɾaʊxt mɪç/","zh":"他需要我","en":"He needs me","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-41-033","lineIndex":33,"speaker":"","original":"Allerdings","ipa":"/alɜdɪŋs/","zh":"那当然了","en":"However","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-41-034","lineIndex":34,"speaker":"","original":"Er ist nicht ganz bei Trost","ipa":"/ɛɾ ɪst nɪçt ɡants baɪ tɾost/","zh":"他简直要疯了","en":"He's not entirely in his right mind","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-41-035","lineIndex":35,"speaker":"","original":"Er säuft","ipa":"/ɛɾ zɔøft/","zh":"他酗酒","en":"He drinks","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-41-036","lineIndex":36,"speaker":"","original":"Er spinnt","ipa":"/ɛɾ ʃpɪnt/","zh":"他胡扯","en":"He's crazy","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-41-037","lineIndex":37,"speaker":"","original":"Er komponiert","ipa":"/ɛɾ kɔmponiɾt/","zh":"他写曲子","en":"He's composing","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-41-038","lineIndex":38,"speaker":"","original":"Wir woll'n Geld","ipa":"/viɾ vɔln ɡɛlt/","zh":"而我们要的是钱","en":"We want money","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-41-039","lineIndex":39,"speaker":"","original":"Lasst ihn","ipa":"/last in/","zh":"放过他吧","en":"Leave him","note":"","sourceLineIndex":39}],"sourceOrder":41,"displayOrder":37},{"order":42,"id":"42-papa-ist-tot","title":"Papa Ist Tot","titleZh":"爸爸死了","lines":[{"id":"mozart-das-musical-42-001","lineIndex":1,"speaker":"","original":"Ich bin nicht da.","ipa":"/ɪç bɪn nɪçt dɑ/","zh":"我不能在这里呆着。","en":"I'm not here.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-42-002","lineIndex":2,"speaker":"","original":"Ich muss arbeiten.","ipa":"/ɪç mʊs aɾbaɪtən/","zh":"我必须工作（作曲）。","en":"I have to work.","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-42-003","lineIndex":3,"speaker":"","original":"Ach-, die Frau Schwester.","ipa":"/ax di fraʊ ʃvɛstɜ/","zh":"啊~，最贵的姐姐","en":"Oh, the woman sister.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-42-004","lineIndex":4,"speaker":"","original":"Welche unverhoffte Ehre.","ipa":"/vɛlçə ʊnfɛɾhɔftə erə/","zh":"什么风把您给吹来了。","en":"What an unexpected honor.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-42-005","lineIndex":5,"speaker":"","original":"Nannerl?!","ipa":"/nanɜl/","zh":"南内尔？！","en":"Nannerl?!","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-42-006","lineIndex":6,"speaker":"","original":"Wolfgang, Papa ist tot.","ipa":"/vɔlfɡaŋ pɑpɑ ɪst tot/","zh":"沃尔夫冈，父亲去世了。","en":"Wolfgang, dad is dead.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-42-007","lineIndex":7,"speaker":"Constance","original":"Er starb, ohne dich zu verzieh'n.","ipa":"/kɒnstəns ɛɾ ʃtaɾp onə dɪç tsu fɛɾtsin/","zh":"康斯坦丝：他至死也没有原谅你。","en":"He died without forgiving you.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-42-008","lineIndex":8,"speaker":"Nannerl","original":"Warum hast du ihm wehgetan?","ipa":"/nanɜl vɑrʊm hast du im veɡetɑn/","zh":"南内尔：你为什么要伤害他？","en":"Why did you hurt him?","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-42-009","lineIndex":9,"speaker":"Cecilia/ Aloysia/ Josephine","original":"Ich hab'den Mann nie gemocht.","ipa":"/kekiliɑ ɑlɔøziɑ jozefinə ɪç hɑbdən man ni ɡəmɔxt/","zh":"采齐莉娅/阿洛伊西娅/约瑟芬：我从来都没喜欢过那个男人。","en":"Cecilia/ Aloysia/ Josephine: I never liked the man.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-42-010","lineIndex":10,"speaker":"","original":"Er war ein Spiesser.","ipa":"/ɛɾ vɑɾ aɪn ʃpisɜ/","zh":"他就是个俗人。","en":"He was a philistine.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-42-011","lineIndex":11,"speaker":"Constance","original":"Doch trotzdem darfst du nicht bitter sein.","ipa":"/kɒnstəns dɔx tɾɔtsdem daɾfst du nɪçt bɪtɜ zaɪn/","zh":"康斯坦丝：但尽管如此，你也不该痛苦。","en":"But you still can't be bitter.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-42-012","lineIndex":12,"speaker":"Nannerl","original":"Er gab dir, was ein Mensch nur geben kann.","ipa":"/nanɜl ɛɾ ɡɑp diɾ vas aɪn mɛnʃ nuɾ ɡebən kan/","zh":"南内尔：他尽他所能给了你一切。","en":"He gave you what a human being can only give.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-42-013","lineIndex":13,"speaker":"Aloysia","original":"Doch ich bin ihm dankbar","ipa":"/ɑlɔøziɑ dɔx ɪç bɪn im daŋkbɑɾ/","zh":"阿洛伊西娅：但我感谢他","en":"But I'm grateful to him","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-42-014","lineIndex":14,"speaker":"Constance","original":"Jeder muss seinen Weg geh'n","ipa":"/kɒnstəns jedɜ mʊs zaɪnən vek ɡen/","zh":"康斯坦丝：每个人都必须走自己的路","en":"Everyone has to go their own way","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-42-015","lineIndex":15,"speaker":"Nannerl","original":"Und zum Dank hast du ihn","ipa":"/nanɜl ʊnt tsʊm daŋk hast du in/","zh":"南内尔：感谢拥有他","en":"And you have him to thank you for","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-42-016","lineIndex":16,"speaker":"Cecilia","original":"Das Erfreuliche am Sterben ist","ipa":"/kekiliɑ das ɛɾfrɔølɪçə am ʃtɛɾbən ɪst/","zh":"采齐莉娅：死亡的魅力在于","en":"The pleasant thing about dying is","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-42-017","lineIndex":17,"speaker":"Sophie/ Josephine","original":"Dein Vater verstand keinen Spaß","ipa":"/zofi jozefinə daɪn fɑtɜ fɛɾʃtant kaɪnən ʃpɑs/","zh":"索菲/约瑟芬：你的父亲不懂乐趣","en":"Your father didn't take a joke","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-42-018","lineIndex":18,"speaker":"Constance","original":"und tun, was er tun muss.","ipa":"/kɒnstəns ʊnt tun vas ɛɾ tun mʊs/","zh":"康斯坦丝：做该做的事。","en":"and do what he has to do.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-42-019","lineIndex":19,"speaker":"Nannerl","original":"hast du mich verraten.","ipa":"/nanɜl hast du mɪç fɛɾrɑtən/","zh":"南内尔：你背叛了我。","en":"have you betrayed me.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-42-020","lineIndex":20,"speaker":"Cecilia","original":"dass fast immer was zu erben ist.","ipa":"/kekiliɑ das fast ɪmɜ vas tsu ɛɾbən ɪst/","zh":"采齐莉娅：继承财产继承的权利。","en":"that there is almost always something to inherit.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-42-021","lineIndex":21,"speaker":"Sophie/ Josephine","original":"Immer war er bös und streng.","ipa":"/zofi jozefinə ɪmɜ vɑɾ ɛɾ bøs ʊnt ʃtɾɛŋ/","zh":"索菲/约瑟芬：始终冷酷严厉。","en":"He was always mean and strict.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-42-022","lineIndex":22,"speaker":"Aloysia","original":"dass ich nicht Frau von Mozart bin.","ipa":"/ɑlɔøziɑ das ɪç nɪçt fraʊ fɔn motsaɾt bɪn/","zh":"阿洛伊西娅：让我不是莫扎特的妻子。","en":"that I am not Mozart's wife.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-42-023","lineIndex":23,"speaker":"Constance","original":"Seinen Vater verlier'n","ipa":"/kɒnstəns zaɪnən fɑtɜ fɛɾliɾn/","zh":"康斯坦丝：他父亲的死","en":"Losing his father","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-42-024","lineIndex":24,"speaker":"Nannerl","original":"Ich werd' dir","ipa":"/nanɜl ɪç veɾt diɾ/","zh":"南内尔：你永远也别想","en":"I'll tell you","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-42-025","lineIndex":25,"speaker":"Cecilia/ Josephine","original":"Grade jetzt! Ich geb' zu","ipa":"/kekiliɑ jozefinə ɡɾɑdə jɛtst ɪç ɡep tsu/","zh":"采齐莉娅/约瑟芬：就是现在！我承认","en":"Right now! I admit","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-42-026","lineIndex":26,"speaker":"Sophie","original":"Nur weil er jetzt tot ist","ipa":"/zofi nuɾ vaɪl ɛɾ jɛtst tot ɪst/","zh":"索菲：他现在死了","en":"Just because he's dead now","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-42-027","lineIndex":27,"speaker":"Constance","original":"heißt endlich erwachsen sein.","ipa":"/kɒnstəns haɪst ɛntlɪç ɛɾvaxzən zaɪn/","zh":"康斯坦丝：意味着它终于成长了。","en":"It means finally being an adult.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-42-028","lineIndex":28,"speaker":"Nannerl","original":"nie verzeih'n","ipa":"/nanɜl ni fɛɾtsaɪhn/","zh":"南内尔：得到我的宽恕。","en":"never forgive","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-42-029","lineIndex":29,"speaker":"Cecilia","original":"dass ich vor Rührung wein.","ipa":"/kekiliɑ das ɪç fɔɾ ryrʊŋ vaɪn/","zh":"采齐莉娅：我感慨万千。","en":"that I cry with emotion.","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-42-030","lineIndex":30,"speaker":"Sophie/ Josephine","original":"musst du doch nicht traurig sein.","ipa":"/zofi jozefinə mʊst du dɔx nɪçt tɾaʊrɪç zaɪn/","zh":"索菲/约瑟芬：你不该为此悲伤。","en":"You don't have to be sad.","note":"","sourceLineIndex":30}],"sourceOrder":42,"displayOrder":38},{"order":43,"id":"43-schliess-dein-herz-in-eisen-ein-reprise","title":"Schliess Dein Herz In Eisen Ein (Reprise)","titleZh":"紧锁心扉，坚如磐石（重唱）","lines":[{"id":"mozart-das-musical-43-001","lineIndex":1,"speaker":"","original":"Vater ich hoffte dir zu beweisen.","ipa":"/fˈɑːtɜ ɪç hˈɔftə diːɾ tsuː bəvˈaɪzən/","zh":"父亲，我曾期望向你去证明","en":"Father I hoped to prove to you.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-43-003","lineIndex":2,"speaker":"","original":"Ich bin deine Liebe wert.","ipa":"/ɪç bɪn daɪnə libə vɛɾt/","zh":"你对我的爱没有白费","en":"I am worth your love.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-43-004","lineIndex":3,"speaker":"","original":"Doch unversöhnlich hast die Hoffnung die es noch gab zerstört.","ipa":"/dɔx ˈʊnfɛɾzˌøːnlɪç hast diː hˈɔfnʊŋ diː ɛs nɔx ɡˈɑːp tsɛɾʃtˈœɾt/","zh":"可我们的矛盾无法调和你将希望亲手摧毁","en":"But unforgivingly you destroyed the hope that still existed.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-43-007","lineIndex":4,"speaker":"","original":"Kalt wie ein Fremde hast du mich verlassen.","ipa":"/kˈalt viː aɪn frˈɛmdə hast duː mɪç fɛɾlˈasən/","zh":"形同陌路你弃我于不顾","en":"Cold as a stranger you left me.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-43-009","lineIndex":5,"speaker":"","original":"Nicht mal ein letztes Wort.","ipa":"/nɪçt mɑl aɪn lɛtstəs vɔɾt/","zh":"临终也无片语之言","en":"Not even a last word.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-43-010","lineIndex":6,"speaker":"","original":"Schliess dein Herz in Eisen ein.","ipa":"/ʃlis daɪn hɛɾts ɪn aɪzən aɪn/","zh":"紧缩心扉，坚如铁石","en":"Lock your heart in iron.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-43-011","lineIndex":7,"speaker":"","original":"Es ist besser hart zu sein.","ipa":"/ɛsɪst bɛsɜ haɾt tsu zaɪn/","zh":"学会冷酷而坚强","en":"It's better to be tough.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-43-012","lineIndex":8,"speaker":"","original":"Hast du oft gesagt und ich wollte dir nicht glauben.","ipa":"/hast duː ˈɔft ɡəzˈɑːɡt ʊnt ɪç vɔltə diːɾ nˈɪçt ɡlˈaʊbən/","zh":"你常苦心告诫我却充耳不闻","en":"You often said and I didn't want to believe you.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-43-014","lineIndex":9,"speaker":"","original":"Du hast Recht gehabt ich weiß.","ipa":"/duː hast rˈɛçt ɡəhˈɑːpt ɪç vˈaɪs/","zh":"你的话句句在理这我清楚","en":"You were right I know.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-43-016","lineIndex":10,"speaker":"","original":"Alles kostet einen Preis.","ipa":"/aləs kɔstət aɪnən pɾaɪs/","zh":"天下没有免费的午餐","en":"Everything has a price.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-43-017","lineIndex":11,"speaker":"","original":"Gottes Wunder gibt es nicht umsonst.","ipa":"/ɡɔtəs vʊndɜ ɡipt ɛs nɪçt ʊmzɔnst/","zh":"上帝的奇迹不会凭空降临","en":"God's miracles don't come for free.","note":"","sourceLineIndex":17}],"sourceOrder":43,"displayOrder":39},{"order":45,"id":"45-irgendwo-wird-immer-getanzt-reprise","title":"Irgendwo Wird Immer Getanzt (Reprise)","titleZh":"总有某处在起舞（重唱）","lines":[{"id":"mozart-das-musical-45-001","lineIndex":1,"speaker":"","original":"Constanze!?","ipa":"/kɔnstantsə/","zh":"康斯坦茨？！","en":"Constanze!?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-45-002","lineIndex":2,"speaker":"","original":"Hast du vergessen, dass wir nach Baden reisen wollten?","ipa":"/hast du fɛɾɡɛsən das viɾ nɑx bɑdən raɪzən vɔltən/","zh":"你已经忘了我们要去巴登郊游了吗？","en":"Did you forget that we wanted to travel to Baden?","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-45-003","lineIndex":3,"speaker":"","original":"Ach, ja… wir wollten einen Familienausflug machen.","ipa":"/ax jɑ viɾ vɔltən aɪnən familɪənaʊsfluk maxən/","zh":"啊对……我们全家要一起去郊游","en":"Oh, yes… we wanted to go on a family trip.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-45-004","lineIndex":4,"speaker":"","original":"Aber… das geht leider nicht.","ipa":"/ɑbɜ das ɡet laɪdɜ nɪçt/","zh":"但是……不行了","en":"But… unfortunately that doesn't work.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-45-005","lineIndex":5,"speaker":"","original":"Ich kann nicht fort.","ipa":"/ɪç kan nɪçt fɔɾt/","zh":"我去不了","en":"I can't leave.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-45-006","lineIndex":6,"speaker":"","original":"Ich muss eine Oper komponieren.","ipa":"/ɪç mʊs aɪnə opɜ kɔmponirən/","zh":"我得为一部歌剧谱曲","en":"I have to compose an opera.","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-45-007","lineIndex":7,"speaker":"","original":"Also, tust du wieder nicht, was du versprochen hast.","ipa":"/alzo tʊst du vidɜ nɪçt vas du fɛɾʃpɾɔxən hast/","zh":"哦，本来答应得好好的事儿你又变卦","en":"So you're not doing what you promised again.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-45-008","lineIndex":8,"speaker":"","original":"Wie dumm war ich doch, mich darauf zu freuen.","ipa":"/vi dʊm vɑɾ ɪç dɔx mɪç dɑraʊf tsu frɔøən/","zh":"我还满心期待简直是太蠢","en":"How stupid I was to look forward to this.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-45-009","lineIndex":9,"speaker":"","original":"Vor lauter Warten hab ich meine beste Zeit verpasst.","ipa":"/fɔɾ laʊtɜ vaɾtən hɑp ɪç maɪnə bɛstə tsaɪt fɛɾpast/","zh":"在等待中我把最好的时光都消磨殆尽","en":"I missed my best time because of all the waiting.","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-45-010","lineIndex":10,"speaker":"","original":"Immer wenn ich glaub' was du versprichst, muss ich es bereuen.","ipa":"/ɪmɜ vɛn ɪç ɡlaʊp vas du fɛɾʃpɾɪkst mʊs ɪç ɛs bərɔøən/","zh":"每次我相信你会信守承诺，最后都要失望","en":"Whenever I believe what you promise, I have to regret it.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-45-011","lineIndex":11,"speaker":"","original":"Doch irgendwo wird immer getanzt.","ipa":"/dɔx ɪɾɡɛndvo vɪɾt ɪmɜ ɡətantst/","zh":"但无论何地都能尽情起舞","en":"But there is always dancing somewhere.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-45-012","lineIndex":12,"speaker":"","original":"Und wenn du nicht mitkommst denk bloß nicht, ich weine.","ipa":"/ʊnt vˌɛn duː nˈɪçt mˈɪtkˌɔmst dˈɛŋk blˈoːs nˈɪçt ɪç vˈaɪnə/","zh":"你如果不与我同行别指望我会掩面哭泣","en":"And if you don't come with me don't think I'm crying.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-45-014","lineIndex":13,"speaker":"","original":"Wenn du keine Zeit hast dann geh ich alleine.","ipa":"/vˌɛn duː kˈaɪnə tsˈaɪt hast dan ɡˈeː ɪç alˈaɪnə/","zh":"你要是没有时间那我就自己走","en":"If you don't have time then I'll go alone.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-45-016","lineIndex":14,"speaker":"","original":"Irgendwann komm ich nach.","ipa":"/ɪɾɡəndvan kɔm ɪç nɑx/","zh":"我随后就去跟你会和","en":"I'll catch up at some point.","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-45-017","lineIndex":15,"speaker":"","original":"Irgendwann ist mir zu spät!","ipa":"/ɪɾɡəndvan ɪst miɾ tsu ʃpɛt/","zh":"“随后”对我来说已经太晚了","en":"At some point it's too late for me!","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-45-018","lineIndex":16,"speaker":"","original":"Lass sie laufen!","ipa":"/las zi laʊfən/","zh":"让她走吧！","en":"Let her go!","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-45-019","lineIndex":17,"speaker":"","original":"Wir Künstler dürfen uns nicht an Weiber binden.","ipa":"/viɾ kʏnstlɜ dʏɾfən ʊns nɪçt an vaɪbɜ bɪndən/","zh":"我们艺术家不能老是跟老婆黏黏糊糊的","en":"We artists are not allowed to tie ourselves to women.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-45-020","lineIndex":18,"speaker":"","original":"An die Arbeit, mein Lieber!","ipa":"/an di aɾbaɪt maɪn libɜ/","zh":"要投入创作，亲爱的伙计！","en":"Get to work, my dear!","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-45-021","lineIndex":19,"speaker":"","original":"Ein bisserl für's Hirn und ein bisserl für's Herz.","ipa":"/aɪn bɪsɜl fyɾs hɪɾn ʊnt aɪn bɪsɜl fyɾs hɛɾts/","zh":"有点思想深度，有点心灵震撼","en":"A little for the brain and a little for the heart.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-45-022","lineIndex":20,"speaker":"","original":"Ein bisserl Glamour und Mirakel.","ipa":"/aɪn bɪsɜl ɡlɑmuɾ ʊnt mirakəl/","zh":"加点魔力和奇迹","en":"A bit of glamor and miracle.","note":"","sourceLineIndex":22}],"sourceOrder":45,"displayOrder":40},{"order":47,"id":"47-der-einfache-weg","title":"Der Einfache Weg","titleZh":"简单的道路","lines":[{"id":"mozart-das-musical-47-001","lineIndex":1,"speaker":"Fürsten","original":"Er hat Erfolg, wie ich sehe, zumindest beim niederen Volk.","ipa":"/fyɾstən ɛɾ hat ɛɾfɔlk vi ɪç zeə tsumɪndəst baɪm nidɜən fɔlk/","zh":"主教看来，他至少在底层颇受欢迎啊","en":"PrincesHe is successful, I see, at least among the lower folk.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-47-002","lineIndex":2,"speaker":"Servant","original":"Will er sich nicht verbeugen vor dem Fürsten?","ipa":"/zɛɾvant vɪl ɛɾ zɪç nɪçt fɛɾbɔøɡən fɔɾ dem fyɾstən/","zh":"仆人见了主教大人何不行礼？","en":"ServantDoesn't he want to bow to the prince?","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-47-003","lineIndex":3,"speaker":"Mozart","original":"Wolfgang Mozart beuget sich vor keinem mehr.","ipa":"/motsaɾt vɔlfɡaŋ motsaɾt bɔøɡət zɪç fɔɾ kaɪnəm meɾ/","zh":"莫扎特沃尔夫冈·莫扎特不再向任何人卑躬屈膝","en":"Wolfgang Mozart no longer bows to anyone.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-47-004","lineIndex":4,"speaker":"","original":"Was wollen Sie von mir, Fürst Colloredo","ipa":"/vas vɔlən zi fɔn miɾ fyɾst kɔloredo/","zh":"您要我做什么，科洛雷多主教","en":"What do you want from me, Prince Colloredo","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-47-005","lineIndex":5,"speaker":"Fürsten","original":"Da dich Gott gesegnet hat Kann ich dich nicht verdammen.","ipa":"/dɑː dɪç ɡˈɔt ɡəzˈɛɡnət hat kˌan ɪç dɪç nˈɪçt fɛɾdˈamən/","zh":"主教你蒙上帝垂青，才华横溢我亦无权对你横加指责。","en":"PrincesSince God has blessed you I cannot condemn you.","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-47-007","lineIndex":6,"speaker":"","original":"Du unterhält'st den Pöbel","ipa":"/du ʊntɜhɛltst den pøbəl/","zh":"你满足于取悦下等人","en":"You're entertaining the mob","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-47-008","lineIndex":7,"speaker":"","original":"Zeit nun dass man dir hilft.","ipa":"/tsaɪt nun das man diɾ hɪlft/","zh":"现在的你需要的是贵人相助","en":"Now it's time for someone to help you.","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-47-009","lineIndex":8,"speaker":"Mozart","original":"Musik verachtet keine","ipa":"/motsaɾt muzik fɛɾaxtət kaɪnə/","zh":"莫扎特音乐不分高低贵贱","en":"MozartMusic despises no one","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-47-010","lineIndex":9,"speaker":"","original":"Ich brauche Ihre Hilfe nicht.","ipa":"/ɪç bɾaʊxə irə hɪlfə nɪçt/","zh":"我不需要您的帮助","en":"I don't need your help.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-47-011","lineIndex":10,"speaker":"Fürsten","original":"Du bist anders als and're","ipa":"/fyɾstən du bɪst andɜs als andɾə/","zh":"主教你与众不同","en":"PrincesYou are different from others","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-47-012","lineIndex":11,"speaker":"","original":"Das nehme ich in Kauf.","ipa":"/das nemə ɪç ɪn kaʊf/","zh":"这我全盘接受","en":"I accept that.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-47-013","lineIndex":12,"speaker":"","original":"Ich biet' dir einen neuen Anfang","ipa":"/ɪç bit diɾ aɪnən nɔøən anfaŋ/","zh":"我要给你一个全新的开始","en":"I offer you a new beginning","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-47-014","lineIndex":13,"speaker":"","original":"Ich nehm' dich wieder auf.","ipa":"/ɪç nem dɪç vidɜ aʊf/","zh":"你可以再次为我效劳","en":"I'll take you back.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-47-015","lineIndex":14,"speaker":"","original":"Man muss sich entscheiden","ipa":"/man mʊs zɪç ɛntʃaɪdən/","zh":"人要自己决定","en":"You have to decide","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-47-016","lineIndex":15,"speaker":"","original":"Was man tut oder lässt","ipa":"/vas man tut odɜ lɛst/","zh":"究竟何去何从","en":"What you do or don't do","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-47-017","lineIndex":16,"speaker":"","original":"Welche Maske man trägt","ipa":"/vɛlçə maskə man tɾɛkt/","zh":"以怎样的面目面对世界","en":"What mask you wear","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-47-018","lineIndex":17,"speaker":"","original":"Und wohin man gehört.","ipa":"/ʊnt vohin man ɡəhœɾt/","zh":"自己的内心又归向何处","en":"And where you belong.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-47-019","lineIndex":18,"speaker":"","original":"Man kann flieh'n oder leiden","ipa":"/man kan flin odɜ laɪdən/","zh":"无论孰去孰留","en":"You can flee or suffer","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-47-020","lineIndex":19,"speaker":"","original":"Nur eines steht fest:","ipa":"/nuɾ aɪnəs ʃtet fɛst/","zh":"有一点确凿无疑：","en":"Only one thing is certain:","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-47-021","lineIndex":20,"speaker":"","original":"Der einfache Weg ist immer verkehrt.","ipa":"/dɛɾ aɪnfaxə vek ɪst ɪmɜ fɛɾkeɾt/","zh":"平坦之路，必通向谬误","en":"The easy way is always wrong.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-47-022","lineIndex":21,"speaker":"Mozart","original":"Was mir Gott gegeben hat Ist da für alle Menschen.","ipa":"/vˈas miːɾ ɡˈɔt ɡəɡˈeːbən hat ɪst dɑː fyːɾ ˈalə mˈɛnʃən/","zh":"莫扎特上天赐予我的才华是为了所有人而存在","en":"MozartWhat God gave me Is there for everyone.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-47-024","lineIndex":22,"speaker":"","original":"Und meine Melodien","ipa":"/ʊnt maɪnə melodɪən/","zh":"我谱写的旋律","en":"And my melodies","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-47-025","lineIndex":23,"speaker":"","original":"Singt man in der ganzen Stadt.","ipa":"/zɪŋt man ɪn dɛɾ ɡantsən ʃtat/","zh":"正在全城传唱。","en":"They sing all over the city.","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-47-026","lineIndex":24,"speaker":"Fürsten","original":"Du bist zwar tief gesunken doch dein Talent ist nicht verlor'n","ipa":"/duː bɪst tsvɑːɾ tˈiːf ɡəzˈʊŋkən dɔx daɪn talˈɛnt ɪst nˈɪçt fɛɾlˈoːɾn/","zh":"主教你虽身陷困境但你的才华尚未被埋没.","en":"PrincesYou may have sunk low but your talent is not lost","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-47-028","lineIndex":25,"speaker":"Mozart","original":"Der Applaus dieser Menschen","ipa":"/motsaɾt dɛɾ aplaʊs dizɜ mɛnʃən/","zh":"莫扎特人们投来的声声喝彩","en":"MozartThe applause of these people","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-47-029","lineIndex":26,"speaker":"","original":"Bedeutet mir sehr viel","ipa":"/bədɔøtət miɾ zeɾ fil/","zh":"对我至关重要","en":"Means a lot to me","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-47-030","lineIndex":27,"speaker":"","original":"Ich brauch' keinen neuen Anfang","ipa":"/ɪç bɾaʊx kaɪnən nɔøən anfaŋ/","zh":"我不需要什么全新的开始","en":"I I don't need a new beginning","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-47-031","lineIndex":28,"speaker":"","original":"Ich bin an meinem Ziel!","ipa":"/ɪç bɪn an maɪnəm tsil/","zh":"我正迈向我的目标！","en":"I've reached my goal!","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-47-032","lineIndex":29,"speaker":"Fürsten","original":"Wahre Kunst muss vermeiden","ipa":"/fyɾstən vɑrə kʊnst mʊs fɛɾmaɪdən/","zh":"主教真正的艺术必须摒弃","en":"PrincesTrue art must avoid","note":"","sourceLineIndex":32},{"id":"mozart-das-musical-47-033","lineIndex":30,"speaker":"","original":"Was das Volk unterhält","ipa":"/vas das fɔlk ʊntɜhɛlt/","zh":"下里巴人的喜好","en":"What entertains the people","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-47-034","lineIndex":31,"speaker":"","original":"Was der Masse gehört das ist nicht mehr wert.","ipa":"/vˈas dɛɾ mˈasə ɡəhˈœɾt das ɪst nˈɪçt mˌeːɾ vˈɛɾt/","zh":"民众的品味于你无足轻重.","en":"What belongs to the masses is no longer worth it.","note":"","sourceLineIndex":34},{"id":"mozart-das-musical-47-036","lineIndex":32,"speaker":"Fürsten / Mozart","original":"Sei kein Narr Ich halt' nicht viel Regeln","ipa":"/fyɾstən zaɪ kaɪn naɾ motsaɾt ɪç halt nɪçt fil reɡəln/","zh":"别再犯傻你要明白 我并不是一个循规蹈矩的人","en":"Don't be a fool I don't keep a lot of rules","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-47-037","lineIndex":33,"speaker":"Fürsten / Mozart","original":"mach dir klar Doch eins geb ich zu","ipa":"/fyɾstən max diɾ klɑɾ motsaɾt dɔx aɪns ɡep ɪç tsu/","zh":"别再犯傻你要明白 但有件事我也同意","en":"make it clear But I admit one thing","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-47-038","lineIndex":34,"speaker":"chorus","original":"Der einfache Weg ist immer verkehrt.","ipa":"/korʊs dɛɾ aɪnfaxə vek ɪst ɪmɜ fɛɾkeɾt/","zh":"平坦之路，必通向谬误（合）","en":"chorusThe easy way is always wrong.","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-47-039","lineIndex":35,"speaker":"Fürsten","original":"Denk an deinen Vater","ipa":"/fyɾstən dɛŋk an daɪnən fɑtɜ/","zh":"主教想想你的父亲","en":"PrincesThink of your father","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-47-040","lineIndex":36,"speaker":"","original":"Er würde wollen dass du Ja sagst","ipa":"/ɛɾ vʏɾdə vɔlən das du jɑ zɑkst/","zh":"他若在世也会希望你同意","en":"He would want you to say yes","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-47-041","lineIndex":37,"speaker":"Fürsten / Mozart","original":"Denk an die Musik, Meine Antwort ist Nein!","ipa":"/fyɾstən dɛŋk an di muzik motsaɾt maɪnə antvɔɾt ɪst naɪn/","zh":"想想那些未完成的作品 我的答案是不！","en":"Think of the music, My answer is no!","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-47-042","lineIndex":38,"speaker":"Fürsten / Mozart","original":"Die ungeschrieben bleibt Ich brauch' eure Gnade nicht!","ipa":"/fyɾstən di ʊnɡəʃribən blaɪpt motsaɾt ɪç bɾaʊx ɔørə ɡənɑdə nɪçt/","zh":"若你不答应 我不需要你的怜悯！","en":"That remains unwritten I don't need your grace!","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-47-043","lineIndex":39,"speaker":"Fürsten / Mozart","original":"Wenn du nicht ja sagst Ich bin unabhängig","ipa":"/fyɾstən vɛn du nɪçt jɑ zɑkst motsaɾt ɪç bɪn ʊnaphɛŋɪç/","zh":"便将再也无法为世人所见，我不需要依靠任何人","en":"If you don't say yes I am independent","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-47-044","lineIndex":40,"speaker":"Mozart","original":"Und werde es für immer sein! Nein!","ipa":"/motsaɾt ʊnt vɛɾdə ɛs fyɾ ɪmɜ zaɪn naɪn/","zh":"莫扎特一直如此！","en":"MozartAnd will be so forever! No!","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-47-045","lineIndex":41,"speaker":"chorus","original":"Man muss sich entscheiden","ipa":"/korʊs man mʊs zɪç ɛntʃaɪdən/","zh":"合人要自己决定","en":"chorusYou have to decide","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-47-046","lineIndex":42,"speaker":"","original":"Was man tut oder lässt","ipa":"/vas man tut odɜ lɛst/","zh":"究竟何去何从","en":"What you do or don't do","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-47-047","lineIndex":43,"speaker":"Fürsten / Mozart","original":"Welche Maske man trägt Welche Last man erträgt","ipa":"/fyɾstən vɛlçə maskə man tɾɛkt motsaɾt vɛlçə last man ɛɾtɾɛkt/","zh":"以怎样的面目面对世界 要背负何等重担","en":"What mask you wear What burden you bear","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-47-048","lineIndex":44,"speaker":"Fürsten","original":"Und wohin man gehört.","ipa":"/fyɾstən ʊnt vohin man ɡəhœɾt/","zh":"主教自己的内心又归向何处","en":"PrincesAnd where you belong.","note":"","sourceLineIndex":48},{"id":"mozart-das-musical-47-049","lineIndex":45,"speaker":"chorus","original":"Man kann flieh'n oder leiden","ipa":"/korʊs man kan flin odɜ laɪdən/","zh":"合无论孰去孰留","en":"chorusYou can flee or suffer","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-47-050","lineIndex":46,"speaker":"","original":"Nur eines steht fest:","ipa":"/nuɾ aɪnəs ʃtet fɛst/","zh":"有一点确凿无疑：","en":"Only one thing is certain:","note":"","sourceLineIndex":50},{"id":"mozart-das-musical-47-051","lineIndex":47,"speaker":"Fürsten","original":"Der einfache Weg","ipa":"/fyɾstən dɛɾ aɪnfaxə vek/","zh":"主教平坦之路","en":"PrincesThe easy way","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-47-052","lineIndex":48,"speaker":"Mozart","original":"Der einfache Weg","ipa":"/motsaɾt dɛɾ aɪnfaxə vek/","zh":"莫扎特平坦之路","en":"MozartThe easy way","note":"","sourceLineIndex":52},{"id":"mozart-das-musical-47-053","lineIndex":49,"speaker":"chorus","original":"Der einfache Weg ist immer verkehrt.","ipa":"/dɛɾ ˈaɪnfˌaxə vˈeːk ɪst ˈɪmɜ fɛɾkˈeːɾt/","zh":"合平坦之路必通向谬误","en":"chorusThe easy way is always wrong.","note":"","sourceLineIndex":53},{"id":"mozart-das-musical-47-055","lineIndex":50,"speaker":"Mozart","original":"Man muss sich entscheiden","ipa":"/motsaɾt man mʊs zɪç ɛntʃaɪdən/","zh":"莫扎特人要自己决定","en":"MozartYou have to decide","note":"","sourceLineIndex":55},{"id":"mozart-das-musical-47-056","lineIndex":51,"speaker":"chorus","original":"wohin man gehört!","ipa":"/korʊs vohin man ɡəhœɾt/","zh":"合究竟归向何方！","en":"choruswhere you belong!","note":"","sourceLineIndex":56}],"sourceOrder":47,"displayOrder":41},{"order":48,"id":"48-mozart-mozart","title":"Mozart, Mozart!","titleZh":"莫扎特，莫扎特！","lines":[{"id":"mozart-das-musical-48-001","lineIndex":1,"speaker":"","original":"Wie hell und klar!","ipa":"/vi hɛl ʊnt klɑɾ/","zh":"明亮澄澈！","en":"How bright and clear!","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-48-002","lineIndex":2,"speaker":"","original":"Mozart!","ipa":"/motsaɾt/","zh":"莫扎特！","en":"Mozart!","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-48-003","lineIndex":3,"speaker":"","original":"Wie rätselhaft!","ipa":"/vi rɛtzəlhaft/","zh":"变幻莫测！","en":"How puzzling!","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-48-004","lineIndex":4,"speaker":"","original":"Mozart!","ipa":"/motsaɾt/","zh":"莫扎特！","en":"Mozart!","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-48-005","lineIndex":5,"speaker":"","original":"Wie wunderbar!","ipa":"/vi vʊndɜbɑɾ/","zh":"美妙绝伦！","en":"How wonderful!","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-48-006","lineIndex":6,"speaker":"","original":"Welch Zauberklang!","ipa":"/vɛlç tsaʊbɜklaŋ/","zh":"何等仙乐！","en":"What a magical sound!","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-48-007","lineIndex":7,"speaker":"","original":"Mozart!","ipa":"/motsaɾt/","zh":"莫扎特！","en":"Mozart!","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-48-008","lineIndex":8,"speaker":"","original":"Welch tiefes Glück!","ipa":"/vɛlç tifəs ɡlʏk/","zh":"莫大福祉！","en":"What deep happiness!","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-48-009","lineIndex":9,"speaker":"","original":"Ist er wirklich ein Mensch wie wir alle?","ipa":"/ɪst ɛɾ vɪɾklɪç aɪn mɛnʃ vi viɾ alə/","zh":"他可是我们一般的血肉之躯？","en":"Is he really human like all of us?","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-48-010","lineIndex":10,"speaker":"","original":"Woher dann die Musik?","ipa":"/voheɾ dan di muzik/","zh":"这样的天籁由何而来？","en":"Then where does the music come from?","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-48-011","lineIndex":11,"speaker":"","original":"Musik, die an die Seele rührt.","ipa":"/muzik di an di zelə ryɾt/","zh":"如此触动灵魂的音乐。","en":"Music that touches the soul.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-48-012","lineIndex":12,"speaker":"","original":"Gott gab dieser Welt","ipa":"/ɡɔt ɡɑp dizɜ vɛlt/","zh":"上帝赐给这个世界","en":"God gave this world","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-48-014","lineIndex":13,"speaker":"das Wunder Mozart","original":"Stern, der die Welt erhellt bis an den Rand der Ewigkeit.","ipa":"/ʃtˈɛɾn dɛɾ diː vˈɛlt ɛɾhˈɛlt bɪs an deːn rˈant dɛɾ ˈeːvɪçkˌaɪt/","zh":"星辰般，他照亮人间直到永恒的尽头。","en":"Star that illuminates the world to the edge of eternity.","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-48-016","lineIndex":14,"speaker":"","original":"Wie leicht und frei!","ipa":"/vi laɪçt ʊnt fraɪ/","zh":"轻快自由！","en":"How easy and free!","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-48-017","lineIndex":15,"speaker":"","original":"Ganz ohne falsches Gefühl.","ipa":"/ɡants onə falʃəs ɡəfyl/","zh":"毫无半点虚情矫饰.","en":"Without any false feeling.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-48-018","lineIndex":16,"speaker":"","original":"Wie traumhaft wahr!","ipa":"/vi tɾaʊmhaft vɑɾ/","zh":"如梦似真！","en":"How dreamily true!","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-48-019","lineIndex":17,"speaker":"","original":"Nichts auf der Erde war je so vollkommen.","ipa":"/nɪçts aʊf dɛɾ eɾdə vɑɾ je zo fɔlkɔmən/","zh":"完美无瑕，超凡脱俗。","en":"Nothing on earth has ever been so perfect.","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-48-020","lineIndex":18,"speaker":"","original":"Wie frisch und neu!","ipa":"/vi frɪʃ ʊnt nɔø/","zh":"不落窠臼！","en":"How fresh and new!","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-48-021","lineIndex":19,"speaker":"","original":"Bewegend.","ipa":"/bəveɡənt/","zh":"让人感动。","en":"Moving.","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-48-022","lineIndex":20,"speaker":"","original":"Unerklärt.","ipa":"/ʊnɛɾklɛɾt/","zh":"使人迷惑。","en":"Unexplained.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-48-023","lineIndex":21,"speaker":"","original":"Mozart! Mozart!","ipa":"/motsaɾt motsaɾt/","zh":"莫扎特！莫扎特！","en":"Mozart! Mozart!","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-48-024","lineIndex":22,"speaker":"","original":"Macht er uns gut?","ipa":"/maxt ɛɾ ʊns ɡut/","zh":"他能否让我们变好？","en":"Does he make us good?","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-48-025","lineIndex":23,"speaker":"","original":"Gibt er uns Trost im Meer der Fragen?","ipa":"/ɡipt ɛɾ ʊns tɾost ɪm meɾ dɛɾ frɑɡən/","zh":"慰藉我们脱离疑问的苦海？","en":"Does he give us comfort in the sea of ​​questions?","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-48-026","lineIndex":24,"speaker":"","original":"Gibt er uns Mut?","ipa":"/ɡipt ɛɾ ʊns mut/","zh":"给我们勇气？","en":"Does he give us courage?","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-48-027","lineIndex":25,"speaker":"","original":"Hoffnung in Zweifel und Zwang?","ipa":"/hɔfnʊŋ ɪn tsvaɪfəl ʊnt tsvaŋ/","zh":"踌躇不定时的希望？","en":"Hope in doubt and compulsion?","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-48-028","lineIndex":26,"speaker":"","original":"Oder lässt er uns erst richtig fühlen wie krank die Erde ist,...","ipa":"/ˌoːdɜ lˈɛst ɛɾ ʊns ˈeːɾst rˈɪçtɪç fˈyːlən viː kɾˈaŋk diː ˈeːɾdə ɪst/","zh":"或者他让我们开始明白这世间是何等病态，...","en":"Or does he let us really feel how sick the earth is,...","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-48-030","lineIndex":27,"speaker":"","original":"...berührt von seinem Himmelsklang.","ipa":"/bəryɾt fɔn zaɪnəm hɪməlsklaŋ/","zh":"...而他的音乐撩动了每个人的心弦。","en":"...touched by his heavenly sound.","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-48-031","lineIndex":28,"speaker":"","original":"Gott gab dieser Welt","ipa":"/ɡɔt ɡɑp dizɜ vɛlt/","zh":"上帝赐给这个世界","en":"God gave this world","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-48-033","lineIndex":29,"speaker":"das Wunder Mozart","original":"Bis sie zu Staub zerfällt ist nichts mehr wie es vorher war.","ipa":"/bɪs ziː tsuː ʃtˈaʊp tsɛɾfˈɛlt ɪst nˈɪçts mˈeːɾ viː ɛs foːɾhˈeːɾ vɑːɾ/","zh":"直到人间灰飞烟灭都不会再有第二个他。","en":"Until it crumbles into dust nothing is the same as it was before.","note":"","sourceLineIndex":33},{"id":"mozart-das-musical-48-035","lineIndex":30,"speaker":"","original":"Was er schuf, ist ein Geschenk das uns befreit:","ipa":"/vas ɛɾ ʃuf ɪst aɪn ɡəʃɛŋk das ʊns bəfraɪt/","zh":"他创造了解救我们的礼物：","en":"What he created is a gift that sets us free:","note":"","sourceLineIndex":35},{"id":"mozart-das-musical-48-036","lineIndex":31,"speaker":"","original":"(Sein Auftrag muss göttlich sein.)","ipa":"/zaɪn aʊftɾɑk mʊs ɡœtlɪç zaɪn/","zh":"（他的使命神圣崇高）","en":"(His mission must be divine.)","note":"","sourceLineIndex":36},{"id":"mozart-das-musical-48-037","lineIndex":32,"speaker":"","original":"Süßer Schmerz und engelhafte Heiterkeit.","ipa":"/zysɜ ʃmɛɾts ʊnt ɛŋəlhaftə haɪtɜkaɪt/","zh":"甜蜜的痛苦，天使般的宁静","en":"Sweet pain and angelic joy.","note":"","sourceLineIndex":37},{"id":"mozart-das-musical-48-038","lineIndex":33,"speaker":"","original":"Doch mehr als das:","ipa":"/dɔx meɾ als das/","zh":"却又不止如此：","en":"But more than that:","note":"","sourceLineIndex":38},{"id":"mozart-das-musical-48-039","lineIndex":34,"speaker":"","original":"(Schon als Wunderkind war er dazu bestimmt, )","ipa":"/ʃon als vʊndɜkɪnt vɑɾ ɛɾ dɑtsu bəʃtɪmt/","zh":"（自他还是个神童起便注定如此）","en":"(Even as a child prodigy he was destined to be)","note":"","sourceLineIndex":39},{"id":"mozart-das-musical-48-040","lineIndex":35,"speaker":"","original":"Er macht uns groß","ipa":"/ɛɾ maxt ʊns ɡɾos/","zh":"他使我们变得强大","en":"He makes us great","note":"","sourceLineIndex":40},{"id":"mozart-das-musical-48-041","lineIndex":36,"speaker":"","original":"in seinen Tönen schwingt die Ahnung jener Wirklichkeit","ipa":"/ɪn zaɪnən tønən ʃvɪŋt di ɑnʊŋ jenɜ vɪɾklɪçkaɪt/","zh":"他的音符中融着","en":"in his tones vibrates the idea of that reality","note":"","sourceLineIndex":41},{"id":"mozart-das-musical-48-042","lineIndex":37,"speaker":"","original":"die wir nicht sehen und nicht verstehen","ipa":"/di viɾ nɪçt zeən ʊnt nɪçt fɛɾʃteən/","zh":"我们没能看见无法理解","en":"which we do not see and do not understand","note":"","sourceLineIndex":42},{"id":"mozart-das-musical-48-043","lineIndex":38,"speaker":"","original":"und die doch da ist unsichtbar.","ipa":"/ʊnt di dɔx dɑ ɪst ʊnzɪçtbɑɾ/","zh":"无从捉摸的现实世界。","en":"and that one is invisible.","note":"","sourceLineIndex":43},{"id":"mozart-das-musical-48-044","lineIndex":39,"speaker":"","original":"(zu strahlen wie ein Licht, )","ipa":"/tsu ʃtɾɑlən vi aɪn lɪçt/","zh":"（这般熠熠生辉，）","en":"(to shine like a light, )","note":"","sourceLineIndex":44},{"id":"mozart-das-musical-48-045","lineIndex":40,"speaker":"","original":"Unbegreiflich wahr.","ipa":"/ʊnbəɡɾaɪflɪç vɑɾ/","zh":"这般令人费解的真实.","en":"Incomprehensibly true.","note":"","sourceLineIndex":45},{"id":"mozart-das-musical-48-046","lineIndex":41,"speaker":"","original":"(Licht!)","ipa":"/lɪçt/","zh":"（光芒四射！）","en":"(Light!)","note":"","sourceLineIndex":46},{"id":"mozart-das-musical-48-047","lineIndex":42,"speaker":"","original":"Gott gab dieser Welt","ipa":"/ɡɔt ɡɑp dizɜ vɛlt/","zh":"上帝赐给这个世界","en":"God gave this world","note":"","sourceLineIndex":47},{"id":"mozart-das-musical-48-049","lineIndex":43,"speaker":"das Wunder Mozart","original":"Bis sie zu Staub zerfällt ist nichts mehr wie es vorher war.","ipa":"/bɪs ziː tsuː ʃtˈaʊp tsɛɾfˈɛlt ɪst nˈɪçts mˈeːɾ viː ɛs foːɾhˈeːɾ vɑːɾ/","zh":"直到人间灰飞烟灭都不会再有第二个他。","en":"Until it crumbles into dust nothing is the same as it was before.","note":"","sourceLineIndex":49},{"id":"mozart-das-musical-48-051","lineIndex":44,"speaker":"","original":"Denn Gott gab uns","ipa":"/dɛn ɡɔt ɡɑp ʊns/","zh":"因为上帝已然赐给了我们","en":"Because God gave us","note":"","sourceLineIndex":51},{"id":"mozart-das-musical-48-052","lineIndex":45,"speaker":"","original":"Mozart!","ipa":"/motsaɾt/","zh":"莫扎特！","en":"Mozart!","note":"","sourceLineIndex":52}],"sourceOrder":48,"displayOrder":42},{"order":49,"id":"49-mozarts-tod","title":"Mozarts Tod","titleZh":"莫扎特之死","lines":[{"id":"mozart-das-musical-49-001","lineIndex":1,"speaker":"","original":"Ich schmeck den Tod schon auf der Zunge.","ipa":"/ɪç ʃmˈɛk deːn tˈoːt ʃˌoːn aʊf dɛɾ tsˈʊŋə/","zh":"我已嗅到死神降临的气息","en":"I can already taste death on my tongue.","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-49-003","lineIndex":2,"speaker":"","original":"Mit mir dauert es nicht mehr lange.","ipa":"/mɪt miɾ daʊɜt ɛs nɪçt meɾ laŋə/","zh":"我已时日无多","en":"It won't be long for me.","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-49-004","lineIndex":3,"speaker":"","original":"Das Requiem an dem du schreibst ist für mich bestimmt.","ipa":"/das rˈeːkviːm an deːm duː ʃrˈaɪpst ɪst fyːɾ mɪç bəʃtˈɪmt/","zh":"你谱写的这部安魂曲其实是为我所写","en":"The requiem that you are writing is intended for me.","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-49-007","lineIndex":4,"speaker":"","original":"Nein, nein!","ipa":"/naɪn naɪn/","zh":"不，不！","en":"No, no!","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-49-008","lineIndex":5,"speaker":"","original":"Ich kann nicht mehr!","ipa":"/ɪç kan nɪçt meɾ/","zh":"我没有血可以给你了","en":"I can't take it anymore!","note":"","sourceLineIndex":8},{"id":"mozart-das-musical-49-009","lineIndex":6,"speaker":"","original":"Was willst du noch?","ipa":"/vas vɪlst du nɔx/","zh":"你还想要什么？","en":"What else do you want?","note":"","sourceLineIndex":9},{"id":"mozart-das-musical-49-010","lineIndex":7,"speaker":"","original":"Du hast erreicht was du wolltest.","ipa":"/du hast ɛɾraɪçt vas du vɔltəst/","zh":"你已经拿到你想要的了","en":"You achieved what you wanted.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-49-011","lineIndex":8,"speaker":"","original":"Gib auf.","ipa":"/ɡip aʊf/","zh":"放弃吧","en":"Give up.","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-49-012","lineIndex":9,"speaker":"","original":"Ich bin ausgeblutet.","ipa":"/ɪç bɪn aʊsɡəblutət/","zh":"我的血已经流干了","en":"I bled dry.","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-49-013","lineIndex":10,"speaker":"","original":"Du müsstest mir schon ins Herz stechen um noch einen Tropfen Blut von mir herauszuholen.","ipa":"/duː mˈʏstəst miːɾ ʃˌoːn ɪns hˈɛɾts ʃtˈɛçən ʊm nɔx ˌaɪnən tɾˈɔpfən blˈuːt fɔn miːɾ hɛrˈaʊstsuːhˌoːlən/","zh":"你大概得往我心脏上扎才能再挤出那么一两滴血来","en":"You would have to stab me in the heart to get another drop of blood out of me.","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-49-015","lineIndex":11,"speaker":"","original":"Aber das wäre mein Ende.","ipa":"/ɑbɜ das vɛrə maɪn ɛndə/","zh":"可那就是我的末日","en":"But that would be the end of me.","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-49-016","lineIndex":12,"speaker":"","original":"Und mein Ende","ipa":"/ʊnt maɪn ɛndə/","zh":"而我的末日","en":"And my end","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-49-017","lineIndex":13,"speaker":"","original":"wäre auch dein... Ende.","ipa":"/vɛrə aʊx daɪn ɛndə/","zh":"也就是你的……末日","en":"would also be your... end.","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-49-018","lineIndex":14,"speaker":"","original":"Der Prinz ist zum König geworden.","ipa":"/dɛɾ pɾɪnts ɪst tsʊm kønɪç ɡəvɔɾdən/","zh":"王子终于成为了国王","en":"The prince has become king.","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-49-019","lineIndex":15,"speaker":"","original":"Doch was bleibt mir von dem, was ich fand?","ipa":"/dɔx vas blaɪpt miɾ fɔn dem vas ɪç fant/","zh":"可我得到的一切又给我留下了什么？","en":"But what remains of what I found?","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-49-020","lineIndex":16,"speaker":"","original":"Ich holte das Gold der Sterne und bin dabei verbrannt.","ipa":"/ɪç hˈɔltə das ɡˈɔlt dɛɾ ʃtˈɛɾnə ʊnt bɪn dɑːbˈaɪ fɛɾbɾˈant/","zh":"我得到了星星上的金子却被燃烧殆尽","en":"I got the gold of the stars and got burned in the process.","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-49-022","lineIndex":17,"speaker":"","original":"Ich bin Dur und ich bin Moll.","ipa":"/ɪç bɪn duɾ ʊnt ɪç bɪn mɔl/","zh":"我是大调，是小调","en":"I am major and I am minor.","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-49-023","lineIndex":18,"speaker":"","original":"Ich bin Akkord und ich bin Melodie.","ipa":"/ɪç bɪn akɔɾt ʊnt ɪç bɪn melodi/","zh":"我是和弦，是旋律","en":"I am chord and I am melody.","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-49-024","lineIndex":19,"speaker":"","original":"Jeder Ton ein Wort und jeder Klang ein Satz mit dem ich sage, was ich fühle.","ipa":"/jˈeːdɜ tˈoːn aɪn vˈɔɾt ʊnt jˈeːdɜ klˈaŋ aɪn zˈats mɪt deːm ɪç zˈɑːɡə vˈas ɪç fˈyːlə/","zh":"一音符即一词，一音调即一句我借他们将我的心声表达","en":"Every sound is a word and every sound is a sentence with which I say what I feel.","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-49-026","lineIndex":20,"speaker":"","original":"Ich bin Takt und Pause, Dissonanz und Harmonie.","ipa":"/ɪç bɪn takt ʊnt paʊzə dɪsonants ʊnt haɾmoni/","zh":"我是节拍，是休止符，不和谐音与和声","en":"I am beat and pause, dissonance and harmony.","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-49-027","lineIndex":21,"speaker":"","original":"Ich bin Forte und Piano, Tanz und Fantasie.","ipa":"/ɪç bɪn fɔɾtə ʊnt piɑno tants ʊnt fantazi/","zh":"我是强拍，是弱拍，舞乐和狂想曲","en":"I am forte and piano, dance and fantasy.","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-49-028","lineIndex":22,"speaker":"","original":"Ich bin, ich bin Musik.","ipa":"/ɪç bɪn ɪç bɪn muzik/","zh":"我是，我就是音乐","en":"I am, I am music.","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-49-029","lineIndex":23,"speaker":"","original":"Und ich gab alles, was ich bin.","ipa":"/ʊnt ɪç ɡɑp aləs vas ɪç bɪn/","zh":"我给你了我的一切","en":"And I gave everything that I am.","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-49-030","lineIndex":24,"speaker":"","original":"Ich hab geopfert was ich hab:","ipa":"/ɪç hɑp ɡəɔpfɜt vas ɪç hɑp/","zh":"我献上了我的所有","en":"I sacrificed what I have:","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-49-031","lineIndex":25,"speaker":"","original":"Die Kindheit, die Jugend, die Schwester, den Vater Freundschaft, Liebe und ein Zuhaus.","ipa":"/diː kˈɪnthaɪt diː jˈuːɡənt diː ʃvˈɛstɜ deːn fˈɑːtɜ frˈɔøndʃaft lˈiːbə ʊnt aɪn tsuːhˈaʊs/","zh":"我的童年，我的青春，我的姐姐，我的父亲我的友谊，我的爱情还有一个真正的家","en":"Childhood, youth, sister, father friendship, love and a home.","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-49-034","lineIndex":26,"speaker":"","original":"Ich wollte...","ipa":"/ɪç vɔltə/","zh":"我想……","en":"I wanted...","note":"","sourceLineIndex":34}],"sourceOrder":49,"displayOrder":43},{"order":50,"id":"50-wie-wird-man-seinen-schatten-los-finale","title":"Wie Wird Man Seinen Schatten Los? (Finale)","titleZh":"如何逃离自己的阴影？（终曲）","lines":[{"id":"mozart-das-musical-50-001","lineIndex":1,"speaker":"","original":"Wie wird man seinen Schatten los?","ipa":"/vi vɪɾt man zaɪnən ʃatən los/","zh":"你要如何逃离自己的阴影？","en":"How do you get rid of your shadow?","note":"","sourceLineIndex":1},{"id":"mozart-das-musical-50-002","lineIndex":2,"speaker":"","original":"Wie sagt man seinem Schicksal Nein?","ipa":"/vi zɑkt man zaɪnəm ʃɪkzɑl naɪn/","zh":"你该如何反抗自己的命运？","en":"How do you say no to your fate?","note":"","sourceLineIndex":2},{"id":"mozart-das-musical-50-003","lineIndex":3,"speaker":"","original":"Wie kriecht man aus der eignen Haut?","ipa":"/vi kɾiçt man aʊs dɛɾ aɪɡnən haʊt/","zh":"又要如何冲破枷锁？","en":"How do you crawl out of your own skin?","note":"","sourceLineIndex":3},{"id":"mozart-das-musical-50-004","lineIndex":4,"speaker":"","original":"Wie kann man je ein anderer sein?","ipa":"/vi kan man je aɪn andərɜ zaɪn/","zh":"如何得到重生？","en":"How can you ever be someone else?","note":"","sourceLineIndex":4},{"id":"mozart-das-musical-50-005","lineIndex":5,"speaker":"","original":"Wen soll man fragen, wenn man sich selber nicht versteht?","ipa":"/ven zɔl man frɑɡən vɛn man zɪç zɛlbɜ nɪçt fɛɾʃtet/","zh":"如果认不清自己，又能向谁去探寻？","en":"Who should you ask if you don't understand yourself?","note":"","sourceLineIndex":5},{"id":"mozart-das-musical-50-006","lineIndex":6,"speaker":"","original":"Wie kann man frei sein, wenn man seinem eignen Schatten nie entgeht?","ipa":"/vi kan man fraɪ zaɪn vɛn man zaɪnəm aɪɡnən ʃatən ni ɛntɡet/","zh":"如果逃离不出自己的阴影，又能如何真正自由？","en":"How can you be free if you never escape your own shadow?","note":"","sourceLineIndex":6},{"id":"mozart-das-musical-50-007","lineIndex":7,"speaker":"","original":"Wenn der Kampf vorüber ist und dein Weg zu Ende bist du nur noch, der du bist.","ipa":"/vˌɛn dɛɾ kˈampf foːrˈyːbɜ ɪst ʊnt daɪn vˈeːk tsuː ˈɛndə bɪst duː nˈuːɾ nɔx dɛɾ duː bˈɪst/","zh":"当你停止抗争孤身一人走到最后你将接近自己的本真","en":"When the fight is over and your path is over you are just who you are.","note":"","sourceLineIndex":7},{"id":"mozart-das-musical-50-010","lineIndex":8,"speaker":"","original":"Dann zählt nur noch, was unzerstörbar ist.","ipa":"/dan tsɛlt nuɾ nɔx vas ʊntsɛɾʃtøɾbɑɾ ɪst/","zh":"那只有坚不可摧的灵魂才得以永荣","en":"Then only what is indestructible counts.","note":"","sourceLineIndex":10},{"id":"mozart-das-musical-50-011","lineIndex":9,"speaker":"","original":"Doch solange wir leben","ipa":"/dɔx zolaŋə viɾ lebən/","zh":"但只要我们还存留于世","en":"But as long as we live","note":"","sourceLineIndex":11},{"id":"mozart-das-musical-50-012","lineIndex":10,"speaker":"","original":"ist es uns aufgegeben","ipa":"/ɪst ɛs ʊns aʊfɡəɡebən/","zh":"就算被弃之不顾","en":"it is up to us to","note":"","sourceLineIndex":12},{"id":"mozart-das-musical-50-013","lineIndex":11,"speaker":"","original":"uns zu fragen, Tag und Nacht:","ipa":"/ʊns tsu frɑɡən tɑk ʊnt naxt/","zh":"也要日夜追问自己","en":"ask ourselves, day and night:","note":"","sourceLineIndex":13},{"id":"mozart-das-musical-50-014","lineIndex":12,"speaker":"","original":"Wie wird man seinen Schatten los?","ipa":"/vi vɪɾt man zaɪnən ʃatən los/","zh":"你要如何逃离自己的阴影？","en":"How do you get rid of your shadow?","note":"","sourceLineIndex":14},{"id":"mozart-das-musical-50-015","lineIndex":13,"speaker":"","original":"Wie sagt man seinem Schicksal Nein?","ipa":"/vi zɑkt man zaɪnəm ʃɪkzɑl naɪn/","zh":"你该如何反抗自己的命运？","en":"How do you say no to your fate?","note":"","sourceLineIndex":15},{"id":"mozart-das-musical-50-016","lineIndex":14,"speaker":"","original":"Wie kriecht man aus der eignen Haut?","ipa":"/vi kɾiçt man aʊs dɛɾ aɪɡnən haʊt/","zh":"又要如何冲破枷锁？","en":"How do you crawl out of your own skin?","note":"","sourceLineIndex":16},{"id":"mozart-das-musical-50-017","lineIndex":15,"speaker":"","original":"Wie kann man je ein anderer sein?","ipa":"/vi kan man je aɪn andərɜ zaɪn/","zh":"如何得到重生？","en":"How can you ever be someone else?","note":"","sourceLineIndex":17},{"id":"mozart-das-musical-50-018","lineIndex":16,"speaker":"","original":"Wen soll man fragen, wenn man sich selber nicht versteht?","ipa":"/ven zɔl man frɑɡən vɛn man zɪç zɛlbɜ nɪçt fɛɾʃtet/","zh":"如果认不清自己，又该向谁去探寻？","en":"Who should you ask if you don't understand yourself?","note":"","sourceLineIndex":18},{"id":"mozart-das-musical-50-019","lineIndex":17,"speaker":"","original":"Wie kann man frei sein, wenn man seinem eignen Schatten nie entgeht?","ipa":"/vi kan man fraɪ zaɪn vɛn man zaɪnəm aɪɡnən ʃatən ni ɛntɡet/","zh":"如果逃离不出自己的阴影，又能如何真正自由？","en":"How can you be free if you never escape your own shadow?","note":"","sourceLineIndex":19},{"id":"mozart-das-musical-50-020","lineIndex":18,"speaker":"","original":"Wie wird man seinen Schatten los?","ipa":"/vi vɪɾt man zaɪnən ʃatən los/","zh":"你要如何逃离自己的阴影？","en":"How do you get rid of your shadow?","note":"","sourceLineIndex":20},{"id":"mozart-das-musical-50-021","lineIndex":19,"speaker":"","original":"Wie können wir leben","ipa":"/vi kœnən viɾ lebən/","zh":"我们该如何生活","en":"How can we live","note":"","sourceLineIndex":21},{"id":"mozart-das-musical-50-022","lineIndex":20,"speaker":"","original":"(Wie lässt man alles hinter sich?)","ipa":"/vi lɛst man aləs hɪntɜ zɪç/","zh":"（又如何将一切抛在脑后？）","en":"(How do you leave everything behind?)","note":"","sourceLineIndex":22},{"id":"mozart-das-musical-50-023","lineIndex":21,"speaker":"","original":"(Wie jagt man sein Gewissen fort?)","ipa":"/vi jɑkt man zaɪn ɡəvɪsən fɔɾt/","zh":"（该如何背弃自己的良心？）","en":"(How do you drive away your conscience?)","note":"","sourceLineIndex":23},{"id":"mozart-das-musical-50-024","lineIndex":22,"speaker":"","original":"solang wir nur dem Schicksal dienen?","ipa":"/zolaŋ viɾ nuɾ dem ʃɪkzɑl dinən/","zh":"假使我们只屈从于命运？","en":"as long as we only serve fate?","note":"","sourceLineIndex":24},{"id":"mozart-das-musical-50-025","lineIndex":23,"speaker":"","original":"(Wie flieht man vor dem eignen ich?)","ipa":"/vi flit man fɔɾ dem aɪɡnən ɪç/","zh":"（要如何逃离自己？）","en":"(How do you escape from your own self?)","note":"","sourceLineIndex":25},{"id":"mozart-das-musical-50-026","lineIndex":24,"speaker":"","original":"(Wie kann man flüchten, )","ipa":"/vi kan man flʏçtən/","zh":"（该如何逃脱？）","en":"(How can you escape, )","note":"","sourceLineIndex":26},{"id":"mozart-das-musical-50-027","lineIndex":25,"speaker":"","original":"Wir können nie","ipa":"/viɾ kœnən ni/","zh":"我们永远不能","en":"We can never","note":"","sourceLineIndex":27},{"id":"mozart-das-musical-50-028","lineIndex":26,"speaker":"","original":"(wenn man sich selbst im Wege steht?)","ipa":"/vɛn man zɪç zɛlpst ɪm veɡə ʃtet/","zh":"（如果你成为了自己的阻碍？）","en":"(if you stand in your own way?)","note":"","sourceLineIndex":28},{"id":"mozart-das-musical-50-029","lineIndex":27,"speaker":"","original":"wir können nie","ipa":"/viɾ kœnən ni/","zh":"我们永远不能","en":"We never can","note":"","sourceLineIndex":29},{"id":"mozart-das-musical-50-030","lineIndex":28,"speaker":"","original":"nie","ipa":"/ni/","zh":"永远不能","en":"never","note":"","sourceLineIndex":30},{"id":"mozart-das-musical-50-031","lineIndex":29,"speaker":"","original":"(Vor deinem Schicksal kannst du nicht fliehen!)","ipa":"/fɔɾ daɪnəm ʃɪkzɑl kanst du nɪçt fliən/","zh":"（你不能在自己的命运面前退缩！）","en":"(you cannot run away from your fate!)","note":"","sourceLineIndex":31},{"id":"mozart-das-musical-50-032","lineIndex":30,"speaker":"","original":"niemals vor unserm eignen Schatten fliehen!","ipa":"/nimɑls fɔɾ ʊnzɜm aɪɡnən ʃatən fliən/","zh":"永远不要在我们自己的阴影面前退缩！","en":"never run away from our own shadow!","note":"","sourceLineIndex":32}],"sourceOrder":50,"displayOrder":44}];
